locale "ja_JP"
------------------------------------------------
section "tome-orcs/data/achievements/special.lua"

t("No mercy!", "慈悲はなし！", "achievement name")
t("Killed 1000 steam giants civilians.", "　スチームジャイアントの一般市民を１０００人殺した。", "_t")
t("Mercy, mercy!", "お慈悲を！　お慈悲を！", "achievement name")
t("Killed Talosis without any civilians deaths.", "　スチームジャイアントの一般市民を一人も殺さずに「警備長タロシス」を斃した。", "_t")
t("This will make a big Omelette!", "山のようなオムレツを！", "achievement name")
t("Collected 40 ritch eggs in the Ritch Hive.", "　リッチ虫の卵を４０集めた。", "_t")
t("An Other Brick in the Wall", "直行でも別に", "achievement name")
t("Defeated Aeryn in the Gates of Morning without destroying the Observatory nor using ritches help.", "　天文台を未制覇で、かつリッチ虫も利用せずに暁の門のエアリンを撃破した。", "_t")
t("No Steam, No Palace. No Palace, No Palace!", "蒸気無くして宮殿無し！", "achievement name")
t("Destroyed the Palace of Fumes without first destroying the geothermal valves in the Steam Quarry.", "　蒸気採掘場のバルブを破壊せずに噴霧の宮殿を制覇した。", "_t")
t("Here, I Think You Dropped This", "あの、これ落ちてましたよ？", "achievement name")
t("Killed Ureslak the Eternal while wielding Ureslak's Femur.", "　★ウレスラックメイスを装備して不死なるウレスラックを斃した", "_t")
t("Do not go gentle into that good night", "死に安らぎ無し", "achievement name")
t("Trapped John.", "　ジョンを指輪に封じ込めた。", "_t")
t("I did not want that!", "そんなつもりじゃ！", "achievement name")
t("Tricked Nektosh into killing one of his own people.", "　ネクトッシュが仲間を殺すように仕向けた。", "_t")
t("We weren't kidding!", "真面目にやってたよ！", "achievement name")
t("Die to Nektosh's beam without being pinned, stunned, asleep, dazed, or confused.", "　移動不能、スタン、睡眠、朦朧、混乱のいずれも受けていない状態でナクトッシュのビームを受けて死亡した。", "_t")
t("Make Him Squirm", "焦らしプレイ", "achievement name")
t("Made Nektosh use up the last of his power, then left the area and ignored him until beating the game. The other Whitehooves will catch on any second now...", "　ナクトッシュのビーム使用残量を使い切らせ、*勝利*まで放置する。彼に敵対する白蹄族の面々はすぐにでも事態を把握するだろう・・・", "_t")
t("True Savior", "真の救世主", "achievement name")
t("Freed all the Orc Prides without killing a single mind-controlled orc.", "　精神支配を受けたオークを一人も殺さずに全てのオーク部族を解放した。", "_t")
t("Mender", "大地の癒し手", "achievement name")
t("Destroyed the bosses of the Primal Forest without killing any uncorrupted treants.", "　邪悪な力に侵されたトレントを１体も斃さずに、原初の森のボスを全て撃破した。", "_t")
t("Sufficiently Advanced Technology", "高度に発達した科学は・・・", "achievement name")
t("Put five points into each of the tinker-crafting talents as any mage class.", "　魔導士系クラスで工士アイテムを作成するタレント全てに５点ずつポイントを振った。", "_t")
t("Radiant Horrorc", "輝ける悪夢", "achievement name")
t("While fighting in a Sunwall zone, use a Fiery Salve to reach at least 66% affinity for Fire and Light. Pointing and laughing is optional.", "　太陽の壁で火炎軟膏を使用し、火炎と光属性の属性吸収を６６％以上にした。太陽の騎士達を指さしてゲラゲラ笑いたいならご自由に。", "_t")
t("Blood on the Moon", "血染めの月", "achievement name")
t("Kill all of the Star Gazers within 7 game turns.", "　７ターン以内に全ての星見を斃した。", "_t")
t("Once Upon A Time, In the West...", "昔々、西の大陸に・・・", "achievement name")
t("Hear the Eidolon's retelling of the Scourge from the West's journey.", "　「西の災厄」の物語をエイドロンから改めて聞いた。", "_t")
t("A Fistful of Gold", "小銭ジャラジャラ", "achievement name")
t("Buy an item from an AAA.", "　自動古代アーカイブでアイテムを購入した。", "_t")
t("For a Few Gold More", "もっとお金を", "achievement name")
t("Completely deplete an AAA's stock.", "　古代自動アーカイブ１軒を品切れになるまで購入した。", "_t")
t("The Good, The Bad, and The Yeti", "良い奴、悪い奴、そしてイエティ", "achievement name")
t("Use mind-controlled yetis to kill 30 foes.", "　精神支配したイエティで敵を３０体斃した。", "_t")
t("Total Annihilation: Redundancy", "滅殺滅殺", "achievement name")
t("Wield the Annihilator as an Annihilator.", "　★滅殺ガトリングをアナイアレーターで装備した。", "_t")

------------------------------------------------
section "tome-orcs/data/achievements/story.lua"

t("Across the Narrow Sea", "海峡を渡って", "achievement name")
t("Destroyed the Sunwall Outpost to secure a way to the mainland.", "　太陽の壁の前哨基地を攻略し、本土への道を確保した。", "_t")
t("Reclaiming Garkul's Heritage", "ガークルの遺志を継ぐ者", "achievement name")
t("Freed the remnants of the Prides from the Internment Camp.", "　オーク拘留基地で全ての部族を解放した。", "_t")
t("The High Lady's Destiny (Finale)", "騎士の運命（結末）", "achievement name")
t("Crushed High Sun Paladin Aeryn and with her destroyed the bastion of the Sunwall.", "　高位騎士エアリンを斃し、太陽の壁を滅ぼした。", "_t")
t("One Ill Turn Deserves Another", "目には目を", "achievement name")
t("The Palace of Fumes stands in ruins, its Council shattered. The Atmos Tribe will not bother the Prides anymore.", "　噴霧の宮殿は廃墟となり、議会は滅びた。最早アトモス族がオークを煩わすことは無い。", "_t")
t("The Dead God Rests", "死せる神眠りに就きたり", "achievement name")
t("You have defeated the Sher'tul Priest trying to resurrect Amakthel, saving both the Prides and the world.", "　アマクテルの復活を企むシェール・タルの大祭司を撃破し、オークを、そして世界を救った。", "_t")
t("To the Bitter End", "苦い結末", "achievement name")
t("You have destroyed the last remnants of the Atmos Tribe, ending their civilization.", "　アトモス族の生き残りを滅ぼし、その文明を抹消した。", "_t")
t("Imp'ing Away", "狙いを逸らして", "achievement name")
t("You have spared the last remnants of the Atmos Tribe, showing mercy where others gave none to the orcs.", "　アトモス族の生き残りを見逃し、寛恕の心を示した。オークがこのような扱いを受けたことは一度もない。", "_t")

------------------------------------------------
section "tome-orcs/data/birth/classes/empyreal.lua"

t("Their most important stats are: Magic and Constitution", "　魔力と耐久が重要です。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD#能力修正:", "_t")
t("#LIGHT_BLUE# * +0 Strength, +0 Dexterity, +3 Constitution", "#LIGHT_BLUE# *耐久＋３", "_t")
t("#LIGHT_BLUE# * +6 Magic, +0 Willpower, +0 Cunning", "#LIGHT_BLUE# *魔力＋６", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# +0", "#GOLD#レベル毎ＨＰ上昇:#LIGHT_BLUE# +0", "_t")
-- untranslated text
--[==[
t("Empyreal", "Empyreal", "birth descriptor name")
--]==]


------------------------------------------------
section "tome-orcs/data/birth/classes/tinker.lua"

t("Tinker", "工士", "birth descriptor name")
t("Tinkers use steamtech to power their attacks, defenses, ...", "　蒸気機械を用いて攻防を強化します・・・", "_t")
t("Build, experiment, discover. The path of inventions is never over!", "　造り、試し、発見する。技術の発展に終わりはない！", "_t")
t("%s healing salve", "%s治癒軟膏", "tformat")
t("simple", "低級", "_t")
t("%s frost salve", "%s冷気軟膏", "tformat")
t("Sawbutcher", "ブッチャー", "birth descriptor name")
t("A formidable behemoth of war using steamsaws to improve his deadliness.", "　恐るべき戦鬼です。スチームソーを用いて戦闘能力を強化します。", "_t")
t("Their most important stats are: Strength and Cunning", "　腕力と賢さが重要です。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD#能力修正:", "_t")
t("#LIGHT_BLUE# * +5 Strength, +0 Dexterity, +1 Constitution", "#LIGHT_BLUE# *腕力＋５　耐久＋１", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +3 Cunning", "#LIGHT_BLUE# *賢さ＋３", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 2", "#GOLD#レベル毎ＨＰ上昇：#LIGHT_BLUE#２", "_t")
t("Gunslinger", "ガンナー", "birth descriptor name")
t("A tinker who dual-wields steamguns to great effect.", "　二丁拳銃で大暴れする工士です。", "_t")
t("Their most important stats are: Cunning and Dexterity", "　賢さと機敏が重要です。", "_t")
t("#LIGHT_BLUE# * +0 Strength, +4 Dexterity, +1 Constitution", "#LIGHT_BLUE# *機敏＋４　耐久＋１", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +4 Cunning", "#LIGHT_BLUE# *賢さ＋４", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# -1", "#GOLD#レベル毎ＨＰ上昇：#LIGHT_BLUE#－１", "_t")
t("Psyshot", "サイコガンナー", "birth descriptor name")
t("Bend the mind, bend the tech. All around inspire dread.", "　心を意のままに。技術を意のままに。全てに恐怖を。", "_t")
t("Powerful psionics are able to enter a gestalt with steam generators and technology to enhance their own mental prowess.", "　強力な超能力者は蒸気機関と一体となり、精神力を高めることができます。", "_t")
t("The Psyshot combines this ability to gestalt to enhance his mindstar all the while shooting her steamgun to devastate the enemy lines.", "　サイコガンナーはこの心機合一の力を結集してマインドスターを強化し、銃撃で敵陣を瓦解させます。", "_t")
t("Their most important stats are: Cunning, Willpower and Dexterity", "　賢さ、意志、機敏が重要になります。", "_t")
t("#LIGHT_BLUE# * +0 Strength, +3 Dexterity, +0 Constitution", "#LIGHT_BLUE# *機敏＋３", "_t")
t("#LIGHT_BLUE# * +0 Magic, +3 Willpower, +3 Cunning", "#LIGHT_BLUE# *意志＋３　賢さ＋３", "_t")
t("Annihilator", "アナイアレーター", "birth descriptor name")
t("The Annihilator is a master of destruction, wielding the most devastating steamtech inventions to lay waste to their foes.", "　アナイアレーターは破壊行為をお手の物としています。強烈な蒸気兵器を携え、敵を壊滅するのです。", "_t")
t("While normally wielding a steamgun loaded with experimental ammunition and an electrically charged shield, they can equip heavy weapons such as flamethrowers.", "　普段はスチームガンに試作型弾丸を装填し、磁場を帯びた盾で身を守ります。しかし火炎放射器のような重火器も装備可能です。", "_t")
t("More adept at technology than most other tinkers, they supplement their weapons with automated turrets, mechanical minions and other such devices.", "　テクノロジーにおいては他の工士クラスを凌駕し、自動タレットやマシンなどのデバイスで火力を補います。", "_t")
t("#LIGHT_BLUE# * +0 Strength, +4 Dexterity, +0 Constitution", "#LIGHT_BLUE# *機敏＋４", "_t")
t("#LIGHT_BLUE# * +0 Magic, +0 Willpower, +5 Cunning", "#LIGHT_BLUE# *賢さ＋５", "_t")
t("Research. Tinker. Annihilate.", "調査。製作。ぶっ壊せ。", "_t")

------------------------------------------------
section "tome-orcs/data/birth/races/orc.lua"

t("Skin", "皮膚", "birth facial category")
t("Facial features", "容貌", "birth facial category")
t("Tatoos", "タトゥー", "birth facial category")
t("Horns", "角", "birth facial category")
t("Special", "特殊", "birth facial category")
t("Orc", "オーク", "birth descriptor name")
t("Orcs have a long and sad history. They are seen, and are, as an aggressive race that more than one time managed to imperil all of Maj'Eyal.", "　オークの歴史は長く、悲しみに満ちています。彼らは好戦的な種族と見なされており、実際にそのような性質を持ち合わせています。史上、一度ならずマイ・イヤル全土を壊滅の危機に晒したのです。", "_t")
t("But one year ago the Scourge from the West came and wiped four of the five Prides. And a hundred years ago King Toknor wiped all traces of orcs from Maj'Eyal.", "　ですが１年前、「西の災厄」が現れ５つの部族のうち４つまでを滅ぼしました。１００年前にトクノール王はマイ・イヤルよりオークを一掃しています。", "_t")
t("The orc race is dangerously on the brink of destruction. One wrong move is all that is needed.", "　オークという種は滅亡の瀬戸際にあります。一手誤るだけで取り返しのつかないことになるでしょう。", "_t")
t("But they are strong and will face whatever is needed to ensure a future of their own!", "　しかしオークは強靭な種族。未来を手にするためにはいかなる危険にも立ち向かいます！", "_t")
t("Skin Color 1", "肌の色１", "_t")
t("Skin Color 2", "肌の色２", "_t")
t("Skin Color 3", "肌の色３", "_t")
t("Skin Color 4", "肌の色４", "_t")
t("Skin Color 5", "肌の色５", "_t")
t("Demonic Red Skin", "デーモンのレッドスキン", "_t")
t("Goggles 1", "ゴーグル１", "_t")
t("Goggles 2", "ゴーグル２", "_t")
t("Goggles 3", "ゴーグル３", "_t")
t("Goggles 4", "ゴーグル４", "_t")
t("Jaws 1", "顎周り１", "_t")
t("Jaws 2", "顎周り２", "_t")
t("Mechbiter 1", "メックバイター１", "_t")
t("Mechbiter 2", "メックバイター２", "_t")
t("Monocle Left 1", "モノクル左１", "_t")
t("Monocle Left 2", "モノクル左２", "_t")
t("Monocle Right 1", "モノクル右１", "_t")
t("Monocle Right 2", "モノクル右２", "_t")
t("Tatoos 1", "タトゥー１", "_t")
t("Tatoos 2", "タトゥー２", "_t")
t("Tatoos 3", "タトゥー３", "_t")
t("Demonic Horns 1", "デーモンの角１", "_t")
t("Demonic Horns 2", "デーモンの角２", "_t")
t("Demonic Horns 3", "デーモンの角３", "_t")
t("Demonic Horns 4", "デーモンの角４", "_t")
t("Demonic Horns 5", "デーモンの角５", "_t")
t("Demonic Horns 6", "デーモンの角６", "_t")
t("Demonic Horns 7", "デーモンの角７", "_t")
t("Demonic Horns 8", "デーモンの角８", "_t")
t("Bikini / Mankini", "アブナイ水着", "_t")
t("They possess the #GOLD#Orcish Fury#WHITE# which allows them to increase all their damage for a few turns.", "#GOLD#　「オークの憤激」#WHITE#の能力で数ターンの間与ダメージを上昇させることが可能です。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD#能力修正:", "_t")
