t("#LIGHT_BLUE# * -1 Magic, +1 Willpower, +1 Cunning", "#LIGHT_BLUE# *魔力－１　意志＋１　賢さ＋１", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 12", "#GOLD#レベル毎ＨＰ上昇：#LIGHT_BLUE#１２", "_t")
