section "tome-orcs/data/birth/races/whitehooves.lua"

t("Skin", "皮膚", "birth facial category")
t("Facial features", "容貌", "birth facial category")
t("Horns", "角", "birth facial category")
t("Special", "特殊", "birth facial category")
t("Undead", "不死者", "_t")
t("Grave strength, dread will, this flesh cannot stay still. Kings die, masters fall, we will outlast them all.", "偉大なる力、恐るべき意思を以ってしても生には限りがある。諸王が世を去り、権力者たちが死に絶えようと、不死者はこの世に留まり続ける。", "_t")
t("Undead are humanoids (Humans, Elves, Dwarves, ...) that have been brought back to life by the corruption of dark magics.", "　邪悪な魔法により、復活した者たちです。（生前は人間、エルフドワーフなどだったのでしょう）", "_t")
t("Undead can take many forms, from ghouls to vampires and liches.", "　グールや吸血鬼、リッチといった様々な形態をとります。", "_t")
t("Skin Color 1", "肌の色１", "_t")
t("Skin Color 2", "肌の色２", "_t")
t("Skin Color 3", "肌の色３", "_t")
t("Skin Color 4", "肌の色４", "_t")
t("Skin Color 5", "肌の色５", "_t")
t("Skin Color 6", "肌の色６", "_t")
t("Skin Color 7", "肌の色７", "_t")
t("Demonic Red Skin", "デーモンのレッドスキン", "_t")
t("Beard 1", "ヒゲ１", "_t")
t("Beard 2", "ヒゲ２", "_t")
t("Redhead Beard", "赤髭", "_t")
t("Hair 1", "髪１", "_t")
t("Hair 2", "髪２", "_t")
t("Hair 3", "髪３", "_t")
t("Hair 4", "髪４", "_t")
t("Redhead Hair 1", "赤髪１", "_t")
t("Redhead Hair 2", "赤髪２", "_t")
t("Horns 1", "角１", "_t")
t("Horns 2", "角２", "_t")
t("Horns 3", "角３", "_t")
t("Horns 4", "角４", "_t")
t("Demonic Horns 1", "デーモンの角１", "_t")
t("Demonic Horns 2", "デーモンの角２", "_t")
t("Demonic Horns 3", "デーモンの角３", "_t")
t("Demonic Horns 4", "デーモンの角４", "_t")
t("Demonic Horns 5", "デーモンの角５", "_t")
t("Demonic Horns 6", "デーモンの角６", "_t")
t("Demonic Horns 7", "デーモンの角７", "_t")
t("Demonic Horns 8", "デーモンの角８", "_t")
t("Bikini / Mankini", "アブナイ水着", "_t")
t("Whitehoof", "白蹄族", "birth descriptor name")
t("A clan of minotaurs turned to necromancy when faced with imminent destruction.", "　存亡の危機に瀕して死霊術に救いの道を求めたミノタウロスの一派です。", "_t")
t("Whitehooves are resilient and magic imbued undead, hardened by their trials and made stronger by their undeath.", "　白蹄族は魔力を宿した頑健なアンデッドなのです。幾多の苦難を乗り越えた彼らは強固な肉体の持ち主で、不死者となったことでその力は一層増しています。", "_t")
t("They now seek to help their orc allies, in hope they will help them back.", "　彼らは現在オークを助けるべく活動しています。そうすれば向こうもそれに報いてくれるとの考えからです。", "_t")
t("They have access to #GOLD#special talents#WHITE# and a wide range of undead abilities:", "　#GOLD#特殊なタレント#WHITE#を習得可能であり、様々なアンデッドの能力を有しています。", "_t")
t("- silence resistance", "・沈黙耐性", "_t")
t("- bleeding immunity", "・出血無効", "_t")
t("- fear immunity", "・恐怖無効", "_t")
t("- no need to breathe", "・呼吸が不要", "_t")
t("- special whitehoof talents: dead hide, lifeless rush, essence drain", "・「デッドスキン」「アンデッドダッシュ」「デスドレイン」のタレントを習得可能", "_t")
t("#GOLD#Stat modifiers:", "#GOLD#能力修正:", "_t")
t("#LIGHT_BLUE# * +3 Strength, -1 Dexterity, +2 Constitution", "#LIGHT_BLUE# *腕力＋３　機敏－１　耐久＋２", "_t")
t("#LIGHT_BLUE# * +2 Magic, -3 Willpower, +1 Cunning", "#LIGHT_BLUE# *魔力＋２　意志－３　賢さ＋１", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 14", "#GOLD#レベル毎ＨＰ上昇：#LIGHT_BLUE#１４", "_t")
t("#GOLD#Experience penalty:#LIGHT_BLUE# 15%", "#GOLD#経験修正：#LIGHT_BLUE#１５％", "_t")

