t("Eyebrows", "眉毛", "_t")
t("Fangs", "キバ", "_t")
t("Mustache", "口ヒゲ", "_t")
t("Demonic Horns 1", "デーモンの角１", "_t")
t("Demonic Horns 2", "デーモンの角２", "_t")
t("Demonic Horns 3", "デーモンの角３", "_t")
t("Demonic Horns 4", "デーモンの角４", "_t")
t("Demonic Horns 5", "デーモンの角５", "_t")
t("Demonic Horns 6", "デーモンの角６", "_t")
t("Demonic Horns 7", "デーモンの角７", "_t")
t("Demonic Horns 8", "デーモンの角８", "_t")
t("Bikini / Mankini", "アブナイ水着", "_t")
t("Kruk Yeti", "クルクイエティ", "birth descriptor name")
t("Yetis are a towering mass of muscle. While normal yetis are non-sentient beasts this kind is special.", "　イエティは筋骨逞しい巨躯の生物です。普通のイエティは知能を持ち合わせてはいません。しかし、この種のイエティは例外です。", "_t")
t("A few orcs of the Kruk pride have mastered techno-psionics, allowing them to literally hijack a yeti's mind and transfer their own mind inside.", "　クルク部族のオークの中にはテクノ・サイオニックを極めた者達がいて、文字通り、イエティの精神を乗っ取って己の精神を移し変えることができます。", "_t")
t("Doing so drains their old knowledge and they need to start afresh, gaining considerable strength in the process; for the good of the Prides.", "　精神をイエティの肉体に移してしまうと、これまで培った知識を全て忘れてしまい、一からやり直さなくてはいけません。その代わり、並々ならぬ筋力を手にするのです。全てのオーク部族を救わんがために。", "_t")
t("They possess the #GOLD#Algid Rage#WHITE# talent which allows them to encase their foes in blocks of ice.", "#GOLD#　「凍てつく怒り」#WHITE#の能力で相手を氷漬けにすることができます。", "_t")
t("#GOLD#Stat modifiers:", "#GOLD#能力修正:", "_t")
t("#LIGHT_BLUE# * +5 Strength, -3 Dexterity, +4 Constitution", "#LIGHT_BLUE# *腕力＋５　機敏－３　耐久＋４", "_t")
t("#LIGHT_BLUE# * +0 Magic, +1 Willpower, -1 Cunning", "#LIGHT_BLUE# *意志＋１", "_t")
t("#GOLD#Life per level:#LIGHT_BLUE# 13", "#GOLD#レベル毎ＨＰ上昇：#LIGHT_BLUE#１３", "_t")
t("#GOLD#Experience penalty:#LIGHT_BLUE# 12%", "#GOLD#経験修正：#LIGHT_BLUE#１２％", "_t")

------------------------------------------------
section "tome-orcs/data/birth/worlds.lua"

t("Orcs: Embers of Rage", "憤怒の残火", "_t")
t("The Prides lie in ruins!", "　四部族は瓦解！", "_t")
t("The Sorcerers have been defeated!", "　２人のソーサラーは倒れました！", "_t")
t("Orcs in all Var'Eyal are in dismay, hunted by the Sunwall and their newfound allies from the west.", "　ヴァル・イヤルのオークたちは途方に暮れています。太陽の壁の騎士たちが西方より新たに助力を得てオークを追い詰めているのです。", "_t")
t("The Scourge from the West is back in the west, but her legacy stays strong: the orc race is once again upon the brink of destruction!", "　「西の災厄」は故郷に戻りましたが、かの者が残した傷痕は未だ深く、オークは滅亡の瀬戸際まで追い詰められています！", "_t")
t("But not all hope is lost.", "　しかしまだ望みはあります。", "_t")
t("On the isolated Clork Peninsula lies the fifth pride: Kruk's Pride; unseen and unharmed by the Scourge.", "　本土から離れたクローク半島にはオーク第五の部族であるクルク部族が「西の災厄」の手を免れています。", "_t")
t("Yet not all is great there either, the Sunwall offensive has set up an outpost blocking the way to the mainland.", "　とはいえ、万事見通しが明るいわけでもありません。太陽の騎士たちが前哨基地を作り、肩を怒らせて本土への道を塞いでいますから。", "_t")
t("But the worst threat comes from the peninsula itself, the main inhabitants are not the orcs, but the Atmos Tribe.", "　何より警戒すべきは敵はこのクローク半島に。この島を支配しているのはオークではなくアトモス族。", "_t")
t("A civilization of steam giants whose mastery of steamtech makes them incredible foes.", "　蒸気機械を自在に操るスチームジャイアントの国家は実に手強い相手です。", "_t")
t("Play an orc, prove your worth! Use steamtech against the giants, reclaim the far east and free it from Sunwall scum!", "　オークとなって自らの力を示しましょう！　蒸気機械の力を借りてジャイアント共を相手取り、東方に再び覇を唱え、この大陸を「太陽の壁」から取り戻すのです！", "_t")
t("Craft your own steamsaws, rocket boots, steam powered armours, and all kind of steamy technology!", "　自分だけのスチームソー、ロケットブーツやスチームアーマーなど、ありとあらゆる蒸気機械が作成可能！", "_t")
t("This is your destiny! For Garkul's Legacy, for the Glory of the Pride!", "　この戦いは天より授かった使命。ガークルの遺志を継ぎ、オークたちの未来をこの手に！", "_t")

------------------------------------------------
section "tome-orcs/data/chats/aaa.lua"

t("#LIGHT_GREEN#*Before you stands a strange triangular device, some kind of automated storage facility.*#WHITE#", "#LIGHT_GREEN#　奇妙なピラミッド型の装置がある。自動保管装置の一種だ。#WHITE#", "_t")
t("[access store]", "アイテムを入手する", "_t")
t("[reprogram it to order it to relocate to Kruk Pride]", "クルク部族への転移が出来るように改造する", "_t")
t("[leave]", "放っておく", "_t")
t("#LIGHT_GREEN#*You tinker with the store bot and manage to activate the relocation function.*#WHITE#", "#LIGHT_GREEN#　装置のプログラムに手を入れて転移機能を起動できるようにした。#WHITE#", "_t")
t("[order it to go to Kruk Pride]", "クルク部族の町へ", "_t")

------------------------------------------------
section "tome-orcs/data/chats/aaf.lua"

t([[#LIGHT_GREEN#*Before you stands a strange triangular device, some kind of automated facility.*#WHITE#
It seems to be able to teach you the tinker crafting techniques, but requires input to do so (500 gold and a talent category point).]], [[#LIGHT_GREEN#　奇妙なピラミッド型の装置がある。自動機械の一種だ。#WHITE#
これを使えば工士アイテムの作り方を学べるようだ。だがそれには対価が要る（５００ゴールドとカテゴリーポイント１点）]], "_t")
t("[pay 500 gold and a talent category points]", "５００ゴールド払い、カテゴリーポイントを消費する", "_t")
t("#PURPLE#The %s teaches you: #GOLD#Steamtech/Physics#LAST#, #GOLD#Steamtech/Chemistry#LAST# and two starter crafting talents.", "#PURPLE#%sを使用して#GOLD#工士／蒸気力学#LAST#と#GOLD#工士／蒸気化学#LAST#のツリーを習得。さらに基礎的な工士アイテム作成タレントを二種学んだ。", "log")
t("[access store]", "アイテムを入手する", "_t")
t("[leave]", "放っておく", "_t")
t([[The machine gives you a small metallic box labelled as #{italic}#"Automated Portable Extractor"#{normal}#.
It seems to be used to break down metallic items into lumps of metal and infusions into herbs which are used to craft tinkers.

#{bold}#You will have to choose to use it or the Transmogrification Chest when you destroy items. You can choose the default one by using it with no items to destroy.#{normal}#
]], [[　装置から小さな金属製の箱が出てきた。「工士用携帯式自動変換機」とラベルしてある。
　アイテムを破壊して金属製のものは金属塊に、ハーブ系の封入品はハーブへと変換し工士アイテムの材料にできるようだ。
#{bold}#　エネルギー変換装置とこちらを使い分けたい場合があるかもしれない。変換可能なアイテムが無い状態でどちらかを使用すると、そちらがデフォルトの変換装置として設定される。#{normal}#
]], "_t")
t("[take it]", "しまっておく", "_t")

------------------------------------------------
section "tome-orcs/data/chats/destructicus-lead.lua"

t([[#LIGHT_GREEN#*Several loyal Orcs are eagerly waiting outside the palace to meet you; one steps forward, handing you a set of keys.  The word 'DESTRUCTICUS' is etched into one.*#WHITE#
Chief @playername@!  The Giants are fleeing, and we intercepted a scout carrying this!  We believe they can be used with...  well, you should see for yourself!  Please, come with us to the mountains just south of Kruk Pride!
#LIGHT_GREEN#*This sounds important.  You should probably head there right away!*#WHITE#]], [[#LIGHT_GREEN#　腹心のオーク数名が宮殿の外でこちらの帰還を待ち侘びていた。一人が前に出て鍵束を手渡してくる。その中に「デストロイヤー」という文字が刻印された鍵があった。#WHITE#
　「@playername@隊長！　ジャイアント共は逃げ惑っております！　敵の斥候を捕らえた所、これを持っていました！　これはきっと・・・いえ、ご自分の目でお確かめください！　一緒に山まで来てください。我らの町から少し南に下ったところです！
#LIGHT_GREEN#*　重要な件のようだ。すぐに向かった方がいいだろう！#WHITE#]], "_t")
t("Lead the way.", "後に続く", "_t")

------------------------------------------------
section "tome-orcs/data/chats/destructicus.lua"

t("DESTRUCTICUS!", "デストロイヤー！", "_t")
t("Fire Imp", "ファイアインプ", "_t")
t("Steam Giant Airship", "スチームジャイアントのエアシップ", "_t")
t("#LIGHT_GREEN#*#{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# stands before you, and as much as it pains you to admit it, Kaltor's advertisement wasn't flattering enough.  This may be the most unreasonably lethal device you've ever seen.  The sunlight, gleaming off its voratun body, seems dull compared to the intensely glowing mass of unstable runes on its tip; its surface has the ornate grooves of a metal that has been psionically reforged through hours of migraine-inducing concentration.  The bayonet mounted on the launching tube just seems like gloating.  This particular model appears to be equipped with an enclosed, fireproof booth around its control panel, and a built-in tea dispenser in said booth, which your fellow orcs have already taken the liberty of filling with looted Dwarven ale.  It is truly a thing of beauty.*#WHITE#", "　これが#LIGHT_GREEN##{bold}#断固断空ミサイル・デストロイヤー#{normal}#か。悔しいが、カルターの広告はあれでも控えめな方だったと認めざるを得ない。知りうる限り、最高最大の破壊兵器だろう。ヴォラタン製のボディに日差しが照りかえって輝いているが、先端部でギラギラと光る無数の爆発性ルーンに比べればそれも色あせて見える。表面には派手な溝模様。偏頭痛を覚えるほどに集中し、超能力を用いて根気良く再加工したものだ。発射管に搭載した銃剣には製作者の悪意をありありと感じる。この独特の形状をした兵器は密閉した防火ブースに繋がっており、その内部には制御パネルがある。また、ドリンクサーバーがブース内に備え付けてあり、頼みもしないのに仲間のオーク達によって戦利品のドワーフエールが補充されていた。実に美しい一品である。#WHITE#", "_t")
t("[continue]", "続ける", "_t")
t("#LIGHT_GREEN#*You enter the booth, sit down, and insert the key.  #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# whirrs to life, its base slightly rotating underneath you.  A strange beaded panel slides in front of you, pins pushing out and pulling back by magnetic force to display the outline of an airship (and a tiny speck), and the words #{italic}#\"AERIAL TARGETS FOUND: 2.\"#{normal}#*#WHITE#", "#LIGHT_GREEN#　ブースに入り、腰を下ろしてキーを挿入。#{bold}#断固断空ミサイル・デストロイヤー#{normal}#が唸りを上げて息づき、コントロールの下、その底部が僅かに回転する。ビーズが並んだ奇妙なパネルが目の前にスライドしてきた。磁力によってビーズに刺さったピンが前後に動き、エアシップの外観（と小さな点）、そして#{italic}#「対空ターゲット発見：２」#{normal}#という文字を形成した。#WHITE#", "_t")
t([[#LIGHT_GREEN#*#{italic}#"OBTAINING SCRYING LOCK...  OBTAINED."#{normal}#
 
The beaded panel is suddenly awash with colors, showing the colossal interior of the airship.  Steam Giant families huddle and weep, sorting through the few belongings they could take with them when fleeing; a guard sits on a pile of luggage and storage crates, head in her hands.  The view pans around the cabin, and you see a few crew members hurrying between the captain's quarters and the engine room, pausing to take worried glances out the window - at you.
 
This airship appears to be evacuating what's left of the Atmos Tribe.  With the press of a single button, you could eradicate the Steam Giant species forever.
 
You press a button labelled #{italic}#"SELECT NEXT TARGET"#{normal}#, and the panel shifts to show a very lost and very confused Fire Imp, flying in the air near nothing of importance.  Firing on it would have little effect whatsoever, aside from showing off DESTRUCTICUS's power in the most harmless way possible.*#WHITE#]], [[#LIGHT_GREEN#*#{italic}#「遠見ロック取得中・・・取得完了」#{normal}#
　パネル一面に色彩が溢れ、広大なエアシップ内部を映し出す。スチームジャイアントの家族が身を寄せ合ってすすり泣き、避難するのに持っていける最低限の荷物をより分けている。山積みになった鞄と木箱の上には女兵士が腰を下ろし、両手で頭を抱えていた。映像の視点が乗組員室周辺に移る。船長室とエンジンルームを慌ただしく行き来する数名のクルーが動きを止め、不安げに視線を窓の外に－こちらへまっすぐ向けるのが視界に入った。
　このエアシップに乗り、アトモス族の生き残りが避難しようとしているようだ。ボタン一つ押すだけでスチームジャイアントという種は地上から消え去るだろう。
　#{italic}#「次のターゲットを選択」#{normal}#とラベルされたボタンを押すとパネルに途方に暮れたファイアインプが映った。飛行中だが付近には特に何もない。こいつを狙って打てば何の犠牲も出さずに済む。誰も傷つけず、大破壊兵器の威力を誇示するだけだ。#WHITE#]], "_t")
t("[shoot down the airship]", "エアシップを撃つ", "_t")
t("[shoot down the imp]", "インプを撃つ", "_t")
t("#LIGHT_GREEN#*Are you SURE you want to ERADICATE THE STEAM GIANTS?*#WHITE#", "#LIGHT_GREEN#　本当にスチームジャイアントを抹殺するのですか？#WHITE#", "_t")
t("[back]", "考え直す", "_t")
t("#LIGHT_GREEN#*Are you SURE you want to WASTE YOUR SHOT?*#WHITE#", "#LIGHT_GREEN#　無駄撃ちになりますが本当に良いのですか？#WHITE#", "_t")
t([[#LIGHT_GREEN#*The Steam Giants are too great a threat to allow their escape - you will not have them simply return someday to finish what they attempted, and wipe out your Pride.  You press the #{italic}#"PREVIOUS TARGET"#{normal}# button, and fire on the airship.  There is a great roar and a flash of flame; you see its missile flying away from you through the window, as you see it racing towards your view, and the terrified passengers, on the scrying panel.

It reaches its mark, and the panel goes dark as a tremendous, multicolored blast fills your vision through the window.
 
The Steam Giants are no more.
 
The secondary charges from the warhead detonate, as burning debris falls into the sea, and the ongoing display serves as a signal to all the Orcs of Var'Eyal, and anyone else who may be watching: This is the fate of all who would try to eradicate the Orcs.  The previous millennia of oppression, genocide, and bullying are over: your people will never be pushed around like this again.
 
A nagging thought in the back of your head insists that you now know how the Sun Paladins felt, how King Toknor felt, how the halflings felt, how everyone that has always committed such atrocities against the Orcs felt.  It can keep whining all it wants - your people are finally safe.*#WHITE#]], [[#LIGHT_GREEN#　スチームジャイアントを逃しては後顧の憂いが残る。奴らを許しては、当初の目的を果たさんとそのうち手のひらを返すに違いない。それではクルク部族が滅びてしまう。#{italic}#「前のターゲット」#{normal}#というボタンを押し、エアシップを撃つ。轟音と共に爆炎が上がり、窓越しにミサイルが彼方へと飛んでいくのが見えた。遠見パネル上では画面に向かって、恐れおののく乗員達を目指しミサイルが迫っている。
　着弾。窓の外が色とりどりの凄まじい爆発で見えなくなり、パネルは真っ暗になった。
　スチームジャイアントは滅びた。
　弾頭で二次爆発が起こり、燃え盛る破片が海へと降り注ぐ。この光景はヴァル・イヤルに生きる全てのオークへの、これを目にするあらゆる種族への意思表示となっている。「オークを滅ぼさんとするものはかくの如き運命を辿るのだ」と。幾千年にも渡る艱難辛苦の時代は終わりを告げた。昔のように迫害を受けることは最早ない。
　胸の中わだかまりが消えない。太陽の騎士達、トクノール王、ハーフリング。こうした大虐殺を常々オークに行ってきた者たちがどんな心持ちであったかを今悟ったのだ。感傷に浸る時間はいくらでもある。ついにオークは平和を手にしたのだから。#WHITE#]], "_t")
t("[leave]", "放っておく", "_t")
t([[#LIGHT_GREEN#*No...  you will not sink to the depths that King Toknor did, that the Sun Paladins did, that so many others have sunk to.  These refugees are not a threat, and could not possibly become one for quite some time...  but it might be for the best that they're made fully aware of what you're capable of, the fate you could've given them through so little effort, and given a display that'll make sure they remember that they owe their lives to your mercy.
 
You target the Fire Imp, and fire the weapon.  With a great roar and a flash of flame, #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# races towards the increasingly distressed imp.  It panics, flitting to the side evasively as #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}# corrects its course to compensate, until it gives up and shrugs dejectedly; you can't hear the scrying panel over the missile's roaring, but you're fairly sure you can see the imp mouthing "this is 'blazing ridiculous."
 
It impacts, and your vision is filled with an enormous, multicolored explosion.  Shrapnel and debris falls harmlessly into a barren mountaintop, and a great booming noise can be heard across the continent.  
 
Taking a swig from a freshly-dispensed mug of ale, you switch the now-empty #{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}#'s targeting controls over to the airship, and you see the giants cheering and hugging, crying in joy and relief.  A few wonder aloud if you meant to do that, but most recognize it as the display of mercy that it is.
 
As the secondary charges go off, the ongoing pyrotechnic display acts as a celebratory signal to the Steam Giants, the Orcs, and anyone else who may be watching: The war is over.  Var'Eyal, and the Orcs who now own it, will know peace for the first time in millennia.*#WHITE#]], [[#LIGHT_GREEN#　駄目だ・・・トクノール王や太陽の騎士達、その他大勢の轍を踏んではならない。この避難民の何が恐ろしいものか。長期的に見ても脅威にはなりえない。とはいえ、こちらの力を見せつけておくのはむしろ良い手かもしれない。「指先にほんの少し力を込めればお前たちがこうなっていた」と叩き込んでおく。その光景を目にすれば、「相手の温情で命を取りとめた」という記憶が刻まれるに違いない。
　ファイアインプに照準を合わせ、ミサイルを撃った。轟音と共に爆炎が上がり、#{bold}#断固断空ミサイル・デストロイヤー#{normal}#が慌てふためくインプをどんどん追い詰めていく。パニックに陥った標的が横に飛んで身を躱しても、#{bold}#断固断空ミサイル・デストロイヤー#{normal}#はコースを補正し、ついにインプは諦めて絶望に慄いた。遠見パネルからはミサイルの轟音しか聞こえないが、相手の口の動きははっきりと判る。
　「一体なんだってこんな目に」
　命中と共に色とりどりの凄まじい爆発が視界を埋め尽くす。金属片の混じった瓦礫がさしたる被害も起きずに不毛の山頂へ降り注ぎ、大陸中に鳴り響くような爆音が轟いた。今しがたマグカップに注いだエールをあおり、もぬけの殻となった#{bold}#断固断空ミサイル・デストロイヤー#{normal}#の照準コントロールをエアシップに合わせて俯瞰すると、喜びに沸き返ったスチームジャイアントたちが肩を抱き合い、安堵の嬉し涙を流しているのが見える。「わざと外したかなんてわかったもんじゃない」と声高に主張する者もちらほらいるが、「見逃してくれたんだ」と真意を理解してくれているのがほとんどだ。
　二次爆発が起こった。だが、今起こっている煌びやかな爆発はスチームジャイアント、オーク、そしてこれを見る全ての種族を寿ぐ狼煙となっている。戦いは終わったのだ。オークはついにヴァル・イヤルを征服した。これで数千年ぶりに平和が訪れる。#WHITE#]], "_t")

------------------------------------------------
section "tome-orcs/data/chats/john-surrender.lua"

t("You cannot summon; you are suppressed!", "召喚を封じられている！", "logPlayer")
t("HATE!", "死ね！", "_t")
t("PAIN!", "苦しめ！", "_t")
t("REGRET!", "悔いろ！", "_t")
t("My love...", "エアリン・・・", "_t")
t("I feel so lost.", "もうどうでもいい。", "_t")
t("Please let me die!", "とどめを刺せ！", "_t")
t("RAAAAARGGGG!", "うおおおおおおおおお！", "_t")
t("Someday you will pay!", "貴様もいつか報いを受けるぞ！", "_t")
t("DEATH!", "「死ね！」", "_t")
t("*Sobs*", "（すすり泣き）", "_t")
t([[#LIGHT_GREEN#*The Crimson Templar looks exhausted, nearly dead. You feel the ring attuning to him and suddenly you understand you could absorb his essence to power the ring.*#WHITE#
Go on kill me @playername@! My life is destroyed, my friends are dead, my dear Aeryn is dead. All dead by your murderous hands! Finish me, let me have some #{italic}#rest#{normal}#.]], [[#LIGHT_GREEN#　赤騎士は疲労困憊し、虫の息のようだ。指輪がジョンに惹きつけられている感じがする。そうだ、ジョンの命を指輪に取り込めるかもしれない。#WHITE#
　「さあ殺せ！　何もかも終わった。仲間は死に、エアリンもこの世にいない。皆貴様が殺したんだ！　止めを刺せ。もう#{italic}#楽#{normal}#になりたい」]], "_t")
t("#LIGHT_GREEN#[destroy him to power the ring]#WHITE# So be it!", "#LIGHT_GREEN##LIGHT_GREEN#（ジョンを殺して指輪を強化する）「ならば死ね！」", "_t")
t("#LIGHT_GREEN#[bind him to the ring]#WHITE# No, you are more useful alive and broken to me!", "#LIGHT_GREEN#（ジョンを指輪に取り込む）「断る。半端に生かしておいた方が役に立ちそうだからな！」", "_t")
t([[#LIGHT_GREEN#*The malevolent energies around you condensate into the ring, absorbing the last remains of John.
The ring is now much more powerful.*#WHITE#
Aeryn... my love...]], [[#LIGHT_GREEN#　辺りを取り巻く邪な力が指輪に集まり、ジョンの体を吸収した。指輪がさらに強力になる。*#WHITE#
　「エアリン・・・愛しているよ・・・」]], "_t")
t("#LIGHT_GREEN#[done]#WHITE#", "#LIGHT_GREEN#立ち去る#WHITE#", "_t")
t([[#LIGHT_GREEN#*The malevolent energies around you condense into the ring, binding John to it forever.
The ring is now able to summon him for a few turns at will.*#WHITE#
#{bold}#I HATE YOU!#{normal}#]], [[#LIGHT_GREEN#　辺りを取り巻く邪な力が指輪に集まり、ジョンを指輪の中へ永遠に封じ込めた。この指輪で好きな時にジョンを数ターンの間召喚できる。
#{bold}#　「おのれえええええ！」#{normal}#]], "_t")

------------------------------------------------
section "tome-orcs/data/chats/john-worldmap.lua"

t([[#LIGHT_GREEN#*As you approach you recognize Outpost Leader John. But there is a kind of terrible darkness, you can feel his hatred crystallize the air.*#WHITE#
@playername@. You malevolent creature! #{bold}#YOU KILLED HER! YOU MURDEROUS DOG!#{normal}#
You #{italic}#dare#{normal}# carry her ring around like a trophy! I can feel it on you. Give it back! DIE!]], [[#LIGHT_GREEN#　近寄ってみるとその人物は前哨基地の指揮官、ジョンだった。だが辺りを不気味な闇が覆っている。これは彼の憎悪が実体化したものだということが伝わってくる。#WHITE#
　「@playername@。忌まわしい化物！　#{bold}#エアリンの仇だ！　この野良犬めが！#{normal}#　#{italic}#恥知らずめ！　#{normal}#あいつの指輪をこれ見よがしに持ち歩くとは！　貴様の手元にあるのを感じるぞ。返せ！　殺してやる！」]], "_t")
t("Oh you liked that paladin lady? I loved killing her!", "「おっと、あの女はお前のお気に入りだったというわけか？　随分楽しませてもらったよ！」", "_t")
t("She left me no choice; I had to protect #{bold}#my#{normal}# people.", "「あの騎士とは戦う以外に道がなかった。こちらも#{bold}#同胞#{normal}#を守る使命があったんだ」", "_t")
t("Whatever.", "「どうでもいい」", "chat_john-worldmap")
t("What?", "「むっ？」", "_t")
-- old translated text
t("Whatever.", "「どうでもいい」", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kaltor-entry.lua"

t([[#LIGHT_GREEN#*As you open the door to the shop, you are greeted by a pair of Steam Giant guards, staring at you and holding their steamguns tightly, at the ready but not aimed at you.*#WHITE#
No sudden moves, @playername@. Kaltor's orders are to consider you a customer for now. Try anything foolish, and you'll be a live demonstration for his newest guns instead.  Understand?]], [[#LIGHT_GREEN#　カルターの店のドアを開けるとスチームジャイアントの二人組が待ち受けていた。鋭い目でスチームガンを握り締めて身構えているが、銃口は狙いを外している。
　「動くな。カルター氏は『とりあえずは客として扱ってくれ』との仰せだ。妙な真似をすれば最新式スチームガンの実験台になってもらうぞ。いいな？」]], "_t")
t("I have gold, you have equipment. This doesn't need to be any more complicated than that.", "「こちらには金があり、そっちには商品がある。何もややこしいことはないじゃないか」", "_t")
t("Those are some pretty fancy guns. Think it'll be hard to get your blood out of the gears?", "「実に素敵な銃だ。ご自慢のスーツはどこまで頼りになるかな」", "_t")
t([[#LIGHT_GREEN#*She smiles, relieved but also slightly disappointed.*#WHITE#
Couldn't have said it better myself. Come on in - and try not to scare the other patrons.]], [[#LIGHT_GREEN#　女巨人は安堵の笑みを浮かべた、そこには軽い落胆が入り混じっている。
　「完璧な答えだな。入れ。他の客人に無礼を働くなよ」]], "_t")
t("[enter]", "入店", "_t")
t([[Good luck with that, savage.
#LIGHT_GREEN#*She smirks, and pulls a cord on the wall beside her as her and her partner duck behind cover; a loud bell rings, and you hear a commotion from further inside the shop.*#WHITE#]], [[　「せいぜい頑張ってみるんだな、ケダモノめ」
　#LIGHT_GREEN#*女巨人はニヤリと笑うと近場の壁についた紐を引き、相棒共々遮蔽物の影に身を隠した。ベルが大きな音を立て、店の奥が騒がしくなってくる。#WHITE#]], "_t")
t("[fight]", "戦う", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kaltor-shop.lua"

t("Finally a practical giant! Show me your wares.", "「話が通じるジャイアントか！　商品を見せてくれ」", "_t")
t("Die giant scum! For Kruk! For Garkul! For the Pride!", "「死ね！　汚らわしいジャイアントめ！　その命をクルク部族に、ガークルに、オークに捧げるがいい！」", "_t")
t("No need for shopping now.", "「別に用事はない」", "_t")
t([[#LIGHT_GREEN#*A well-dressed giant stands in front of you, covered in expensive jewelry; judging from the poorly-fastened clasp on his necklace, you can assume he acquired it all fairly recently.  He grins as he leans down over the counter to get a good view of you.*#WHITE#
Ah, welcome, @playername@! #LIGHT_GREEN#*he yells in a voice loud enough to catch the attention of all in the shop, as he lifts his head to look around.*#WHITE# Yes, you heard me right, @playername@! The very same one who's been running rampant through the Vaporous Emporium is coming to ME for armaments! I don't think I could've asked for a stronger endorsement! #LIGHT_GREEN#*He looks back down to you, leaning over the counter to point out a glass display case loaded with exotic weaponry and armor.*#WHITE#
Well, I'm not one to turn down anyone with gold, and seeing as you've already made me rich, I'll even give you a discount, down to my pre-attack prices. #LIGHT_GREEN#*He leans in uncomfortably close, staring you in the eyes.* #WHITE#Or, if you came to do here what you did in the Emporium... #LIGHT_GREEN#*He directs his glare toward the multiple well-armed guards staring at you and standing still on the sides of the room.*#WHITE# I'm sure my #{italic}#emergency safety measures#{normal}# would just #{italic}#love#{normal}# an opportunity to try out their shiny new toys.]], [[#LIGHT_GREEN#　豪勢な身なりをしたジャイアントが目の前にいる。値段の張る宝飾品をこれでもかと身に纏っているが、ネックレスがきちんと留まっていないところを見るに、ごく最近入手したものらしい。にんまりと笑い、カウンター越しに身を乗り出してしげしげと見つめてくる。#WHITE#
　「やあ。いらっしゃい。@playername@！」
#LIGHT_GREEN#　巨人が顔を上げて周囲を見回し、大声で呼びかけると店中の視線が２人に集まった。#WHITE#
　「そう、君だよ。@playername@！ 霧の商業区で大暴れしたご本人様がこの私の店に装備を整えに来るという！　最高の宣伝になったよ！」
#LIGHT_GREEN#　店主はこちらに目線を戻すと、前のめりにガラス製の展示ケースを指さした。中には見慣れぬ武器や鎧が入っている。#WHITE#
　「ふむ、代金を払ってくれるなら誰だってお客様だ。君のおかげで随分と儲けさせてもらったからねえ。特別価格で戦前の相場で譲ってあげてもいい」
#LIGHT_GREEN#　ぎょっとするほど間近に顔が迫り、視線が合う。#WHITE#
　「だが商業区での態度がここでもまかり通ると思っているなら・・・」
#LIGHT_GREEN#　店主の視線が完全武装した警備兵の一団に移る。皆、左右の壁際で直立不動の姿勢を取り、こちらを注視していた。#WHITE#
　「きっと『有事の際のために雇った皆さん』は『新品のオモチャを試す良い機会だ！』とばかりに大喜びすることだろうよ」]], "_t")
t([[Welcome back, @playername@!  You see this, customers?  This fearsome, savage master of battle was so impressed by my products that he came back for more!
#LIGHT_GREEN#*He points to a new poster on the wall next to him, showing your face and the caption #{bold}#"KALTOR: THE CHOICE OF DESTROYERS!"#{normal}#*#WHITE#

So, what'll it be?]], [[　「おかえり@playername@！　一同ご覧あれ。最凶の戦鬼が本店の商品をお気に召してリピーターになってくれた！」
#LIGHT_GREEN#　カルターは近場の壁に貼ってある新しいポスターを指さした。そこには自分の顔が描いてあり、見出しがつけられている。
　#{bold}#カルターの店は戦鬼の御用達！#{normal}#*#WHITE#
　「さて、どうするね？」]], "_t")
t([[#LIGHT_GREEN#*Kaltor is busy packing some of his goods away in crates; he hands one to a worker, carrying it out the back door, before turning to you.*#WHITE#
	Make it quick, @playername@. Not to be rude, but there's a private airship out there with my name on it, and I'd rather have a bird's-eye view of what you're about to do than a front-row seat.]], [[#LIGHT_GREEN#　カルターは慌ただしく木箱に商品を詰め込んでいる最中だった。木箱の一つを受け取った店員が裏口から出ていくと、カルターがこちらを振り向く。#WHITE#
　「早いとこ行動に移してくれないか、@playername@。無礼な物言いをしたいわけじゃないんだがね。私の名前を入れた私用エアシップを外に待たせてあるんだ。君が今からすることは最前列に座るよりも高みの見物といきたいものだからねえ」.]], "_t")
t([[#LIGHT_GREEN#*He frowns in mock disappointment, as he presses a button on his stylish coat; it hisses, and you hear motors whirring*#WHITE#
Oh, what a pity.  Guards?  Ten thousand gold to whoever gets the killing blow.  Store credit, of course.]], [[#LIGHT_GREEN#　やれやれとわざとらしく眉を顰めると、カルターはその洒落たコートについているボタンを押した。シューという音が上がり、モーターの回転音が鳴り始める。
　「それは残念。いいか警備員？　首を取った者には１万Ｇ進呈だ。店内貨幣でだよ。当たり前だろ」]], "_t")
t("DEATH!", "「死ね！」", "_t")

------------------------------------------------
section "tome-orcs/data/chats/kruk-tinker-shop.lua"

t("Welcome @playername@ to my shop.", "「ようこそ@playername@」", "_t")
t("Let me see your wares.", "「商品を見せてくれないか」", "_t")
t("I am looking for special training.", "「技術を学びたいんだ」", "_t")
t("Sorry, I have to go!", "「これで失礼します！」", "chat_kruk-tinker-shop")
t("I can indeed offer some training (talent category Steamtech/Physics and Steamtech/Chemistry) for a fee of 100 gold pieces each.", "確かに技術指導はしてやれる。一種類につき１００ゴールド払ってもらうが」（工士／蒸気力学と工士／蒸気化学のカテゴリーです）", "_t")
t("Please train me in physics.", "「蒸気力学を教えてほしい」", "_t")
t("The tinker spends some time with you, teaching you the basics of smithing.", "工士と一緒にしばらく訓練し、鍛冶の基礎を習得した。", "logPlayer")
t("Please train me in chemistry.", "「蒸気化学を教えてほしい」", "_t")
t("The tinker spends some time with you, teaching you the basics of therapeutics.", "工士と一緒にしばらく訓練し、医療の基礎を習得した。", "logPlayer")
t("No thanks.", "「やめておくよ」", "_t")
-- old translated text
t("Sorry, I have to go!", "「これで失礼します！」", "_t")

------------------------------------------------
section "tome-orcs/data/chats/metash.lua"

t([[#LIGHT_GREEN#*Before you stands an impressive undead minotaur.*#WHITE#
I would like to talk to you.]], [[#LIGHT_GREEN#　独特の雰囲気を纏うアンデッドのミノタウロスがいる。#WHITE#
　「どうか話を聞いてくれ」]], "_t")
t("Yes?", "「うん？」", "_t")
t("Your clan is free Metash, the tyrant is no more.", "「白蹄族は自由を取り戻したぞ。圧政者は死んだ」", "_t")
t("Not now.", "「やめておくよ」", "_t")
t("Soft-foot of the Kruk, I come to give you a warning, an apology, and a plea for help.  An incredible magical force has awakened within one of our elders, Nektosh the One-Horned, and he has gone mad with its power.  Those who stood up against him were reduced to less than ashes by a beam from his horn, a beam that tunneled far up through the rock above him until we could see the sky.  He has convinced some of us that he can use this terrible force to conquer Eyal and terrified others into going along with him; he has announced that his first step will be to lead his followers in an attack on Kruk Pride.", "　「柔き蹄のクルク族よ。俺がここへ来たのは警鐘を鳴らし、許しを請うためだ。そして叶うならば力を貸してほしい。我らが長老衆の一人、『一本角のネクトッシュ』にとてつもない魔法の力が宿ったのだ。あの男は力を手にしてから狂ってしまった。反旗を翻した仲間達は奴が角から放った光線で跡形もなく消し炭と化し、その威力たるや洞窟の天井をどこまでも貫いて蒼穹を仰ぐに至った。『この素晴らしき力を以ってイヤルを支配し、まつろわぬ者どもの心胆を寒からしめて平服させん！』との言葉に従った者もいる。そして手始めに信奉者達を引き連れ、クルク部族へ攻め入ると言い放った」", "_t")
t("[listen]", "続きを聞く", "_t")
t("The rest of us have fled, hiding in caverns across the peninsula...  I cannot in good conscience ask you to face certain death before his magic for our sakes, but striking first may be the only way to save your people.  He appears to be stalling the invasion, buying you some time, but if you cannot catch him off-guard before he finally commits to it...  I've seen his power cut through a mountain like it was a leaf, soft-foot.  There can be no victory against that kind of magic.  Run, hide, and hope he falls victim to an accident or loses the remaining fragments of his sanity that keep him capable of casting spells.", "　「生き残った仲間は奴の手を逃れ、半島各地の洞窟に身を潜めた・・・恥を忍んで言う。決死の覚悟で奴の魔法に立ち向かい、我らを救ってくれ。機先を制さねばオークも滅びの道を辿るだろう。ネクトッシュは攻撃を先延ばしにしているようだ。まだ猶予はある。とはいえ隙を突けぬまま侵攻を許すことになれば・・・柔き蹄の者よ、俺は奴が木の葉の如く山を貫くのをこの目で見た。かかる魔術に正面からあたったところで望みはない。一所には留まるな。身を隠し、ネクトッシュが隙をさらす時を狙え。さもなくばあの男が完全に正気を失い、魔法の制御が利かなくなるのを待つのだ。", "_t")
t("I will check it out", "「やってみよう」", "_t")
t("We of the Krimbul Clan have faced our near-certain deaths all too many times, even after our hearts stopped beating; this is the first time we have been shown the kindness of utter salvation by an outsider.  Those who were not enthralled by Nektosh and are not delusionally faithful to his \"cause\" will reclaim the Mana Caves in time; until then, we will join your Pride in your revolution.  You have liberated us, and we will not rest until you are freed of your oppressors as well.", "　「我らクリンブル族は幾度も存亡の危機を味わってきた。この心の臓が動きを止めた後でさえな。だが外の者の力添えで滅亡の危機を脱したのはこれが初めてだ。ネクトッシュの手を逃れた仲間や、奴の『大儀』に内心疑念を抱いていた者たちがいずれ『マナの洞窟』を奪還するだろう。その日が来るまでクリンブル族はクルク族の志に従い戦おう。貴殿は自由を与えてくれた。クルク族が共に迫害の手より解き放たれてこそ、我らにも安寧の時が来るというもの」", "_t")
t("Thanks.", "「ありがたい」", "chat_metash")
t("Hail, @playername@!", "「@playername@！」", "_t")
t("Our is free Metash, the tyrant is no more.", "「クリンブル族はもう自由だ。暴君は消え去った」", "_t")
t([[I came here to warn the Kruk Pride of the threat Nektosh poses and ask for their help, but they have some more immediate threats to deal with...  We should help them repel these Steam Giants.  They are the only people who have ever treated us with respect and dignity; if they are crushed by the Atmos Tribe or the Allied Kingdoms, we will surely be next.  Their success is our survival.

Unfortunately, they cannot afford to spare the warriors to retake the Mana Caves from that tyrant, and I need to stay here to help them defend their land.  The task of freeing our clan is in your hands, when you feel ready for it.]], [[　「俺がここへ来たのはクルク族にネクトッシュの脅威を伝え、助力を仰ぐためだ。だが、クルクの者たちは差し迫った問題を抱えている・・・彼らに手を貸し、スチームジャイアントを撃退せねば。これまで我らを丁重に遇してくれたのはクルク族だけだ。アトモス族や連合王国に敗れることあらば、次なる標的は必ずやクリンブル族となる。クルク族が滅びれば、我らの命脈は保てない。
　残念だがオークたちは戦力に余裕がない。かの暴君よりマナの洞窟を奪還する人員は回せぬのだ。俺もこの地に残り、防衛の一助とならねばならぬ。クリンブル族の自由を賭けた戦いを貴殿に委ねよう。心行くまで準備を重ねてくれ」]], "_t")
t("Nektosh claims he is the invincible, omnipotent descendant of a unicorn, but I don't believe that bull for a second.  While the great magical power that suddenly awakened within him is as fearsome as it is insanity-inducing,  he has yet to use it to make a shield or teleport himself, and even with his all-powerful beam, his aim isn't always perfect...  I think he has a weakness he's trying to hide.  Fight with courage, fellow Whitehoof, and the Krimbul Clan may be free once more!", "　「ネクトッシュは自らを全能無敵なるユニコーンの裔と称しているが全く馬鹿げた話だ。確かに奴は突如として凄まじい魔法の力に目覚めた。目の当たりにした者が恐怖で正気を失いかねないほどのな。だがネクトッシュは未だその力を防護や転移に割いている。とてつもない威力の光線を放つとはいえ、百発百中というわけでもない・・・恐らく奴には弱みがあり、それを見せまいとしているのだろう。白き蹄の同胞よ、勇気をもって戦え。クリンブル族に再び自由を！」", "_t")
t("I will!", "「必ずや！」", "chat_metash")
t([[He...  he found a wand?  And he realized it was running dry, but only after taking over the tribe?  I pity him, but I cannot forgive him for being willing to sacrifice so many Whitehooves and Orcs to escape the consequences of his brief lapse into madness...  still, as a personal request I ask that you not tell others of his last thoughts.  The Nektosh we once knew saved our tribe from the corrupted magic deep under Eyal; he deserves to, at worst, be remembered as one who tragically succumbed to its influence.

Ultimately, though, the choice is yours; it is more important that he is no longer a threat.  There are some who may still cling to the false hope he gave them, but we will retake the Mana Caves from them in time.  We owe you a great debt, and now that we have no more pressing concerns, we can aid Kruk Pride in their rebellion.  Good travels, @playername@.]], [[　「奴は・・・ネクトッシュはワンドを使っていたのか？　しかもクリンブル族を掌握したその直後に、パワーが切れかかっていると悟ったのか？　哀れな。だが奴を許す気にはなれぬ。気の迷いから狂気に走り、その責から逃れんと数多の同族、そしてオーク達を犠牲にするつもりだったのだから。だが、俺としては奴の最後の思惑は貴殿一人の胸にしまっておいて欲しい。俺たちが知る昔のネクトッシュはイヤルの深淵にてクリンブル族を悪しき魔術より救った男。かの力に侵された悲劇の人物として語り継がれるくらいの資格はあるはずだ。
　まあ、それはどの道貴殿次第だ。大事なのはネクトッシュの脅威が除かれたということだからな。あの男が与えた偽りの希望に未だしがみついている者もいるが、マナの洞窟を奪還するのはそう遠い日の話ではなかろう。貴殿には大きな借りができたな。悩みの種は全て摘み取った。我らもクルク族の支援に回れる。@playername@、良き旅を！]], "_t")
t("To you too, Metash.", "「良き旅を、メタッシュ」", "_t")
-- old translated text
t("Thanks.", "「ありがたい」", "_t")
t("I will!", "「必ずや！」", "_t")

------------------------------------------------
section "tome-orcs/data/chats/phonograph.lua"

t("[insert %s]", "%sを入れる", "tformat")
t("#LIGHT_GREEN#*This machine seems to have a slot for some kind of disks.*#WHITE#", "#LIGHT_GREEN#　この機械には円盤のようなものを入れるようだ。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/chats/shertul-priest.lua"

t([[#LIGHT_GREEN#*Before you stands a tentaculous horror which you recognize for what it truly is. A living #{bold}#Sher'Tul#{normal}#!.*#WHITE#
Who are you, young creature, to stand up to a High Priest of Amakthel? Do you not know that you are before a servant of the Almighty Creator, the Sunfather, the God of Gods, Lord of all Eyal? In the millenia I have lived I have killed whole races like yourself. I have even wrenched the spirits of immortal gods from this world. So who are you, little one, who dare defy me?]], [[#LIGHT_GREEN#　目の前にいるのは触手を生やした化物だ。自分はコイツの正体を知っている。実物の#{bold}#シェール・タル#{normal}#！#WHITE#
　「身の程を弁えるがいい、未熟なる生物よ。アマクテルの大祭司に立ち向かうとは。全能なる創造主にして太陽の父、最高神たるイヤルの王。その方の僕を前にしているのだぞ。我は幾千年を過ごし、貴様の如き種族を悉く滅ぼしてきた。不死なる神々の魂すらこの世界より追放したのだ。然るに貴様は何者か、卑小なる者よ。愚かにもこの我に挑むというのか？」]], "_t")
t("I... am %s, of the seed of Garkul the Devourer. Garkul taught us to fight legends, and to flinch not from even the most desperate deed. Here and now I face you without fear or hesitation, for the spirit of Garkul burns within me. And in his name I will #{bold}#break#{normal}# you!", "「我は・・・%s。大食らいガークルの裔なり。大いなる敵に挑み、無謀を常とするのがガークルの教え。今、貴様を前に恐れも惑いもない。ガークルの遺志がこの胸に燃えているからだ。 かの名においてお前を#{bold}#討つ#{normal}#！」", "tformat")
t("I... am %s, though I lack my original body my mind is bound to Garkul the Devourer. Garkul taught us to fight legends, and to flinch not from even the most desperate deed. Here and now I face you without fear or hesitation, for the spirit of Garkul burns within me. And in his name I will #{bold}#break#{normal}# you!", "「我は・・・%s。元の体は捨てたがこの魂は大食らいガークルに連なる者。大いなる敵に挑み、無謀を常とするのがガークルの教え。今、貴様を前に恐れも惑いもない。ガークルの遺志がこの胸に燃えているからだ。 かの名においてお前を#{bold}#討つ#{normal}#！」", "tformat")
t("I... am %s and I am not mortal! Garkul taught the orcs to fight legends, and to flinch not from even the most desperate deed. We learned that from them! Here and now I face you without fear or hesitation, for cold touch of undeath is within me. And I will #{bold}#break#{normal}# you!", "「我は・・・%s。常命の者に非ず。ガークルはかつてオーク達に告げた。『大いなる敵に挑み、無謀を常とせよ』と。我らはオークよりその教えを学んだのだ！　今、貴様を前に恐れも惑いもない。胸に宿るは冷たき死の感触。お前を#{bold}#討つ#{normal}#！」", "tformat")
t("I... am %s. Here and now I face you without fear or hesitation, for the utter determination burns within me. And I will #{bold}#break#{normal}# you!", "「我は・・・%s。今、貴様を前に恐れも惑いもない。不屈の意志が胸の内で燃えているからだ。お前を#{bold}#討つ#{normal}#！」", "tformat")

------------------------------------------------
section "tome-orcs/data/chats/weissi-machine.lua"

t([[#LIGHT_GREEN#*Before you is an extremely old looking machine. It seems to be infused with some sort of psionic energy; impossible as this sounds.
And it #{bold}#speaks#{normal}# to you!*#WHITE#
Welcome @playername@. We have been waiting for you.]], [[#LIGHT_GREEN#　機械がある。遥か古代の物のようだ。信じがたいことに、ある種の超能力を帯びているらしい。そしてその機械は#{bold}#話しかけてきた#{normal}#！#WHITE#
　「ようこそ@playername@。待っていたよ」]], "_t")
t("What are you?", "「何者だ？」", "_t")
t("Waiting for me?", "「待っていた？」", "_t")
t("What do you need me for?", "「何が目的だ？」", "_t")
t("I have muscle tissue for you.", "「筋組織を持ってきたぞ」", "_t")
t("[leave]", "放っておく", "_t")
t("#LIGHT_GREEN#*You feel a powerful presence in your mind.*#WHITE#", "#LIGHT_GREEN#　頭の中を強大な存在感が満たした。#WHITE#", "_t")
t("I see...", "「なるほど・・・」", "_t")
t("Yes. We predict you will be useful to us. If you are not, another will be.", "　「そうだ。お前は我々のために働いてくれる。でなければ他の誰かが」", "_t")
t([[We require recent yeti muscle tissue from powerful specimens. You will help us, or you will not. Either way they will come to us.
If you do so we shall reward you with petty knowledge so that you may postpone your death.]], "　「我々は新鮮なイエティの筋組織を集めている。強力な個体の筋組織を。お前は協力するはずだ。しないかもしれない。どちらにしろ我らの下に集まるのだが。やってくれるなら見返りにちょっとした技術を教えてやろう。学んでおけば九死に一生を得ることもあるだろうな」", "_t")
t("That is... generous of you.", "「それは・・・どうも御親切に」", "_t")
t("Talent categories", "タレントツリー", "_t")
t("Talents", "タレント", "_t")
t("Improved core stats", "基本能力値上昇", "_t")
t([[#LIGHT_GREEN#*The muscle tissue suddenly vanishes from your inventory.*#WHITE#
Thank you @playername@, this is indeed a suitable specimen. We shall honor our bargain with you. What do you wish to learn?]], [[#LIGHT_GREEN#　筋組織がフッと道具袋から消え去った。
　「礼を言うぞ、@playername@。では、約束を果たさねばな。何を学びたいのだ？」]], "_t")
t("What do you wish to learn?", "何を学びますか？", "_t")
t("You cannot use your %s anymore; it is tainted by magic.", "もう %s は使えない。魔法の力を宿している。", "logPlayer")
t([[Antimagic is a very special category. If you learn it you will never be able to use arcane powered items or talents again.
Do you still wish to take this path?]], "　反魔法は極めて特殊なタレントです。習得すると魔法の力を宿したアイテムやタレントは今後使用できなくなります。本当に習得しますか？", "_t")
t("No.", "やめる", "_t")
t("Yes!", "習得！", "_t")
t("Select the party member to receive the reward:", "パーティーメンバーを選択してそちらに適用する", "_t")
t("Very well. We can teach you a talent category; which do you want?", "　「結構。教えてやろう。どれにするのだ？」", "_t")
t("Physical techniques", "肉体系技能", "_t")
t("Arcane spells", "魔法系技能", "_t")
t("Nature/Psionic talents", "自然・超能力技能", "_t")
t("Hum no let me change my mind.", "「ふむ、気が変わった」", "_t")
t("[Allow training of talent category %s (at mastery %0.2f)]", "%sを習得する (補正値は %0.2f)]", "tformat")
t("Very well. We can teach you a talent.  Which do you want?", "　「結構。教えてやろう。どれにするのだ？」", "_t")
t("Very well. We can teach you a talent; which type do you want?", "　「結構。教えてやろう。どれにするのだ？」", "_t")
t("[%s talent %s (+%d level(s))]", "%s %s (+%d レベル)]", "tformat")
t("Improve", "増加", "_t")
t("Learn", "習得", "_t")
t([[Antimagic talents are very special. To learn one means you will never be able to use arcane powered items or talents again.
Do you still wish to take this path?]], "　反魔法は極めて特殊なタレントです。習得すると魔法の力を宿したアイテムやタレントは今後使用できなくなります。本当に習得しますか？?", "_t")
t("Very well. We can teach you a talent (unlocking the talent category is separate). Which do you want?", "　「結構。教えてやろう。どれにするのだ？」（ツリーのアンロックは自分でする必要があります）", "_t")
t("[Improve %s by +%d]", "%s が %d上昇]", "tformat")
t("Very well. We can increase one of your core stats by 4, which one?", "　「結構。４点上げてやろう。どの能力にするのだ？」", "_t")

