section "tome-orcs/data/general/npcs/domestic-yeti.lua"

t("giant", "ジャイアント", "entity type")
t("yeti", "イエティ", "entity subtype")
t("pet yeti", "ペットイエティ", "entity name")
t("This yeti is somewhat smaller than the average yeti, and its fur seems well groomed. Nonetheless, it looks quite unhappy to see its master's home invaded.", "　普通のイエティよりも小さめで毛皮には手入れが行き届いている。とはいえ主人の家が攻撃されている現状に甚く機嫌を損ねているようだ。", "_t")
t("guard yeti", "イエティガード", "entity name")
t("This yeti is large and angry, with claws far more sharply honed than those found in nature.", "　怒り狂った巨大イエティだ。野生の個体に比べて爪が研ぎ澄まされている。", "_t")
t("attack yeti", "イエティソルジャー", "entity name")
t("This yeti's claws are coated in sharply carved iron. It glares at you with a long trained anger.", "　このイエティの鉤爪は鋭く削り上げた鋼鉄で覆ってある。こちらを睨む瞳には長年の調教で植え付けられた怒りが宿っている。", "_t")

