section "tome-orcs/data/general/npcs/hethugoroth.lua"

t("elemental", "エレメンタル", "entity type")
t("vapour", "蒸気", "entity subtype")
t("hethugoroth", "ヘスゴロス", "entity name")
t("A swirling mass of hot vapour animated into a semblance of life.", "　渦巻く高温の蒸気だ。仮初の命を与えられている。", "_t")
t("greater hethugoroth", "巨大ヘスゴロス", "entity name")
t("ultimate hethugoroth", "最上位ヘスゴロス", "entity name")

------------------------------------------------
section "tome-orcs/data/general/npcs/horror.lua"

t("saw horror", "スチームソー・ホラー", "entity name")
t("Oh. Oh no. Where did it get those?", "　おいおいおいおい。コイツどこでアレをせしめたんだ？", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/plant-add.lua"

t("Sawtree", "ソーツリー", "entity name")
t([[#{italic}##ANTIQUE_WHITE#Is that... a tree that cuts down trees?
Oh no don't worry. Only adventurers!#LAST##{normal}#]], [[#{italic}##ANTIQUE_WHITE#これは・・・樹が木を切り倒している・・・！？
ああ、大丈夫。切り倒すのは冒険者だけさ！#LAST##{normal}#]], "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/ritch-extended.lua"

t("insect", "昆虫", "entity type")
t("ritch", "リッチ虫", "entity subtype")
t([[Ritches are giant insects native to the arid wastes of the southern parts of the Far East.
Vicious predators, they inject corrupting diseases into their foes, and their sharp claws cut through most armours.]], "　リッチ虫は東方世界南部の不毛の地に生息する巨大昆虫だ。凶悪なハンターであり、獲物を病原体で侵しては鋭い爪でどんな鎧も易々と切り裂く。", "_t")
t("ritch larva", "リッチ幼虫", "entity name")
t("ritch hunter", "ハンター・リッチ虫", "entity name")
t("ritch hive mother", "マザー・リッチ虫", "entity name")
t("ritch centipede", "ムカデリッチ虫", "entity name")
t("This strange creature looks like a ritch hunter but with more legs. So many legs.", "　ハンター・リッチ虫に似ているが足が多い。それはもう沢山。", "_t")
t("larvae bloated ritch mother", "産卵マザーリッチ虫", "entity name")
t("The skin of this creature is literally crawling with larvae, yet she seems to be moving toward you very fast.", "　このリッチ虫の体表には無数の幼虫が蠢いている。にもかかわらず、目にも止まらぬ速さで向かってくるのだ。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/snake-add.lua"

t("Gunsnake", "ガンスネーク", "entity name")
t("#{italic}##ANTIQUE_WHITE#From a bygone era it slithers...#LAST##{normal}#", "#{italic}##ANTIQUE_WHITE#　今は過ぎ去りし日の生き残りだ・・・#LAST##{normal}#", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-drone.lua"

t("mechanical", "マシン", "entity type")
t("drone", "ドローン", "entity subtype")
t("steam drone", "蒸気機関ドローン", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. A huge clonking spider that runs to you at great speed ready to cut you to pieces with its two rotating saws in place of mandibles.", "　八本足の機械生物だ。蜘蛛に見えないこともない。大地を踏み鳴らす巨大な蜘蛛だ。こちらを細切れにせんと高速接近するその顎には牙の代わりにスチームソーの歯が一組備わっている。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-giant-arcane.lua"

t("giant", "ジャイアント", "entity type")
t("steam", "蒸気", "entity subtype")
t("necropsych's ghost", "サイキック・ゴースト", "entity name")
t("undead", "不死者", "entity type")
t("ghost", "ゴースト", "entity subtype")
t("The spirit of a recently deceased necropsych. It moans painfully but seems impervious to most worldly things.", "　先ほど死亡したネクロサイキックだ。苦痛に呻いているが、外部からの干渉をほとんど受けないようだ。", "_t")
t("steam giant necropsych", "ネクロサイキック", "entity name")
t("Covered in arcane runes of death, this steam giant means business.", "　死のルーンで全身を覆ったスチームジャイアントだ。本気でこちらの命を狙っている。", "_t")
t("#LIGHT_DARK#As %s falls you see its spirit rising for revenge.", "#LIGHT_DARK#%sが斃れるとその魂は復讐に燃える亡霊と化した。", "logSeen")
t("steam giant blood carver", "ブラッディ", "entity name")
t("Blood seems to ooze from the towering giant, yet seemingly to no ill effect.", "　この巨体のスチームジャイアントからは血潮が溢れ出ている。有害な効果を発揮するのはこれからのようだ。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-giant-gunner.lua"

t("giant", "ジャイアント", "entity type")
t("steam", "蒸気", "entity subtype")
t("steam giant gunner", "ジャイアント・ガンマン", "entity name")
t("This steam giant is carrying a powerful looking gun.", "　いかにも破壊力のありそうな銃を構えたスチームジャイアントだ。", "_t")
t("steam giant gunslinger", "ジャイアント・ガンナー", "entity name")
t("This steam giant carries a steamgun in each hand.", "　二丁拳銃を構えたスチームジャイアントだ。", "_t")
t("steam giant flameshot", "フレイムシューター", "entity name")
t("This steam giant carries a steamgun in each hand. The barrels appear to be flaming.", "　二丁拳銃を構えたスチームジャイアントだ。銃口からは火を噴くようだ。", "_t")
t("retaliator of Atmos", "アトモス・リベンジャー", "entity name")
t("This steam giant carries a steamgun in each hand. She is here to eliminate any and all aggression towards the Atmos tribe.", "　二丁拳銃を構えたスチームジャイアントだ。アトモス族に仇成す輩を抹殺するのが使命である。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-giant-warrior.lua"

t("giant", "ジャイアント", "entity type")
t("steam", "蒸気", "entity subtype")
t("steam giant guard", "ジャイアントガード", "entity name")
t("This titanic figure walks towards you, a massive sword and shield in each hand.", "　重厚な剣と盾を構えて巨体が歩み寄ってくる。", "_t")
t("steam giant berserker", "ジャイアントバーサーカー", "entity name")
t("This steam giant carries a massive greatsword with both hands, and you see a cloud of thick steam enveloping the blade.", "　両手で大剣を構えたスチームジャイアントだ。刃の周りには蒸気がモクモクと立ち込めている。", "_t")
t("steam giant yeti rider", "イエティライダー", "entity name")
t("Riding atop a massive armored yeti, this steam giant wields a huge greatsword.", "　重装備イエティに騎乗したスチームジャイアントだ。特大の両手剣を構えている。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/steam-spiders.lua"

t("mechanical", "マシン", "entity type")
t("arachnid", "スパイダー", "entity subtype")
t("mecharachnid warrior", "マシンスパイダー", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. A huge clonking spider that runs to you at great speed ready to cut you to pieces with its two rotating saws in place of mandibles.", "　八本足の機械生物だ。蜘蛛に見えないこともない。大地を踏み鳴らす巨大な蜘蛛だ。こちらを細切れにせんと高速接近するその顎には牙の代わりにスチームソーの歯が一組備わっている。", "_t")
t("mecharachnid flame thrower", "フレイム・スパイダー", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. The huge flame thrower mounted on its back however is definitively un-spider-like.", "　八本足の機械生物だ。蜘蛛に見えないこともない。背中に装着した火炎弾発射装置はどうみても蜘蛛に似つかわしいものではないが。", "_t")
t("mecharachnid destroyer", "デストロイ・スパイダー", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. An armed to the teeth, well, mandibles, spider.", "　八本足の機械生物だ。蜘蛛に見えないこともない。全身武装した蜘蛛である。全身と言っても蜘蛛だから胸はないのだが。", "_t")
t("mecharachnid repairbot", "リペアマシン・スパイダー", "entity name")
t("This eight legged mechanical construct looks suspiciously like a spider. It seems to be more concerned by its fellow arachnids than by you.", "　八本足の機械生物だ。蜘蛛に見えないこともない。こちらよりも仲間の機械蜘蛛に集中している。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/sunwall-mage.lua"

t("humanoid", "人型", "entity type")
t("elf", "エルフ", "entity subtype")
t("sun-mage recruit", "照陽術師・新兵", "entity name")
t("A mage dressed in glowing robes.", "　輝くローブを纏った魔法使いだ。", "_t")
t("sun-mage", "照陽術師", "entity name")
t("A mage dressed in shining robes.", "　煌くローブを纏った魔法使いだ。", "_t")
t("anorithil", "アノーリシル", "entity name")
t("A mage dressed in ornate robes depicting both light and darkness.", "　光と闇の双方を象徴する煌びやかなローブを纏った魔法使いだ。", "_t")
t("astral conjurer", "星術師", "entity name")
t("human", "人間", "entity subtype")
t("elven astromancer", "エルフの星界師", "entity name")
t("A mage who has studied all there is to know about the stars and their working.", "　星々とその働きに関する知識を極めた魔法使いだ。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/sunwall-warrior.lua"

t("humanoid", "人型", "entity type")
t("human", "人間", "entity subtype")
t("sunwall guard", "太陽の番兵", "entity name")
t("This guard stands tall and proud, wearing the symbol of the Sunwall.", "　威風堂々とした戦士である。「太陽の壁」の紋章を身に着けている。", "_t")
t("sunwall archer", "太陽の弓兵", "entity name")
t("elf", "エルフ", "entity subtype")
t("You see an archer with his bow drawn back, and a golden sun embossed on his armor.", "　弓を引き絞った弓兵だ。鎧には黄金色の太陽が彫金してある。", "_t")
t("sun paladin recruit", "新米騎士", "entity name")
t("The shield of this soldier glows with a bright light. You see a golden sun engraved in its center, and he carries a sword in his other hand.", "　輝く盾を構えた戦士だ。その中心には黄金色の太陽が彫金してある。もう片方の手には剣を携えている。", "_t")
t("sun paladin", "太陽の騎士", "entity name")
t("The shield and sword of this soldier glow with a bright light. You see a golden sun engraved in the shield's center.", "　輝く剣と盾を構えた戦士だ。盾の中心には黄金色の太陽が彫金してある。", "_t")
t("sunwall vindicator", "光の審判者", "entity name")
t("This mean looking soldier of the Sunwall holds steady his big two handed weapon, looking dangerously at you.", "　厳めしい顔つきをした、太陽の戦士だ。両手武器を握りしめており、その目は敵意に満ちている。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/titan.lua"

t("giant", "ジャイアント", "entity type")
t("titan", "タイタン", "entity subtype")
t("titan battlesmasher", "スマッシャータイタン", "entity name")
t("This creature looks like one of the steam giants, but nastier, bigger and somehow corrupted by unknown forces. Oh and it is wielding a huge maul too!", "　スチームジャイアントに似ているが醜悪でさらに巨大、それに正体不明の力に侵されているようだ。おっと、戦槌を構えていることも付け加えておこう！", "_t")
t("titanic horror", "ホラータイタン", "entity name")
t("While a titan usually look like a corrupted steam giant, this one looks more like a giant-sized horrific mass of living flesh.", "　タイタンは通常、邪悪な力に侵されたスチームジャイアントといった外見をしている。しかしこいつはむしろおぞましい巨大な肉塊といった風だ。", "_t")
t("titan searing seer", "ヘルサイキック", "entity name")
t("Wreathed in arcane flames you can feel the intense psionic forces ripping at your mind emanating from this titan.", "　魔法の炎を纏うタイタンだ。強力な理力を発してこちらの精神を破壊してくる。", "_t")
t("titan vile spewer", "パンデミック・タイタン", "entity name")
t("The wretched titan's skin is of a sickly green, full of ever-oozing wounds, cracks and pustules. Worms and all kind of vile things crawl over it.", "　見るも無残な姿のタイタンだ。肌はどんよりとした緑色で、全身が傷やヒビ、疱瘡に覆われており、そこから体液がとめどなく滲み出ている。蟲やありとあらゆる不浄が体表を埋め尽くしている。", "_t")
t("titan dreadnought", "ドレッドノート", "entity name")
t("One of the biggest titans you have seen yet, it is fully clad in deep black stralite full plate, charging menacingly towards you at a terrible pace.", "　これまでに見たタイタンの中でも一際の巨体だ。だが漆黒のストラライトでできたプレートアーマーで身を固め、敵意を露わにどんどん間合いを詰めてくる。", "_t")
t("sher'tan", "シェール・タン", "entity name")
t("This abomination has the height of any other titan but its features definitively remind you of the few Sher'Tul images you have seen. Your very being rebels to the thought and sheer terror takes hold of your mind.", "　この化け物はサイズこそ他のタイタンと変わらない。だが、姿形はこれまでに幾度か見たシェール・タルの外観を彷彿とさせる。その思いに本能が警鐘を鳴らし、血の凍るような恐怖に体が震えた。", "_t")
t("gargantuan sher'tan", "ガルガンチュア", "entity name")
t("This abomination has the height of any other titan but its feature definitively remind you of the few Sher'Tul images you have seen. Your very being rebels to the thought and sheer terror takes hold of your mind.", "　この化け物はサイズこそ他のタイタンと変わらない。だが、姿形はこれまでに幾度か見たシェール・タルの外観を彷彿とさせる。その思いに本能が警鐘を鳴らし、血の凍るような恐怖に体が震えた。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/troll-pirates.lua"

t("giant", "ジャイアント", "entity type")
t("troll", "トロル", "entity subtype")
t("troll pirate", "海賊トロル", "entity name")
t("This is a Troll pirate.", "　トロルの海賊だ。", "_t")
t("troll marauder", "殺手トロル", "entity name")
t("This lean but muscular troll deftly wields two daggers. He glares at you with eyes filled with cunning.", "　細身だが筋肉質のトロルだ。二本のダガーを巧みに操る。こちらを注視するその視線はいかにも狡賢そうだ。", "_t")
t("troll captain", "トロルキャプテン", "entity name")
t("This troll is barking orders to the other trolls around him. He effortlessly holds a longsword in each hand.", "　周囲のトロルに激を飛ばし、二本の長剣を軽々と振るっている。", "_t")
t("troll guard", "トロルガード", "entity name")
t("This troll carries a large sword and shield, and appears to be wearing segments of armor.", "　大きな剣と盾を携えている。身に纏っているのは鎧の断片らしい。", "_t")
t("troll aquamancer", "水術師トロル", "entity name")
t("This troll is holding a tall staff in one hand. Tendrils of water circle around it.", "　片手に長い杖を携えたトロルだ。周囲には水流がいくつも旋回している。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/undead-drake.lua"

t("undead", "不死者", "entity type")
t("dragon", "ドラゴン", "entity subtype")
t("undead drake hatchling", "アンデッドベビードラゴン", "entity name")
t("A skeletal drake hatchling; not too powerful by itself, but if it's anything like living ones, it's probably not alone.", "　ベビードラゴンのスケルトンだ。これ自体は大して強くはない。だが、生きている方の奴らと同じなら集団で出てくるだろう。", "_t")
t("undead drake", "アンデッドドラゴン", "entity name")
t("A skeletal drake, armed with a deadly breath weapon and nasty claws.", "　ドラゴンのスケルトンだ。強烈なブレスと鋭い鉤爪を備えている。", "_t")
t("undead wyrm", "アンデッドワイアーム", "entity name")
t("The skeleton of a long-lived wyrm, armed with a deadly breath weapon and nasty claws.", "　古竜のスケルトンだ。強烈なブレスと鋭い鉤爪を備えている。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/whitehooves.lua"

t("undead", "不死者", "entity type")
t("minotaur", "ミノタウロス", "entity subtype")
t("whitehoof ghoul", "白蹄族のグール", "entity name")
t("It is a cross between a human and a bull, but more ... dead.", "　牛と人間の合いの子だ。そして・・・命を宿していない。", "_t")
t("whitehoof maulotaur", "白蹄族のマウロタウロス", "entity name")
t("This big undead minotaur is carrying a nasty looking hammer, imbued with lightning.", "　巨躯のアンデッドミノタウロスだ。雷を纏う凶悪な戦槌を携えている。", "_t")
t("whitehoof invoker", "白蹄族の死霊使い", "entity name")
t("Vortexes of sickly arcane energies circle this great undead frame.", "　この巨躯の不死者の周囲には邪悪な魔力が渦を成している。", "_t")
t("whitehoof hailstorm", "白蹄族の雹嵐術師", "entity name")
t("The air seems to freeze and wither around this terrible undead.", "　この恐るべき不死者の周囲では大気が凍てついてしまうようだ。", "_t")

------------------------------------------------
section "tome-orcs/data/general/npcs/yeti.lua"

t("giant", "ジャイアント", "entity type")
t("yeti", "イエティ", "entity subtype")
t("yeti cub", "ベビーイエティ", "entity name")
t("This humanoid form is coated with a thick white fur.", "　白く分厚い毛皮に覆われた人型生物だ。", "_t")
t("yeti", "イエティ", "entity name")
t("This large humanoid form is coated with a thick white fur.", "　白く分厚い毛皮に覆われた巨躯の人型生物だ。", "_t")
t("yeti warrior", "イエティの戦士", "entity name")
t("This huge humanoid form is coated with a thick white fur, with large, vicious claws. It looks angry.", "　白く分厚い毛皮に覆われた巨大な人型生物だ。大きな鋭い鉤爪が生えている。", "_t")
t("yeti demolisher", "イエティ・グラップラー", "entity name")
t("This huge humanoid form is coated with a thick white fur, with large, vicious claws. Will you welcome the embrace of its large muscular arms?", "　白く分厚い毛皮に覆われた巨大な人型生物だ。大きな鋭い鉤爪が生えている。君を抱きしめるこの太い両腕に身を委ねてみてはくれないか？", "_t")

------------------------------------------------
section "tome-orcs/data/general/objects/boss-artifacts.lua"

t("Yeti-fur Cloak", "★イエティの毛皮クローク", "entity name")
t("matted fur cloak", "艶消し済みの毛皮", "_t")
t("This fur cloak is thick and matted, yet remains incredibly soft to the touch.", "毛皮のクロークだ。分厚くて、もじゃもじゃとしている。それでいて驚くほど柔らかい。", "_t")
t("Korbek's Spyglass", "★コーベクの望遠鏡", "entity name")
t("golden telescope", "黄金の望遠鏡", "_t")
t("This antique spyglass is weathered from use, but seems well maintained.", "アンティークの小型望遠鏡だ。使い込んで色あせているが、手入れは欠かしていないようだ。", "_t")
t("Talosis' Counterpoint", "★タロシスの反論", "entity name")
t("ornate gun", "豪華な銃", "_t")
t("It's said that Talosis never lost an argument. Now you know why.", "タロシスは口喧嘩に負けたことがなかったという。今その理由が解った。", "_t")
t("The Twisted Blade", "★アビスブレード", "entity name")
t("vile, twisted steamsaw", "不浄なるスチームソー", "_t")
t("You see flecks of gold in this vile mass of twisted steel, implying a once great origin. Whatever glory it once had is long gone, replaced by something far more sinister...", "吐き気を催す邪悪な鉄の塊だ。所々に黄金色の輝きを放っており、元は大いなるアーティファクトであったことが偲ばれる。その煌めきはとうの昔に失われて久しく、代わりに背筋が凍ような何かが宿っている・・・", "_t")
t("Fully heal yourself. (15 turn cooldown)", "自身のＨＰが完全回復（クールダウン１５ターン）", "_t")
t("Sunstone", "★太陽石", "entity name")
t("warm stone", "暖かな石", "_t")
t("This strange stone shines with the heat of the Sun. Perhaps it could be used to generate more steam?", "不思議な輝く石だ。太陽の熱を宿している。これを利用して蒸気を生み出せるかもしれない？", "_t")
t("Overseer", "★監査の瞳", "entity name")
t("cracked mindstar", "ひび割れたマインドスター", "_t")
t("Fragments of the Mindwall's power still inhabit this cracked, ancient gem.", "マインドウォールの力の一部がこのひび割れた古い宝石に残留している。", "_t")
t("reduces mental save", "精神セーブ低下。", "_t")
t("either mentally dominate or psychically stun (depending on immunities) a nearby target within range %d for %d turns (success depends on Mindpower)", "半径%d以内の敵１体を精神支配、または超能力でスタンさせる（耐性に依存）持続時間は%dターン（成功率は精神パワーに依存）", "tformat")
t("#Source# psychically dominates #target# through %s %s!", "#Source#は%s %sで#target#を精神支配した！", "logCombat")
t("Ureslak's Focus", "★ウレスラックの精髄", "entity name")
t("multi-hued", "七色の宝石", "entity subtype")
