section "tome-orcs/data/general/objects/quest-artifacts.lua"

t("tinker", "工士", "entity type")
t("power", "パワー", "entity subtype")
t("Automated Portable Extractor", "工士用自動変換機", "entity name")
t([[The APE is a multifunction tinker toolbox. It can store temporarily any amount of items and when requested melt them down using metallurgic and chemical processes.
The metals are melted into lumps of ore to server for the creation of tinkers.
Any remains are melted and turned into valuable materials.]], [[　多様な機能を備えた工士のツールボックスだ。一時的にアイテムを幾らでも保管しておける。また、好きな時に冶金・化学的プロセスを経て保管したアイテムを分解できる。
　金属から成るアイテムは溶解して鉱石塊にし、工士アイテムの原料に使用できる。
　その他のアイテムも全て溶解し価値ある物質に変換する。]], "_t")
t("melt all the items in the APE at once (also done automatically when you change level)", "　中身のアイテムを全部変換する（別の階に移動する際、これは自動的に実行されます）", "_t")
t("APE", "工士用変換機", "_t")
t("Make the Automated Portable Extractor the default item's destroyer?", "　工士用の変換器をデフォルトのアイテム変換器として使いますか？", "_t")
t("You do not have any items to melt in your APE or on the floor.", "　足元にアイテムがない。", "_t")
t("Melt all %d item(s) on the floor?", "　足元のアイテム %d 個を変換しますか？", "tformat")
t("Melt all %d item(s) in your APE?", "　全 %d 個のアイテムを変換しますか？", "tformat")
t("You cannot bring yourself to drop the %s", "%sは捨てられない。", "logPlayer")

