t("Steam Powered Armour", "★スチームパワードアーマー", "entity name")
t("Using small steam engines and the miracles of the latest automation discoveries you are able to create Steam Powered Armour. A full plate armour that helps your movement and has intrinsic protection mechanisms.", "小型の蒸気エンジンと最新式の驚くべき自動化技術により、スチームパワードアーマーを作れるようになりました。動きの補助をするフルプレートアーマーで、高度な防御機構を備えています。", "_t")
t("The more steam the better!", "蒸気を集めよう！", "_t")
t("#GOLD#Your steam-powered boots, helm and gauntlets automatically connect to your steam-powered armour, enabling new functions.", "#GOLD#スチームパワードブーツ、ヘルム、ガントレットがひとりでにパワードスーツと繋がって、新機能が起動した。", "logSeen")
t("#GOLD#Your steam-powered armor disconnects from the other pieces.", "#GOLD#　パワードアーマーの部品が外れた。", "logPlayer")
t("%s saw projector", "%sソーシューター", "tformat")
t("%s kinetic stabiliser", "%sスタビライザー", "tformat")

