t("voratun", "ヴォラタン製", "_t")
t("crude", "初心者作の", "_t")
t("good", "中級者作の", "_t")
t("well-made", "上級者作の", "_t")
t("mastercraft", "名人作の", "_t")
t("perfect", "完璧な", "_t")
t("HEAD", "頭部用", "entity on slot")
t("%s focus lens", "%sフォーカスレンズ", "tformat")
t("HANDS", "小手用", "entity on slot")
t("%s toxic cannister launcher", "%sポイズンスモッグランチャー", "tformat")
t("%s viral needlegun", "%sウイルスニードル", "tformat")
t("%s razor edge", "%sレイザーエッジ", "tformat")
t("BODY", "体防具用", "entity on slot")
t("%s armour reinforcement", "%sアーマーブースター", "tformat")
t("%s crystal edge", "%sクリスタルエッジ", "tformat")
t("Deals high light damage and increases critical multiplier.", "光属性の高ダメージを与え、クリティカル倍率が増加します。", "_t")
t("flashes light on your target dealing %d damage", "対象を照らし %d ダメージを与えます。", "tformat")
t("%s crystal plating", "%sクリスタルプレート", "tformat")
t("armor", "防具", "entity type")
t("hands", "グローブ", "entity subtype")
t("Hands of Creation", "★烈火の手甲", "entity name")
t("plated gauntlets", "プレートガントレット", "_t")
t("From your hands have been wrought incredible works. Your works have been forged in fire, and so have you.", "あなたの手によって数々の素晴らしい作品が生み出されてきました。それらは炎の中で鍛え上げられたものです。作者もまた然り。", "_t")
t("On landing any melee attack, release a fiery shockwave, dealing fire and physical damage each equal to your steampower in a cone from the target of radius 3.", "攻撃が命中する毎に炎の衝撃波を放ちます。これは蒸気パワーに等しい物理属性と火炎属性ダメージを、攻撃対象を中心として半径３マスの扇状範囲に与えます。", "_t")
t("%s spike attachment", "%sスパイクオプション", "tformat")
t("%s silver filigree", "%sシルバーフィルグリー", "tformat")
t("BELT", "ベルト用", "entity on slot")
t("%s back support", "%sリフトサポート", "tformat")
t("CLOAK", "クローク用", "entity on slot")
t("%s grounding strap", "%sアースストラップ", "tformat")

