section "tome-orcs/data/general/objects/tinkers/therapeutics.lua"

t("simple", "低級", "_t")
t("potent", "中級", "_t")
t("powerful", "上級", "_t")
t("great", "高級", "_t")
t("amazing", "最高級", "_t")
t("%s healing salve", "%s治癒軟膏", "tformat")
t("heal %d", "回復 %d", "_t")
t("%s pain suppressor salve", "%sの痛覚抑制軟膏", "tformat")
t("let you fight up to -%%d life and reduces all damage by %d%%%% for %d turns (takes no time to activate)", "ＨＰの下限が %%d 増加します。また、被ダメージが %d%%%% 低下します。持続時間は%dターンです。使用にターンを消費しません。", "tformat")
t("%s frost salve", "%s冷気軟膏", "tformat")
t("remove %d physical effects and grants a frost aura (%s cold, darkness and nature affinity)", "物理系のデバフを %d 種解除し、冷気のオーラを得ます（冷気、暗黒、自然の属性吸収 %s ）", "tformat")
t("%s fiery salve", "%sの火炎軟膏", "tformat")
t("remove %d magical effects and grants a fiery aura (%s fire, light and lightning affinity)", "魔法系のデバフを %d 種解除し、火炎のオーラを得ます（火炎、光、電撃の属性吸収 %s ）", "tformat")
t("%s water salve", "%sの静水軟膏", "tformat")
t("remove %d mental effects and grants a water aura (%s blight, mind and acid affinity).", "精神系のデバフを %d 種解除し、水のオーラを得ます（腐敗、精神、酸の属性吸収 %s ）", "tformat")
t("%s unstoppable force salve", "%sの限界突破軟膏", "tformat")
t("increases all saves by %d and healing factor by half", "各種セーブが %d 上昇し、ＨＰ回復倍率が５０％上昇する。", "_t")
t("armor", "防具", "entity type")
t("light", "軽鎧", "entity subtype")
t("Life Support Suit", "★生命維持スーツ", "entity name")
t("advanced medical armour", "高機能医療スーツ", "_t")
t("\"We've done it, men. We cured death.\"", "「やったぞ。ついに死を克服した」", "_t")
t([[You cannot bleed.
When you take damage, if your life is under 20%%, heal for 30%% of your max life. %s]], "出血状態になりません。ダメージを受けた際にＨＰが２０％未満になると、最大値の３０％分回復します。%s", "tformat")
t("(%d turns until ready)", "（あと %d ターン待ち）", "tformat")
t("(15 turn cooldown)", "（クールダウン１５ターン）", "_t")
t("BODY", "体防具用", "entity on slot")
t("%s second skin", "%s人工皮膚", "tformat")
t("HEAD", "頭部用", "entity on slot")
t("%s air recycler", "%sエアリサイクル", "tformat")
t("Returns %d air each turn.", "毎ターン空気が %d 戻ってくる。", "tformat")
t("FEET", "ブーツ用", "entity on slot")
t("%s moss tread", "%sフォレストウォーカー", "tformat")
t("BELT", "ベルト用", "entity on slot")
t("%s fungal web", "%s真菌ウェブ", "tformat")
t("Heals you for %d life when you use a salve.", "軟膏使用時にＨＰが %d 回復します。", "tformat")

