section "tome-orcs/data/general/objects/world-artifacts.lua"

t("Medical Urgency Vest", "★救急医療ベスト", "entity name")
t("medical armour", "医療装置付きの鎧", "_t")
t("This light leather armour features a special medical injector.", "特殊な注射器を取り付けたレザーアーマーだ。", "_t")
t("Steam Powered Boots", "★スチームパワードブーツ", "entity name")
t("Boots. But with steam power!", "ブーツだ。蒸気の力を秘めている！", "_t")
t("Generate %d steam each time you walk.", "歩くごとに蒸気が %d 増加。", "tformat")
t("The more steam the better!", "蒸気を集めよう！", "_t")
t("Steam Powered Helm", "★スチームパワードヘルム", "entity name")
t("A Helmet. But with steam power!", "ヘルメットだ。蒸気の力を秘めている！", "_t")
t("Steam Powered Gauntlets", "★スチームパワードガントレット", "entity name")
t("Gauntlets. But with steam power!", "ガントレットだ。蒸気の力を秘めている！", "_t")
t("Anti-Gravity Boots", "★反重力ブーツ", "entity name")
t("overheating steel greaves", "超高温のスチールグリーブ", "_t")
t([[These boots seem to have been made by a... creative individual who seems to have decided that launching yourself through the air via rocketry qualifies as "anti-gravity".
They look like they will work, though.
Probably.
If you're very careful.]], [[このブーツを造ったのは・・・独創力に富んだやつのようだ。ロケット噴射で宙に浮くのを「反重力」と称することにしたらしい。まあ、動作はするみたいだ。
　多分ね。
　細心の注意を払えばの話だけど。]], "_t")
t("These boots have a %d%% chance to fail to operate properly (reduced by Cunning).", "%d%% の確率で起動失敗（賢さに依存）", "tformat")
t("jump to a nearby location within range %d, blasting everything within radius 2 (%d burning fire damage, 2 tile knockback) of the jump point and within radius 3 (%d burning fire damage, 3 tile knockback) of the landing point (damage based on Cunning)", "%dマス以内の地点にジャンプする。元いた場所には半径２マスの爆発を起こす（炎上ダメージ %d ２マスノックバック）ジャンプ先には半径３マスの爆発（炎上ダメージ %d ３マスノックバック）（賢さに依存）", "tformat")
t("#LIGHT_RED#You see no place to land near there.", "#LIGHT_RED#着地可能地点が見当たらない。", "logPlayer")
t("#Source# ignites %s %s, creating a #LIGHT_RED#blast of fire#LAST# that %s!", "#Source#は%s%sを起動して#LIGHT_RED#ロケット噴射#LAST#した！　%s", "logCombat")
t("engulfs %s spectacularly", "炎がその体を派手に包む！ %s", "tformat")
t("launches %s in the air", "勢いよく宙に舞い上がる！ %s", "tformat")
t("#Source# lands in a #LIGHT_RED#firey explosion#LAST#!", "#Source#は#LIGHT_RED#爆炎#LAST#と共に着地した！", "logCombat")
t("Assassin's Surprise", "★暗器手甲", "entity name")
t("glistening steel gauntlets", "光る鉄の小手", "_t")
t("These steel gauntlets feature a hidden contraption embedded in the left index finger that fires poisonous bolts.", "鋼鉄のガントレットだ。左手の人差し指に装置が仕込んであり毒矢を撃てる。", "_t")
t("fire a poisonous bolt out to range %d that deals %d nature damage and afflicts the target with crippling poison (%d%% fail chance) that deals %d addition nature damage over %d turns (damage based on Cunning)", "射程 %d の毒矢を放つ。これは自然属性の %d ダメージを対象に与えて神経毒に侵す（これによるタレント失敗率 %d%% ）さらに自然属性の %d ダメージを %d ターンかけて与える（賢さ依存）", "tformat")
t("#Source# fires a bolt of #GREEN#poison#LAST# at #target# from %s %s!", "#Source#は毒矢を#target#に撃った。%s%sの仕掛けだ！", "logCombat")
t("something", "物体", "_t")
t("Nacrush's Decimator", "★ナクラッシュの虐殺銃", "entity name")
t("unwieldy gun", "不格好な銃", "_t")
t("Nacrush was known for a tendency towards overkill.", "ナクラッシュはおよそ加減というものを知らないことで有名だった。", "_t")
t("Knocks you back when fired.", "射撃時に自身が後退する。", "_t")
t("#Source# recoils from the shot.", "#Source#は反動で下がった。", "logCombat")
t("Signal", "★シグナルガン", "entity name")
t("red barreled steamgun", "赤いバレルの銃", "_t")
t("An odd, stubby gun with a large, red barrel.", "ずんぐりとした変わった銃だ。銃身が大きく、赤い。", "_t")
t("Glacia", "★フリーザー", "entity name")
t("frozen gun", "凍った銃", "_t")
t("Strange coils encircle this extremely cold gun.", "　妙なコイルが何重にも巻き付けてある銃だ。手がくっつきそうなほど冷たい。", "_t")
t("deal cold damage equal to 100 + the higher of your steam or spellpower, and attempt to freeze the target (20% chance).", "１００＋Xの冷気属性ダメージ。Xは蒸気パワーと魔法パワーのどちらか高い方。２０％の確率で凍結させる。", "_t")
t("Tinkerer's Twinblaster", "★工士の二連銃", "entity name")
t("two barreled steamgun", "双銃身のスチームガン", "_t")
t([[This gun seems to be some experiment in firing multiple shots simultaneously.
The design is somewhat rudimentary, but it seems to work.]], "同時に２発の弾丸を撃つ銃の試作品らしい。設計は稚拙だが動作はするようだ。", "_t")
t("Flashpoint", "★火炎銃", "entity name")
t("overheated gun", "熱い銃", "_t")
t("\"Have you ever looked at some guys and thought 'you know, I really wish they were on fire right now', but you didn't feel like walking all the way over there? Well, there's now a better way!\"", "「誰かを見かけて、ええと、『あいつ燃やしたいけどわざわざ歩いていくのもダルいな』と思ったことはありませんか？　そんな時にはこれを！」", "_t")
t("S.H. Spear", "★Ｓ．Ｈ．スピア", "entity name")
t("engraved steamgun", "象眼した銃", "_t")
t([[This gun is engraved with a strange material which focuses mental powers.
It seems like your mind will operate even faster with this equipped.]], "精神力を高める不思議な金属を象眼した銃だ。手に取ると頭の回転が桁違いになる。", "_t")
t("Dreamweaver", "★ドリームガン", "entity name")
t("shimmering steamgun", "輝く銃", "_t")
t("This isn't so much a gun, as it is the idea of a gun.  You'll be able to remember it pretty easily if you lose it.", "これは銃というよりも銃の概念である。無くしてしまっても思い出すのは容易い。", "_t")
t("throw the gun and cause it to explode, dealing by %d mind damage (based on Cunning and Willpower) to all targets in an area, attempting to put them to sleep, and disarming yourself for 3 turns", "この銃を投げて爆破する。精神属性の%dダメージを範囲内の敵全員に与えて眠らせる（賢さと意志に依存）その後、自身は３ターンの間、武器解除状態になる。", "tformat")
t("%s tosses %s %s!", "%sは%s %sを投げた！", "logSeen")
t("%s resists the sleep!", "%sは睡眠に抵抗した！", "logSeen")
t("Thoughtcaster", "★精神銃", "entity name")
t("crystalline handgun", "水晶のハンドガン", "_t")
t("From body, mind. From mind, body.", "　体から心。心から体。", "_t")
t("deal %0.2f mind damage (based on Mindpower) in a radius 1 around the target", "%0.2f の精神属性ダメージを対象の周囲１マスに与える（精神パワーに依存）", "tformat")
t("On hitting with a mindstar, deal physical damage equal to your steampower in radius 1 around the target.", "マインドスターで攻撃した際、命中時に蒸気パワーに等しい物理属性ダメージを対象の半径１マスに与える。", "_t")
t("Spider's Fangs", "蜘蛛の牙", "entity name")
t("pouch of envenomed shots", "★毒牙弾", "_t")
t("A dedicated technician seems to have built pockets of spider venom into these rounds. It's not clear how happy the spiders were about this.", "　研究熱心な技術者が弾丸の中に蜘蛛の毒嚢を仕込んだようだ。当の蜘蛛達が喜んだかどうかは定かではない。", "_t")
t("(cooling down: %d turns)", "(クールダウン: %d ターン)", "tformat")
t("Ready to trigger!", "準備ＯＫ！", "_t")
t("bursts into an cloud of spydric poison, pinning those inside (with a 10 turn cooldown)", "蜘蛛毒の噴霧を発生させる。範囲内の全員を移動不能にする（クールダウン１０ターン）", "_t")
t("Scattermind", "★砕心石", "entity name")
t("shattered mindstar", "粉々のマインドスター", "_t")
t("A linen pouch of jagged mindstar fragments, each radiating a palpable sense of confusion and pain. They must have made up an impressive whole originally, before some cretin turned it to bits.", "ギザギザとしたマインドスターの破片が詰まった亜麻布袋だ。その一つ一つから訳の解らない苦痛がひしひしと伝わってくる。元は素晴らしい力を有していたに違いないが、大馬鹿者が粉々にしてしまったのだろう。", "_t")
t("strike the target with one of Mind Sear, Psychic Lobotomy, or Sunder Mind, at random.", "Ｐｓｉバーン、Ｐｓｉロボトミ、ブレインオープナーのいずれかがランダムで対象に発動。", "_t")
t("Thundercrack", "★雷鳴弾", "entity name")
t("pouch of copper shots", "銅弾の袋", "_t")
t("Through a combination of magic and airborne probes, these shots incite powerful bolts of lightning to strike your target from above, frying them and those around them!", "気象観測装置に魔法をかけることによって、弾丸が上空からしたたかに電撃を落とせるようになっている。標的もその周囲もまっ黒焦げ！", "_t")
t("a bolt of lightning strikes your target, dealing lightning damage to them and fire damage to those around them.", "対象に電撃を発射。対象に電撃属性ダメージを与え、周囲には火炎属性ダメージを与える。", "_t")
t("Vindicator", "★ジャッジメント", "entity name")
t("engraved gun", "象眼した銃", "_t")
t("\"Pesky undead plaguing your village? Necromancers ransacking your burial grounds? The Vindicator is the solution to all your woes!\"", "「忌々しい不死者にお悩みのお宅はありませんか？　死霊術師がご先祖のお墓を荒らしてはいませんか？　このジャッジメントで全て解決です！」", "_t")
t("release a burst of light dealing damage equal to your cunning plus your magic in a ball of radius 2. If the target is undead, the damage and radius are doubled.", "光の奔流で半径２マスのボール状範囲へ光属性ダメージを与える。これは自身の賢さ＋魔力の値に等しい。不死者に対してはこのダメージが２倍に。", "_t")
t("Overburst", "★バーストガン", "entity name")
t("wide barreled steamgun", "広銃身の銃", "_t")
t("\"Have you ever fired a shot into a group of monsters and thought 'there must be a better way?' Well now, there is!\"", "「モンスターの集団に弾丸を撃ちこんだものの『もっと楽な方法があるよなあ？』という経験はありますか？　あるんですよこれが！」", "_t")
t("Release a burst of shrapnel, dealing physical damage equal to your steampower in a cone from the target of radius 4.", "榴散弾を放つ。対象を起点とした半径４マスの扇状範囲に物理属性ダメージ。これは自身の蒸気パワーに等しい。", "_t")
t("Murderfang's Surekill", "★マーダーファングの確殺銃", "entity name")
t([["Murderfang came over yesterday, raving about this idea for a steamgun he had. He described it in great detail, everything, except for how it would actually work.
What do you even grip it by? Insisted I make it though, left some design notes.
They all just say 'make it really flashy'.
 
-Pizurk, Master Tinker]], [[「マーダーファングが昨日わざわざやってきて、『こんな銃を思いついた！』とまくし立てた。微に入り細を穿ち喋り尽したが構造はとんと解らぬ。グリップですらどうしたものか？　『とにかく頼んだ』と押し切って奴は企画書を置いていった。『ド派手なヤツを』としか書いてないんだが」

　－工匠ピザーク]], "_t")
t("Burst apart, dealing physical damage equal to 25% of the original damage in a ball of radius 1.", "敵を吹き飛ばす。元ダメージの２５％の分を物理属性として半径１マスのボール状範囲に与える。", "_t")
t("The Long-Arm", "★ロングアーム", "entity name")
t("long barreled gun", "長銃身の銃", "_t")
t("This gun has an absurdly long barrel. You wonder for whom it may have been designed.", "異常なほど銃身が長い。誰の為に作ったものなのだろうか？", "_t")
t("Focus your aim on a target, marking them for death - reducing their ranged defense by %d and their resistances by %d%%", "対象を次の獲物として狙う。遠距離回避を %d 低下させ、全ての耐性を %d%% 減少させる。", "tformat")
t("#Source# takes aim at #target# using %s!", "#Source#は#target#に狙いを定めた。%sの餌食になれ！", "logCombat")
t("Annihilator", "★滅殺ガトリング", "entity name")
t("gigantic many barreled gun", "多銃身の巨大銃", "_t")
t("This gun features a wheel with several barrels attached and seems to be powered by an engine. It looks... impressive.", "ホイールに銃身を幾つも取り付けた銃だ。エンジンで動かすらしい。これは・・・凄いな。", "_t")
t("Fire rate increases while firing, up to 5 shots per turn. Resets after 5 turns without firing.", "射撃中は射撃率が上昇する。最大で５発／ターンまで。射撃しなければ５ターン後にリセット。", "_t")
t("50% chance to reload 1 ammo", "５０%の確率で矢弾を１装填。", "_t")
t("The Shotgonne", "★虐殺ショットガン", "entity name")
t("huge gun", "巨大な銃", "_t")
t([[This huge steamgun can be loaded with more than one bullet so that multiple shots can be fired in a nasty cone of death.
It also seems to have been carefully balanced to work like a dual gun set.]], [[巨大なスチームガンだ。弾丸を幾つも装填できるようになっており、斉射して広範囲の敵を皆殺しにする。
　重心を念入りに調整してあるらしく、片手用の銃としても使える。]], "_t")
t("When fired, shoots up to 4 extra shots at random foes with a radius 4 cone centered on the target.", "射撃時にランダムな敵４体までに追加射撃。範囲は最初の対象を中心とした半径４マスの扇状範囲。", "_t")
t("Cloak of Daggers", "★ダガークローク", "entity name")
t("bladed cloak", "刃のクローク", "_t")
t("This cloak seems to incorporate a series of blades attached to various spring mechanisms.  Apparently the designer believed that the best defense was an active one.", "このクロークは無数のダガーを様々な射出装置に組み込んで取り付けているようだ。設計者の信条は「攻撃は最大の防御」だったのだろう。", "_t")
