I guess it probably grinds things pretty well.]], "狂った時魔導士が実験で生み出したものだ。奇妙不可思議なこのデバイスは逆宇宙へのポータルとなっている！そこでは全てのものが逆方向にスピンしているのだ。何かをすり潰すのに好都合なんじゃないかな。", "_t")
