t("Oh, for the love of...  You're way too busy to deal with this nonsense.  You rev up Mirrorazor again, re-syncing it with the Mirror Universe, and toss the note back in.  A different note flies out the other side, miraculously not torn to shreds by the massive difference in planetary rotations.", "　ああ・・・後生だから・・・一秒たりともこんな時間の無駄をしている暇はないはずだぞ。もう一度ミラーエッジの回転数を上げ、再び鏡宇宙と同期させた。そしてメモを投げ返す。こちら側に別のメモが飛び出してきた。２つの惑星の逆方向をとる凄まじい自転に挟まれてバラバラになる、という事態は奇跡的に免れている。", "_t")
t("#LIGHT_BLUE#Mirrorazor shudders as a note falls out from a different timeline!", "#LIGHT_BLUE#ミラーエッジが震えると別の時間軸からノートが落ちてきた！", "saySimple")
