t("\"So we were thinking. You know what's better than saws? Really BIG saws. Unfortunately, no one could lift them. So we came up with an innovative new solution: Mount them on a motorized platform, allowing easy transportation and unparalleled cutting power!\"", "「それで思案したんですよ。スチームソーより凄い武器ってなんだか分かります？　*でっかい*スチームソーです。生憎と誰も持ち上げられなかったんですけどね。で、革命的な解決策に辿り着いたわけです。モーター付きの台座に載せれば、運ぶのが楽だし出力も桁外れ！」", "_t")
