t([[Faced with the petty quandaries of 'conventional physics', some mad tinker must have coated this sawblade with a fine sheathe of dilated time to maximize its speed.
 
There were ...side effects.]], [[煩わしい「古典力学」の壁にぶち当たったせいか、常軌を逸した工士が時流を伸ばして見事にスチームソーを覆ったと見える。これにより速度が最高潮に達した。

　その際に・・・副作用が出たが。]], "_t")
t("Attack speed increases with paradox, up to 250% at 1000 paradox.", "攻撃速度が逆説値に依存。逆説値１０００の時に２５０％が上限。", "_t")
