t("increase paradox by a drastic amount with a chance to do an anomaly (%d%% chance). If anomaly triggers, halve paradox.", "逆説値が大幅に上昇し、アノーマリーが一定確率で発生（確率 %d%% ）アノーマリーが発生すると逆説値が半減する。", "tformat")
t("Heartrend", "★ブラッドハート", "entity name")
t([[There is an attached note.
 
'I've spilt the heartsblood of my work, feeling it pound, like a heart, in my palms.
Some people just can't let go until they've bled dry.']], [[書置きが貼り付けてある。

　我が命を注ぎし作　生を得たる心臓の如く　この手の中で打ち震え
　これなる刃を手放せぬ　者も中にはいるだろう　血の一滴の尽きるまで]], "_t")
t([[All damage dealt by or to you (that is over 1% of max life) bleeds for an additional 20% of the damage as physical damage (ignores most status resistances).
While you are bleeding, Heartrend's damage increases and it gains lifesteal.]], "相手にダメージを与えるとき、また自分がダメージを受けるとき、それが最大ＨＰの１％を超えるなら、追加でダメージの２０％に等しい出血効果が発生する。これは物理属性で耐性の類をほとんど無視する。自身が出血効果を受けているとこの武器のダメージは上昇し、ＨＰ吸収を得る。", "_t")
t("If bleed damage per turn is greater than 5% of max life, attacks cleave.", "ターン毎に受ける出血ダメージが、最大ＨＰの５％を超えているとき、攻撃が切り払いになる。", "_t")
t("Dethzaw", "★ですそー", "entity name")
t("fiery steamsaw", "燃えるスチームソー", "_t")
t([[Grushgore the Destroyer was absolutely enthralled when he discovered steamsaws. He immediately kidnapped several tinkerers and forced them to create this for him.
His naming skills have not improved.]], [[破壊者グルシュゴアはスチームソーを初めて見た時、すっかり虜になってしまった。そこで工士をひっさらって自分の為にスチームソーを作らせたのだ。
　ネーミングセンスは全く向上していない。]], "_t")
t("deal a melee attack against all other enemies in a circle around you", "自身の周囲１マス全員に近接攻撃する。", "_t")
t("Galen's Flowing Robe", "★ガレンの揺らめくローブ", "entity name")
t("ample robe", "ゆったりとしたローブ", "_t")
t("This robe was worn by the Technomancer Galen, infused with technomancy enchantments it is said to react to techno-spells!", "魔工学士のガレンが纏っていたローブだ。魔導工学の付与術が込められており、魔導工学の魔法に反応すると言われている！", "_t")
t([[20% chance when casting a technomancy spell (or 10% chance when casting a normal spell) to power-up the internal defense circuits of the robe.
The circuit will do one of:
#AQUAMARINE#if more than one foe is in melee range#LAST#: teleport away all foes
#AQUAMARINE#if below 50% life#LAST#: increase all resistances by 20% for 5 turns
#AQUAMARINE#if below 20 steam#LAST#: supercharge the arcane dynamo to produce 4 more steam per 10 mana spent for 5 turns
#AQUAMARINE#otherwise#LAST#: reset the cooldown of the spell with the highest remaining cooldown
]], [[　魔工学系の魔法を使用した際に２０％の確率で、ローブに内蔵された防御回路の出力が増加する（普通の魔法なら１０％）
　これにより以下のいずれかの効果が発生する。
　・#AQUAMARINE#２体以上の敵が隣接されている場合#LAST#：敵全員をテレポートさせる。
　・#AQUAMARINE#ＨＰが５０％未満の場合#LAST#：全ての耐性が５ターンの間２０％増加する。
　・#AQUAMARINE#蒸気が２０未満の場合#LAST#：魔導ダイナモを過充填し、５ターンの間、消費マナ１０当たりの蒸気獲得量が４上昇する。
　・#AQUAMARINE#上記以外の場合#LAST#：クールダウン中の魔法のうち、一番高いものを解除する。
]], "_t")
