section "tome-orcs/data/lore/destructicus.lua"

t("kaltor's shop", "カルタ－の店", "newLore category")
t("DESTRUCTICUS!", "デストロイヤー！", "_t")
t([[INTRODUCING!

The most powerful, most fearsome, most awesome weapon ever conceived by giants, men, nature, or anything before us:

#{bold}#DESTRUCTICUS, IMPOLITE PENETRATOR OF THE SKY#{normal}#

Containing a warhead laden with explosive runes, alchemical reagents, vile curses, steel drake scales, ritch venom, and little slips of paper bearing most unkind statements about your target's mother

Travelling at a speed which could be charitably described as absurd, and uncharitably described as obscene

Launched with such force that its operator will need a fireproof suit to avoid immolation from the backblast alone (fireproof suit not included)

Absolutely guaranteed to destroy ANY autonomous entity it detonates against!  Orcs!  Dragons!  Golems smaller than a medium-sized village!

A MANDATORY addition to your home or airship!

For pricing, please discuss the matter with Kaltor, and then forget about it entirely.  If price is a factor for you, you almost certainly cannot afford DESTRUCTICUS.

#{italic}#(Disclaimer: We are not responsible for any injuries, deaths, or loss of property resulting from improper transport of DESTRUCTICUS.  We are not responsible for determining the proper method of transporting DESTRUCTICUS.  Additional missiles for DESTRUCTICUS are not available.  Accuracy at ranges greater than DESTRUCTICUS' blast radius is not guaranteed.  We are not responsible for any injuries, deaths, or loss of property resulting from DESTRUCTICUS changing direction in mid-flight.)#{normal}#]], [[　ご案内！
	　
	　最強にして最恐。空前絶後の最驚兵器。#{bold}#断固断空ミサイル・デストロイヤー！#{normal}#
	　
	　弾頭には爆発ルーン、錬金試薬、邪悪な呪い、鋼鉄竜の鱗、リッチ毒、標的の母親に関する罵詈雑言を連ねた紙吹雪を散りばめてあります。
	　
	　飛行速度は控えめに申し上げても馬鹿げたスピードです。有り体に申せば物理法則を置き去りにしてございます。
	　
	　超高速で発射するため、ご使用の際には防火スーツを着用していただきます。さもなくば発射の際のバックファイアで周辺一帯ごと消し炭になるでしょう（防火スーツは別売りとなります）
	　
	　着弾地点に存在する勢力は１２０％の確率で滅亡します！　オークも！　ドラゴンも！　小規模ならゴーレムの村だって！
	　
	　ご自宅やエアシップに*必携*の一品！
	　
	　お値段につきましてはカルターにお問合せの上、きっぱりとお諦めください。お値段を気にされるお客様にご購入はまず厳しいかと存じます。
	　
	#{italic}#　免責事項
	・本品を不適切に運搬した際に発生した身体・金銭上の損失については責任を一切負いかねます。
	・適切な運搬法につきましてはお客様の責任でご判断ください。
	・弾頭は限定品となります。
	・爆発半径外の射程に対しては命中しない可能性があります。
	・飛行中に方向を変更した場合に発生した身体・金銭上の損失については責任を一切負いかねます。#{normal}#]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/dominion-port.lua"

t("dominion port", "カー・ハイブの港", "newLore category")
t("'disciplinary report'", "懲戒記録", "_t")
t([[DISCIPLINARY REPORT:

-Blackhorn the Brash, theft of personal quantities of Atmos absinthe.  Twenty lashes.
-Swabbie Grobbo, theft of personal quantities of Shaloren wine.  Twelve lashes.
-First Mate Grapeshot, improper use of a cannon.  Twenty lashes, demotion.
-Taroggos, killing crew of targeted supply ship in defiance of client's wishes.  Three lashes.  [i]note: payment received regardless,  all goods retrieved and delivered accordingly[/i]
-Runty, theft of personal quantities of Dwarven ale.  Eleven lashes.
-Hamfist, theft of commercial quantities of Ogric brandy.  Fifty lashes, docked pay.
-Dogchucker the Summoner, disfiguring another crewmember.  Punishment waived.  [i]note: determined to be accident[/i]
-Tidal Torgor, accidental sinking of friendly vessel.  One thousand lashes, over five days.  [i]note: should be keelhauled but we need all the aquamancers we can get![/i]
-Lieutenant Grapeshot, improper use of a cannon.  Thirty lashes, demotion.
-Lady Laggo, skimming profits from loot sales.  Thirty lashes, demotion to punitive duties.
-Shifty, insubordination.  Ten lashes.
-Swabbie Grogbreath, insufficient swabbing.  Loss of liquor privileges.
-Cannoneer Grapeshot, improper use of a cannon.  Thirty lashes, demotion.
-Pencil-Pusher Pilgo, reassigning Grapeshot to cannoneer position.  Thirty-five lashes.  [i]note: laugh it up you insubordinate punk[/i]
-Smokey, excessive use of fire onboard flammable ship.  Will not be allowed healing for wounds sustained when hat caught fire.
-Swabbie Grogbreath, violation of loss of liquor privileges.  Punishment waived.  [i]note: the foul swill he found is punishment enough[/i]
-Sticks, attempted mutiny.  Keelhauled.
-Crabhide, support of attempted mutiny.  Keelhauled.
-Pegfist Pogga, failure to report attempted mutiny.  Keelhauled.
-Gunner Bilgebloat, fraternizing with attempted mutineers.  Keelhauled.
-First Mate Brakka, failure to keelhaul enough attempted mutineers.  Keelhauled.
-Captain Bloody-Keel, excessive keelhauling.  Keelhauled twice.
-Swabbie Grapeshot, improper use of a mop.  Fifty lashes, demotion.
]], [[　懲戒記録
	　
	・せっかちブラックホーン
	　
	　私物のアトモスアブサンをくすねた。鞭打ち２０回。
	　
	・水兵グロッボ
	
	　私物のシャローレワインをくすねた。鞭打ち１２回。
	　
	・一等航海士グレープショット
	　
	　大砲を誤射。鞭打ち２０回。降格。
	　
	・タロゴス
	　
	　襲撃した補給船のクルーを殺った。雇い主の期待を裏切ったぞ。鞭打ち３回。
	[i]　備考：支払いには影響無し。戦利品はしっかり全部回収し、搬送した。[/i]
	　
	・ランティ
	　
	　私物のドワーフエールをくすねた。鞭打ち１１回。
	　
	・ハムフィスト
	　
	　商用のオーガブランデーを横流し。鞭打ち５０回。減給。
	　
	・召喚士ドグチェッカー
	　
	　仲間の顔面を破壊。処分はまだ決めてない。
	[i]　備考：事故であったと結論。[/i]
	　
	・津波のトーガー
	　
	　間違って味方の船を沈めた。５日かけて鞭打ち１０００回。
	[i]　備考：船底潜りの刑にかけたいところだが水術師は無駄にできん！[/i]
	　
	・二等航海士グレープショット
	　
	　大砲を誤射。鞭打ち３０回。降格。
	　
	・ラッゴ嬢
	　
	　戦利品の売り上げを横領。鞭打ち３０回。奉仕活動に配置。
	　
	・シフティ
	　
	　命令を聞かなかった。鞭打ち１０回。
	　
	・水兵グロッグブレス
	　
	　掃除を手抜き。酒抜きだ。
	　
	・砲撃手グレープショット
	　
	　大砲を誤射。鞭打ち３０回。降格。
	　
	・万年事務のピルゴ
	　
	　グレープショットをまた砲撃手に配置。鞭打ち３５回。
	[i]　備考：好きなだけ笑っていいぞ。このはねっかえりめが。[/i]
	　
	・スモーキー
	　
	　火気厳禁の船で火を起こした。帽子を燃やした重い火傷は治してやらん。
	　
	・水兵グロッグブレス
	　
	　断酒の罰を破った。処分は保留。
	[i]　備考：泥水みたいな酒を飲むハメになったんだから勘弁してやる。[/i]
	　
	・スティックス
	　
	　反乱を画策。船底潜りの刑。
	　
	・クラブハイド
	　
	　反乱計画に加担。船底潜りの刑。
	　
	・釘手のポッガ
	　
	　反乱計画を報告しなかった。船底潜りの刑。
	　
	・銃士ビルゲブロート
	　
	　反乱分子と交流。船底潜りの刑。
	　
	・一等航海士ブラッカ
	　
	　反乱分子にちゃんと船底潜りの刑をしてない。船底潜りの刑。
	　
	・ブラッディキール船長
	　
	　船底潜りの刑をやりすぎだ。船底潜りの刑２回。
	　
	・水兵グレープショット
	　
	　モップを悪用した。鞭打ち５０回。降格。
]], "_t")
t("operations performed", "進捗状況", "_t")
t([[OPERATIONS PERFORMED:

-With information provided by "Sunny Day," we were able to secure an Allied Kingdoms supply ship during the brief window in which it was unguarded, with no personal casualties.  We technically broke our agreement (Taroggos has been adequately disciplined), but because the ship was carrying more useful materials than expected, we were able to take a hefty supply of troll-sized (or close enough to it) arms and armor, alongside lumber, furniture, and smaller stralite equipment which can be easily melted down and repurposed into something useful, before delivering the promised amount of cargo to "Vapor Trail."  Combined with the payment received from "Sunny Day," we made a significant profit and reinforced our relationship with "Vapor Trail."  (Our relationship with "Sunny Day" is of no consequence; repeat business was unlikely.)

-The last cargo ship I had sent home, the one with countless small crates and the order to confiscate them all and hold onto them for further instruction, contains one crate full of You-Know-What received as payment for a product received via Iron Throne smugglers.  This crate is labelled "47-C."  Dispose of the others, as they are [i]extremely[/i] thoroughly trapped.  The exchange with "Sherry Toll" was mercifully uneventful, and the goods provided appear to be functional.  With all due respect, Boss, if this doesn't get me a promotion, what will?

-Our contacts with the black market of Maj'Eyal and our establishment of a safe trading hub for their activity has continued to be immensely profitable, in addition to providing us an exploitable means of getting objects of our choosing into Maj'Eyal.  "Vapor Trail" has been an eager participant, and we've made a killing off selling Atmos absinthe to the Allied Kingdoms smugglers, as well as selling Elvala wine and brandy to them.  I'll be sending a ship full of our profits (useful metals, alchemical ingredients, slaves) back home on a bi-monthly basis; search the crew to make sure they haven't been lining their pockets, and keelhaul any you catch.

-Crew disobedience and morale continues to be something of a problem, despite regular floggings, but we're still retaining enough of them and getting enough use out of them.  That said, feel free to keep sending sentenced criminals our way - they're surprisingly productive as long as we give them enough booze and cheerblossom.]], [[・進捗状況
　
・「晴天」のタレコミのおかげで連合王国の補給船を確保。手薄になった隙を狙えましたぜ。死傷者はなし。契約違反がなかったわけじゃあありませんが（タロゴスにはヤキをいれておきやした）いい物資を思ってたよりたんまり積んでたんで、トロルに合う（ぴったりじゃないかもしれませんがね）武器も鎧もどっさりぶん取りました。それに材木に家具。他には小さめなストラライトの備品なんかですな。こっちは簡単に溶かせるんで、使い良いようにしてから約束した分を「霧の道」にカーゴで送ります。「晴天」からの報酬を勘定に入れれば大層な稼ぎで、「霧の道」とは長い付き合いが出来そうでさ（「晴天」の方はほっぽっといてもいいんじゃねえですかね。こっちとの商売はこれっきりみたいでしたんで）
　
・この前クニに送った、ちいせえ箱が仰山積んであるカーゴですがね。ひとつ残らず回収してもらって詳しいことは後で連絡するってやつですが「例のアレ」が詰まった箱を乗っけてあります。鉄の王座の闇商人共から都合した商品を、取引に使ってせしめたやつですぜ。４７－Ｃっていう箱なんで。他の箱は全部うっちゃってくだせえ。*たんと*罠が仕掛けてあるもんで。「シェリー樽」との取引はありがてえことにすんなり終わりました。受け取った品はちゃんと使えるみてえです。ボス、こんな具合なら出世間違いなしですな？
　
・マイ・イヤルのブラックマーケットとは連絡を取り合ってやす。奴らが腰を据えて商売できるように拠点を作ってやったんで、大儲けできてますわ。おまけにマイ・イヤルに好きなモンを持ち込むルートが使えるときた。「霧の道」はやる気満々で、アトモスアブサンを連合王国の闇商人共に持っていけば良い稼ぎになりやす。エルヴァラのワインとかブランデーを「霧の道」に持ってっても儲かりますぜ。稼ぎをありったけ積んだ（値打ち物の金属やら錬金素材やら奴隷を）船を一ヶ月おきにそちらへ送るんで、クルーどもが儲けをくすねたらすぐに船底を見せてやってくだせえ。
　
・クルーどもは生意気でやる気がねえもんで手を焼いておりやす。しょっちゅうヤキを入れてるんですがね。まあ、人手は足りてるし、十分使えますわ。そんでも、罪人どもはどんどんこっちに送ってくだせ。酒とバーサークフラワーを切らさなきゃ目が回るほど働いてくれますんで。]], "_t")
t("overall analysis", "総括", "_t")
t([[OVERALL ANALYSIS:

Boss, if there's one thing I can say, it's that you didn't make a mistake by pardoning me and my crew.  The materials I've shipped home have surely been invaluable for our preparations, and the moment the top brass decides they want to start the invasion, I can start spiking the outgoing liquors and cheerblossom with time-delay potions of your choice, crippling the Allied Kingdoms from within by starting a plague or turning every minor lawbreaker into a berserk madman.  If nothing else, the You-Know-What will be [i]very[/i] useful when push comes to shove.

As per your orders, we've restricted most of our intervention to sabotaging the Allied Kingdoms, but I wonder if some amount of focus on the orcs would be helpful.  A band of them has recently emerged from the Clork Peninsula, victorious over Sun Paladins and Atmos alike; we've lost contact with "Sunny Day," and "Vapor Trail" has kept exports to a minimum for fear of detection.  If we don't do something about this soon, they may become a bigger obstacle than the Allied Kingdoms.

I await your reply - and more dried meat, my crew loves the stuff and these smugglers can't be arsed to bring us something so mundane.]], [[・総括
　
　ボス、一つ言わせてもらえるなら、俺たちを雇って正解でしたぜ。クニに送った物資のおかげで準備がずいぶん捗ったんじゃありませんか。それにお偉いさんが侵攻を始めろって言やあ、すぐにでも流してるバーサークフラワー入りの酒に後から効いてくるポーションを混ぜますぜ。ボスが選んだ通りのヤツです。悪い病気が流行ったり、ゴロツキどもが暴れまわったりで連合王国はにっちもさっちも行かなくなるに違えねえ。上手くいかなくてもいよいよって時には「例のアレ」が大活躍でさ。
　
　言われた通り、連合王国への手出しはできるだけ控えておりやす。でもオーク共にはちっとばかり気を付けた方がいいかもしれませんぜ。最近になってやつらがクローク半島から出てきまして。太陽の騎士共もアトモスもへこまされちまいました。「晴天」とは連絡がつかねえです。「霧の道」はあんまし商品を流さなくなりやした。見つかるかもしれねえってビビってます。早いとこ手を打たねえと連合王国よりも厄介なことになるんじゃないですかね。
　
　返事を待ってますぜ。あと、干し肉をもっと送ってくだせえ。ウチのクルーはアレが大好物なんで。闇商人共に普通に売ってるモンを頼んでもちっとも耳を貸さねえんです。]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/emporium.lua"

t("vaporous emporium", "霧の商業区", "newLore category")
t("a large poster", "大きなポスター", "_t")
t([[#{bold}#CLOGGING NO MORE!#{normal}#
If steam-vent congestion ails you, avail yourself of:
 
#{italic}#[An illustration depicts a rectangular glass bottle, labelled "DR. RAGLUK's DECLOGGING DRAUGHT".]#{normal}#
 
MADE WITH LOVE, CARE, AND THE PUREST MINERALS FROM THE STEAM QUARRY
 
Just one capful will cleanse your pores, flushing toxins out with the steam!
 
ALSO EFFECTIVE FOR: Headaches, nausea, ennui, fatigue, aches and pains, and general malaise!
 
#{italic}#[A disclaimer occupies the bottom margin of the poster, in print so small you doubt the giants would be able to read it.]#{normal}#
 
WARNING: This product has been determined by the Council of Health Authority to be correlated with the following conditions: Inverse vertigo, increased hair flammability, non-vaporous sweating, night terrors, liver dysphoria, headaches, miner's lung, brainlock, day terrors, mitosis, visions of a great butchered being, miner's elbow, skeletal emancipation, gastrointestinal infamy, brittle kidney, pinaciphobia, decreased global speed, teleportitis, miner's tongue, merged nostrils, an ancient and foul curse, lowered steam pressure, fat burning (literal), ocular feathering, Orcish body odor, arcane disruption, gravity loss, bloodlock, malfeasance, rectal carpeting, nihilism, mid-evening terrors, knee rust, and minor clogging of the pores.]], [[#{bold}#もう詰まらない！#{normal}#
　
　蒸気孔詰まりにお悩みの貴方。
　
#{italic}#（三角フラスコの絵が描いてある。「ラグラック博士の通風薬」というラベルがしてある）#{normal}#
　
をお試しください。愛と思いやり、そして蒸気採掘場の高純度ミネラルが主成分です。
　
　たった一滴で蒸気孔がキレイに！　蒸気と一緒に毒素を追い出します！
　
　こうした症状にもお勧めです：頭痛、吐き気、うつ症状、疲労、体の痛み、倦怠感
　
#{italic}#（下の方に注意書きがしてあるが、小さすぎる。とてもスチームジャイアントの目に留まるとは思えない）#{normal}#
　
　本製品は「議会衛生局」により、以下のような症状との関連が確認されています。
　
　強烈なめまい、頭髪の油分増加、非気化性発汗、夜驚症、神経不安、頭痛、炭肺、精神封鎖、白昼夢、分裂、おぞましい幻覚、肘の痛み、骨格異常、消化器疾患、腎疾患、リスト恐怖症、速度低下、ランダムテレポートの変異、舌の黒ずみ、鼻骨溶解、太古の怨念、蒸気圧低下、脂肪燃焼（文字通り燃えます）、目周りの増毛、オークみたいな体臭、魔法阻害、重力喪失、ブラッドロック、犯罪傾向、腸内ポリープ、ニヒリズム、悪夢、膝関節痛、軽度の蒸気孔詰まり]], "_t")
t("tattered poster", "ボロボロのポスター", "_t")
t([[CLOSING SALE
for
KALTOR's FIREARMS, ARMOR, AND OTHER MARTIAL SUNDRIES
 
It is with a heavy heart that I must announce our closing.  After over twenty years of service, I am shutting my doors - the people of the Atmos Tribe apparently wish to trust the Guard with their well-being, and the Guard chooses to maintain the weapons it already has rather than purchase things like the #{italic}#BRILLIANT AUTO-LOADING ORC EXPELLER#{normal}# (only 30 gold!), or the #{italic}#PRESSURE-ENHANCED SLASHPROOF COMBAT SUIT#{normal}# (only 450 gold!).  I even offered discount options such as the #{italic}#LIL SURPRISE#{normal}# (now only 15 gold!), and yet the city would have none of it.  It would seem my services, and my talents, are simply not wanted.
 
Even if you have no fear of the orcish tribes, ritch swarms, and other assorted threats that lurk just outside our city walls, please consider purchasing some of my wares.  They are truly beautiful displays of craftsmanship, and would do well as a desk sculpture or (if properly disarmed) a child's toy.  If nothing else, you will be ensuring that a once-proud artisan with great love and respect for his craft need not resort to begging on the streets.]], [[　カルターの武具百貨店
	閉店セールのお知らせ
　
　遺憾ながら、閉店の報せをお伝えいたします。創業二十年にして店を畳むことと相成りました。アトモスの皆様はシティガードに治安を委ねたいとお考えのようですね。ですがシティガードは既存の装備を使い続ける方針です。#{italic}#最高級自動装填オークキラー#{normal}#（たったの３０ゴールド！）や#{italic}#圧力式防刃戦闘スーツ#{normal}#（４５０ゴールドぽっちで！）をご購入頂く予定はないとのこと。#{italic}#リトルサプライズ#{normal}#（今ならなんと１５ゴールド！）のような値引きオプションも提案させて頂きましたが、不要とのことでした。私の仕事も技能も無用の長物なのでしょうか。
　
　オークやリッチ虫、その他シティの目と鼻の先に蔓延る外敵。それらの襲撃など杞憂と思われる方もいらっしゃるでしょう。そういったお客様にも重ねてお願い申し上げます。当店をご利用ください。当方の兵器は匠の技が紡ぎだす美の化身でございます。机のインテリア、（きちんと装置を解除すれば）お子様の玩具としてもお使い頂けます。いずれにも興味がない、という方もお求めください。己の技術を自負する一端の職人が路頭に迷わずに済みます。.]], "_t")
t("ornately-painted poster", "派手なポスター", "_t")
t([[Stylish.  Elegant.  Exclusive.

#{bold}#EXTINCTION#{normal}#, a new line from Faerlhing's Weavings, the finest name in fashion.

Steel drakes can no longer be found in the wild - our pens contain the ONLY living ones in Var'Eyal, and possibly the last generation to not be marred by inbreeding-induced deformities.  When you wear our wonderful coats, dresses, boots, or corsets to a party, meeting, or other get-together, the others won't just notice the unique, metallic sheen matched with unparalleled flexibility unique to their scales.  They'll know that they CANNOT imitate your look.  That it's a look their children will NEVER have.  That YOU have made your mark on ecological history, and reaped the fashionable, comfortable benefits.  And steel drake scales are not known to decay naturally, so proof of your impeccable taste will live far longer than the species they were taken from.

Place your orders now.  Open bidding will run for 30 days, after which point orders will be handled on a first-come, first-serve basis.

Other fashions come and go.  #{bold}#EXTINCTION#{normal}# is forever.
]], [[　スタイリッシュ、エレガント、オンリーワン。

　トップブランドのファールヒング・ドレッサーから最新のモード#{bold}#滅美（ほろび）#{normal}#をお届け。今日、野生の鋼鉄竜は絶滅しています。当ブランドがヴァル・イヤルの牧場に抱える群が現存する唯一の個体。また、健全に生まれてくる最後の世代でもあります。これより下の世代は交配が進み過ぎてしまうのです。私共の自信作をお召しになって、公私の集いにご出席ください。出席者の皆様は独特の光沢に目を奪われることでしょう。鋼鉄鱗ならではの柔軟性にマッチしたその輝きは、他の追随を許しません。それだけではありません。このファッションは決して真似できないと痛感してもらえるのです。未来永劫、不可能であると。お客様が環境保護の歴史に名を刻み、スタイリッシュで快適な成果を上げたことを知るでしょう。その上、鋼鉄鱗は自然劣化しないとされています。ですからお客様の完全無欠なセンスの証は、鋼鉄竜が滅んだ後もこの世に残ります。
　
　今すぐご注文を。最初の３０日間は公開入札となり、その後は先着順となります。

　ファッションには流行り廃りがあります。しかし #{bold}#滅美#{normal}#は永遠です。
]], "_t")
t("official-looking poster", "お堅いポスター", "_t")
t([[#{bold}#KEEP THE PRESSURE UP!#{normal}#
#{italic}#An announcement on power consumption, paid for by the Council of Geothermal Authority#{normal}#

As per our previous announcements, the geothermal vents of the Steam Quarry have begun to taper off in output.  While our geologists and military consider all available options for finding new vents (or alternative sources of steam power), we need YOUR cooperation to keep the pipes from running dry!  Here's how you can help make sure we have enough steam for everyone:

-Cook the old-fashioned way - with flame magic, or a firewood stove.  Flash-steamers, although certainly a convenient way of preparing food, are VERY inefficient.  For a free handbook on delicious and easy-to-learn recipes for a conventional or pyromancy-based stove, simply come to the Council of Geothermal Authority offices and take one from the lobby.

-Remember to shut off your appliances when you're done with them!  A full 5% of our power usage is estimated to be from washing machines, mills, carousels, generator-powered lighting, and other such devices left plugged in when not in use.  When you are done using an appliance, make sure it has been deactivated; to be completely sure, our experts recommend shutting off the valve entirely, then disconnecting the appliance and placing a standard cap over the output pipe.

-Have your pipes checked regularly.  Leaking valves and loose fittings can consume tremendous amounts of steam pressure; you are only required to have your home steam-pipes inspected every three years, but additional inspections are available at no charge (once every six months).  Volunteering for these inspections can reduce your geothermal consumption, and fees, dramatically.

-Use your own steam!  With regular exercise and a good diet, you can create your own power by wearing a collection suit, and plug the pressurized reserve tanks into your home intake valves to reduce the amount of power drawn from the geothermal system by over 40% (depending on personal production).  Short-term use of declogging tonics may help, but long-term use is generally ill-advised.

-Do NOT pressurize tanks from the tap and sell them to others!  This is a violation of Council law, punishable by a fine of up to 3,000 gold and up to four years in prison, per tank.

Thank you for helping ensure we ALL have power, while we work on curing this shortage!]], [[#{bold}#蒸気節約にご協力ください！#{normal}#
　
#{italic}#料金をお支払いの蒸気使用に関して、地熱調査局よりお知らせです。#{normal}#
　
　度々お知らせしてきたように、蒸気採掘場の火道は冷えてきています。地質学者と軍は一体となって新たな火道（あるいは代わりの熱源）を発見するためあらゆる選択肢を検討しています。ですが蒸気の枯渇を防ぐには*皆様*のご協力が不可欠です！　以下の項目にご留意下さい。過不足なく蒸気を供給するため、ご協力をお願いします。
　
　
・昔ながらの調理法を。火炎魔法や薪ストーブを使いましょう。
　
　蒸気調理器を使えば確かに料理の手間暇を省けます。しかし*極めて*非効率です。どなたでもできる美味しいレシピを掲載したハンドブックをご案内しています。薪・火炎魔法ストーブを利用した調理法です。地熱調査局のロビーでご自由にお持ちください。
　
　
・使い終わった機器はきちんと切っておきましょう！
　
　洗濯機、粉挽き機、回転木馬や照明。そのほか使い終わった機器にプラグを刺しっぱなしにしていることで、蒸気使用量の実に５％を消費しているとされています。使い終わった機器はきちんと停止しておきましょう。調査局の専門家は以下の手順を推奨しています。確実に停止するにはまず、バルブを完全に閉めます。その後、機器を取り外し、所定のキャップを供給パイプに嵌めましょう。
　
　
・パイプの定期点検を
　
　バルブが蒸気漏れしていたり、緩んでいたりすると蒸気圧が大幅に無駄になります。ご家庭の蒸気パイプ点検義務は３年に一度で良いということになっておりますが、追加の点検を無料で実施しています（６ヶ月に一度となります）点検にご協力いただければ地熱の消耗を大幅に抑え、使用料金も激減します。
　
　
・ご自身で蒸気を！
　
　常日頃から体を鍛え、食事に気を使っていれば、集気スーツを装着し、ご自身で利用する蒸気を生み出せます。加圧保存タンクをご家庭の吸入バルブに接続すれば、地熱による蒸気の消費は４０％以上減少します（個人の蒸気産出量によります）通風薬は短期的に使う分には有用ですが、長期間服用するのは一般的にお勧めできません。
　
　
・蛇口からタンクに加圧して蒸気を売るのは厳禁！
　
　議会法違反です。タンク１つ当たり、最大で３０００ゴールドの罰金、４年の実刑となります。
　
　蒸気の*幅広い*供給にご協力いただきありがとうございます。蒸気不足解消に向けて鋭意作業中です！]], "_t")
t("hastily-written poster", "大急ぎで描いたポスター", "_t")
t([[KALTOR's FIREARMS, ARMOR, AND OTHER MARTIAL SUNDRIES
is
OPEN FOR BUSINESS AGAIN!
 
The orcish hordes are upon us!  Although I am not normally one for gloating, I feel I must take this opportunity to say:
 
#{bold}#I TOLD YOU SO, YOU INGRATES#{normal}#
 
Do you see the need for my wonderful devices of self-defense NOW?  Do you see why I toiled so thoughtfully and tirelessly to make such exquisite contraptions that could've saved so many lives, if you'd only been willing to pay what I was asking for them, only a tiny fraction of what they were worth?  Does the USELESS City Guard see why they should have been purchasing my newest, improved models, such as the #{italic}#BRILLIANT AUTO-LOADING ORC EXPELLER#{normal}# (only 600 gold!  Get yours now!  Protect your family!) instead of abusing my built-to-last craftsmanship to keep my original production run around for over a decade?
 
Don't make the same mistake twice!  Purchase the #{italic}#LIL SURPRISE#{normal}# for merely 150 gold!  What's that?  You can't afford that entry-level price?  I guess you should've bought it while I was still making them!  Don't want to get your guts torn out by a little green-skinned savage?  My old price for the #{italic}#PRESSURE-ENHANCED SLASHPROOF COMBAT SUIT#{normal}# was a steal at 700 gold - if you want one now, I'm sure your life is worth at least 3800 gold to you.  It utilizes your own vents to power tiny motors hidden in its joints, granting an unparalleled combination of fortitude and mobility; guaranteed to protect you from ANY sort of harm those savages can dish out, without slowing you down!  Notice all those dead guardsmen around?  Notice how they AREN'T wearing a #{italic}#PRESSURE-ENHANCED SLASHPROOF COMBAT SUIT#{normal}#, despite my desperate recommendations?  Don't let that be you or your loved ones!
 
I'm sure you have your doubts as to the efficacy of my lovingly-made armaments; for a free demonstration of the quality and effectiveness of my goods, you are invited to try to take them by force.  I dare you - and that includes the City Guard, should they have any delusions about confiscating them for the public good.  The public has dug their own grave, and I will not pull them up simply out of charity; after all, they have offered me no such charity in the past.
 
#{italic}#[An address is listed at the bottom of this poster.  You could attempt to raid this store, if you wanted, but the owner's armed to the teeth - it's unlikely it'll be worth the risk.]#{normal}#
]], [[　カルターの武具百貨店
　
　営業再開のお報せ！
　
　オークの大群が迫っていますね！　いつもは万事控えめにしているのですが、こういう機会は滅多にないでしょうからな。
　
#{bold}#　だから言ったろう　このマヌケどもが#{normal}#
　
　これで当店自慢の護身装備が如何に大切かお解りになりましたね？　私が四苦八苦して傑作を作り上げた理由も納得して頂けたかと。みんな助かったはずなんですよ？　お勧めした時にお買い上げくださっていれば。正当な評価額に比べたら端金みたいな値段でしたのにねえ。無能なシティガードの皆様も後悔なさっているでしょうな。#{italic}#最高級自動装填オークキラー#{normal}#みたいな最新鋭モデルを採用していれば、とね（たったの６００ゴールド！　すぐにお買い求めを！　家族が大事なら！）その代わり何をしたか？　私の作が耐久性を誇るのをいいことに、初期作品を１０年以上も使い続けたんですよ。
　
　同じ失敗を繰り返してはいけません！　#{italic}#リトルサプライズ#{normal}#をお求めください。ほんの１５０ゴールド！　どうかなさいましたか？　まだまだお求めやすい部類なのですがね？　製造期間中にご購入頂けていればねえ！　緑のちっぽけな蛮人共に腹を裂かれるのは御免でしょう？　#{italic}#圧力式防刃戦闘スーツ#{normal}#は出血大サービスの７００ゴールドにて提供しておりましたが、今お求めになるなら３８００ゴールドから。お客様のお命がよもやそれ以下ということはありますまい。当スーツはご自身の蒸気孔を利用し、各関節部に内蔵したモーターを起動します。類まれなる防御力を機動性を併せ持つ一品。蛮人共の攻撃など受けつけません。それでいて超軽量！　そこら中にガード達の死体が転がっていますね？　このスーツを着てなかったでしょうが。あれほどお勧めしたんですがねえ？　ご自身やご家族を奴らの二の舞にしてはなりません！
　
　私の手塩にかけた装備品がどれほどのものか、お疑いですね。無料体験会を実施いたします。できるものなら力づくで品物を奪ってごらんなさい。遠慮はいりません。シティガードの皆様もこぞってご参加を。命賭けで街を守るなんていう酔狂なガードがいればの話ですが。アトモス族は自らの手で墓穴を掘りました。「穴の底から引き上げてくれ」と、親切心を当てにされても困ります。その手の親切をあなた方から受けた試しがないものでして。
　
#{italic}#（一番下に店の場所が書いてある。その気があれば襲撃してみるのもいいだろう。だが、相手は完全武装している。危険に見合う収穫があるとは思えない）
]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/gem.lua"

t("G.E.M", "地熱探査モグラ", "newLore category")
t("strange black disk (1)", "不思議な黒ディスク（１）", "_t")
t([["...thing on? Okay, good. This is Haze Commander Parmor of the Geothermal Exploratory Mole, on a mission to..."  She sighs. " 'Find the Loyalist and arrange for our safe transport to his refuge, offering him his previous terms of agreement.' Which is Council-speak for 'flee in terror to the only thing that could bail us out of this mess, and bring the Eye with us.' Personally, I'm not keen on putting our fates in the hands of some nutter who lives underground and..." Indistinct grumbling. "...not even my damn job, I didn't sign up to be some politician's valet--"

#{italic}#(You hear a door opening, and another voice speaks.)#{normal}#

"Captain, the tea-maker isn't working!  Get someone on that, post-haste!"

#{italic}#(The door closes.)#{normal}#

"...Yeah, Councillor Tantalos is getting his tea as soon as he can un-kick the hornet's nest that got us into this chaos.  Moving on...  departure was on time, projected journey to the Loyalist's last known position is underway, making a tunnel there from right under the palace.  All systems functioning, except for the tea-maker, and I can't give a slag about that.  End log."]], [[・・・丈夫？　オーケー。よし。こちら噴霧司令官パーマー。地熱探査モグラに搭乗中。現在の作戦は・・・」
	
	　息をつく。
	
	　「『使徒の場所を特定し、そこまで無事我々を送り届けること。そこで以前の契約を切り出す』　この議員言葉を訳すとこうなるわね。『超特急で出かけるぞ。このヤバイ事態をどうにかしてくれるのは一人だけ。『目』と俺たちを連れてってくれ』言わせてもらえるなら、気が進まないわ。地の底に住む馬の骨にみんなの運命を託すなんて・・・」
	
	　よく聞き取れないが不満の声。
	　
	　「・・・こんな任務。それに議員のお守りを引き受けた覚えは・・・」
	　
#{italic}#（ドアの開く音がして、別の声）#{normal}#
	　
	　「パーマー君、ティーメーカーが動かないぞ！　誰かよこしてくれ！　すぐにだ！」
	　
#{italic}#（ドアが閉まった）#{normal}#
	　
	　「・・・ええ。タンタロス議員はティータイムよ。大騒動が収まるって分かった途端、この有様。記録を続けるわ・・・出発は予定通り。前回使徒を確認した地点へ現在移動中。宮殿の真下へ掘り進んでいる。システムに異常なし。ティーメーカーは壊れてるけど、至極どうでもいいことね。記録終了」]], "_t")
t("strange black disk (2)", "不思議な黒ディスク（２）", "_t")
t([["...for posterity!  Let's make sure future generations can hear the moments of history being made!" You hear the voice of Councillor Tantalos again... and then you hear a very strange voice, one that's all too clear. Even with the device playing it, it sounds like it's coming from inside your own head.#{normal}#

"Yes, yes, good idea. This is an important day, for both of us - no, for Eyal...  You've brought what I asked for so long ago, then?"

"Of course!  It's just--  bring the cart around here!"  (Clanking and grinding.)  "Open it up, if you wish."

"No need.  I can feel its power, it's so familiar and yet so new...  This could only be the Eye of Amakthel Himself!  It's beautiful, and all will know its beauty..."

"Er...  splendid, I assume!  This is the beginning of a long and beautiful partnership between the Atmos and...  your people!  Shall I go back up and tell them we're ready for them, and you're ready to handle the Orc situation? They're, ah, rather eager to come down here--"

"GO FORTH, MY HERALD. TELL THEM ALL ARE WELCOME."

"Wh-what are you--"  #{italic}#Screams in the background.  Gurgling.  Crashing.  A distant, bestial roar.#{normal}#

"AMAKTHEL WILL REWARD YOU FOR YOUR SERVICE AS YOU DESERVE." More crashing.  "YOU SHALL BE BLESSED WITH A BETTER NEW FORM.  A BETTER NEW MIND.  ALL YOUR PEOPLE ARE WELCOME TO..."

#{italic}#(You hear Parmor's voice again.)#{normal}#  "Slag it, RUN!  Grab everything and--"  (The recording ends.)
]], [[　・・・子の代まで！　この歴史的瞬間を後世に刻もうではないか！」
	　
	　またタンタロスの声だ・・・それに応えたのは奇妙不可思議な声だった。あまりにも鮮明。装置で再生した音声なのに、頭の中から響いてくるような感じがする。#{normal}#
	　
	　「然り、然り。妙案だ。今日という日にはそれだけの価値がある。我ら両者にとって・・・否、イヤルにとって・・・持ってきているのだろう？　頼んだのは随分と昔のことだ」
	　
	　「もちろん！　すぐそこ・・・カートをこっちのほうに！」（カチャリという音とともに何かがずれる音）
	　
	　「良ければ中身を検めたまえ」
	　
	　「不要だ。この力、判らぬはずもない。それでいて初めて触れるような・・・これぞアマクテルその人の目に相違ない！　美しい。世界のすべてがこれを目の当たりにする」
	　
	　「あー・・・素晴らしいものなんだろうな、きっと！　これでアトモスと・・・そちらは恒久的に同盟を結んだわけだ！　上に戻って伝えてこようか？　君に引き合わせる準備ができたとね。オーク共を始末する手筈は整っているんだろう？　早くこっちに通してくれと、皆、首を長くして―」
	　
	　「行け、我がしもべよ。来る者は拒まぬと告げるがいい」
	　
	　「なっ、何を―」
	　
	　#{italic}#その背後で悲鳴が上がる。ゴボゴボという音。何かが砕けた。獣じみた咆哮が遠く響く。#{normal}#
	　
	　「我が主アマクテルは汝の働きに相応しい報いを与えん」
	　
	　さらに破壊音。
	　
	　「強靭な体を授けよう。優れた魂に作り変えてやろう。汝ら尽く主の寵に・・・」
	　
	　#{italic}#（パーマーの声が響く）#{normal}#  
	　
	　「ちいっ！　総員退避！　持てるだけ―」
	　
	　（記録終了）]], "_t")
t("strange black disk (3)", "不思議な黒ディスク（３）", "_t")
t([[#{italic}#(You hear loud, mechanical rumbling; in the distance, you hear sounds of struggling and bludgeoning, swords slicing through flesh, steamguns being fired, and shouts of pain from giant and horror alike.  Parmor sounds panicked.)#{normal}#

"Mayday, mayday, we are bailing out!  Tantalos is gone, and we are NOT going back for him!  Scrap the tunnel to the Palace of Fumes, scrap the entire damn council, we're getting as far away from here as we can--"  Loud hissing.  "MOTHER OF--!"  Grunts, squishing, slashing.  "Flooring it all the way to the damn Sunwall, we're taking the first farportal off this continent whether those tinies like it or not!  Guess this technically counts as treason, mutiny, whatever, but if the Council's hearing this, BLOW IT OUT YOUR STEAM-HOLES, WE'D RATHER LIVE!  Altitude rising, surface approaching, this is H.C. Parmor signing off--"]], [[#{italic}#　（機械音が鳴り響く。遠くで激しい戦いが繰り広げられているようだ。刃が肉を切り裂き、銃弾が飛び交う。ジャイアントと化け物共の悲鳴がない交ぜになっていた。パーマーはパニックに陥っているようだ）#{normal}#
	　
	　「メーデー、メーデー！　我々は撤退する！　タンタロスは行方不明！　見捨てるわ！　宮殿への通路なんてどうでもいい！　くたばれ議員ども！　進行可能ギリギリまでの地点に退―」
	　
	　大きくシューッという音。
	　
	　「このっ―」
	　
	　ググー、ゴボゴボ。一閃。
	　
	　「全速前進中。目的地はあの忌々しい太陽の壁。大陸端、この地における初の大ポータルを奪取する！　小人共の都合なんてしったこっちゃないわ！　これって反逆？　命令違反？　何とでも言え。聞いてる？　議員様方！　いけしゃあしゃあと偉そうに！　死んでたまるか！高度上昇、地表に接近。こちら噴霧司令官パーマー。通信終了―」]], "_t")
t("erratic scribblings", "妙な走り書き", "_t")
t("why is it down there why is it ANYWHERE", "なんで下にアレがいるんだ　なんでそこら中に", "_t")
t("If anyone finds this, tell the Jarsovi brothers their father lov", "これを読んでいる方へ　ヤルソビ家の子供たちに伝えてほしい　愛していると父", "_t")
t("Too many of them.  Couldn't pull more Atmos back in, wasn't safe, couldn't tell them from the others.  Hope we've got enough fuel to get us to the surface.", "ヤツら数が多すぎる　仲間の帰投はあれで限界　マズイ状況だった　敵味方入り乱れて　地上まで燃料が持てばいいんだが", "_t")
t("What have we done...  why didn't I stop it?", "なんてことを・・・止めていれば・・・", "_t")
t("nothing living should have that many", "あんな生き物がいるなんて　あんなにたくさんの", "_t")
t("so that's what it looks like.  what THEY look like.  now I see why so many depictions were destroyed", "アレはああいう姿なのか　ヤツらはああいう姿をしていたのか　記録がほとんど残っていない理由がこれで解った", "_t")

------------------------------------------------
section "tome-orcs/data/lore/internment-camp.lua"

t("internment camp", "拘留基地", "newLore category")
t("internment camp correspondence (1)", "拘留基地における書簡のやりとり（１）", "_t")
t([[#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

It's good to see that you and your followers have arrived safely! Hopefully you're settling in all right; thank you for coming, and pass my thanks on to the Elvala diplomats for getting you here on such short notice. I hope this is the first step in your kind - you Ogres, of course, but also the Shaloren who sent you here - joining forces with the Allied Kingdoms.

There are no Ziguranth here in the Far East, and the orcs in this camp have been compliant so far, on account of Mindwall's elaborate illusions. It's the most humane way to deal with them that we've found so far - we hope that his influence will have a permanent calming effect on them over time, but until then, they're happy and docile in their little dream-world. All you have to do is protect against any stragglers outside the walls looking to break their kin out of here, and patrol the halls to make sure any orcs who've managed to shake off the illusions are swiftly apprehended and dealt with. This should be a pretty easy job - if you need any particular help or provisions, though, let me know and I'll do what I can!

Sincerely,
Administrator Quellop

#{bold}#---#{normal}#

#{italic}#To: Administrator Quellop
From: Guard Captain Galsamae#{normal}#

We need four more chairs in the break room.

-Galsamae

#{bold}#---#{normal}#

#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

I'm sorry, but we can't really afford that, as the budget for amenities and luxuries is stretched pretty thin here as-is. Please try to keep your requests limited to necessities - even with Last Hope's merchants competing on price, the security over by the farportal means it's still not cheap to get things here.

Regretfully,
Administrator Quellop]], [[#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　御一同つつがなく到着されてなにより！　この地に上手く馴染めるといいのだが。よくぞ来てくれた。エルヴァラの外交官たちに感謝の意を伝えて頂きたい。急な話であるにも関わらずこちらに派遣してくれるとは。御一同が、これは貴官らオーガのみならず派遣元のシャローレも含んでのことだが、連合王国軍の一翼を担う第一歩となれば幸いである。
	　
	　ここ東方にはジグランスなど一人もいない。それにマインドウォールの見事な幻覚のおかげで、基地内のオークはすっかりおとなしい。奴らへの対応として、一番慈悲深いやり方が今のところこれなのだ。この抑制効果がいずれいつまでも続くようになるといいが。現時点では素敵な夢の世界で微睡んでもらっている。貴官らは仲間を解放せんと侵入してくる残党共を一人残らず撃退してくれればいい。あとは基地内を巡回して、幻覚から目覚めてしまったオークを少しでも見かけたら即座に確保し、対応してもらいたい。実に楽な仕事のはずだ。とはいえ何か困ったことや要望があるなら遠慮せずに言ってほしい。出来るだけのことはしよう！
	　
	　敬具
	　ケロップ管理官
	　
	#{bold}#---#{normal}#
	　
	#{italic}#　ケロップ管理官殿
	　
	　警備隊長ガルサメイより#{normal}#
	　
	　休憩室に椅子を４脚追加されたし。
	　
	　ガルサメイ
	　
	#{bold}#---#{normal}#
	　
	#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　申し訳ないが椅子を購入する余裕はない。娯楽品・贅沢品に関する予算は今の段階では大幅に制限を受けている。要望は必需品に関する方面に限定して頂きたい。都の商人たちも値下げ競争しているのだが、大ポータル周辺における安全確保の関係上、こちらに輸送する費用はなかなか安くならない。
	　
	　謝意を込めて
	　ケロップ管理官]], "_t")
t("internment camp correspondence (2)", "拘留基地における書簡のやりとり（２）", "_t")
t([[#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

I'm disappointed. I went around the camp for my first inspection today, and the hallways are filthy! Haven't you mopped them once since you got here? Not only that, but there was a guard sleeping on the job by the northwest corner! I thought you guys making a good impression was the entire point of this - if things keep going this poorly, I've got half a mind to ship you lot out and bring in some dwarves instead! They might not be cheap, but at least they're reliable!

Get your act together,
Administrator Quellop

#{bold}#---#{normal}#

#{italic}#To: Administrator Quellop
From: Guard Captain Galsamae#{normal}#

We need four more chairs in the break room. If you want the floors mopped, we'll need five chairs.

-Galsamae

#{bold}#---#{normal}#

#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

Do you have #{italic}#any#{normal}# idea how much it costs to transport an ogre-sized chair #{italic}#all the way out here?#{normal}# No.

With growing impatience,
Administrator Quellop]], [[#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　何だこれは。査察初日ということで基地内の見回りをしてみたが、廊下の汚れはどういうことだ！　赴任以来、一度でもモップ掛けをしたのか？　まだあるぞ。北西の曲がり角で勤務中にもかかわらず居眠りをしている警備がいた！　オーガの評判を上げるのが今回の第一目的ではなかったのか。この調子で続けるというなら、まとめて送り返し、代わりにドワーフ達に着任してもらった方がいいのではないか！　費用がかさむにしても、きちんと仕事をしてくれるだろう！！
	　
	　誠実に勤務するように
	　ケロップ管理官
	　
	#{bold}#---#{normal}#
	　
	#{italic}#　ケロップ管理官殿
	　
	　警備隊長ガルサメイより#{normal}#
	　
	　休憩室に椅子を４脚追加されたい。モップ掛けをする必要があるなら５脚。
	　
	　ガルサメイ
	　
	#{bold}#---#{normal}#
	
	#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　オーガサイズの椅子を#{italic}#はるばる#{normal}#ここまで持ってくるのに#{italic}#一体#{normal}#幾らかかると思っているんだ？　却下する。
	　
	　忍耐にも限度がある
	　ケロップ管理官]], "_t")
t("internment camp correspondence (3)", "拘留基地における書簡のやりとり（３）", "_t")
t([[#{italic}#To: Condescending Little Cretin
From: Guard Captain Galsamae#{normal}#

Listen here, you little cretin.

When we agreed to this, we requested 60 mind-caging helmets, properly sized, alongside 60 sets of mail armor, a minimum of 30 beds, and shifts of no more than eight hours a day. We GOT 35 helmets, and had to send 25 of our guards back lest they get sucked into Mindwall's illusions like these orcs - furthermore, the helmets were crudely modified, and wound up weighing about twice as much as they needed to. We got plate armor instead of mail, further increasing the burden each of us has to carry, and our reduced numbers mean we have to take 12-hour shifts. (Obviously, such a schedule leaves no time for mopping.) Combined with all that, we don't even have enough beds for everyone - depending on the day, 5 to 10 of us are stuck without a place to sleep.

With anyone else, this would be a recipe for a workforce that would quickly get exhausted. Our runes buy us a lot of time before that happens, but that saturation still builds up over time, and we need to rest. We can't just sleep on the floor, we're too big to not get sores from our weight pressing into a hard surface, so each shift, a few of us are stuck without sleep or rest. What you saw in the northwest corner was someone who'd collapsed from exhaustion, who has the longest patrol route and (due to my personal oversight, and I apologize for that) wound up being one of the few who couldn't sleep the previous night.

We know that getting more mind-caging helmets would cost a lot, as would more beds, so we've come up with the cheapest available option to fix this: more chairs. We can get almost as good a rest sleeping in a chair as we can in a bed, provided we throw in the couple of pillows we've managed to make from spare grain sacks. If we don't get this, though, my estimate is that within the next three months, we'll have another guard collapse on a main patrol route, not just that way-out-there one the last guy collapsed on. As in, close enough to the prisoners where his or her helmet might just roll off and into their grasp. And the moment some Orc puts that helmet on, it's all over.

We're fine with these miserable conditions. All things considered, it's still some of the best interpersonal interaction we've gotten outside of Elvala. We'd even be fine with a few of us dying from overwork, if that was the only consequence of such an awful work schedule - but it'd lead to a breakout. And we will NOT be blamed for ANOTHER catastrophe that WASN'T OUR FAULT.

I've said it before, and I'm saying it for the last time: #{bold}#WE NEED MORE CHAIRS IN THE BREAK ROOM.#{normal}# If you think it's too expensive, I will #{italic}#personally#{normal}# come down to your quarters and restrain you while my men confiscate your fancy little bed, desk, and dresser, then repurpose them as scrap lumber and padding to build ourselves some new chairs. I'm not any more comfortable with insubordination than you are, but this is quite literally a matter of life and death, and not just for my people.

-Galsamae

PS: If any mention of this is made to your superiors, I'll make sure they also know about the Atmos absinthe you had smuggled in here last week.]], [[#{italic}#　相手の事情に頓着しない愚かなチビ助殿
　
　警備隊長ガルサメイより#{normal}#
　
　よく聞け、この愚かなチビ助が。
　
　今回の仕事を請けるにあたって条件を出した。我らの頭に合う精神防御の兜を６０着、メイルアーマーを６０着、ベッドは最低でも３０床、さらに勤務時間は最長でも８時間交代と。ところが届いた兜は３５着。２５人を送り返さねばならなかった。あの兜が無いとオーク共と同じくマインドウォールの幻覚に囚われてしまうからな。しかも兜は無理矢理こちらのサイズに合わせたものではないか。おかげで本来の倍近く重くなっている。メイルアーマーの代わりに支給されたのはプレートアーマー。また重荷が増えたというわけだ。頭数が減ったせいで１２時間交代を余儀なくされている（このようなスケジュールではモップ掛けをする余裕などあるわけがない）その上、人数分のベッドすら満足に用意していないのだぞ。日によって異なるが、寝床が無くてどうにもならない者が５人から１０人は出てしまう。
　
　このような状況で働けば誰であろうとすぐに疲労困憊だ。我らはルーンのおかげで相当我慢が効くが、それでも次第に負荷が重なっていく。だから休息を取らねばならぬのだよ。床の上に身を投げ出すわけにはいかない。オーガは巨体故、固い寝床の上では自重で床擦れを起こす。従って交代毎にどうしても休息が取れぬ者が数名いる。北西の曲がり角でそちらが見たのは疲れのあまり倒れてしまった警備兵だ。最長の巡回ルートを担当し、前日寝床にありつけなかった（こちらの点に関しては見落としていた。謝罪する）ためにな。
　
　兜を増やしてもらうのは金がかかりすぎる。ベッドも同じだ。そこで一番安く済む解決策を考えた。椅子を増やしてもらおう。椅子があればゆっくり休める。予備の穀物袋を利用して作った枕を２つ添えれば、ベッドと大差ない。それでも椅子が無理だと言うなら、私の予測では３ヶ月以内に、今度は主要巡回ルートで倒れる者が出てくるだろう。この間、警備が倒れた出口への順路では済まない。仮にそこが囚人共の目と鼻の先で、兜がそのまま転がり落ちて奴らの手に渡ったら。オーク共が兜を被った瞬間に全ては水の泡だ。
　
　今の酷い環境でもこちらは構わない。思い起こせば、エルヴァラの外で受けた対応としてはこれでも一、二を争うほど丁重だ。過労で何人か死ぬことになったとしても甘受しよう。だがそれはあくまでも「この過酷な労働の末に」という意味である。現状を放置すればそのうちオークは脱走するだろう。*再び*大惨事が起きたとしても責められる謂われは*微塵も*ない。*当方の責任ではない*のだから。
　
　このことは以前にも要請した。これが最後通牒になる。#{bold}#休憩室に椅子を追加してくれ。#{normal}#これでもまだ「椅子は高過ぎる」と思っているなら#{italic}#勝手に#{normal}#そちらの兵舎に赴き、貴殿を拘束させてもらおう。部下達がその可愛いミニチュアみたいな家具を木材にバラして、自分で椅子を新調するぞ。こちらとて貴殿同様、勝手な真似をするのは気が引ける。だとしてもこれは文字通り生死のかかった問題だ。ただし当方の命に限った話ではない。
　
　ガルサメイ
　
　追伸
　
　この話を上官に漏らせば、先週ここで貴殿がアトモスアブサンの密売に関わっていたことも併せて伝わることになる。]], "_t")
t("internment camp correspondence (4)", "拘留基地における書簡のやりとり（４）", "_t")
t([[#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

I've requested an increase to our budget. Ten beds and eight chairs are on their way. Is there anything else you need?

With my sincerest apologies,
Administrator Quellop

#{bold}#---#{normal}#

#{italic}#To: Administrator Quellop
From: Guard Captain Galsamae#{normal}#

A steel hand-rail on the south staircase would be nice.

-Galsamae

#{bold}#---#{normal}#

#{italic}#To: Guard Captain Galsamae
From: Administrator Quellop#{normal}#

Done.

-Quellop]], [[#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　予算の増額を申請しておきました。ベッド１０床、椅子８脚を注文済みです。何か他に入用ですか？
	　
	　心よりお詫び申し上げます
	　ケロップ管理官
	　
	#{bold}#---#{normal}#
	　
	#{italic}#　ケロップ管理官殿
	　
	　警備隊長ガルサメイより#{normal}#
	　
	　南の階段に鉄製の手すりがあると有難い。
	　
	　ガルサメイ
	　
	#{bold}#---#{normal}#
	　
	#{italic}#　警備隊長ガルサメイ殿
	　
	　ケロップ管理官より#{normal}#
	　
	　設置しました。
	　ケロップ]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/krimbul.lua"

t("krimbul clan", "クリンブル族", "newLore category")
t("the journey of the Krimbul Clan", "クリンブル族の旅路", "_t")
t([[We are not people of great ambition or complex desires, we Minotaurs.  We seek not to choose a direction for the world, we wish not to spread across the land, we are content not to build great machines or greater empires.  What we wish more than anything is simply to live; alas, the rest of the world wishes that we do not.  We cannot say where or how the hostilities started...  if we had to guess, perhaps the soft-footed considered us a pest for seeking out homes in their storerooms and armories.  We are drawn to great magic, especially when it is concentrated into artifacts, and over the eons of persecution, we have developed an equally strong instinctual drive towards safe places underground (although, again, this is simply a guess).  If there is enough stray magic around, we can live on it without eating or drinking, and see no need to come to the surface; indeed, under such conditions we might not even age.  Most minotaur tribes that find a safe habitat - glowing with magic, and filled with enough dark twisting passages that the soft-footed will not come down in force - discover that they no longer need cooperation to survive, and slowly lose themselves to instinct; for a long time, it was only our willpower that made us different, and even that was beginning to wane.  In a way, maybe what happened to us was genuinely a blessing.

We cannot tell you how long ago it was, as we did not write down our history at that time, and we had more pressing concerns soon after.  At some point, though, we felt a home, better than any we'd ever felt before, through a long, long series of caverns and tunnels.  The magic here... it was incredible!  It...  well, you do not have a word for it, but "tasted" is close enough - different than anything we'd absorbed before, hearty and rich, and it soaked into our tired bodies so easily.  We did not even need to stop to rest, it kept us so rejuvenated...  so we kept going down, losing track of how far it was.  In truth, I think we walked the length of a continent, if not more, cheerfully pressing onward, eager to see what awaited us at the end.

If only we'd noticed that what we were feeling wasn't rejuvenation.

Our leader, Garnok of the Stormy Fist, was the first to fall victim to it, and if he hadn't done so in such dramatic fashion, we may have all been lost.  His eyes became frantic and wandering as we walked onward, and he began making odd, pained grunts before stumbling and falling.  We heard a crack, and suspected that he may have broken an arm; we dashed closer to him, but stopped when his back and shoulders bulged and shifted, shortly before several tentacles burst from him, covered in the blood, fur, and skin that they dragged with them.  He simply pushed himself up with these new appendages, as though nothing was wrong.

We backed away from him, and he grew wild, grabbing at Karbatha the One-Horned and surging that unfamiliar magic that saturated these caverns; at once, a strange creature burst forth, separating the two before hovering over us.  He made false promises to us as Nektosh ran to his sister's side, claiming that Garnok's fate was a gift, and asking us to join him.

We are simple, but we are not fools.  We ran; we felt a wave of magic surge forth, sickly like rotten meat, and Karbatha cried out in her brother's arms.  We kept running, as the tunnels bent back and forth, spiraling upward, until we were certain the creature had lost sight of us...  and then we heard a message in our minds.  "It's too late.  The blessing is already within you, and these tunnels are far too long to escape before it takes root.  Come back, so we can guide it into a form you will find pleasing."  And from deeper back in the tunnels, we heard a bellow from what used to be Garnok.

As we examined ourselves, feeling tiny hints of that blighted magic within us all, Nektosh took Karbatha away to a hastily-assembled tent, and she...  well, she was gone.  After the commotion ended, he strode out and gave a remarkably lucid assessment: the magic seemed to only work on the living.  Karbatha's illness stopped when her heart did...  and although it was certainly a drastic idea, if we couldn't purge this curse through some other means, we had to consider purging the life it fed on instead.

He was not our only necromancer, but the idea was still nearly unthinkable...  until we realized that it was growing.  There were no visible signs, our bodies and minds were resisting it...  but it was only a matter of time, and perhaps even less time for Nektosh.

We reluctantly agreed, and he prepared the spells and potions needed to keep us mostly as we were, but bereft of life.  Preserved, strong, even feeling and smelling when most liches could not..  but still cut off from Nature's gifts entirely, and still incapable of bearing young.  This generation would not age to death, but it would nonetheless be our last.  He volunteered to be the last one, only instructing another of us on how to convert him once all of us had been treated...  Whether it was because the infection had more time to fester within him, or because of what he suffered through in his sister's tent, Nektosh has never really been the same since then.

In a cruel twist of fate, we found what would have been paradise not long after our escape - the Mana Caves, laden with magic, but we only needed a tenth of it now as we did alive.  Nonetheless, it has been our home ever since...  most soft-feet would have raided the caverns and wiped us out like common vermin, but the Kruk Pride treated us with respect and dignity that perhaps no minotaur OR undead creature has received before (let alone the combination).  We are still a reclusive people, and our current state gives us even fewer reasons to need trade with them...  but they are the closest thing we have ever had to friends, and I suspect that right now, we are that to them as well.]], [[　我らは大それた目標を掲げることもなければ、あれこれと望みを抱くこともない。我らミノタウロスは。ただ世の趨勢に従い、現状維持を良しとする。世紀の大発明や広大な版図を手にしようとも思わない。ただ平和に暮らしていきたいというのが何よりの願いである。悲しいかな、世界はそれを許さぬのだ。我らが敵視されるようになった大元の理由は定かではない・・・あくまで推測になるが、柔き蹄の者達はこちらを宝物庫や武器庫を荒らす害獣と見なしたのではないだろうか。我らは強力な魔力に惹かれてしまう。アーティファクト内部に凝縮されている魔力ならなおさらだ。そして幾世代にも渡って迫害を受ける内に、強い衝動が芽生えた。魔力を求める本能に負けず劣らず、安住の地を地下に探し求める習性である（重ねて言うがこれはあくまでも推測である）魔力が存分に漂っている場所ならば、我らはそれだけで生きていける。水も食事も不要だ。従って、地上に出る動機がない。事実、そのような場所で暮らしていれば年を取ることすらないだろう。ミノタウロスの部族は安住の地－魔力満ちる暗闇に通路が複雑に行き交い、柔き蹄の者達が大挙して攻め入ることのない地－を見出すと大抵の場合、「もう仲間がいなくても生きていける」と悟り、次第に理性を失っていく。クリンブル族が永らく理性を保っていたのは、ひとえに意志の力によるものだ。とはいえ、その意志も次第に淀みつつあった。考えようによっては、我らの身に起こった出来事は僥倖と言えるものだったのかもしれぬ。
	　
	　どれくらい前のことかは判らない。当時クリンブル族には歴史を記す習慣がなかったからだ。直後に差し迫った問題を抱えたせいもある。ともあれ、ある時我々は住処とすべき場所を感じ取った。坑道入り組む洞窟の奥深くに、楽園と言うべき場所があると。そこに漂う魔力は・・・途轍もないものだった！　どう表現したものか・・・そちらの言葉では言い表せないが「味わう」という単語で解ってもらえると思う。このような魔力を味わうのは初めてだった。芳醇で、疲弊した体へあっという間に染み渡っていく。「少し休みを取ろう」という気さえ起きなかった。この魔力のせいでまるで疲れを覚えなかったのだ・・・そうして我らは下へ下へと降りていった。どれほど進んだのか判らなくなるほどに。実際のところ、大陸を横断するほどの距離を進んだのではないか。それほどでないにしても、意気揚々と歩を進め、「一体最深部には何があるのか」と心を焦がしていた。
	　
	　「疲れを知らない」という感覚になぜ違和感を覚えなかったのか・・・
	　
	　我らの長、「嵐拳のガーノック」が最初の犠牲者となった。長に降りかかった災いがあれほどの惨劇だったからこそ、クリンブル族は全滅を免れたのかもしれない。先へ進むうち、ガーノックの瞳は狂乱の態を見せ始め、苦しげに妙な唸り声を上げるようになった。そして躓き、倒れたのだ。何かが割れる音が聞こえたので、我らは長の腕が折れたのだと思い駆け寄ったが、その足が止まった。背中から肩にかけて体が膨らみ、蠢いていたからだ。直後、何本もの触手が飛び出した。血に塗れ、食い破った毛皮と皮膚が至る所にこびりついている。ガーノックは新たに生えた触手で以って平然と立ち上がった。まるで何事もなかったかのように。
	　
	　一同が身を引く。ガーノックが猛然と「一本角のカーバサ」に掴みかかり、洞窟内に充満するあの未知の魔力がうねる。その時、奇妙な生物が突如姿を現し二人を引き離した。そして宙から皆を見下ろす。ネクトッシュが妹のカーバサに駆け寄る中、その生き物は虚言を弄した。「これなる変容は天の恩寵。共に浴するがいい」と。
	　
	　クリンブル族は素朴であっても愚かではない。我らは逃げた。魔力の波が押し寄せてくるのを感じながら。それは悪臭を放つ腐肉の洪水に似ており、カーバサが兄の腕の中で悲鳴を上げる。走って、走って、坑道を進んでは戻り、螺旋を描くように上へ登っていく。ついにあの生き物を振り切った・・・と確信した時、頭の中に声が響いた。「手遅れだ。既に寵はお前たちの中に下った。ここは地の奥底。逃れようとてその前に寵は根を張る。戻れ。お前たちの気に入る形に導いてやろう」
	　
	　そして遠く背後でガーノックだった物の咆哮が深淵に轟いた。
	　
	　各々の体を検めてみると、全員の中にかの悪しき魔力の気配が微かに認められた。一方ネクトッシュはカーバサを仮設テントに隔離し、そこで・・・彼女は・・・息を引き取った。ネクトッシュはひとしきり痛哭した後、テントを飛び出し、至極明瞭に己が知見を述べた。曰く「この魔法は生あるものにしか効かぬようだ。心臓が止まった瞬間、妹の症状は消えた・・・」さらに「奇策には違いない。しかしこの呪いを除く手段が無いのなら、代わりに原動力となっている命を除去するのも視野に入れねば」とも。
	　
	　ネクトッシュはクリンブル族における死霊術の第一人者、というわけではなかったが、それにしても突飛な意見に思えた・・・ところがあの魔力は段々強くなっていったのだ。はっきりとした兆候は見えず、心身共に抑え込んではいたが・・・しかし後は時間の問題であった。恐らくネクトッシュにはその時が間近に迫っていただろう。
	　
	　仕方なく我らはネクトッシュの案に同意した。彼が手配した魔法とポーションは我々を極力元の状態に保ちながらも、命を捨て去るための物であった。劣化しない頑強な肉体。しかも慈悲の心を保ち、体臭もある。これはリッチにはまずあり得ないことだ・・・とはいえ、常なる生物とは全く異質の存在となる。次の世代を担う命も宿せない。我らは不老の生を得たが、同時に最後の世代となるのだろう。ネクトッシュは自らの施術を最後にすると申し出た。全員の処置が終わった時点でようやく、どうやって自身に施術するかを指導したのである・・・侵食を長時間許してしまったためか、それとも肉親の死に際して味わった悲憤のためか、以来彼はどこかおかしくなってしまった。
	　
	　何という運命の悪戯か。それから程なくして、本来なら楽園と言って差し支えない場所が見つかった。マナの洞窟だ。魔力に満ち溢れる地ではあるが、我らに必要な魔力量は生きていた頃の十分の一に過ぎなかった。それでも今に至るまで安住の地としているのであるが・・・柔き蹄の者ならば普通はマナの洞窟に攻め込み、我らを害獣の如く討ち果たそうとしたはずだ。だが、クルク族の者たちはクリンブル族を丁重に遇してくれた。このような扱いを受けたミノタウロス、なかんづく不死者は他に例を見ないだろう（まして手を取り合うなど）我らは依然、外界との接触に縁のない民であり、現状を鑑みるにクルク族と交易をする必要性は見当たらない・・・しかし彼らは我々にとって輩と言える初めての存在であり、思うにクルク族にとってもそれは同じ話なのではないだろうか。]], "_t")
t("a transcribed speech", "スピーチ原稿", "_t")
t([[Men and women of the Krimbul Clan!  I come before you today because with my awakening shall come a greater destiny, one we shall all share.  The dawn of a new age is at hand, and it would do you no good to sleep through it.  Allow me to open your eyes, before I lead you to our ultimate destiny!

Unicorns!  I'm sure you know the story of these incredible creatures, their beauty and power.  The Humans know it too!  And the Orcs!  And the Steam Giants - they ALL had their own variants on this myth, a one-horned creature of incredible magical potential, but an elusive one.  For many years, I have told you that Karbatha and I were descendants of these "mythical" creatures, and you denied it!  For just as many years, I could not prove it...  but all that changed when the flying machine fell in the lake.  None of you foolish cowards wanted to go down and investigate, none of you - so I had to go down instead.

Fortunately, your ignorance paid off.  Without any of you other wastrels to scare it off, the unicorns of old myth, the creatures that have stayed hidden from me because you were all too close, finally found me in enough privacy to grant me their blessing.  Even still, they did not directly appear to me...  but in their own way, they awakened the power that it has always been my right to possess, the strength that has lied dormant inside me for so long.  And AWAKEN IT DID!

Look, to the south, at Frostgraze Mountain!  Do you see the hole through it?  THAT is my power, a mere side effect of what happened when some insolent swine dared to question it!  THAT is the power I have always had, the power I have always deserved, the power that shall now lead me to my rightful place over the Giants, the Orcs, and Nature itself!

Cheer!  CHEER, DAMN YOU!

Now...  as your new Lord, you are lucky that I am a merciful one.  I grant you all a tremendous honor, the opportunity to serve me and personally witness the fall of all who would oppose me.  Gone are the days of hiding from the Steam Giants, gone are the days of treating those Kruk Orcs as equals.  Gone are the days of the living claiming dominion over this world; they shall bow to us for the mercy of being made undead, or I shall personally annihilate them.  The living - and those who would not join me - shall be crushed under our hooves, and the world shall be ours!
]], [[　クリンブル族の諸君！　本日、私は君たちの上に立つ。何故ならば、この新たな力によって私は大いなる栄光を手にするからだ。この栄光を部族の者は等しく享受することになる。新時代の夜明けまであと少し。惰眠を貪っていては身のためにならぬぞ。まずは一同の蒙を啓こう。その上で皆を完全なる勝利に導こうではないか！
	　
	　ユニコーン！　この聖獣にまつわる伝説を耳にしたことがあるはずだ。美と力を併せ持つ驚異の存在。人間も！　オークも！　巨人も！　皆例外なく、独自の変化が加わったユニコーン伝説を伝えていた。途轍もない魔力を有するが、滅多に姿を見せない独角獣のことを。長きに渡り、「我ら兄妹は『伝説に謡われる』ユニコーンの裔である」と訴えてきたが誰も耳を貸さなかった！　その歳月を、血の証が立てられぬまま・・・だが空を行く機械が湖に落ちて、状況は一変する。愚かで小心なる諸君は一人も湖中に赴こうとはしなかった。誰一人として。そこで代わりに私が調査に赴く仕儀となったわけだ。
	　
	　幸いにも諸君らのその愚かさが良い方向に転がった。無用な騒ぎを起こす、有象無象と距離を置いたおかげだ。古のユニコーン。諸君らが間近にいたせいで姿を見せなかった聖獣が、ようやく衆目の届かぬ所で私を見出し祝福を授けてくれた。とはいえ、直接姿を現したわけではないが・・・まあいい。ユニコーン達は独自の方法で私の力を引き出してくれた。生まれながらにして約束された力。遥か以前より私の中に眠っていた力を。そう、私は目覚めたのだ！
	　
	　南を見よ！　雪食みの山を！　あの山を貫く穴が見えるか？　あれこそ我が力！　傲岸不遜な豚が異を唱えた折、巻き添えで開いたに過ぎぬ！　今まで秘めていた力。私は最初からこれを振う資格を有していた。この力を以って、然るべき高みへと昇ろう！　ジャイアント共を従え、オーク共を従え、そして生あるもの全てを征服する！
	　
	　称えよ！　称えよ愚民ども！
	　
	　さて・・・私を王に戴く諸君らは幸せ者だ。私は慈悲深い君主だからな。素晴らしい栄誉を授けよう。私に仕える幸運に浴し、まつろわぬ者どもが滅びる様を見よ。スチームジャイアントに怯える日々はもう終わった。クルクのオークなんぞと誼を結ぶ必要もない。生者が世の覇権を唱える時代は終焉を告げたのだ。皆こぞって不死者となるべく首を垂れることになる。さもなくばこの手で消し去ってくれよう。全ての生者、そして私に歯向かうものは我らが蹄の下に斃れる。世界は我らのものだ！
]], "_t")
t("personal journal of Nektosh the One-Horned", "「一本角のネクトッシュ」の手記", "_t")
t([[no no no no no no no no no no no no no

I can feel it running out...  the voice spoke to me again, said "Warning, low energy, less than ten pulses remaining," and the energy that once flowed so beautifully through this artifact is beginning to grow cold.  No matter how much I beg and plead down in the lake, the unicorns will not come to me directly, will not tell me why I've angered them or what I could do for them to keep my power...  was this power ever mine in the first place...?

...  All right.  So, five to ten more uses...  I need to think about how this is going to work.  I've gone way too far to simply back out and act like everything should go back to normal - hee hee, can you imagine...  what do i do what do i do i can't keep stalling the conquest i can't come clean i can't win against the steam giants i can't i can't

someone just told me the giants attacked the orcs, the orcs won

I...  yes.  I've got a way out.  The Orcs must be weakened, wounded, easily dealt with or at least intimidated.  My people march on Kruk Pride, I arrange a meeting with the Giants and tell them the favor I did them, give them back the artifact if I can get it out of my horn without blowing my hand off...  they'll shelter me.  they'll give my people a plot of land.  they'll...  they'll do something that gives me some chance of not getting trampled by an angry mob...

i'm sorry karbatha]], [[ああああああああああああああああああああああああ　力が消えていく・・・また声がした。「警告　エネルギー残量小　残り１０回未満です」　このアーティファクトの中を煌びやかに流れていたエネルギーが冷たくなっていく。湖底でひれ伏しても、ユニコーン達は姿を見せない。私の何が悪かったのか、この力を保つにはどうしたらいいのかも教えてくれない・・・そもそもこれは本当に私の力だったのか・・・？
　
　・・・いいだろう。あと五回から十回・・・これをどう活用するか思案せねば。今更手を引いて、何食わぬ顔で全て無かったことにするような真似は・・・ハハッ、とてもじゃないが・・・どうするどうする攻撃は延ばせぬ事情を説明するのはもっての外スチームジャイアントに勝つのも無理だ無理だ無理だ
　
　ついこの間ジャイアント共がオークに攻撃を仕掛けたとか。それでオークが勝った。
　
　なら・・・よし・・・活路が開けた。今オーク共は疲弊しているに違いない。攻めるなら今だ。そうでなくとも勢いを削がれているはず。クルク族へ兵を出そう。ジャイアント共と会談の席を設けて、奴らの為に何をしてやったのかを伝えるんだ。このアーティファクトも返そう。角から取り外すときに私の手が原型を留めているといいが・・・ジャイアント共に匿ってもらおう。ジャイアント共なら我が民に猫の額ほどの領土を分けてくれるはずだ。ジャイアント共なら・・・ジャイアント共なら暴徒の手を逃れうる何がしかを手配してくれる・・・
　
　済まないカーバサ]], "_t")

------------------------------------------------
section "tome-orcs/data/lore/misc.lua"

t("sunwall observatory", "天文台", "newLore category")
t("an astronomer's journal", "星界師の日記", "_t")
t([[The strange movement on the far side of Wintertide continues - a shadow here, a tiny speck or flash of light there.  Still obscured and difficult to identify.  Obfuscating magic is likely at work, but whether it's on our end or Wintertide's, I cannot say.

The nebula behind the Neira constellation continues its slow fading.  Star Gerlyk-P is gone now too, and by most current models, Amakthel-N will be next.  If the last century is any indication, the rate of disappearances is accelerating...  this is most worrying, but what may be more worrying is that Star Quekjora-B has reappeared in an abrupt flash of light, powerful enough to illuminate the night sky for a brief moment.  It is oscillating between green and purple now, a far cry from its original glow of pale orange, and does not quite seem to be spherical...  I can feel its power from here just like I can Shandral or our two moons, dimly but growing stronger.  It's impossible to meaningfully speculate on something so unprecedented, so I will not write my theories down here, but none of them are reassuring.

Aside from these phenomena, all is normal.  The cracks on Mal'Rok and the other Spellblaze-blasted planets in other systems are still slowly fading, and the lights on more distant worlds continue to twinkle.  Stars outside the Neira constellation remain steady, or decay according to standard astronomical models.]], [[　冬輝の月の裏では相変わらず不思議な現象が続いている。こちらには影が差し、あちらでは小さな点や閃光が見えるのだ。依然ぼんやりとしていて判別は難しい。魔法の力によって観測が困難になっていると思われるが、イヤルと月、どちら側で働いているものなのかは分からぬ。
　
　ネイラ座の背後にある星雲は次第に光が弱くなっていっている。ゲーリュクＰ星も消えてしまい、現時点でのモデルによれば、次はほぼ間違いなくアマクテルＮ星だ。前世紀の観測結果から判断するに、加速度的に星が消えていく・・・由々しき事態だ。だがさらに気がかりなのは、クェコージャＢ星が突如光を放って再び空に現れたことだろうか。あまりの眩さに夜空が一瞬明るくなったほど。今の色は緑から紫の間を揺れ動いており、本来の淡い橙色とは似ても似つかない。その姿もきれいな球形にはなっていないようだ・・・まさにシャンドラルや２つの月のように、この場所からクェコージャＢ星の力を感じる。微かではあるが、しかし強くなってきているのだ。前代未聞の事態に対して満足のいく推論は立てられない。よってここに私の説を記すのはやめておこう。だが、どう考えても楽観はできない。
　
　これらの点が気がかりだが、他におかしなところはない。マル・ロックや他星系において魔法大禍の被害を受けた惑星。それら表面の亀裂は、現在も徐々に薄くなっている。もっと遠くにある星々の輝きにも依然変化なし。ネイラ座外の星は安定しており、一般的な天文モデルに従って崩壊している。]], "_t")
t("ureslak's lair", "ウレスラックの巣", "newLore category")
t("a note lying in a puddle", "水たまりに浸かった書置き", "_t")
t([[If you think I'd just leave my plans lying around for anyone to find them, you're an even greater buffoon than Rak'Shor's followers.  You, unlike them, are of no use to me.  [b]Die.[/b]

[i](The bottom half of the paper is illegibly smudged, on account of water dripping onto it from a stalactite above, but has the approximate shape of an explosive-rune trap.  You drop the note, wary of any lingering power it might still have.)[/i] ]], [[　己が計画を捨て置き、衆目に晒すとでも思っていたのかこの大馬鹿者めが。ラク・ショルの信徒共の方が余程ましというものだ。奴らには使い道があるからな。[b]死ぬがいい。[/b]
　  
　[i]（書置きの下半分は滲んで読めなくなっている。天井の鍾乳石から水が滴っているためだ。だが、爆発のルーンがおおよその形を留めている。もしかしたらまだ作動するかもしれない、と書置きを投げ捨てた）[/i] ]], "_t")
t("var'eyal", "ヴァル・イヤル", "newLore category")
t("dropped demonic orders", "デーモン達への指令", "_t")
t([[I'm not going to lie to you: things aren't going great.  Between the Doomelf escape incidents, the deaths of Khulmanar and a great deal of our more expensive combatants at the hands of the Anomaly, and the disappearance of the First Duathedlen, we've been set back pretty far this year.  As such, your orders are simple: lay low.  Stay out of sight, and conduct passive observation until we can get a foothold and a new plan.

And regarding the First Duathedlen - quit your murmuring right now.  I've seen his track record, and I know most of you know it too, which is why we can safely say that despite his... nature, his loyalty is [b]not[/b] in question - we can assume his abrupt cessation of communication is a necessary part of his investigations, and not him going rogue.  If you see him, tell us of his whereabouts, but do not interfere.

[i](The letter is signed with an unreadable but formal-looking demonic seal.)[/i] ]], [[　率直に言おう。状況は芳しくない。ドゥームエルフの脱走事件に端を発し、クルマナール様を始め貴重な戦力が次々とかの「異分子」の手に斃れた。そしてデュアセドレン第一号の失踪。今期は大幅に後退してしまった。従って諸君への指令は単純なものとなる。時を待て。隠密行動を取り、情報収集は最低限に留めよ。その間に拠点を確保し、新たに計画を練る。
	　
　デュアセドレン第一号についてだが・・・憶測でものを言うのは今後一切禁ずる。奴の足跡はこちらで追っている。諸君らが話しているようなことは十分把握済みだ。よって断言しよう。奴は・・・気質に問題はあっても忠誠心に疑わしいところはない。急に連絡を絶ったのも、調査の一環として必要だったからと思われる。任務を放棄したとは考えにくい。見かけたら居場所を報告すること。接触はするな。

　[i]（この手紙には判で名前が押してある。何と書いてあるのか判別できないが、デーモンが公式文書で使うもののようだ）[/i] ]], "_t")
t("bootlegger's complaint letter", "密造酒業者の小言", "_t")
t([[Look, I know the whole point of this market was to make a place for ANY sort of open trade, without the Allied Kingdoms' scryers breathing down our necks, and I know it's not exactly feasible to set up another portal off the continent...  but do you have any idea how bad it is for business to have the slavers using this with us?  Nobody's going to want to have a nice mug of unregulated-strength ale or pick up a shiny new stolen necklace when, not ten yards away, some helpless person is being led away in chains and wailing in misery.

I'm telling you, ditch the slaves and you'll be bringing in ten times as many patrons for everything else.  Whatever your boss is paying you for the slaves, you'll make more than that - and if you're using the manual labor for yourself, just use the excess funds to buy golems!  Win-win decision, in my opinion.]], [[　なあ、確かに「*どんな*商品でも自由に取引できる場を用意しよう」っていうのがこのマーケットの理念だ。連合王国の予見術師共に付きまとわれずに済むようにな。この大陸沖にもう１つ大ポータルを設置するのだってちょっと無理のある話だろう。だがな、奴隷商と共同で大ポータルを使うととてつもない損失が出るんだぞ？　思い切り度数の高いエールを一杯やったり、故買屋で新品のネックレスを手に取る客がいなくなる。なんたって目の鼻の先で、鎖に繋いだ哀れな奴隷がめそめそ泣きながら引き立てられていくんだぜ。
　
　いいか、もう奴隷を扱うのはやめよう。そうすりゃ他の商品に今の１０倍は客が入るようになるさ。あんたのボスが奴隷にどれだけ払ってくれるかは知らないが、こっちの方がよほど儲かるぞ。人手が要るってんなら、余った資金でゴーレムを買えばいいじゃないか！これがお互いの為に良いと思うんだがな。]], "_t")
t("wand-smuggler's apology letter", "ワンド密売人の謝罪文", "_t")
t([[My sincerest apologies, Admiral.  I received the conjuration wands in bulk, and I had no idea that several of them were merely wands of trap destruction - testing each one would have drained some charge from each, providing an inferior product.

I will be retrieving what portion of the cheerblossom I can get from my deceptive supplier, or her head - whichever you would prefer.  At that point, I will ask that you please consider revoking my banishment from your marketplace.]], [[　大変申し訳ございません、提督。あの大量に仕入れた攻撃魔法ワンドですが、罠解除のワンドが混じっているなど思いもよりませんでした。１つ１つ振って確認していては封入した魔力を消費してしまい、商品を万全の状態でお届けできなくなるものでして。
　
　インチキ問屋にはありったけのバーサークフラワーポーションで償わせます。さもなくばあの女の首を。お好きな方をお選びください。つきましては、マーケットからの除名をご再考下さるようお願いいたします。]], "_t")
t("slaver's inquiry", "奴隷商人の提案", "_t")
t([[The anti-scrying nexus you folk set up here is damn impressive, as is the time-release pseudo-rune powered by it - hard to find a spare spot on my skin for it, but I can feel it working for a few days after I'm back in Maj'Eyal.  Great for making sure we can get away from the West portal and disperse without the A.K. catching on or tracking us to a common point of convergence.

Got a proposal, though.  With a few little tweaks, I could make one that doesn't require the bearer's consent to use.  You aren't the only ones buying slaves from me, and when I get a customer who wants them taken right back to the West, we have to do the anti-scrying enchantments ourselves.  I don't know if you've noticed, but proper mages still aren't easy to come by - I barely made a profit last time I did it.

Say the word, and I'll send over the temporary rune design so you can set the nexus to recognize it.  No charge from me - if you accept it, it'll pay for itself.

[i](You assume the elaborate, glowing shape below is an Ogric equivalent to a signature.)[/i] ]], [[　友よ、君がここに設置した対予見術システムはまったく素晴らしいな。こいつを利用する時限式疑似ルーンも実に見事。私の肌にルーンの空きを探すのには苦労したが、マイ・イヤルに戻ってから数日は効き目が残る感じだ。これなら西方の大ポータルを出てから確実に姿を晦ませるぞ。連合に気取られることもなければ、いつもの集合地点を追跡される心配もない。
　
　だが１つ提案がある。何ヶ所か少し改良すれば、ルーン保持者の意向を無視して使えるようになると思う。君の他にも奴隷を買ってくれる客がいてね。相手方が商品をすぐに西方に持ち帰りたい場合には、こちらで対予見術魔法を処置しなきゃいけない。気づいているかは知らないが、そういうことができる魔法使いは今でも気軽に雇えるものじゃない。この前雇ったときはほとんど利益が出なかったよ。
　
　もし良ければ、短期型ルーンの図案を送ろう。認証できるよう、そちらのシステムを設定してくれたまえ。代金は要らないさ。使ってくれるならそれが何よりの報酬だよ。
　
[i]　（下段にある光り輝く複雑な図形はオーガが署名に使うものなのだろう）[/i] ]], "_t")
t("STOP BLOWING OUR COVER", "足がつくようなマネはやめろ", "_t")
t([[We get it: it's our fault the farportal mailing system isn't perfect.  Our people are still working on undoing that jury-rigged configuration that keeps your portal from transporting anything that isn't living - and if we get it wrong, that means people start getting teleported into walls again.  It's already a damn miracle you can get through the portal without coming out naked on the other side, let alone still carrying your backpacks and all their contents.

In the meantime: we're still losing a few letters going through the mailing system, and the lost ones could end up teleported to pretty much anywhere.  They could end up ten feet from the portal, or they could end up right in some A.K. busybody's hands, or they could just warp themselves right up Urh'Rok's nose for all we know.  Likewise, anything written on those notes could end up exactly where you don't want them, wherever that might be.

My point is, when you're writing those letters, write them like King Tolak's looking over your left shoulder and your grandmother's looking over your right - or at least show SOME semblance of subtlety.  Don't complain about the prices of "illegal potions," complain about "extra-strength medicine."  Don't ask about safety accommodations for "slaves," ask about "private servants."  And please, for the love of Linaniil, [i]stop calling the farportal a farportal![/i]  The A.K. doesn't even know we [i]have[/i] this thing yet, and we don't want to give them any ideas on where or how to start looking.  Call it a courier, or a pack golem, or a trained uruivellas for all I care.

-Korbek

PS: Yes, I'm breaking my own rules with this letter - you idiots clearly don't understand subtlety, so I can't assume you'd understand a subtly-written letter.  Yes, I'm aware there's a chance this letter could end up in enemy hands.  No, the irony of that situation would not be lost on me.  Yes, I will hurt whoever thinks they're clever by bringing up any of the preceding.]], [[　わかったぞ。こっちの手違いで大ポータルの転送システムに不味いところがあった。手下共があの適当な設定をせっせと直している。そっちのポータルが生き物しか通さねえのはこの設定のせいだ。しくじれば、また壁ん中に転送されるハメになるな。今だってちゃんと服を着たまま出てこれるってのは奇跡みてえなもんよ。しかも荷物袋も中身ごと全部無事ときた。
　
　今のところ、転送した手紙がまだちらほらと行方不明になっている。どこへ転送されたんだか分かったもんじゃない。ポータルの近くかもしれんが、おせっかいな連合の奴らの手に収まっているかもしれねえ。ひょっとしたらアーロックの目の前かもしれんな。同じ話になるが、ああいう手紙に書いたことが知られちゃならん奴の手にそのまま渡るってこともある。そいつがどこの誰であろうともだ。
　
　要するにだ、ああいう手紙を書くときには左後ろでトラックのヤツが、右後ろで婆様が見張ってるつもりで書くんだ。でなきゃせめて書き方をちっとは工夫しやがれ。「ご禁制のポーション」の値段に文句をつけるな。「強精剤」と書け。安全な「奴隷」収容所の話題も厳禁だ。「使用人」だろうが。それにリナニールにかけて、後生だから[i]大ポータルを大ポータルって言うのをやめろ！[/i]　連合はこいつが俺たちの[i]手元[/i]にあるなんざ夢にも思ってねえ。どこでどんなふうにアタリをつければいいかなんて手がかりはこれっぽっちも握らせるかよ。だから輸送機だとか荷造りゴーレムとか、調教済みのウルイヴェラスだとか何でもいいがそういう風に呼べ。
　
　コーベクより
　
　追伸
　
　おうよ、この手紙自体言ってる事と逆だってか。手前らマヌケ共は手紙の上手い書き方をちっとも解ってねえからな。遠回しに言ったところで伝わるはずもねえ。そうだな、こいつが奴らの手に渡るってこともあるだろう。ああ、その皮肉はわからんでもない。よし、今の話を持ち出してくるお利口さんは一人残らずぶちのめしてやるぞ。]], "_t")
t("severed hand", "切断された手首", "_t")
t([[[i](You see here a rotting human hand in a black leather glove, severed at the wrist.  It is still clutching a cracked artifact resembling an Orb of Many Ways, with a note folded up between the orb and its palm.)[/i]

"Drew the short straw" for the calibration [i]my entire ass.[/i]  That cheat used translocation magic and everyone there knew it.  If there's one thing I miss about the Ziguranth, it's that with them around, you only had to watch for sleight-of-hand and wear a mind-caging cap to avoid getting ripped off.

Speaking of ripoffs, why are we trusting this corpse-lover anyway? I guess it WOULD cost more to make a fake this convincing than we paid for it, but...  why would Tannen have made a portal that only works on the living, then used it to pay off a necromancer, [i]the only type of person who'd call that a downside?[/i]

Well, I guess that's what made him a [i]mad[/i] alchemist, and not some rich potion-brewer living comfortably.  Not like anyone can ask him now, except for who we got this altar from.

Anyway...  Korbek, if you're reading this, it means those crotch-heights screwed up again.  Send them back the orb, and hopefully it'll tell them what they need (well, as far as I'm concerned, [i]hopefully[/i] it'll blow them apart).  You got the calibration right on your end, and your poorly-disguised thugs are doing just fine (and stop with the illusions, it's just insulting, we don't care who or what you are as long as your gold glitters).  We just need to get the signal lock straight on our side, and we'll be able to fill the order you sent over, and then some.

Seriously, though, I'm writing this note so even if I get killed from this, I'm doing you a favor.  If I'm dead, I'd appreciate you showing your gratitude by making sure that ankle-biting son-of-a-ritch has played his last game of musical straws.
]], [[i]　腐敗した人の手がある。黒革の手袋をはめており、ちょうど手首のところで切断されている。それでもなお手中にはひび割れたアーティファクトを握りしめていた。分岐のオーブに似ている。オーブと掌の間にはきっちりと折りたたんだ紙が挟まっていた。[/i]
　
　*ハズレクジを引いて*較正作業をすることになっちまった。[i]まんまとカモにされちまったよ畜生め。[/i]あのイカサマ野郎は位置替えの魔法を使ってた。あそこにいた奴らは全員分かってやがったんだ。ジグランスのことで一つ頭から抜けてたことがあるとするなら、奴らがそばにいる時はとにかく妙な真似をしないように目を光らせ、精神防護の帽子を被ってぼったくられないようにするってことだな。
　
　ぼったくるって言えば、何だってあの死体マニアを信用するんだ？　これほどのレプリカは自前で作るよりかは買った方が*きっと*安くつくだろうが・・・タンネンが生き物しか転送できないポータルを作った理由がさっぱり解らん。さらにそいつを死霊術師との取引に使ったんだからなあ。[i]「生き物しか」ってのを欠点呼ばわりするのはああいう連中くらいのものだろう？[/i]
　
　ああ、そんなんだから[i]イカレた[/i]錬金術師と呼ばれるようになったんだろう。ポーションで大儲けして悠々自適ってわけにはいかなかったな。今となっちゃタンネンに事情を聞ける奴も限られてくる。このポータルの卸元くらいのもんだ。
　
　どうでもいいか・・・コーベクよう、こいつを読んでいるってことは「裾上げ」がまた不味いことになってるってことだ。このオーブをあいつらに送り返してくれ。奴らの知りたいことがこれで解るといいな（まあ俺としてはオーブがあいつらの手元で大爆発してくれると[i]いいんだが[/i]）そっちでは較正がちゃんと終わってる。正体バレバレなアンタの手下共はよくやってるよ（だがゴマカシはやめろ。そいつは人を舐めた話だ。アンタの素性なんてどうだっていいさ。金払いさえ良けりゃな）あとはこっちでシグナルをきちんとロックすればいい。そうすりゃアンタが送ってきた指令も果たせるし、いろいろご期待に沿えるってわけだ。
　
　まあ、真面目な話、コイツを書いているのは例えこれで死ぬハメになっても、アンタの仕事はしっかり果たしておきたいからだ。俺が死んだら感謝のしるしに、あのクソガキが二度と藁クジでイカサマができんようにしてくれるとありがたい。
]], "_t")
