section "tome-orcs/data/quests/amakthel.lua"

t("The Dead God Awaits", "死せる神待ちいたり", "_t")
t("Deep within Eyal you found a huge cavern containing some of the remains of the great dead god Amakthel...", "　イヤルの深淵で巨大洞窟を発見した。そこには死せる最高神アマクテルの肉体の一部が・・・", "_t")
t("Along with what appears to be a living Sher'tul that seems to be trying to resurrect him.", "　さらにシェール・タルの生き残りと思しき者がアマクテルの復活を企てているようだ。", "_t")
t("It must be stopped at all cost, the Prides only just got their freedom back, you can not allow anything to take it away again!", "　アマクテルの復活は何としても阻止せねばならない。オークたちは自由を手にしたばかり。これをまた脅かそうというのなら、誰であろうと許さない！", "_t")
t("The Sher'tul Priest has been taken care of, Amakthel will keep on sleeping forever now. The Prides and the world are safe.", "　シェール・タルの大祭司は斃れた。最早アマクテルが目覚めることはない。オークと世界の平和は守られた。", "_t")
t("#LIGHT_GREEN#You have won the game!.#WHITE#", "#LIGHT_GREEN#　*勝利*しました！#WHITE#", "_t")
t("#CRIMSON#You feel as if your Rod of Recall is working again in this area.", "#CRIMSON##CRIMSON#　帰還のロッドが使えるようになったみたいだ。", "log")
t("Orc Warrior", "オークの戦士", "_t")
t("Winner", "勝利", "_t")
t("#GOLD#Well done! You have won the Tales of Maj'Eyal: Embers of Rage!#WHITE#", "#GOLD#　おめでとうございます！　「憤怒の残火」キャンペーンで*勝利*！#WHITE#", "_t")
t("You have thwarted the Steam Giants' genocidal plans, and avenged those killed in the attack on Kruk Pride.  Their desperate pact with the High Priest did nothing to stop you; the priest and his god lay dead at your feet, and you have ensured they will #{italic}#stay#{normal}# dead for the foreseeable future.", "　スチームジャイアントのオーク殲滅作戦を阻止し、仲間の仇を討ちました。 追い詰められた彼らはシェール・タルの大祭司と手を結びましたがそれも功を奏さず。死せる神とその僕は地に伏しています。あなたの目の黒いうちは*このまま*のはずです。", "_t")
t("The humans, elves, and halflings will not be able to hurt your people again.  By destroying the farportal and denying King Tolak's army its glorious battle, you have ensured the safety of your people from the Allied Kingdoms, and by storming the Gates of Morning you have eliminated the last bearers of the West's hateful aggression in Var'Eyal.", "　人間、エルフ、ハーフリングたちに脅かされることはもうありません。  大ポータルを破壊し、トラック軍の聖戦を退けた今、連合王国の脅威は去りました。暁の門を強襲し、滅ぼした以上オークを狩り立てる西方の拠点はこの大陸から全て消えました。", "_t")
t("For now, peace reigns.  You know that this will not last forever.  You may have repelled its vanguard, but the Kar'Haïb Dominion bides its time waiting for a weakness it can exploit; the smugglers' portals from Maj'Eyal remain undiscovered, and while neither you nor King Tolak has any remaining desire to take the other's continent, the fear of invasion will linger in the backs of your minds.", "　とりあえずは平穏な時代が訪れたのです。しかしこれも何時まで続くことやら。 先兵を退けたとはいえ、カー・ハイブは虎視眈々とこちらの隙を窺っています。マイ・イヤルからこちらへと繋がる闇商人達のポータルも未だ所在は判らず。トラック王もあなたも、もうこれ以上の戦いは望んでいませんが、西方側の侵攻は考慮に入れておかねばなりません。", "_t")
t("  The messages of the Lost City give you cause to remain ever vigilant for the threats they warned of, including their authors, and you wonder what your people will do now that their struggle to escape eradication, one that has defined them for their entire recorded history, has ceased to be a concern.", "　「滅びし都」の者達が警告した数々の脅威にも絶えず目を配らなければ。その中には警告した本人達も含まれます。滅びを逃れんと足掻く彼らは有史以来、種の存続を行動原理としてきました。あの者達を懸案事項のリストから外すためにオークは何をしたらいいのでしょうか。", "_t")
t("Regardless...  You just killed a god and gave your people the first chance to relax in thousands of years.  It's been a pretty good day.", "　それでも・・・神を殺し、同胞達に数千年来初の平和をもたらしました。今日は実にめでたい日です。", "_t")
t("You may continue playing and enjoy the rest of the world.  Your soldiers may want to speak with you outside...", "　ゲームを続け、世界を探索してもかまいません。オークたちが外であなたとの歓談を待ち望んでいることでしょう・・・", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/annihilator.lua"

t("Research. Tinker. Annihilate.", "調査。製作。ぶっ壊せ。", "_t")
t("Inside some of your foes you have found some intact pieces that give you new ideas.", "　敵の残骸から新たな発明のヒントとなる無傷の部品を回収した。", "_t")
t("Keep on killing mechanical contraptions or steam-related foes...", "　スパイダーマシンや蒸気機関に関係する敵を倒していこう・・・", "_t")
t("#LIGHT_GREEN#* You destroyed a mecharachnid equiped with a flamethrower. Both those things could prove very useful.#WHITE#", "#LIGHT_GREEN#*　火炎放射器を搭載したスパイダーマシンを破壊した。２つとも参考になりそうだ。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have studied the 'remains' of an greater or ultimate hethugoroth, providing new ideas for ways to annihilate with heat.#WHITE#", "#LIGHT_GREEN#*　強力なヘスゴロスの「死体」を調査し、熱気で敵を殲滅する着想を得た。#WHITE#", "_t")
t("#LIGHT_GREEN#* The impressive Automated Defense System remains will prove very useful to create automated and self-deploying constructs.#WHITE#", "#LIGHT_GREEN#*　自動防衛システムの残骸は参考になる。自律兵器を開発するのに役立つことだろう。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/destroy-sunwall.lua"

t("The Deconstruction of Falling Stars", "星墜ちて新たな夜明け", "_t")
t([[The people of the sunwall have lingered on this land for too long and now they are spreading their control to all the mainland. This must not be allowed!
With the help of their newfound allies in the west they keep a permanent guard over the farportal. The portal must be permanently destroyed to prevent reinforcements.
The leader of the Sunwall, High Sun Paladin Aeryn must be punished for her crimes against the Prides.]], "　太陽の壁の奴らは延々とこの地に跋扈してきた。そして今また勢力を全土に伸ばそうとしている。これを許すわけにはいかない！奴らは新たに西方勢力と手を結び、大ポータルの周辺一帯を堅持している。金輪際援軍を送れぬよう、このポータルを破壊しなければ。太陽の壁の指導者、高位騎士エアリンに裁きの鉄槌を下すのだ。", "_t")
t("#LIGHT_GREEN#* You have killed Aeryn, making sure no more troops will come from the west.#WHITE#", "#LIGHT_GREEN#*　エアリンを殺し、西方からの援軍を断ち切った。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/free-prides.lua"

t("Children of Garkul, Unite!", "集えガークルの子らよ！", "_t")
t("All the few remaining orcs of the mainland have been captured by Sunwall and their western allies.", "　太陽の壁と西方勢力は手を結び、僅かに生き残ったオークたちを本土で捕らえている。", "_t")
t("To ensure a future, any future, for our race they must be freed.", "　オークが未来を手に掴むためには、それがどんな未来であろうとも、とにかく同胞を解放しなくては。", "_t")
t("The internment camp is located somewhere to the north. The orcs are subdued into obedience by a powerful #{halfling}# psionic, Mindwall, and guarded by elite Sunwall troops.", "　オーク拘留基地は北方にある。マインドウォールという強大な超能力者がオークたちの精神を支配しており、太陽の壁の精鋭が警護に当たっている。", "_t")
t("Mindwall must be taken care of and the prides set free.", "　マインドウォールを始末し、各部族を解放しよう。", "_t")
t("But #{bold}#BEFORE#{normal}# that you should go and destroy the Sunwall Observatory to the east, as our spies have found a way to resist Mindwall's psionic powers which requries #{italic}#ingredients#{normal}# from there.", "　だが#{bold}#その前に#{normal}#東にある天文台を攻略した方がいい。こちらが放ったスパイ達がマインドウォールの超能力に対抗する手段を発見した。それには天文台にある#{italic}#材料#{normal}#が要る。", "_t")
t("#LIGHT_GREEN#* You have destroyed Mindwall body but he managed to split his mind into many pieces and taken direct control of the subdued orcs. Destroy the pillars in each level four other levels.#WHITE#", "#LIGHT_GREEN#*　マインドウォールを斃したが、奴は自らの精神を無数に分割し、精神支配したオーク達に憑依していた。各エリアにある４つの柱を破壊しろ。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Vor Pride orcs.#WHITE#", "#LIGHT_GREEN#*　ヴォー部族を解放した。#WHITE#", "_t")
t("#GREY#* You need to have free the Vor Pride orcs.#WHITE#", "#GREY#*　ヴォー部族を解放しよう。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Rak'Shor Pride orcs.#WHITE#", "#LIGHT_GREEN#*　ラク・ショル部族を解放した。#WHITE#", "_t")
t("#GREY#* You need to have free the Rak'Shor Pride orcs.#WHITE#", "#GREY#*　ラク・ショル部族を解放しよう。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Gorbat Pride orcs.#WHITE#", "#LIGHT_GREEN#*　ゴーバット部族を解放した。#WHITE#", "_t")
t("#GREY#* You need to have free the Gorbat Pride orcs.#WHITE#", "#GREY#*　ゴーバット部族を解放しよう。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have freed all the Grushnak Pride orcs.#WHITE#", "#LIGHT_GREEN#*　グルシュナク部族を解放しよう。#WHITE#", "_t")
t("#GREY#* You need to have free the Grushnak Pride orcs.#WHITE#", "#GREY#*　グルシュナク部族を解放した。#WHITE#", "_t")
t("#LIGHT_GREEN#* The Pride is once again free and united.#WHITE#", "#LIGHT_GREEN#*　全ての部族が再び自由となり、手を取り合った。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


