section "tome-orcs/data/quests/gem.lua"

t("Mole Down, Two To Go", "壊れたモグラ・残す敵はあと２つ", "_t")
t("As you left the Gates of Morning in ruins you noticed a strange powerful tremor that seems to come from nearby.", "　廃墟となった暁の門を後にしようとしたとき、妙な地響きを感じた。発生源はこの近くのようだ。", "_t")
t("Investigating you have found a huge mechanical mole of obvious steam giant origin.", "　調べてみると巨大な機械モグラを発見。疑いようもなくスチームジャイアントのものだ", "_t")
t("#LIGHT_GREEN#* You have crushed both the horrors and the giants, making sure no precious information will come back to the Palace of Fumes.#WHITE#", "#LIGHT_GREEN#*　化け物どもとスチームジャイアントどもを葬り去った。これで「噴霧の宮殿」側は事態を把握できない。#WHITE#", "_t")
