section "tome-orcs/data/quests/kaltor-shop.lua"

t("The Grumpy Shopowner", "不機嫌な店主", "_t")
t("Kaltor's shop seems to be nearby in the mountain. Maybe it could be interesting to pay him a visit?", "　カルターの店は山の麓にあるらしい。顔を出してみるのも面白いかもしれない。", "_t")
t("He does sound well armed, though, so be prepared as it is likely very dangerous.", "　だが、警備は厳重なようだ。くれぐれも油断は禁物。", "_t")
t("So maybe take some time to plan the raid.", "　襲撃計画は慎重に練った方がいいだろう", "_t")
t("#LIGHT_GREEN#* You have disposed of Kaltor, the loot is yours!#WHITE#", "#LIGHT_GREEN#　カルターを始末した。お宝ゲット！#WHITE#", "_t")
t("#PURPLE#You heard a loud noise!", "#PURPLE#耳障りな音が響いた！", "saySimple")

------------------------------------------------
section "tome-orcs/data/quests/kill-dominion.lua"

t("This is our land!", "父祖より継ぎしこの大地！", "_t")
t("A group of trolls from the Kar'Haïb Dominion is trying to take foot on the mainland.", "　カー・ハイブ自治領から来たトロル共が本土に足がかりを作ろうとしている。", "_t")
t("With the Sunwall at full force we can not have the luxury of having to fight on both fronts, the Dominion port of the south must be destroyed.", "　太陽の壁が全力で向かってくる以上、両面作戦を取る余裕があるはずもない。南にあるカー・ハイブの港を潰さなければ。", "_t")
t("A potent bomb was given to you, you must place it at a weak spot of the tower where it will detonate and destroy the port.", "　強力な爆弾を用意した。これを塔のウィークポイントとなる部分に設置しよう。そこを爆破すれば港は壊滅する。", "_t")
t("It would be a good idea for you to not be there anymore when the bomb explodes however.", "　設置した後はさっさとずらかるのが賢明だろう。", "_t")
t("#LIGHT_GREEN#* You have destroyed the Dominion port, the trolls will not be a problem in the near future.#WHITE#", "#LIGHT_GREEN#*　カー・ハイブの港を爆破した。当面トロル共のことは気にしなくていい。#WHITE#", "_t")
t("Tower Detonator", "★塔破壊用爆弾", "_t")
t("This bomb was tailored to weaken the structure of the Dominion's port tower. If placed at the right spot it will explode after 100 turns and destroy the whole port.", "　カー・ハイブの港にある塔を崩すのにうってつけの爆弾だ。然るべき場所に設置すれば１００ターン後に爆発し、港は跡形もない。", "_t")
t("place the bomb on the structural weakness.", "　ウィークポイントに爆弾を設置しよう。", "_t")
t("Sewer Detonator", "爆破", "_t")
t("You must first locate the structural weakness in the Dominion's port tower.", "　まずは塔のウィークポイントを見つけなければ。", "_t")
t([[You place the detonator, you have 100 turns to get out or be destroyed by the explosion.
Use your #{bold}##GOLD#Rod of Recall#LAST##{normal}#!]], [[　爆弾を設置した。１００ターン以内に逃げないと道連れになる。
#{bold}##GOLD#帰還のロッド#LAST##{normal}#を使おう！]], "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/krimbul.lua"

t("Clan of the Unicorn", "ユニコーンの旗の下に", "_t")
t("Metash has asked you to investigate the Krimbul Clan, south of the peninsula.", "　メタッシュからクリンブル一派の調査を頼まれた。場所はクローク半島の南だ。", "_t")
t("A whitehoof turned mad with power is trying to lead them in a war against Kruk Pride.", "　力を得た白蹄族の者が変心し、クルク部族への戦いを扇動しているという。", "_t")
t("#LIGHT_GREEN#* You have stopped the pitiful Nektosh, ensuring one less threat for the Pride and a future for the Whitehooves.#WHITE#", "#LIGHT_GREEN#*　哀れなネクトッシュの息の根を止めてクルク部族の懸案事項を１つ減らし、そして白蹄族の未来を守った。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/kruk-invasion.lua"

t("Homeland", "部族を守れ", "_t")
t("The giants have breached the mountain-side of Kruk pride!", "　スチームジャイアント達が町の山側に穴を開けた！", "_t")
t("They are invading the town just when most of our forces are outside.", "　現在奴らは町に侵攻してきているが、こちらの主力は丁度出払っている。", "_t")
t([[Only you and few others are left to close the breach by collapsing the tunnel from the inside.
]], [[　自分を含め、残っているのは数名だけだ。この人員で地下通路を内部から破壊し穴を塞がなければ。
]], "_t")
t("#LIGHT_GREEN#* You have collapsed the tunnel, saving the Pride. For now.#WHITE#", "#LIGHT_GREEN#*　地下通路を爆破しクルク部族を救った。とりあえずは安心だ。#WHITE#", "_t")
t("#LIGHT_GREY#* You must place the bomb at the end of the tunnel to destroy it.#WHITE#", "#LIGHT_GREY#*　突き当たりに爆弾を設置し、地下通路を爆破しよう。#WHITE#", "_t")
t("Cave Detonator", "★地下通路破壊用爆弾", "_t")
t("This bomb was tailored to crumble the tunnel used by the Steam Giants to invade Kruk Pride.", "　スチームジャイアントがクルク部族の町を攻撃するのに通ってくる地下通路。こいつを爆破するのにお誂え向きだ。", "_t")
t([[You place the detonator, you have 220 turns to get out or be destroyed by the explosion.
Use your #{bold}##GOLD#Rod of Recall#LAST##{normal}#!]], "　爆弾を設置した。２２０ターン以内に脱出しなければ巻き添えになる。\\n#{bold}##GOLD#帰還のロッド#LAST##{normal}#を使おう！", "_t")
t("#LIGHT_GREEN#Kruk Pride is safe for now. Now is time for revenge!", "#LIGHT_GREEN#　クルク族の危機はひとまず去った。反撃に転じよう！", "saySimple")

------------------------------------------------
section "tome-orcs/data/quests/palace.lua"

t("No Fumes Without Fire", "火のない処に湯気は上らず", "_t")
t("The time for revenge is at hand! The Tribe stands crippled under your assaults.", "　逆襲の時は来た！　度重なる攻撃でアトモス族は揺らいでいる。", "_t")
t("Enter the Palace of Fumes and crush their leaders once and for all!", "　「噴霧の宮殿」に突入し、議会のメンバーを殲滅しろ！", "_t")
t("For Kruk!", "　クルク部族に勝利を捧げよ！", "_t")
t("For the Prides!", "　オークに勝利を捧げよ！", "_t")
t("For the Garkul!", "　ガークルに勝利を捧げよ！", "_t")
t("#LIGHT_GREEN#* Council Member Nashal is dead.#WHITE#", "#LIGHT_GREEN#　ナシャール死亡#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Tormak is dead.#WHITE#", "#LIGHT_GREEN#　トーマック死亡#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Pendor is dead.#WHITE#", "#LIGHT_GREEN#　ペンダー死亡#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Palaquie is dead.#WHITE#", "#LIGHT_GREEN#　パラクワイエ死亡#WHITE#", "_t")
t("#LIGHT_GREEN#* Council Member Tantalos is dead.#WHITE#", "#LIGHT_GREEN#　タンタロス死亡#WHITE#", "_t")
t("#LIGHT_GREEN#* You have destroyed the Council and shattered the Tribe.#WHITE#", "#LIGHT_GREEN#　議会メンバーは全滅し、アトモス族は瓦解した。#WHITE#", "_t")
t("What is all this noise about!", "一体何の騒ぎだ！", "_t")
t("Tantalos! What have you done!", "タンタロス！？　何という姿に！", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/quarry.lua"

t("Hunter, Quarry", "採掘場をぶっ飛ばせ", "_t")
t("The Steam Quarry is a strategic zone for the Atmos tribe, it provides them with much of their energy needs.", "　「蒸気採掘場」はアトモス族の要衝だ。必要なエネルギーは殆どここから供給を受けている。", "_t")
t("If you are to assault the Palace of Fumes you need to cut that supply off. Destroy the three giant steam valves to make the Palace vulnerable.", "　「噴霧の宮殿」を襲撃するならエネルギーの供給を絶っておかねばならない。巨大バルブを３つ全て破壊しよう。そうすれば宮殿の守りは薄くなる。", "_t")
t("#LIGHT_GREEN#* The first valve has been destroyed.#WHITE#", "#LIGHT_GREEN#　第一バルブを破壊した。#WHITE#", "_t")
t("#LIGHT_GREEN#* The second valve has been destroyed.#WHITE#", "#LIGHT_GREEN#　第二バルブを破壊した。#WHITE#", "_t")
t("#LIGHT_GREEN#* The third valve has been destroyed.#WHITE#", "#LIGHT_GREEN#　第三バルブを破壊した。#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/ritch-hive.lua"

t("A Ritch Party", "エッグパーティ", "_t")
t("Our ultimate goal on the mainland is to get rid of the Sunwall once and for all.", "　本土における最終目標は太陽の壁を永久に葬り去ることだ。", "_t")
t("To do that we will prepare a special surprise to help our final attack.", "　大望を果たすため、決戦に備えてとっておきのサプライズを用意しておこう。", "_t")
t("Go to the Ritch Hive in the mountains north of the Erúan desert and collect a big pile of ritch eggs.  About 30 viable eggs should be sufficient.", "　エリューアン砂漠北方の山脈に「リッチ虫の巣」がある。そこでリッチ虫の卵を大量に集めよう。３０もあれば十分だ。", "_t")
t("When you have enough, find a tunnel leading north and use the special sand shredder gloves tinker to open a path under the Gates of Morning.", "　集め終わったら北へと続く地下通路に入れ。砂壁粉砕ドリルを使って先へ進めば暁の門の下に出る。", "_t")
t("Finally, place the eggs in a protected spot to hatch.  With luck, they will provide a distraction while you later assault the city.", "　卵を誰にも邪魔されない場所に置いて孵化の時を待とう。運が良ければ暁の門へ攻め入った時に大騒ぎになる。", "_t")
t("#LIGHT_GREEN#* You have collected enough eggs.#WHITE#", "#LIGHT_GREEN#　卵は十分集めた。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have tunnelled close enough to the Gates of Morning.#WHITE#", "#LIGHT_GREEN#　砂壁を掘り、暁の門の下に出た。#WHITE#", "_t")
t("#LIGHT_GREEN#* You have placed the little surprise.#WHITE#", "#LIGHT_GREEN#*　ちょっとしたサプライズを仕込んだ。#WHITE#", "_t")
t("Stralite Sand Shredder", "★ストラライト製砂壁粉砕ドリル", "_t")
t("Automatically deploy a huge rotating drill when you hit a sandwall, carving out a big part of it quickly.", "　砂壁を殴ると自動的に巨大ドリルが回転し、瞬時に大穴が開く。", "_t")
t("You cannot bring yourself to drop the %s", "%sは捨てられない。", "logPlayer")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/start-orc.lua"

t("Of Steamwork and Pain", "立ち上る蒸気　流せ汗水", "_t")
t([[To win the war you must help the Pride by striking a blow to the giant's morale and supply lines.
]], [[　戦いに勝利するにはクルク部族の支援をせねば。ジャイアント共の士気を挫き、補給線を絶とう。
]], "_t")
t("#LIGHT_GREEN#* You have assaulted the Vaporous Emporium, crushing the morale of the Atmos tribe.#WHITE#", "#LIGHT_GREEN#　「霧の商業区」を襲撃し、アトモス族の士気を挫いた。#WHITE#", "_t")
t("#SLATE#* You must assault the Vaporous Emporium to crush the morale of the Atmos tribe!#WHITE#", "#SLATE#　「霧の商業区」を襲撃し、アトモス族の士気を挫け！#WHITE#", "_t")
t("#LIGHT_GREEN#* You have explored the yeti cave and vanquished the Yeti Patriarch.#WHITE#", "#LIGHT_GREEN#　イエティの族長を討伐した。#WHITE#", "_t")
t("#SLATE#* You must explore the Yeti Cave and destroy the patriarch!#WHITE#", "#SLATE#　「イエティの洞窟」を探索し、イエティの族長を討て！#WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/sunwall-observatory.lua"

t("Stargazers", "星を見る者", "_t")
t("Our ultimate goal on the mainland is to get rid of the Sunwall once and for all.", "　本土における最終目標は太陽の壁を永久に葬り去ることだ。", "_t")
t("Our scouts have noticed the Gates of Morning is being reinforced with sun and moon orbs.", "　斥侯によると暁の門は太陽と月のオーブで守られている。", "_t")
t("Go to the Sunwall Observatory and destroy everything there to reduce their supplies.", "　天文台を蹂躙し、暁の門への支援を絶て。", "_t")
t("#LIGHT_GREEN#* You have destroyed the Observatory, the Gates of Morning defenses will be weakened.#WHITE#", "#LIGHT_GREEN#　天文台を滅ぼし暁の門の戦力は低下した。#WHITE#", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/to-mainland.lua"

t("You Shall Pass!", "通ってよし！", "_t")
t("The Atmos tribe is not our sole problem. The Sunwall as grown in strength since the Scourge from the West came and murdered the other Prides leaders.", "　アトモス族の他にも敵はいる。「西の災厄」が現れ、四部族の長を手にかけてからというもの太陽の壁はその力を増している。", "_t")
t("Our brothers on the mainland lay enslaved, but before we free them you must secure a way to the mainland.", "　本土の同胞たちは囚われの身となった。まずは本土への道を確保し、救出に向かおう。", "_t")
t([[Go to the sunwall outpost. Show them the wrath of Garkul, show no mercy for they have none for us.
]], [[　太陽の壁の前哨基地へ行け。ガークルの怒りを知らしめるのだ。慈悲無き者達に情けをかける必要はない。
]], "_t")
t("#LIGHT_GREEN#* You have destroyed the sunwall outpost, and secured a way to the mainland.#WHITE#", "#LIGHT_GREEN#　前哨基地を潰し、本土への道を確保した。#WHITE#", "_t")
t("To the mainland!", "本土へ！", "_t")
t([[The way to the mainland is now clear.
Travel there using the bridge on the worldmap.]], [[　本土への道が開けた。
ワールドマップの橋を渡って進もう。]], "_t")

------------------------------------------------
section "tome-orcs/data/quests/voyage.lua"

t("Voyage to the Center of Eyal", "イヤルの中心へ", "_t")
t("In the Palace of Fumes you found a geothermal vent that digs deep into the planet's core.", "　噴霧の宮殿で火口を発見した。この星の中心に繋がっている。", "_t")
t("Strange mutated giants came out. You must find the source of those titans!", "　奇形化した不気味なジャイアントたちが姿を現した。奴らの正体を突き止めねば！", "_t")
t("#LIGHT_GREEN#* Travelling deep within Eyal you found the source of all corruptions: the dead god #{bold}##CRIMSON#Amakthel#LAST##{normal}#.#WHITE#", "#LIGHT_GREEN#　イヤルの奥底でこの惨事の元凶を見出した。死せる神#{bold}##CRIMSON#アマクテル！#LAST##{normal}##WHITE#", "_t")

------------------------------------------------
section "tome-orcs/data/quests/weissi.lua"

t("Mystery of the Yetis", "イエティの秘密", "_t")
t("You have found a bit of preserved yeti muscle, probably somebody somewhere will be interested.", "　保存状態のいいイエティの筋組織を入手した。どこかで役に立つだろう。", "_t")
t("For each yeti muscle you return to the psy-machines in the ruins of a lost city you will gain a great reward.", "　筋組織１つにつき滅びし都の超能力マシンから大きな見返りが貰える。", "_t")
t("#LIGHT_GREEN#* You have helped the strange psionic machines and got rewards out of them. You still feel like somehow you did wrong...", "#LIGHT_GREEN#　奇妙な超能力マシンの言葉に従い、見返りを貰った。これで本当によかったのだろうか・・・", "_t")
-- untranslated text
--[==[
t("", "", "_t")
--]==]


------------------------------------------------
section "tome-orcs/data/quests/yeti-abduction.lua"

t("Yeti Reinforcements", "イエティの援軍", "_t")
t("You found a yeti mind control tinker. If you can tame 8 wild yetis and send them back to Kruk Pride they can be trained and sent back to you at your request using a psychoportation beacon.", "　イエティの精神コントローラーを入手した。野生のイエティを８体捕獲してクルク部族の町に送れば向こうで調教してくれる。調教済みのイエティはサイコテレポートビーコンを使って好きな時に呼び出せる。", "_t")
t("Wild yetis are mostly found in yeti's caves.", "　野生のイエティは主に「イエティの洞窟」に生息している。", "_t")
t("#LIGHT_GREEN#* Captured eight yetis (will be available to summon at level 20).#WHITE#", "#LIGHT_GREEN#　イエティを８体捕獲した（レベル２０で召喚できるようになります）#WHITE#", "_t")
t("#LIGHT_GREY#* Captured %d/8 yetis.#WHITE#", "#LIGHT_GREY#　イエティを %d/8 体捕獲。#WHITE#", "tformat")
t("Yeti's Psychoportation Beacon", "★サイコテレポートビーコン", "_t")
t("Call a trained yeti to your side.", "　調教したイエティを呼び出せる。", "_t")
t("Yetis left to call: %d", "召喚可能イエティ: %d 体", "tformat")
t("call a trained yeti for help", "調教済みのイエティを呼び出して戦わせる", "_t")
t("The yetis are not ready yet.", "召喚できるイエティがいない。", "log")
t("Yeti", "イエティ", "_t")
t("You extract the psychoportation beacon from the mind controller. Yetis will require some time to train before being usable.", "精神コントローラーからサイコテレポートビーコンを抜き取った。イエティの調教にはしばらく時間がかかるはずだ。", "log")
-- untranslated text
