section "tome-orcs/data/talents/celestial/cosmic.lua"

t("Lunar Orb", "ルナオーブ", "talent name")
t("Fires out a bolt of cosmic energy in the target direction. The projectile continues until it hits a wall or the edge of the map, dealing %0.2f dark damage to enemies hit and restoring %d negative energy. The negative energy gained is reduced by 25%% per enemy hit, restoring a maximum of %d. Enemies hit will become aware of you.", "宇宙の力を目標地点へ放ちます。これは壁かマップの端に衝突するまで進み続けます。命中した相手に %0.2f の暗黒属性ダメージを与え月光力を %d 回復します。月光力の回復量は命中するごとに２５％減少します。回復量は最大で %d となります。これを受けた相手は術者に気づいてしまいます。", "tformat")
t("Astral Path", "アストラルロード", "talent name")
t("The spell fizzles: there are no available spots to teleport to.", "魔法が失敗した。テレポート可能な地点がない。", "logSeen")
t([[Fire an orb of negative energy towards a spot within range %d.
		When the orb reaches its destination, it will teleport you to its location.
		The speed of the projectile (%d%%) increases with your movement speed]], [[距離 %d 以内の目標地点に月光球を放ちます。
		　月光球が目標地点に到達すると術者はその地点にテレポートします。
		　月光球の飛行速度（ %d%% ）は術者の移動速度に依存します。]], "tformat")
t("Galactic Pulse", "ギャラクシィ", "talent name")
t([[Sends out a slow-moving spiral of cosmic energy towards a target location within range 8.
		As the cosmic energy moves, it pulls in targets adjacent to it, dealing %0.2f darkness damage and granting you 1 negative energy per hit.]], [[ゆっくりと移動する宇宙エネルギーの渦を半径８マス以内の目標地点に放ちます。
		　この渦は隣接した相手を引き込み %0.2f の暗黒属性ダメージを与えます。また、命中する毎に月光力が１回復します。]], "tformat")
t("Supernova", "スーパーノヴァ", "talent name")
t([[Expend all of your negative energy to create a massive burst of dark energy (radius %d) at a target location within range %d.
		This deals %0.2f darkness damage and pins targets hit for %d turns.
		The damage and pin chance increase with your spellpower, and the damage, radius and pin duration all increase with negative energy and talent level]], [[全ての月光力を込めて巨大な闇の力を解き放ちます。範囲は半径 %d マス、射程は %d マスです。
		　範囲内の相手に暗黒属性の %0.2f ダメージを与え %d ターン移動不能にします。ダメージ量と移動不能付与確率は魔法パワーに依存します。また
		　ダメージ、範囲、移動不能の持続時間は月光力とタレントレベルに伴って上昇します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/crepescula.lua"

t("Twilit Echoes", "トワイライトエコー", "talent name")
t([[The target feels the echoes of all your light and dark damage for %d turns. 

Light damage slows the target by %0.2f%% per point of damage dealt for %d turns, up to a maximum of %d%% at %d damage.
Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source while Twilit Echoes is active, dealing its remaining damage over the new duration as well as the new damage.]], [[対象は光・暗黒属性ダメージの反響を %d ターン受けます。
　対象は光属性の被ダメージ１点当たり %0.2f%% 減速します。持続時間は %d ターンです。減速量の上限は %d%% で、これは光属性被ダメージが %d ポイントの時です。
　暗黒属性のダメージを受けるとその場にダメージ場を %d ターン生成します。これはトリガーとなったダメージの %d%% 分を毎ターン与えます。トワイライトエコーの効果中はどんな暗黒属性ダメージを受けても、このダメージ場は上書きされます。この際、まだ与えていない分のダメージと、新たに生成して与える分のダメージを合計し、持続時間をリセットします。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/energies.lua"

t("Celestial Acceleration", "スタースピード", "talent name")
t("Increases your movement speed by %0.2f%% per percent of positive energy and your casting speed by %0.2f%% per percent of negative energy, up to a maximum of %0.2f%% at 80%%. Sustained energy still counts toward the maximum.", "陽光力１％につき移動速度が %0.2f%% 上昇します。また、月光力１％につき詠唱速度が %0.2f%% 上昇します。８０％時が上限となり最大で %0.2f%% となります。オンオフ系タレントで変化している分も割合計算に関与します。", "tformat")
t("Polarization", "分極化", "talent name")
t("Whichever of your positive and negative energies is a higher percentage regenerates towards its max instead of its normal resting value (%d positive, %d negative). Your negative and positive regeneration/degeneration rates are increased to %0.2f.", "陽光力と月光力の内、最大値に対する割合が高い方が最大値に向かって増加していきます。これは通常の休憩時における増減よりも優先されます（陽光力 %d 月光力 %d ）陽光力と月光力の変化量が %0.2f になります。", "tformat")
t("Magnetic Inversion", "磁力反転", "talent name")
t("Swap your current positive and negative energy levels. This spell takes no time to cast.", "現在の陽光力と月光力の値を交換します。この魔法は使用にターンを消費しません。", "_t")
t("Plasma Bolt", "プラズマボルト", "talent name")
t("Fires out a bolt of pure energy, dealing %0.2f light and %0.2f darkness damage in a radius of %d, and slowing targets hit. Their movement is reduced by %d%% and attacking, casting and mind attacks by %d%%. The bolt will attune to your current positive and negative energy amounts.", "純粋なエネルギーの塊を放ちます。範囲内に光属性の %0.2f ダメージと暗黒属性の %0.2f ダメージを与えます。範囲は半径 %d マスです。これを受けた相手は動きが鈍くなります。移動速度が %d%% 低下し攻撃、詠唱、精神速度が %d%% 低下します。このタレントの効果量は現在の陽光力と月光力に応じて変化します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/reflection.lua"

t("Diffraction Pulse", "回折パルス", "talent name")
t("Create a distortion at the target tile, knocking back all projectiles and changing their direction to face away if possible.", "指定したマスの空間を捻じ曲げます。飛来物を弾き、可能ならば進行方向を反転させます。", "_t")
t("Mirror Wall", "ミラーウォール", "talent name")
t("mirror wall", "鏡壁", "_t")
t("Creates a wall %d units long for %d turns, reflecting all projectiles that hit it and blocking sight.", "長さ %d マスの壁を生成します。持続時間は %d ターンです。これはあらゆる飛来物を反射し、また射線を遮ります。", "tformat")
t("Spatial Prism", "空間プリズム", "talent name")
t("Target a projectile in mid-flight to clone it and target that projectile independently. You gain ownership over the new projectile.", "飛行中の飛来物を１つ選択し、複製します。その複製を好きな所へ向けて打ち出します。このタレントの術者は複製した飛来物の発射元として扱われます。", "_t")
t("Mirror Self", "ミラーコピー", "talent name")
t("Mirror Image (%s)", "ミラーコピー (%s)", "tformat")
t("A cloned image of you.", "　術者のコピーだ。", "_t")
t("Mirror Self", "ミラーコピー", "_t")
t("Summons a clone for %d turns which casts all the spells you cast, dealing %d%% damage and having %d%% health. Additionally, all light damage the clone deals becomes darkness damage and all darkness damage becomes light damage.", "術者のコピーを作り出します。持続時間は %d ターンです。コピーは術者の有する全ての魔法を使用可能です。与ダメージには %d%% の補正が、ＨＰには %d%% の補正がかかっています。また、コピーが与える光属性ダメージは暗黒属性ダメージに、暗黒属性ダメージは光属性ダメージとなります。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/sol.lua"

t("Solar Orb", "サンオーブ", "talent name")
t("Solar Orb", "サンオーブ", "_t")
t("Fire out an orb of light that deals %0.2f light damage and then returns, dealing the same amount of damage again and reducing the cooldown by half (%d) when it reaches you. The damage will increase with your spellpower. The ball will travel at most %d distance to return to you.", "光弾を放ち %0.2f の光属性ダメージを与えます。この光弾は術者の元に戻ってきます。戻ってくる最中にも同じダメージを敵に与え、術者に到達するとこのタレントのクールダウンを半分短縮します（ %d ）ダメージは魔法パワーに依存します。光弾は戻る際に移動距離が %d マスを超えると消滅します。", "tformat")
t("Solar Wind", "ソーラーウインド", "talent name")
t("While sustained, this ability speeds up outgoing projectiles by %d%% while slowing incoming projectiles by %d%%. The increase and decrease improve with your spellpower", "起動中は術者が放つ飛来物の移動速度が %d%% 上昇します。また、術者に向かう飛来物は移動速度が %d%% 低下します。速度変化量は魔法パワーに依存します。", "tformat")
t("Lucent Wrath", "ソルキャノン", "talent name")
t("After %d turns, the target area in (radius %d) is blasted with a beam of light, dealing %0.2f damage and lighting the area", " %d ターン後、指定したエリア（半径 %d ）にレーザーが降り注ぎます。範囲内に %0.2f のダメージを与え、暗闇を払います。", "tformat")
t("Lightspeed", "光の速さで", "talent name")
t("%s moves at light speed!", "%sが光の速さで動く！", "logSeen")
t("Instantly gain %d%% percent of a turn.", " %d%% 分の行動ターンを即時獲得します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/celestial/void.lua"

t("Nebula Spear", "ネビュラスピア", "talent name")
t("Fire out a spear of cosmic energies. If it hits an enemy it deals %0.2f damage, otherwise it explodes in a thin cone of radius %d at the end of its range, blocked by enemies, which deals %0.2f to %0.2f damage depending on how much the enemies block.", "宇宙エネルギーの槍を撃ち出します。敵に命中すると %0.2f のダメージを与えます。誰にも命中しない場合、射程距離の終端で細長い扇状の範囲に爆発を起こします。この範囲は半径 %d マスです。範囲内の敵は %0.2f から %0.2f のダメージを受けます。これは爆発が敵によってどれくらい遮蔽されたかに依存します。", "tformat")
t("Crescent Wave", "クレセントダンス", "talent name")
t("Fires out a projectile in a clockwise arc. If it hits an enemy it deals %0.2f damage and roots them for one turn. If another projectile damages them within %d turns, they take half that damage and are rooted again.", "時計回りに弧を描く飛来物を撃ちます。これは敵に命中した場合 %0.2f ダメージを与え、１ターンの動きを封じます。対象が %d ターン以内に別の飛来物によってダメージを受けた場合、そのダメージの半分を与え、再び動きを封じます。", "_t")
t("Twilit Echoes", "トワイライトエコー", "talent name")
t([[The target feels the echoes of all your light and dark damage for %d turns. 

Light damage slows the target by %0.2f%% per point of damage dealt for %d turns, up to a maximum of %d%% at %d damage.
Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source while Twilit Echoes is active, dealing its remaining damage over the new duration as well as the new damage.]], [[対象は光・暗黒属性ダメージの反響を %d ターン受けます。
　対象は光属性の被ダメージ１点当たり %0.2f%% 減速します。持続時間は %d ターンです。減速量の上限は %d%% で、これは光属性被ダメージが %d ポイントの時です。
　暗黒属性のダメージを受けるとその場にダメージ場を %d ターン生成します。これはトリガーとなったダメージの %d%% 分を毎ターン与えます。トワイライトエコーの効果中はどんな暗黒属性ダメージを受けても、このダメージ場は上書きされます。この際、まだ与えていない分のダメージと、新たに生成して与える分のダメージを合計し、持続時間をリセットします。]], "tformat")
t("Starscape", "星界招", "talent name")
t("This spell cannot be cast here.", "ここでは唱えられない。", "logPlayer")
t("Summons the starscape in the surrounding area in a radius of %d. For %d turns, this area exists outside normal time, and in zero gravity. In addition to the effects of zero gravity, Movement of projectiles and other creatures is three times as slow. Spells and attacks cannot escape the radius until the effect ends.", "周囲に星界を喚び出します。範囲は %d マスです。持続時間は %d ターンとなります。星界は常なる時流の外に存在しており、重力が存在しません。無重力状態の他に、飛来物と他のキャラクターは移動速度が１／３になります。魔法や攻撃はこのタレントの効果が終了するまで星界の中に留まります。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/misc/npcs.lua"

t("Petrifying Gaze", "石化睨み", "talent name")
t([[Gaze at your foes and turn them to stone for %d turns.
		Stoned creatures are unable to act or regen life, and are very brittle.
		If a stoned creature is hit by an attack that deals more than 30%% of its life, it will shatter and be destroyed.
		Stoned creatures are highly resistant to fire and lightning, and somewhat resistant to physical attacks.
		This spell may fail against creatures resistant to being stunned, that are specifically immune to stoning, or certain bosses.]], [[敵をにらみ、石に変えます。持続時間は %d ターンです。
		　石化した相手は行動ができず、ＨＰが自動回復することもありません。さらに非常に脆くなっています。
		　石化中に攻撃を受け、一撃でＨＰの３０％分を超えるダメージを受けると砕け散って即死してしまいます。
		　石化した相手は火炎と電撃に非常に強くなっており、物理耐性も若干向上しています。
		　この魔法はスタンに抵抗力を持つ相手には効かないことがあります。石化を無効化するような相手、特定のボスが該当します。]], "tformat")
t("Gnashing Maw", "ガップリ行くぞ", "talent name")
t([[Hits the target with your weapon, doing %d%% damage. If the attack hits, the target's Accuracy is reduced by %d for %d turns.
		Accuracy reduction chance increases with your Physical Power.]], [[武器で攻撃し倍率 %d%% ダメージを与えます。命中すると対象の命中を %d 低下させます。持続時間は %d ターンです。
		　命中低下の成功率は物理パワーに依存します。]], "tformat")
t("Sandrush", "砂潜り", "talent name")
t("@Source@ dives in the sand!", "@Source@は砂地に潜り込んだ！", "_t")
t("You are too close to build up momentum!", "敵との距離が近すぎる！", "logPlayer")
t([[Dive into the sand and rush towards your target at up to range %d, gaining a free attack if you reach it.
		At the exit point, up to 9 sand pits will appear that last for %d turns (based on your Strength).
		You must rush from at least 2 tiles away.]], [[砂中に飛び込んで敵に突進します。射程は %d マスです。接敵すると追加攻撃します。
		　出現地点には最大で９マスの穴が出現します。個数は腕力に依存し %d ターン持続します。
		　実行するには対象との距離が２マス以上空いていなくてはいけません。]], "tformat")
t("Ritch Larva Infect", "卵を植える", "talent name")
t("@Source@ stings with her ovipositor!", "@Source@は産卵管を突き刺した！", "_t")
t([[Sting the target with your ovipositor, injecting %d larvae into it to finish their hatching process.
		Over a 5 turn gestation period, the larvae will feed on the victim internally, dealing %0.2f to %0.2f physical damage each turn (increasing as they grow).
		After the gestation period is complete, each larva will rip itself free of its host, dealing %0.2f physical and %0.2f fire damage.
		]], [[産卵管を対象に突き刺して幼虫を %d 体植え付け、孵化に向けての最後の一押しをしてやります。
		　幼虫は５ターンの間対象に寄生し、体の内側を食らって成長します。これによって対象は毎ターン物理属性の %0.2f から %0.2f ダメージを受けます。これは成長に伴ってダメージが増加します。
		　孵化すると幼虫は宿主の体を食い破って外に出ます。この際物理属性の %0.2f ダメージと火炎属性の %0.2f ダメージを与えます。]], "tformat")
t("Slumbering...", "眠りに・・・", "talent name")
t("@Source@ enters a deep slumber.", "@Source@は深い眠りに就いた。", "_t")
t("#STEEL_BLUE#%s slumbers...", "#STEEL_BLUE#%sは眠っている・・・", "saySimple")
t("#CRIMSON#%s awakens!", "#CRIMSON#%sが目覚めた！", "saySimple")
t("The Dead God slumbers. For now.", "死せる神は眠りに就いている。今のところは。", "_t")
t("Tentacle Spawn", "触手生成", "talent name")
t("@Source@ spawns a tentacle near @target@.", "@Source@は@target@の傍に触手を生み出した。", "_t")
t("You cannot summon; you are suppressed!", "召喚を封じられている！", "logPlayer")
t("Not enough space to summon!", "召喚する場所がない！", "logPlayer")
t("#ORCHID#%s summons a %s...", "#ORCHID#%sは%sを召喚した・・・", "logCombat")
t("#ORCHID#%s summons a %s...", "#ORCHID#%sは%sを召喚した・・・", "saySimple")
t("The Dead God wishes to tickle you...", "死せる神はこちらにちょっかいを出すつもりだ・・・", "_t")
t("Curse of Amakthel", "アマクテルの呪い", "talent name")
t([[Create a circle of cursed ground (radius %d) for %d turns. Any foes inside will be cursed, all new negative effects on them will have their duration doubled.
		]], "半径 %d マスの地面に呪いをかけます。持続時間は %d ターンです。範囲内にいる敵に対して新たにデバフが付与されるとその効果の持続時間が２倍となります。", "tformat")
t("Temporal Ripples", "時の波紋", "talent name")
t([[Creates a circle of radius %d of altered time for %d turns. Any damage your foes take while standing in it will heal the attacker for 200%% of the damage dealt.
		]], [[一定範囲内の時間を操作します。範囲は %d マスで持続時間は %d ターンとなります。この範囲内にいる敵がダメージを受けるとその２００％に等しい値だけ攻撃者のＨＰが回復します。
]], "tformat")
t("Saw Storm", "ソーストーム", "talent name")
t([[Summon a storm of swirling sawblades to slice your foes, inflicting %d physical damage and bleeding to anyone who approaches for %d turns.
		The damage and duration will increase with your Mindpower.]], [[荒れ狂う回転ノコギリを生成して敵を切り刻みます。近寄る敵に物理属性の %d ダメージを与え、さらに出血効果を付与します。持続時間は %d ターンです。
		　ダメージと持続時間は精神パワーに依存します。]], "tformat")
t("Razor Saw", "レイザーソー", "talent name")
t([[Launches a sawblade with intense power doing %0.2f physical damage to all targets in line.
		The damage will increase with Mindpower]], [[回転ノコギリを凄まじい速度で射出し、射線上の全ての相手に物理属性の %0.2f ダメージを与えます。
　ダメージは精神パワーに依存します。]], "tformat")
t("Rocket Dash", "ロケットラン", "talent name")
t("@Source@ rockets forward!", "@Source@はロケット噴射で飛んだ！", "_t")
t([[Dash forward using rockets.
		If the spot is reached and occupied, you will perform a free melee attack against the target there.
		This attack does 130% weapon damage.
		You must dash from at least 2 tiles away.]], [[ロケット噴射で前方へ飛びます。
		　対象地点に誰かがいる場合はその相手に対して攻撃を行います。これは倍率１３０％の武器攻撃です。
		　対象との距離が２マス以上離れている必要があります。]], "_t")
t("Mind Controlled Yeti", "精神支配イエティ", "talent name")

------------------------------------------------
section "tome-orcs/data/talents/misc/objects.lua"

t("steam", "蒸気", "talent category")
t("object techniques", "アイテム技能", "talent type")
t("Steam powers of the various objects of the world.", "　様々なアイテムを用いた蒸気機関の力です。", "_t")
t("Overgrowth", "オーバーライフ", "talent name")
t([[Instantly grow a moss circle of radius %d at target area.
		Each turn the moss deals %0.2f nature damage to each foe within its radius.
		This moss is very thick and sticky causing all foes passing through it have their movement speed reduced by %d%% and have a %d%% chance to be pinned to the ground for 4 turns.
		The moss lasts %d turns.
		Moss talents are instant but place all other moss talents on cooldown for 3 turns.
		The damage will increase with your Mindpower.]], [[対象の半径 %d マスに苔が生えてきます。
		　範囲内の敵は毎ターン %0.2f の自然属性ダメージを受けます。
		　この苔は極めて分厚く、粘着質なため、この上を通過する敵は移動速度が %d%% 低下し %d%% の確率で４ターンの間移動不能となります。
		　苔の持続時間は %d ターンです。
		　苔系のタレントは使用にターンを消費しませんが、発動すると他の苔系タレントに３ターンのクールダウンが発生します。
		　ダメージは精神パワーに依存します。]], "tformat")
t("Ceasefire", "トドメと行こうか", "talent name")
t("You require at least a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t("%s resists!", "%s は抵抗した！", "logSeen")
t([[You fire an incredibly potent shot at an enemy, doing %d%% damage and dazing them for %d turns.
		The daze chance increases with your Steampower.]], [[超強力な射撃を行います。これは倍率 %d%% の射撃です。また対象を %d ターン朦朧状態にします。
		　朦朧状態の付加確率は蒸気パワーに依存します。]], "tformat")
t("Surekill", "確殺銃", "talent name")
t([[You fire an exceptionally lethal shot at an enemy, doing %d%% damage.
Damage dealt by this talent is increased by half your critical multiplier, if doing so would kill the target.]], [[致命的な威力の射撃を行います。これは倍率 %d%% の射撃です。
　この射撃のダメージは使用者のクリティカル倍率の半分に等しい割合だけ上昇します。この効果は適用後、対象が死亡する場合にのみ適用されます。]], "tformat")
t("Rocket Smash", "ロケットスマッシュ", "talent name")
t("@Source@ rockets forward!", "@Source@はロケット噴射で飛んだ！", "_t")
t("You are too close to build up momentum!", "敵との距離が近すぎる！", "logPlayer")
t([[Dash forward using rockets.
		If the spot is reached and occupied, you will perform a free melee attack against the target there and knock them back 4 spaces as well as anyone else they collide with.
		This attack does 180% weapon damage.
		You must dash from at least 2 tiles away.]], [[ロケット噴射で突進します。
		　対象地点に誰かがいる場合はその相手に対して追加の近接攻撃を行い、４マスノックバックさせます。吹き飛ばした相手が誰かに衝突すると、そちらも同様にノックバックさせます。
		　この攻撃は倍率１８０％の武器攻撃です。
		　このタレントを使用するには対象との距離が２マス以上空いていなければいけません。]], "_t")
t("Laser Powered Smash", "レーザースマッシュ", "talent name")
t("@Source@ unleashes the power of the Gloryhammer!", "@Source@がグローリーハンマーの力を解き放つ！", "_t")
t([[Unleash the ultimate power of the Gloryhammer to all foes around in radius 1.
		This attack creates an explosion of radius 1 around every affected target, dealing 50% weapon damage and blinding them for 4 turns.]], [[グローリーハンマーの真価を半径１マスの敵全員に発揮します。
		　この攻撃を受けた相手のそれぞれ半径１マスに爆発を起こし、倍率５０％の攻撃ダメージを与えて４ターン盲目状態にします。]], "_t")
-- old translated text
t("object techniques", "アイテム技能", "_t")

------------------------------------------------
section "tome-orcs/data/talents/misc/races.lua"

t("race", "種族技能", "talent category")
t("yeti", "イエティ", "talent type")
t("The various racial bonuses a character can have.", "種族の特殊能力です。", "_t")
t("Algid Rage", "凍てつく怒り", "talent name")
t([[Your yeti is attuned to the cold climates.
		For 5 turns all damage you deal has %d%% chance to encase the target in an iceblock for 3 turns.
		While Algid Rage is up you easily pierce through iceblocks, reducing the damage they absorb by 50%%.
		The bonus will increase with your Willpower.]], [[イエティは寒さに適応した体の持ち主です。
		　５ターンの間、敵にダメージを与えると %d%% の確率で対象を氷漬けにします。氷牢の持続時間は３ターンです。
		　効果中は氷牢を易々と貫通できるため、氷牢に分散する分のダメージが５０％低下します。
		　確率は意志に依存します。]], "tformat")
t("Thick Fur", "防寒剛毛", "talent name")
t("Your yeti's fur acts like a shield, providing %d%% cold resistance, %d%% physical resistance and %d magical save.", "イエティの毛皮が盾のように機能します。冷気耐性が %d%% 上昇し、物理耐性が %d%% 増加します。また、魔法セーブも %d 増加します。", "tformat")
t("Resilient Body", "タフネス", "talent name")
t([[Your yeti's body is very resilient to detrimental effects.
		Each time you are hit by a physical, magical, or mental detrimental effect your body reacts with a burst of healing.
		This effect heals for %d and can only occur up to 3 times per turn.
		It increases with your Constitution stat.]], [[イエティの体は有害な作用に対して極めて頑健です。
		　物理、魔法、精神いずれかのデバフを受ける毎に強力な治癒力が働きます。
		　この効果によってＨＰが %d 回復しますが。これは１ターンにつき３回までしか発動しません。
		　回復量は耐久に依存します。]], "tformat")
t("Mindwave", "ブレインパージ", "talent name")
t([[You willingly fry a few parts of your yeti's brain to trigger a huge psionic blast in cone of radius %d.
		Any foes caught in the blast will suffer %0.2f mind damage and be confused (35%% power) for %d turns.
		The damage will increase with your Constitution and the apply power will be the highest of your mind, spell, or physical power.]], [[イエティの脳をあえて一部破壊することにより、強大な精神波が発生します。範囲は扇状の半径 %d マスです。
		　これを受けた相手は精神属性の %0.2f ダメージを受け、混乱します（３５％の確率で行動失敗）これは %d ターン継続します。
		　ダメージは耐久に依存し、混乱付与の判定には精神、魔法、物理パワーの一番高いものを参照します。]], "tformat")
t("whitehooves", "白蹄族", "talent type")
t("Whitehooves", "白き蹄", "talent name")
t([[Improves your undead body, increasing Strength and Magic by %d.
		Each time you move you gain a charge (up to %d) of death momentum, increasing your movement speed by 20%%.
		Each turn spent not moving you lose a charge.]], [[不死の肉体を強化します。腕力と魔力がそれぞれ %d 増加します。
		　また、移動する毎に「死の衝撃」のチャージが１増加します。チャージ数１点当たり、移動速度が２０％上昇します。チャージ数の累積上限は %d 点までです。
		　移動しないターンを挟むとチャージ数は１減少します。]], "tformat")
t("Dead Hide", "デッドスキン", "talent name")
t("Your undead skin hardens under stress. Each charge of death momentum also increases all flat damage resistance by %d.", "不死の体は外部から刺激を受けると硬化します。「死の衝撃」のチャージ数１点につき、被ダメージを固定値で %d 減少させます。", "tformat")
t("Lifeless Rush", "アンデッドダッシュ", "talent name")
t([[You summon your undead energies to instantly build up death momentum to its maximum possible charges.
		The effect will only start to decrease after %d turns.
		In addition, the death momentum effect also grants +%d%% to all damage per charge.]], [[不死力を呼び起こし、即座に「死の衝撃」のチャージ数を最大まで充填します。
		　これによりチャージ数が %d ターン後まで減少しなくなります。
		　また、チャージ数１点毎に与ダメージが %d%% 上昇します。]], "tformat")
t("Essence Drain", "デスドレイン", "talent name")
t([[You send a wave of darkness at your foe, dealing %0.2f darkness damage.
		The darkness will drain a part of its life essence (only works on living targets) to increase the duration before the next charge of death momentum is used by %d.
		Only usable when you have the death momentum effect.
		The damage scales with your Magic stat.]], [[敵を闇で飲み込み、暗黒属性の %0.2f ダメージを与えます。
		　この闇は敵の生命力を一部吸収し（生きている相手にしか効果を発揮しません）「死の衝撃」の持続時間が %d ターン増加します。
		　この効果を適用した後にチャージ数減少の処理を適用します。「死の衝撃」のチャージを獲得している状態でなければ使用できません。
		　ダメージは魔力に依存します。]], "tformat")
-- old translated text
t("yeti", "イエティ", "_t")
t("whitehooves", "白蹄族", "_t")

------------------------------------------------
section "tome-orcs/data/talents/psionic/action-at-a-distance.lua"

t("Condensate", "スチームプレス", "talent name")
t([[Condensate hot steam around your foes in radius %d, burning them for %0.2f fire damage and applying the wet effect for 4 turns, halving their stun resistances.
		The damage will increase with your Mindpower.]], [[半径 %d マスの敵の周囲に高温の蒸気を集めて %0.2f の火炎属性ダメージを与えます。さらに水浸し状態にしてスタン耐性を半減させます。
		　ダメージは精神パワーに依存します。]], "tformat")
t("Solidify Air", "ソリッドエア", "talent name")
t("solid air", "固形空気", "_t")
t("a piece of solidified air", "　この場所には空気が固形化している。", "_t")
t([[You concentrate your will in a cone in front of you, condensing the air into a tangible, solid form.
		Any creatures caught inside take %0.2f physical damage.
		Any places with no creatures will be filled with solid air, blocking the way for %d turns.
		The damage will increase with your Mindpower.]], [[扇状の範囲に意志を集中し、空気を固めて触れる程に固形化します。範囲内の相手は %0.2f の物理属性ダメージを受けます。
		　キャラクターが存在しないマスには固形化した空気が集まり %d ターンの間進行を妨害します。
		　ダメージは精神パワーに依存します。]], "tformat")
t("Superconduction", "超電導撃", "talent name")
t([[Call a streak of lightning on your target, dealing %0.2f to %0.2f lightning damage.
		If it is wet the lightning propagates to all foes in radius %d, doing the same damage to each.
		All affected foes are seared for 4 turns, reducing their fire resistance by %d%% and and mind save by %d.
		The damage will increase with your Mindpower.]], [[対象へ稲妻を放ちます。これは %0.2f から %0.2f の電撃属性ダメージです。
		　対象が水浸し状態の場合、半径 %d マス以内の全ての敵に対して伝播し、同じダメージを与えます。
		　これを受けた相手は４ターンの間、黒焦げになり火炎耐性が %d%% 精神セーブが %d 低下します。
		　ダメージは精神パワーに依存します。]], "tformat")
t("Negative Biofeedback", "生体抑制", "talent name")
t([[Any time you deal damage with a psionic ability you incur a negative biofeedback in your foes, stacking up to %d times for 5 turns.
		Each stack reduces their physical save by %d, defense and armour by %d.
		This effect may only occur once per turn.]], [[超能力系のタレントで敵にダメージを与えた際、対象の生体機能を抑制します。これは %d 回までスタックし５ターン持続します。
		　スタック数１当たり対象の物理セーブが %d 低下し、回避とアーマーが %d 減少します。
		　この効果は１ターン当たり１回までしか発動しません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/gestalt.lua"

t("Gestalt", "心機合一", "talent name")
t([[You let your mind tap into your steam generators for energy, increasing your Mindpower in proportion to your steam level: %d when at full steam and 0 when at 0 steam.
		Using a psionic talent will feedback into your generators, increasing your Steam power by %d for your next steamtech talent.
		Using a steamtech talent will feedback into psionic focus, increasing your psi level by %d.
		The effects increase with your Willpower.]], [[蒸気発生装置に精神を接続してエネルギーを利用します。精神パワーが蒸気の値に応じて上昇します。これは蒸気が最高値の時に %d となり０の時には０となります。
		　超能力系のタレントを使用した場合蒸気発生装置の出力が増加し、次に使用する蒸気機械系タレントの蒸気パワーが %d 上昇します。
		　蒸気機械系のタレントを使用した場合は理力の集中が高まり、Ｐｓｉが %d 回復します。
		　効果量は意志に依存します。]], "tformat")
t("Improved Gestalt", "ゲシュタルトバリア", "talent name")
t([[When you use a steamtech talent while Gestalt is active you drain some residual power to form a psionic shield.
		The shield forms for 3 turns and absorbs %d damage.
		The effects increase with your Mindpower.]], [[「心機合一」を起動している際に蒸気機械系のタレントを使用すると残余分のエネルギーを一部吸収して超能力シールドを形成します。
		　これは３ターン持続する強度 %d のシールドです。強度は精神パワーに依存します。]], "tformat")
t("Instant Channeling", "インスタント・チャネリング", "talent name")
t("You must have either a psionic damage shield active or Improved Gestalt available to use this talent.", "超能力シールドを展開していないか「ゲシュタルトバリア」が使用できない状態です。", "logPlayer")
t([[Instantly channel all of your remaining steam to replenish your psi energies and either enhance your active psionic damage shield or trigger a new one.
		The (new or existing) shield duration is increased by 3 turns and its power is boosted by %d%% of the steam used.
		You restore psi equal to %d%% of the steam used.
		This talent requires Gestalt to be active and either an active psionic damage shield or Improved Gestalt off cooldown.]], [[残っている蒸気を瞬時に全て引き出してＰｓｉを回復します。また、展開中の超能力シールドを強化します。超能力シールドを展開していない場合は新たに展開します。
		　（新しく展開したものでも）シールドの持続時間は３ターン増加し、消費した蒸気の %d%% 分に等しい値だけ強度が増加します。
		　Ｐｓｉの回復量は消費した蒸気の %d%% です。
		　このタレントを使用するには「心機合一」を起動しておかなくてはいけません。
		　さらに超能力シールドを展開しているか「ゲシュタルトバリア」が使用可能である必要があります。]], "tformat")
t("Forced Gestalt", "ゲシュタルト接続", "talent name")
t([[Temporarily expand your mind to force your Gestalt upon your foes in a radius of 5. Up to %d foe(s) will be affected.
		The Gestalt will drain each affected foe's powers (physical power, mind power, spell power and steam power) by %d for 5 turns.
		Your own powers will be increased in return by the drained amount (reduced for each additional foe).
		In addition for 5 turns you can sense creatures beyond your sight, even through walls in radius %d.
		The effects improve with your Mindpower.]], [[一時的に精神を遠くへ伸ばし、蒸気発生装置への精神接続を半径５マス内の敵に強制付与します。これは最大 %d 体までの敵に効果を発揮します。
		　これにより、対象の各種パワーを %d 吸収します。持続時間は５ターンです。術者の各種パワーは吸収分上昇します（対象が増える程、上昇量は減衰します）
		　また、５ターンの間視界外のキャラクターを感知します。この効果によって半径 %d マス以内の相手を壁越しであっても感知できます。
		　効果量は精神パワーに依存します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/psionic-fog.lua"

t("Vaporous Step", "スチームジャンパー", "talent name")
t([[You concentrate your will to psychoport some of the steam of your generator to a remote location. Each turn steam accumulates there, up to %d charges.
		When you deactivate the effect you release the accumulated psionic and steam energies, instantly switching places with the target location and releasing the charges in a fiery explosion of hot wet steam in radius 4.
		The explosion will do %0.2f fire damage, multiplied by 33%% (diminutive) for each charge and apply the wet effect.
		The effect will fizzle if the charged grid is currently occupied by a creature or not in sight.
		The damage will increase with your Steampower.]], [[精神を集中し、蒸気発生装置の蒸気を一部離れた地点へテレポーテーションさせます。ターン毎にその地点へ蒸気が集まっていき、最大で %d 回まで堆積します。
		　タレントを解除すると堆積した理力蒸気のエネルギーを解き放ち、対象地点と位置交換します。さらに堆積した蒸気は半径４マスに水蒸気爆発を起こします。これは %0.2f の火炎属性ダメージです。堆積数が増える毎にダメージは上昇しますが、上昇幅は減衰していきます（堆積数が１の時に３３％上昇）爆発を受けた相手は水浸し状態になります。
		　タレント解除時、対象地点に誰かがいる場合は失敗します。解除時に対象地点が視界外となっている場合も同様です。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Inhale Vapours", "蒸気吸入", "talent name")
t([[When you deactivate Vaporous Step, if the psychoport succeeds you inhale some of the vapours, regenerating %d steam and %d life.
		The effects will be multiplied by 33%% (diminutive) for each charge of Vaporous Step.
		The healing done will increase with your Mindpower.]], [[「スチームジャンパー」を解除した際、テレポーテーションに成功したならば、堆積した蒸気を一部取り込んで蒸気を %d ＨＰを %d 回復します。
		　堆積数が増える毎に回復量は上昇しますが、上昇幅は減衰していきます（累積数が１の時に３３％上昇）
		　ＨＰ回復量は精神パワーに依存します。]], "tformat")
t("Psionic Fog", "サイキック・フォグ", "talent name")
t([[Using the steam of your generators you shape it into a psionic fog that lasts %d turns. Any foes caught inside will take %0.2f damage per turn and be seared, reducing their fire resistance by %d%% and and mind save by %d.
		The damage will increase with your Mindpower.]], [[蒸気発生装置の蒸気を用いてサイキックスチームを作り出します。これは %d ターン持続します。この中にいる敵は毎ターン %0.2f ダメージを受けて黒焦げになります。これにより対象の火炎耐性が %d%% 低下し、精神セーブが %d 減少します。
		　ダメージは精神パワーに依存します。]], "tformat")
t("Uncertainty Principle", "不確定性原理", "talent name")
t("#STEEL_BLUE#(%d quantum shifted)#LAST#", "#STEEL_BLUE#（%d　不確定性原理）#LAST#", "tformat")
t([[While inside a psionic fog the quantum state of space is warped by your powerful tech-augmented psionic powers.
		When you would get hit you instead find yourself in an adjacent location.
		This effect has a cooldown.]], [[サイキックスチームの中にいる時、蒸気機械で増幅した凄まじい精神力を用いて量子状態を捻じ曲げます。
		　攻撃を受ける際に自動的に隣接するマスへ転移します。
		　このタレントにはクールダウンが存在します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/psionic/psionic.lua"

t("psionic", "超能力", "talent category")
t("gestalt", "サイコエンジン", "talent type")
t("Harness steam energies to power your own mind.", "　蒸気を操り、自身の精神力を高めます。", "_t")
t("action at a distance", "フェノメノン", "talent type")
t("Focus your mental energies to make things happen. Or combust.", "　精神エネルギーを集中して様々な現象を引き起こします。ドッカーンとね。", "_t")
t("psionic fog", "サイコスチーム", "talent type")
t("Psionically manipulate steam to harass your foes and protect yourself.", "　精神力によって蒸気を操作し有利に立ち回ります。", "_t")
-- old translated text
t("gestalt", "心機合一", "_t")
t("action at a distance", "フェノメノン", "_t")
t("psionic fog", "サイコスチーム", "_t")

------------------------------------------------
section "tome-orcs/data/talents/spells/galvanic-technomancy.lua"

t("Galvanic Rod", "サンダーロッド", "talent name")
t("You need an arcane dynamo to cast this spell.", "魔導ダイナモを装備していない。", "logPlayer")
t([[You summon a galvanic rod at a location. Upon arrival the rod releases a shock in radius %d dealing %0.2f galvanic damage (fire and lightning) to all creatures.
		You have 3 rods each with their own %d turns cooldown.
		This spell works with Burning Wake.
		This spell has 25%% chance to try to activate Hurricane, if used.
		The damage will increase with your Spellpower.]], [[帯電ロッドを召喚します。
		　ロッドは出現時に半径 %d マスに電撃を放ち、熱電属性（火炎属性と電撃属性）の %0.2f ダメージを全員に与えます。
		　ロッドは３本存在し、それぞれが独立して %d ターンのクールダウンを有しています。
		　「バーニングフィールド」が起動しているならこの魔法で発動します。
		　「ハリケーン」が起動しているなら２５％の確率で効果を付与します。
		　ダメージは魔法パワーに依存します。]], "tformat")
t("Galvanic Arcing", "サンダーアーク", "talent name")
t([[Using your arcane power you force galvanic rods to linger for %d turns. While lingering they are inert, but can link up to other rods.
		When two rods are present in range %d of one another they link with a galvanic beam.
		When three rods are present in range %d of one another they link with a triangular galvanic zone.
		Any creature caught in a galvanic beam or zone take %0.2f galvanic damage per turn.
		You can maintain at most 3 rods.
		At level 3 all affected creatures are shocked, reducing their stun and pin resistances by half.
		At level 5 your weapon (if metallic, or embedded with a metallic tinker) acts as a rod that does not count towards your maximum.
		This spell has 15%% chance to try to activate Hurricane, if used.
		The damage will increase with your Spellpower.]], [[魔法の力を用いて帯電ロッドを %d ターン残留させます。残留したロッドは機能を停止してますが、他のロッドとリンクできます。
		　２本のロッドが互いに %d マス以内に存在する時、２つの間に熱電ビームが発生します。
		　３本のロッドが互いに %d マス以内に存在する時、三角形の熱電ゾーンが発生します。
		　これらの範囲内にいる相手は毎ターン熱電属性の %0.2f ダメージを受けます。
		　残留しておけるロッドは一度に３本までです。
		　タレントレベル３からはこれらのダメージを受けた相手が感電し、スタン・移動不能耐性が半減します。
		　タレントレベル５から自分の武器（金属製か、金属製の工士アイテムをセットしている必要があります）もロッドとして機能します。自分の武器はロッドの残留本数上限に引っかかりません。
		　「ハリケーン」を起動しているなら１５％の確率で効果が発生します。
		　ダメージは魔法パワーに依存します]], "tformat")
t("Unstable Blast", "暴走ブラスト", "talent name")
t("You need Galvanic Arcing active and at least one rod to cast this spell.", "「サンダーアーク」を起動し、帯電ロッドを１つは生成していないと使えない。", "logPlayer")
t([[Reaching through the aether you temporarily destabilize a galvanic rod's control systems. (Using your weapon as a rod does not count as a valid target)
		This creates a blast in radius 1 around it, or through all connected rods if they are linked dealing %0.2f galvanic damage to all creatures and stunning them for %d turns.
		This spell works with Burning Wake.
		The damage will increase with your Spellpower.]], [[エーテルを介して一時的に帯電ロッドのコントロールシステムを暴走させます。自分の武器はロッドとして機能していても対象になりません。
		　このタレントを使用するとロッドの半径１マスに爆発が起こります。リンクを形成しているロッドは全て対象となります。ダメージは熱電属性の %0.2f で、これを受けた相手は %d ターンスタンします。
		　「バーニングフィールド」が起動しているならその効果も発揮します。
		　ダメージは魔法パワーに依存します。]], "tformat")
t("Energy Mass Conversion", "エネルギー質量変換", "talent name")
t("You need Galvanic Arcing active and three rods to cast this spell.", "「サンダーアーク」を起動し、帯電ロッドを三本生成していないと使えない。", "logPlayer")
t([[Using large amounts of arcane power you create a supercharged Unstable Blast in your rods.
		The extra energy is briefly converted to a huge mass, pulling in all creatures (but you) in range %d of any rod towards the center of the galvanic field.
		Can only be used with a triangular field is setup.]], [[膨大な魔力を用いて、過充填版の「暴走ブラスト」を帯電ロッドに起こします。
		　余剰分のエネルギーは一時的に巨大な質量に変換されます。これにより各ロッドの半径 %d マス以内に存在する全員が熱電ゾーンの中心部へ引き寄せられます。
		　術者はこの影響を受けません。
		　このタレントはロッドで熱電ゾーンが形成されていなければ使用できません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/occult-technomancy.lua"

t("Metaphasic Spin", "メタフェイズスピン", "talent name")
t("You need an arcane dynamo to cast this spell.", "魔導ダイナモを装備していない。", "logPlayer")
t("Select the steamsaw to use?", "どのスチームソーにしますか？", "_t")
t([[You imbue a steamsaw with arcane and temporal forces, making it spin very fast around your waist (ignoring requirements).
		The saw spins so fast it it disturbs spacetime around you, increasing your spellpower by up to %d, your spell critical chance by up to %d and your mana regen by up to %0.1f (depending on steamsaw tier).
		Any successful melee attack against you also triggers an automatic steamsaw attack that cannot miss dealing %d%% weapon damage as occult damage (arcane and temporal).
		The steamsaw used will provide its bonus as if it was worn, but you can not Block with it.
		Increases steamsaws weapon damage by %d%% and uses Magic instead of Strength to determine their damage.
		If using Aether Avatar, all Occult Technomancy spells become usable for its duration and all occult damage becomes pure arcane.

		#{italic}#When you first learn this talent you also learn the Steamsaw tinker creation if you didn't already know it.#{normal}#
		]], [[スチームソーに神秘の力と時空の力を込め、胴の周囲をぐるぐる回るようにします。これは装備条件を無視して装備します。
		　スチームソーが凄まじい速さで回転し、周囲の時空を歪めます。そのため魔法パワーが最大で %d 魔法クリティカル率が最大で %d マナの自動回復量が最大で %0.1f 増加します。この増加量はスチームソーのランクに依存します。
		　近接攻撃を受けるとこのスチームソーで自動的に反撃します。これは回避されず、倍率 %d%% の攻撃です。属性は空霊属性となります（神秘属性と時間属性）
		　装備中のスチームソーが有する効果は通常装備した際と同じく適用されます。ただしこれで「ブロッキング」は使用できません。
		　このタレントによってスチームソーの与ダメージが %d%% 上昇し、ダメージ計算の際に腕力の代わりに魔力を参照します。
		　このツリーのタレントは「エーテルの化身」の効果中に使用できるものとして扱われ、効果中はダメージが神秘属性単一に変化します。

		　#{italic}#このタレント習得した際にスチームソーの作成法を知らなければ、一緒に習得します。#{normal}#
		]], "tformat")
t("Reality Breach", "次元キャノン", "talent name")
t("You need to activate Metatemporal Spinner to cast this spell.", "「メタフェイズスピン」を起動していない。", "logPlayer")
t("#Source# annihilates '#Target#'!", "#Source#が#Target#を消し飛ばす！", "logCombat")
t([[Spin your saw at incredible speeds for an instant, fully breaking reality in a 3-wide beam in front of you.
		Any creatures caught by the beam take %0.2f occult damage and are untethered from reality, reducing their global speed by %d%% and the speed of any projectiles they fire by %d%% for 4 turns.
		At level 3 any projectiles caught in the beam are instantly annihilated.
		At level 5 the beam is so strong that all creatures caught inside are knocked back 3 tiles.
		The breach is so deep that the beam will always have the maximum possible length it can.
		The damage will increase with your Spellpower.]], [[スチームソーを瞬間的に超高速回転させて空間を滅茶苦茶にし、３連ビームを前方に放ちます。
		　これを受けた相手は空霊属性の %0.2f ダメージを受け、空間から切り離されます。これにより速度が %d%% 低下し、発射する飛来物の飛行速度が %d%% 減少します。持続時間は４ターンです。
		　タレントレベル３からは範囲内の飛来物を即座に破壊します。
		　タレントレベル５からは強烈な威力で範囲内の対象を３マスノックバックさせます。
		　スチームソーによって生じた空間の断裂は非常に深く、３連ビームは常に最大射程まで達します。
		　ダメージは魔法パワーに依存します。]], "tformat")
t("Ethereal Steam", "イセリアルリンク", "talent name")
t([[You reach out through the aether to all creatures in sight that were slowed by Reality Breach or Congeal Time.
		For each target you create a link of arcane infused steam to it that lasts %d turns.
		Any time the target uses a talent one of your cooling down spells is reduced by 1 (prioritizing Technomancy spells).
		Each turn the link is up the target and any creature inside the link takes %0.2f occult damage.
		As long as at least one link is up, the cooldown of your Metaphasic Spin spell is set to 6 turns instead of 30.
		The damage will increase with your Spellpower.]], [[エーテルを通して視界内の敵全員を捕らえます。これは「次元キャノン」か「時封じ」の効果で減速している相手にだけ効果があります。
		　該当するそれぞれの対象と魔法の力を込めた蒸気で %d ターン繋がります。
		　対象がタレントを使用する毎に、自身の魔法タレント１種のクールダウンが１減少します。これは魔工学タレントが優先されます。
		　蒸気リンクの対象とその経路上にいる相手は毎ターン %0.2f の空霊属性ダメージを受けます。
		　蒸気リンクが１本以上維持できているなら、「メタフェイズスピン」のクールダウンが３０ターンの代わりに６ターンになります。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Metaphasic Echoes", "メタフェイズエコー", "talent name")
t("You can only cast this spell on the turn after Reality Breach.", "「次元キャノン」を使っておかないと使用できない。", "logPlayer")
t([[Using your sheer arcane power you keep breaches in spacetime open for %d turns.
		Each turn they are open you project an occult clone of your saw along each breach, damaging any creature caught for %d%% occult weapon damage.
		The saw cuts both in a physical and arcane way, reducing the duration of a random beneficial effect on each target by %d each time.
		Each target can only be affected once per turn.
		This spell is only usable for one turn after casting Reality Breach but any Reality Breach cast during its duration is also recorded inside.]], [[純粋な魔法の力で空間断裂を %d ターンの間キープします。
		　この断裂が開いていると毎ターン、それぞれの断裂に沿ってスチームソーの空霊コピーが発射され、範囲内の相手に倍率 %d%% の武器攻撃を空霊属性ダメージとして与えます。
		　この攻撃は肉体的にも魔法的にも損傷を与えるため、ランダムなバフ１種の持続時間を %d ターン短縮します。
		　対象１体につき、ターン毎に１回しか影響を受けません。
		　この魔法は「次元キャノン」使用後の１ターンまでしか使えません。ただしこのタレントの効果中に「次元キャノン」を使用すると、新たにできた空間の断裂にも空霊コピーが発生します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/other-technomancy.lua"

t("Electron Incantation", "電子操作術", "talent name")
t("You need an arcane dynamo to cast this spell.", "魔導ダイナモを装備していない。", "logPlayer")
t("You can only cast this spell after casting an other technomancy spell.", "魔工学系の魔法を使用した後でないと実行できない。", "logPlayer")
t([[After casting a technomancy spell you store some of its energies that you can then use to overload your arcane dynamo, increasing the steam it generates per 10 mana spent by 4 for 4 turns.
		In addition the energies spills outward in radius 3, dealing %0.2f damage (damage type based on the type of technomancy spell used).
		This spell is only usable after casting a technomancy spell and until you use any other spell or talent.
		The damage will increase with your Spellpower.]], [[魔導工学系の魔法を使用した際に、そのエネルギーの一部を蓄えて魔導ダイナモをオーバーロードできます。これによりダイナモが生成する蒸気が消費マナ１０あたり４増加します。持続時間は４ターンです。
		　さらに半径３マスにエネルギーが放出され %0.2f のダメージを与えます。
		　この属性は使用した魔導工学の種類に依存します。
		　このタレントは魔導工学系のタレントを使用した後でなければ使えません。他の魔法やタレントを実行するとその時点で使用不可となります。
		　ダメージは魔法パワーに依存します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/spells.lua"

t("spell", "魔術", "talent category")
t("undead drake", "不死竜", "talent type")
t("Take on the defining aspects of an Undead Drake.", "　アンデッドドラゴンの形態を取ります。", "_t")
t("galvanic technomancy", "熱電魔学", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with fire and lightning.", "　蒸気機関と魔法の力を組み合わせ、炎と電撃の力で敵を殲滅します。", "_t")
t("terrene technomancy", "冷地魔学", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with earth and water.", "　蒸気機関と魔法の力を組み合わせ、地と水の力で敵を殲滅します。", "_t")
t("occult technomancy", "空霊魔学", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes with arcane and time.", "　蒸気機関と魔法の力を組み合わせ、神秘の力と時空の力で敵を殲滅します。", "_t")
t("other technomancy", "魔学雑多", "talent type")
t("Combine the power of steamtech and arcane forces to destroy your foes.", "　蒸気機関と魔法の力を組み合わせ、敵を殲滅します。", "_t")
-- old translated text
t("undead drake", "不死竜", "_t")
t("galvanic technomancy", "熱電魔学", "_t")
t("terrene technomancy", "冷地魔学", "_t")
t("occult technomancy", "空霊魔学", "_t")
t("other technomancy", "魔学雑多", "_t")

------------------------------------------------
section "tome-orcs/data/talents/spells/terrene-technomancy.lua"

t("Micro Spiderbot", "スパイダーボット", "talent name")
t("You need an arcane dynamo to cast this spell.", "魔導ダイナモを装備していない。", "logPlayer")
t([[You build %d micro spiderbot(s) from the earthly elements around you. Spiderbots are powered by an arcane cryogenic power unit directly linked to your own power.
		Spiderbots will deal %0.2f terrene damage (physical and cold) each turn to their targets. The deep cold of the attack has 25%% chance to freeze the feet of the target, pinning it to the ground for 5 turns.
		If a target dies, the spiderbot will jump onto a new target in range %d around you.
		If there are multiple spiderbots on a single target and more free targets are in range they will dispatch on as many as possible.
		If there are multiple spiderbots on a single target they attack as one, stacking their damage (with disminishing returns) and trying to freeze once.
		You can maintain up to %d spiderbots at once and each can last up to %d turns, but spiderbots need to be in sight to be able to act.
		The cooldown of this spell is affected by Body of Stone.
		The damage will increase with your Spellpower.

		You have currently %d spiderbot(s) up.]], [[地中の元素から微小なスパイダーボットを %d 体作り出します。これらは術者にリンクしている、魔法の極低温ユニットを動力としています。
		　スパイダーボットは毎ターン対象に %0.2f の冷地属性（物理属性と冷気属性です）ダメージを与えます。
		　超低温攻撃によって対象の足元が２５％の確率で凍り付き、５ターンの間地面に張り付けます。
		　対象が死亡すると機体は術者の半径 %d マス以内に存在する新たな相手へ取り付きます。
		　単体に複数の機体が取り付いている状態で、範囲内にスパイダーボットを受けていない相手がいるなら出来るだけ散らばるように取り付きます。
		　そのような相手がいない場合は一丸となって攻撃し、まとめてダメージを与えます（数が増える毎に１体当たりのダメージは低下していきます）この場合、足元への凍結は１回しか試みません。
		　一度に保持しておける機体は %d 体までです。それぞれ %d ターンの間存在し続けますが、視界内にいなければ動作しません。
		　このタレントのクールダウンは「鉱身化」の影響を受けます。
		　ダメージは魔法パワーに依存します。
		
		　現在 %d 体のスパイダーボットを保持可能です。]], "tformat")
t("Cryogenic Digs", "グラウンドダイブ", "talent name")
t([[Each time a spiderbot expires it digs around, producing either a Glacial Vapour (%0.2f cold damage and doing 30%% more damage to wet targets) or Earthquake (%0.2f physical damage and 25%% chances to stun for 2 turns) of radius 1 that last for %d turns.
		Those special kinds of Glacial Vapour and Earthquake do not affect the caster.
		The damage will increase with your Spellpower.]], [[スパイダーボットが消滅する際に周囲の地面に潜り込み
		　「フロストミスト」（冷気属性の %0.2f ダメージを与えます。対象が水浸し状態ならダメージが３０％増加します）か「アースクエイク」（物理属性の %0.2f ダメージを与え２５％の確率で２ターンの間スタンさせます）を半径１マスに発生させます。
		　これらは %d ターン継続します。特殊版なので、術者には影響を与えません。
		　ダメージは魔法パワーに依存します。]], "tformat")
t("Ramming Bot", "ボットアタック", "talent name")
t("You need an arcane dynamo and an active spiderbot to cast this spell.", "魔導ダイナモを装備して、スパイダーボットがいないと発動しない。", "logPlayer")
t([[Command a random spiderbot to jump onto your target at ramming speed. The impact destroys the bot (possibly triggering Cryogenic Digs).
		This creates a radius %d explosion dealing %0.2f terrene damage to all creatures while also freezing them for %d turns and rendering them wet for %d turns.
		The cooldown of this spell is affected by Body of Stone.
		The damage will increase with your Spellpower.]], [[ランダムなスパイダーボットを対象へ特攻させます。この衝撃で機体は破壊されます（「グラウンドダイブ」も発動するでしょう）
		　これにより半径 %d マスに爆発が起こり、冷地属性の %0.2f ダメージを全員に与えます。
		　さらに %d ターンの間凍結状態にして %d ターン水浸しにします。
		　このタレントのクールダウンは「鉱身化」の影響を受けます。
		　ダメージは魔法パワーに依存します。]], "tformat")
t("Spiderbot Shield", "ボットシールド", "talent name")
t([[You call back up to %d spiderbots to you to create protective barrier for %d turns.
		Spiderbots have %d life and they take damage in order, always fully absorbing the blow that destroyed them.
		If Cryogenic Digs is active when a spiderbot is destroyed it jumps to the attacker and triggers the dig there.
		The cooldown of this spell is affected by Body of Stone.
		]], [[スパイダーボット %d 体を呼び戻し、防御バリアを %d ターンの間形成します。
		　各機体は %d のＨＰを有しており、順番にダメージを肩代わりしていきます。
		　破壊された際のダメージも完全に受け切ります。
		　「グラウンドダイブ」が起動しているならこのタレントで破壊された機体は攻撃者へ突進し、地面に潜ります。
		　このタレントのクールダウンは「鉱身化」の影響を受けます。
		]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/spells/undead-drake.lua"

t("Raze", "暴走死竜", "talent name")
t([[You revel in death, devouring the souls of your victims. Whenever you inflict damage to a target, you deal an additional %0.2f darkness damage.
		Additionally, you gain %d souls whenever you score a kill.
		The damage will scale with the highest of your spell or mind power and can only occur up to 25 times per turn.]], [[嬉々として敵を撃破し対象の魂を貪ります。敵にダメージを与えた際に追加で %0.2f の暗黒属性ダメージを与えます。
		　また、敵を撃破した際に魂を %d 獲得するようになります。
		　ダメージは魔法パワーと精神パワーの高い方に依存します。]], "tformat")
t("Infectious Miasma", "悪疫の瘴気", "talent name")
t([[Release a cloud of deadly miasma over a targeted area, dealing %0.2f darkness damage to all units inside it with a 20%% chance of inflicting a disease that will do blight damage and weaken either Constitution, Strength or Dexterity for %d turns.
		The damage will scale with the highest of your spell or mind power.]], [[命を蝕む瘴気を対象地点一面に放ちます。範囲内にいるキャラクター全員に %0.2f の暗黒属性ダメージを与え、２０％の確率で病に冒します。感染した相手は腐敗属性のダメージを受け続け、耐久、機敏、腕力のいずれかが低下します。病気の持続時間は %d ターンです。
		　ダメージは魔法パワーと精神パワーの高い方に依存します。]], "tformat")
t("Vampiric Surge", "ヴァンパイアサージ", "talent name")
t([[You surge with a life draining energy for %d turns.
		While the effect lasts, you heal yourself for %d%% of all damage you deal.]], [[生命吸収のエネルギーを纏います。持続時間は %d ターンです。
		　効果中は与ダメージの %d%% 分のＨＰが回復します。]], "tformat")
t("Necrotic Breath", "ネクロブレス", "talent name")
t("@Source@ breathes a wave of darkness!", "@Source@は怒涛の如く闇を吐いた！", "_t")
t([[You breathe a wave of deathly miasma in a cone of radius %d. Any target caught in the area will take %0.2f darkness damage over 4 turns and receive either a bane of confusion or a bane of blindness for 4 turns.
		The damage will increase with your Magic, and the critical chance is based on your Spell crit rate.]], [[命を蝕む瘴気の波を扇状範囲に吐きます。範囲は半径 %d です。対象に %0.2f の暗黒属性ダメージを４ターンかけて与えます。また対象は４ターンの間、盲目の苦悶か混乱の苦悶を受けます。
		　ダメージは魔力に依存し、クリティカル率は魔法クリティカルを参照します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/artillery.lua"

t("Rocket Pod", "ロケットポッド", "talent name")
t([[You equip an automated, shoulder mounted rocket launcher. Each turn it will launch rockets at up to %d enemies in weapon range, dealing %d%% steamgun damage as fire.
		The rockets will pass harmlessly through allies, but on-hit effects triggered by them only deal 50%% of their usual damage.]], [[自動ロケットランチャーを肩に装着します。射撃射程内の最大 %d 体までの敵に対して毎ターンロケット弾を撃ちます。これは倍率 %d%% スチームガンによる射撃で火炎属性です。
		　ロケット弾は味方を素通りしますが、射撃命中時に発生する特殊効果の与ダメージは通常の５０％となります。]], "tformat")
t("Incendiary Powder", "ボムパウダー", "talent name")
t([[Augment your rockets with highly flammable materials, causing them to burn targets for %0.2f fire damage over 3 turns. Subsequent shots against burning targets refresh the effect of the duration (but do not stack) and inflict %0.2f additional fire damage.
Targets affected by this burning that fall below 25%% life enter a state of panic, giving them a %d%% chance each turn to flee in terror from you.
The fire damage will increase with your Steampower.]], [[爆発性物質でロケット弾を強化します。
		　これにより敵が炎上し %0.2f の火炎属性ダメージを３ターンかけて受けるようになります。ロケット弾を当て続けるとそのたびに炎上の持続時間は更新され（スタックはしません）火炎属性の %0.2f 追加ダメージを与えます。この炎上効果を受けている相手のＨＰが２５％未満になると恐慌状態となり、毎ターン %d%% の確率で逃げ出します。
		　火炎属性ダメージは蒸気パワーに依存します。]], "tformat")
t("Lock On", "ロックオン", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t([[Lock on to your target with your rocket pod for 5 turns.
While locked on your regular rocket pod attacks are disabled. However, each turn you automatically fire a rocket barrage dealing %d%% increased damage at your target.
Marked targets also lose %d defense and cannot benefit from concealment or evasion.
The defense loss will increase with your Steampower.]], [[対象をロケット砲で５ターンの間ロックオンします。
		　この効果を発揮している間は通常のロケット弾を撃ちません。
		　その代わり毎ターン対象へダメージが %d%% 増加したロケット弾を乱射します。
		　対象は回避が %d 低下し、不可視効果や身躱し効果による恩恵を受けられません。
		　回避の低下量は蒸気パワーに依存します。]], "tformat")
t("Death From Above", "上からくるぞ！", "talent name")
t([[You use your rocket pods to launch yourself into the air for 3 turns, firing a radius 2 barrage of rockets that deal %d%% steamgun damage as fire in radius 2. 
		While flying you gain %d%% movement speed, %d%% chance to evade melee and ranged attacks, and can reactivate this talent at will to repeat the rocket barrage.
		Using any talent other than Rocket Barrage will end this effect immediately.]], [[ロケット砲で半径２マスにロケット弾を乱射し、３ターンの間宙を飛びます。
		　これは倍率 %d%% のスチームガンによる射撃で、半径２マスに火炎属性ダメージを与えます。
		　宙を飛んでいる間は移動速度が %d%% 増加し %d%% の確率で近接・射撃攻撃を避けます。この間、本タレントを再使用することでいつでもロケット弾を乱射できます。
		　「ロケット乱射」以外のタレントを使用するとその時点で効果は終了します。]], "tformat")
t("Rocket Barrage", "ロケット乱射", "talent name")
t("Fires a barrage of rockets in radius 2, dealing %d%% steamgun damage as fire.", "半径２マスにロケット弾を乱射します。倍率 %d%% のスチームガン射撃を火炎属性として与えます。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/automated-butchery.lua"

t("Continuous Butchery", "エンドレスカット", "talent name")
t("You require a steamsaw for this talent.", "スチームソーを装備していない。", "logPlayer")
t([[You attune your saws to a specific target for 5 turns.
		Each time you strike this target all damage done with steamsaws (including by other talents) is increased by +%d%%.
		If you strike any other foe the bonus ends.
		#{italic}#Metal your foes to death!#{normal}#]], [[５ターンの間、対象に合わせてスチームソーを調整します。
		　スチームソーで対象に与えるあらゆるダメージが %d%% 上昇します。
		　これは他のタレントによる攻撃にも適用されます。現在対象となっている敵以外を攻撃するとダメージ上昇ボーナスは消滅します。
		
		#{italic}#　死をもたらす鋼の刃！#{normal}#]], "tformat")
t("Explosive Saw", "オートカッター", "talent name")
t([[You send a saw mounted on an automated steam propulsor to assault a foe, dealing %0.2f physical damage each turn for 4 turns and silencing it.
		At the end of the duration, the saw explodes for %0.2f fire damage and flies back, pulling the target up to %d tiles towards you.
		The damage will increase with your Steampower.]], [[自動蒸気推進装置にスチームソーを取り付けて敵に放ちます。毎ターン対象に %0.2f の物理属性ダメージを与えます。持続時間は４ターンです。また対象を沈黙させます。
		　４ターン目にこのスチームソーは爆発して火炎属性の %0.2f ダメージを与え、手元に戻ってきます。この際、対象を自分の方へ %d マス引き寄せます。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Mow Down", "焚きつけにしよう", "talent name")
t([[When you kill a foe with a melee strike you quickly throw some of their remains in your steam engine, instantly regenerating %d steam.
		When you deal a critical melee strike you also have a %d%% chance to cut a part of your foe and use it in your steam engine.
		When either of those happens this strikes fear in all foes in radius 4 of the victim, brainlocking them for %d turns.
		#{italic}#To the meat grinder!#{normal}#]], [[近接攻撃で敵を撃破した際、即座に死体の一部を蒸気エンジンに放り込みます。これにより、蒸気が %d 回復します。
		　また、近接攻撃でが発生した場合も %d%% の確率で敵の肉片を蒸気エンジンの燃料にします。
		　どちらかが発動すると対象の半径４マスの敵が怯え、精神封鎖状態になります。この持続時間は %d ターンです。
		
#{italic}#　１名様ご案内！#{normal}#]], "tformat")
t("Tech Overload", "オーバーロード", "talent name")
t([[You override all security measures of your tinkers, allowing you to reset the cooldown of %d of most of your steamtech talents of tier %d or less and instantly increases your steam level by %d%% of the maximum.
		In addition for 6 turns your maximum steam capacity is doubled, but steam regeneration is halved.
		#{italic}#Master of Tech, Master of Death!#{normal}#]], [[蒸気機械のセキュリティを無効にします。蒸気機械系のタレントの中から %d 種類、クールダウンを解除します。この効果が適用されないタレントもあります。対象となるのはランク %d 以下のものだけです。また、即時に蒸気を最大値の %d%% 分回復します。
		　さらに６ターンの間、蒸気の最大値が二倍となります。ただしこの間蒸気の自動回復量は半減します。

		#{italic}#　技術の支配者にして死の支配者！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/automation.lua"

t("Pulse Detonator", "パルスボム", "talent name")
t([[Sends a pulse detonator to the target. Upon arrival it explodes in radius 4 cone, dealing %0.2f physical damage, knocking back foes by 3 and dazing them for %d turns.
		Damage increases with your steampower.]], [[衝撃波発生装置を対象に投げつけます。着弾すると扇状の半径４マスに %0.2f の物理属性ダメージを与え、３マスノックバックさせます。また、この際に %d ターン朦朧状態を付加します。
		　ダメージは蒸気パワーに依存します。
]], "tformat")
t("Flying Grapple", "グラップルドローン", "talent name")
t("Flying Grapple", "グラップルドローン", "_t")
t("A flying grapple pull %s into %s!", "射出した鉤が%sを%sに引き寄せる！", "logSeen")
t([[You send a small steam-powered flying grapple to a target. The drone is homing so if the target moves it will follow.
		When it reaches its target it deploys grapples in all directions around it in radius 4.
		The grapples latch onto any foes and pull them toward the target. If they are stopped by a creature (or the target) both them and the creature take %0.2f physical damage.
		]], [[蒸気で動く小型の飛行ドローンを対象に放ちます。このドローンは対象を追尾するため、相手が動くと軌道が変化します。
		　対象に取り付くと、このドローンは周囲４マスの全方位に鉤を放ちます。
		　鉤は範囲内の敵全員を対象へと引き寄せます。引き寄せられた敵が別の敵（もしくは対象）に衝突した場合、互いに %0.2f の物理属性ダメージを受けます。
]], "tformat")
t("Net Projector", "電磁ネット", "talent name")
t("%s resists the net.", "%sは電磁ネットに抵抗した。", "logSeen")
t([[Sends a lightly electrified net of radius 2 toward a target, all creatures caught inside will be pinned in place for 5 turns.
		While the electricity is not enough to do damage it does shock their body, reducing all resistances by %d%%.]], [[微弱な電流を帯びたネットを対象の半径２マスに放ります。範囲内の相手は５ターンの間、移動不能となります。
		　ネットの電流は相手にダメージを与えるほどではありませんがショックを与えて全ての耐性を %d%% 低下させます。]], "tformat")
t("Sawfield", "ラウンドブレード", "talent name")
t([[For 4 turns many small saws circle around the target in radius %d, making any creature caught inside bleed for %0.2f physical damage.
		Damage increases with your steampower.]], [[４ターンの間対象の周囲で小型のスチームソーが無数に渦を巻きます。範囲は半径 %d マスです。範囲内の相手に出血効果を与えて物理属性の %0.2f ダメージを与えます。
		　ダメージは蒸気パワーに依存します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/avoidance.lua"

t("Automated Cloak Tessellation", "自動式メタルクローク", "talent name")
t("@Source@ tessellates @hisher@ cloak!", "@Source@は@hisher@クロークに三角の金属片を敷き詰めた！", "_t")
t("You require a cloak to use this talent.", "クロークを装備していない。", "logPlayer")
t([[You tessellate your cloak with small pieces of metal, providing %d damage reduction against all attacks.
		The myriad metal scraps also help against incoming projectiles, providing a %d%% chance of deflecting them to a nearby spot.]], [[三角形の金属片をクロークに敷き詰めます。あらゆる被ダメージが %d 減少します。
		　これら無数の金属片は飛来物に対しても効果を発揮し %d%% の確率で近場に逸らします。]], "tformat")
t("Cloak Gesture", "ジェスチャ式クローク", "talent name")
t("@Source@ weaves @hisher@ cloak!", "@Source@@hisher@のクロークが揺れた！", "_t")
t([[With a gesture of your cloak, you drop a small incendiary device in front of you, creating a wall of thick steam of %d length that burns creatures passing it for %0.2f fire damage and blocks sight for 5 turns.
		At level 5 the action is so perfect that your foes even lose track of you entirely.
		Damage increases with your steampower.]], [[クロークを払って小型の発火装置を目の前に落とします。これは蒸気の壁をモクモクと生成します。壁の長さは %d マスです。この蒸気に触れた相手は %0.2f の火炎属性ダメージを受けます。また、視界を遮る効果もあります。持続時間は５ターンです。
		　タレントレベル５からは完璧な動作で実行し、敵が術者を完全に見失います。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Embedded Restoration Systems", "内蔵型回復システム", "talent name")
t("#LIGHT_BLUE#%s's embedded restoration system activate.", "#LIGHT_BLUE#%sの内蔵回復システムが起動！", "logSeen")
t("%s activates %s cloak's restoration systems!", "%sは%s内蔵回復システムを起動！", "logSeen")
t("%s deactivates %s cloak's restoration systems.", "%sは%s内蔵回復システムを切った。", "logSeen")
t([[Your cloak is lined with an automated health system that activate when no enemies are visible.
		When it triggers, you will be healed for %d life.
		At talent level 3, it will also remove one detrimental physical effect.
		The system can only trigger once every %d turns.]], [[装備中のクロークには自動治療システムが裏打ちしてあり、敵がいない場所で起動します。
		　起動するとＨＰが %d 回復します。タレントレベル３からは物理系のデバフを１つ解除します。
		　このシステムは %d ターン毎にしか発生しません。]], "tformat")
t("Cloaking Device", "クローキング", "talent name")
t([[Trigger an array of small mirrors to appear all over your cloak.
		The mirrors are positioned to reflect all light shining on you, granting %d stealth power for 10 turns.
		Stealth power increases with your steampower.]], [[クローク一面に無数の小型ミラーが出現します。
		　この鏡は自らを照らす光を全て屈折させるため、隠密効果量が %d 増加します。持続時間は１０ターンです。
		　隠密効果量は蒸気パワーに依存します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/battle-machinery.lua"

t("Explosive Steam Engine", "暴走蒸気エンジン", "talent name")
t("critical steam engine", "暴走蒸気エンジン", "_t")
t("trap", "罠", "_t")
t([[Throw a small, unstable steam engine on the battlefield that will go critical after 2 turns.
		It will then create an explosion of hot vapour in radius %d, burning all foes for %0.2f fire damage.
		Any bleeding foe caught in the flames will take 40%% more damage.
		Damage scales with your Steampower.
		#{italic}#Tick Tock Tick BOOM!#{normal}#]], [[小型の暴走蒸気エンジンを放ります。これは２ターン後に臨界に達します。
		　この際、半径 %d マスに水蒸気爆発を起こし、範囲内の敵全員に火炎属性の %0.2f ダメージを与えます。
		　出血効果を受けている相手に対してはこのダメージは４０％増しとなります。
		　ダメージは蒸気パワーに依存します。
		
		#{italic}#　チック！　タック！　ドーン！#{normal}#]], "tformat")
t("Lingering Cloud", "残留煙幕", "talent name")
t([[Explosive Steam Engine vapour now lingers for 5 turns.
		Each turn, bleeding foes inside the cloud will take %0.2f fire damage.
		Any steamtech-using creature will also regenerate %d additional steam per turn while inside the cloud.
		Damage scales with your Steampower.
		#{italic}#Modern technology at the service of burnination!#{normal}#]], [[「暴走蒸気エンジン」の蒸気が５ターン残留します。
		　出血している敵はこの中にいると火炎属性の %0.2f ダメージを毎ターン受けます。
		　蒸気機関で活動する相手はこの蒸気の中にいる限り、追加で蒸気が %d 回復します。
		　ダメージは蒸気パワーに依存します。
		
		#{italic}#　最新式の焦熱地獄！#{normal}#]], "tformat")
t("Tremor Engine", "人工地震デバイス", "talent name")
t("tremor engine", "人工地震デバイス", "_t")
t([[Throw a tremor engine on the battlefield that will trigger after 2 turns.
		For 5 turns after triggering, it will constantly shake the ground and stun, pin, or disarm any creature in radius %d for %d turns.
		#{italic}#The ground is mere paper to you!#{normal}#]], [[振動発生装置を地面に投げます。これは２ターン後に起動します。
		　起動後、５ターンの間は地面を揺らし、範囲内の敵をスタン、移動不能攻撃不能のいずれかの状態にします。効果範囲は %d マスです。異常状態の持続時間は %d ターンとなります。
		
		#{italic}#　ペラッペラの地面よのう！#{normal}#]], "tformat")
t("Seismic Activity", "人工火山", "talent name")
t("raging volcano", "活火山", "_t")
t([[On its last pulse, your Tremor Engine shakes violently, raising a volcano for %d turns.
		Each turn, the volcano will send out fiery boulders that deal %0.2f fire and %0.2f physical damage.
		Damage scales with your Steampower.
		#{italic}#All the fury of fire at your disposal!#{normal}#]], [[「人工地震デバイス」が振動発生を止めた後暴走し、地中より火山が出現します。持続時間は %d ターンです。
		　毎ターンこの火山は火炎弾を放ち、火炎属性の %0.2f ダメージと物理属性の %0.2f ダメージを与えます。
		　ダメージは蒸気パワーに依存します。
		
		#{italic}#　荒れ狂う炎を意のままに！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/battlefield-management.lua"

t("Saw Wheels", "ソーホイール", "talent name")
t("You require a steamsaw for this talent.", "スチームソーを装備していない。", "logPlayer")
t([[Firmly plant your steamsaws in the ground, using them to propel yourself very quickly (+%d%% movement speed).
		Any foes on either side of your movement get wrecked by the saws, knocking them 3 tiles away from you.
		Attacking or using any talent will break this effect.
		When this effect is broken or cancelled the sudden change in motion deals %d%% weapon damage to all foes around you. To do full damage you need to have moved at least 5 times, otherwise damage is lower (or null for no movement).
		#{italic}#The wheels of death! Amazing!#{normal}#]], [[スチームソーを地中に深々と突き刺して、高速移動します。（移動速度＋ %d%% ）
		　効果中は移動時に左右の敵をスチームソーで削り、３マスノックバックさせます。
		　攻撃するかタレントを使うかすると効果は終了します。
		　効果終了時もしくは解除した際に急停止するためダメージ倍率 %d%% の武器攻撃を周囲に行います。このダメージ倍率は移動したマスが５マス以上の場合です。それ未満の場合はダメージが低くなります（移動しなかった場合はダメージが発生しません）
		
		#{italic}#　殺戮の車輪！　最高！#{normal}#]], "tformat")
t("Grinding Shield", "スピニングガード", "talent name")
t([[Spin your saws wildly around you to create a wall of steamy sawteeth.
		All melee damage against you is reduced by %d%%, you have %d%% chance to evade projectiles and you can never take a blow that deals more than %d%% of your max life.
		#{italic}#Split their bones on the saws of death!#{normal}#]], [[スチームソーを周囲で高速回転させ、刃の壁を作り出します。
		　近接攻撃による被ダメージが %d%% 減少し飛来物を %d%% の確率で回避します。さらに、単発で最大ＨＰの %d%% を超えるダメージを受けません。
		
		#{italic}#　骨ごとぶった切れ、死の刃！#{normal}#]], "tformat")
t("Punishment", "パニッシュメント", "talent name")
t("#CRIMSON#%s unleashes a punishing strike for %d%% bonus damage!", "#CRIMSON#%sは強烈な一撃を見舞い、%d%%増加ダメージの攻撃を放った！！", "logSeen")
t([[Slam your saws into your target, dealing 100%% weapon damage + %d%% per physical, magical, or mental effect on them (up to 7 effects).
			Sustains are not effects.
		#{italic}#The Metal Punisher!#{normal}#]], [[スチームソーを叩き付け倍率１００％の武器攻撃を行います。これは対象の物理、魔法、精神系のステータス効果１つにつき %d%% ダメージが上昇します（最大７つまで）
		　オンオフ系タレントは勘定に入れません。
		
		#{italic}#　鋼の裁き！#{normal}#]], "tformat")
t("Battlefield Veteran", "ベテランキラー", "talent name")
t([[You have lived through many battles, and your experience makes you a gritty veteran.
		Saw Wheels end of effect attack increased by %d%%.
		Grinding Shield lets you live below your normal limits, up to -%d life.
		Punishment has a %d%% chance to have its cooldown reduced by 1 for each effect.
		#{italic}#Domination for all!#{normal}#]], [[数多の戦場を戦い抜いたことにより、経験を積んだ古強者となります。
		　「ソーホイール」終了時の範囲攻撃ダメージが %d%% 上昇します。
		　「スピニングガード」起動時にＨＰの下限が %d 増加します。
		　「パニッシュメント」が %d%% の確率でステータス効果１つにつき、同タレントのクールダウンを１短縮します。
		
		#{italic}#　全てを圧倒しろ！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/blacksmith.lua"

t("Massive Physique", "マッシヴ", "talent name")
t([[Working iron has honed your body into an amazing shape, granting %d strength and constitution.
		At talent level 5, you are so incredibly built that you gain one size category.]], [[鋼鉄を扱ううちに自身の肉体も鍛え上げられました。腕力と耐久が %d 増加します。
		　タレントレベル５からは異常なまでに肉体が発達し、サイズが１増加します。]], "tformat")
t("Endless Endurance", "我慢なら誰にも", "talent name")
t([[Working long hours at a forge has made you incredibly slow to tire and given you endless vitality.
		Your healing factor is increased by %d%% and your life regeneration by %0.2f.
		Stopping you is nearly impossible; your pinning resistance is increased by %d%%.]], [[永らく鍛冶場で作業を続けてきたため、とてつもない持久力が備わりました。
		　ＨＰ回復倍率が %d%% 増加し、ＨＰ自動回復量が %0.2f 上昇します。
		　また、大抵のことには怯まないため、移動不能耐性が %d%% 上昇します。]], "tformat")
t("Life in the Flames", "鍛冶場生まれ", "talent name")
t([[Slaving for many years at the forge has made you more resilient to physical pain and fire burns.
		Your fire resistance is increased by %d%% and your physical resistance by %d%%.
		At talent level 5, you are so accustomed to the flames that you become immune to the fireburn effect.]], [[鍛冶場で長年、肉体を酷使してきた結果、痛みと熱に一層強くなりました。
		　火炎耐性が %d%% 上昇し、物理耐性が %d%% 増加します。
		　タレントレベル５からは炎を友とするため、炎上によるダメージを受けなくなります。]], "tformat")
t("Craftsman's Eye", "名工の見切り", "talent name")
t([[You can easily see the weak points in your enemy's defenses. After all, you know to look for the same flaws in your own work.
		This grants %d armour penetration and %d%% critical strike multiplier.
		At talent level 5, you can also fight stealthed and invisible creatures without penalty.]], [[敵の防御における弱点を易々と看破できるようになります。要は自分の作品に見られる欠陥と同じものを探せばいいのです。
		　アーマー貫通が %d 上昇し、クリティカル倍率が %d%% 増加します。
		　タレントレベル５からは隠密、透明状態の敵に対してペナルティを受けずに攻撃できます。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/bullets-mastery.lua"

t("Overheat Bullets", "ヒートバレット", "talent name")
t("You must dual wield steamguns for this talent.", "二丁拳銃していないと使えない。", "logPlayer")
t([[By sending a stream of hot steam over your bullets you overheat them. For the next %d turns, each bullet will set the target ablaze, making it burn for %0.2f fire damage over 5 turns (most of your shooting talents fire two bullets at once).
		Damage will increase with Steampower.
		Only one bullet enhancement can be used at once.]], [[高温の蒸気流で弾丸を包み、弾丸を過熱します。使用後 %d ターンの間、弾丸が敵を炎上させ、火炎属性の %0.2f ダメージを５ターンかけて与えます（このクラスにおける射撃タレントはほとんどが一度に二発の銃弾を放ちます）
		　ダメージは蒸気パワーに依存します。
		　このツリーのタレント同士は効果が重複しません。]], "tformat")
t("Supercharge Bullets", "ピアースバレット", "talent name")
t([[You are able to polish your bullets so well they can go through multiple targets for %d turns.
		This also improves their armour penetration by %d.
		Only one bullet enhancement can be used at once.]], [[弾丸を研磨して敵を貫通するようにします。持続時間は %d ターンです。
		　これによりアーマー貫通も %d 増加します。
		　このツリーのタレント同士は効果が重複しません。]], "tformat")
t("Percussive Bullets", "ラージバレット", "talent name")
t([[You swap your bullets for more massive ones for %d turns.
		When striking a creature, these bullets have a %d%% chance of knocking it back 3 tiles and a %d%% chance of stunning it for 3 turns.
		The chances to knockback and stun increase with your Steampower.
		Only one bullet enhancement can be used at once.]], [[使用する弾丸を特大サイズに取り替えます。持続時間は %d ターンです。
		　攻撃に %d%% の確率で対象を３マスノックバックさせ %d%% の確率で３ターンスタンさせます。
		　それぞれの確率は蒸気パワーに依存します。
		　このツリーのタレント同士は効果が重複しません。]], "tformat")
t("Combustive Bullets", "ボムバレット", "talent name")
t([[You coat your bullets with flammable materials, for the next %d turns each bullet will explode when it hits its target, dealing %0.2f fire damage to all foes within radius 2 (most of your shooting talents fire two bullets at once).
		Damage will increase with Steampower.
		Only one bullet enhancement can be used at once.]], [[可燃性物質で弾丸をコーティングします。 %d ターンの間弾丸が命中した際に半径２マスに爆発を起こし、火炎属性の %0.2f ダメージを与えます。（このクラスにおける射撃タレントはほとんどが一度に二発の銃弾を放ちます）
		　ダメージは蒸気パワーに依存します。
		　このツリーのタレント同士は効果が重複しません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/butchery.lua"

t("Steamsaw Mastery", "スチームソー・マスタリー", "talent name")
t("Increases weapon damage by %d%% and Physical Power by 30 when using steamsaws.", "スチームソーを使用する際の物理パワーが３０増加し、与ダメージが %d%% 上昇します。", "tformat")
t("Overheat Saws", "赤熱メタル", "talent name")
t("You require two steamsaws for this talent.", "スチームソーを二刀流していないと使えない。", "logPlayer")
t([[Channel hot steam around your saws, burning foes you strike in melee for %0.2f fire damage over 3 turns (which can stack)!
		#{italic}#Hot, steamy maiming!#{normal}#]], [[スチームソーが熱気を纏います。近接攻撃時に対象を炎上させて %0.2f の火炎属性ダメージを３ターンかけて与えます（スタックします！）
		
		#{italic}#　熱いぜ！　燃えちまうぜ！#{normal}#]], "tformat")
t("Tempest of Metal", "メタルテンペスト", "talent name")
t([[Continuously swing your steamsaws around you, dealing %d%% weapon damage to adjacent foes each time you attack.
		Your chaotic motions make it difficult for anything to hit you, granting %d%% chance to completely negate all damage.
		Damage avoidance chance increases with Steampower.
		#{italic}#Make the metal talk!#{normal}#]], [[周囲をスチームソーで斬り続けます。攻撃時に隣接する敵へ武器攻撃の %d%% ダメージを与えます。
		　暴れまわるため、敵はタレント使用者を上手く捕捉できなくなります。これによってあらゆる被ダメージを %d%% の確率で無効化します。
		　無効化の確率は蒸気パワーに依存します。
		
		#{italic}#　工学系肉体言語！#{normal}#]], "tformat")
t("Overcharge Saws", "モーターチャージ", "talent name")
t([[You temporarily overcharge the saw motors, increasing the effective talent level of all saw talents by %d%% for %d turns.
		#{italic}#The pain shall never stop!#{normal}#]], [[スチームソーのモーターを一時過充電します。これにより、スチームソーを用いるタレントの実効レベルが %d%% 上昇します。持続時間は %d ターンです。
		
		#{italic}#　永遠の痛みを！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/chemical-warfare.lua"

t("Miasma Engine", "ミアズマエンジン", "talent name")
t([[You repurpose your steam engine to emit a cloud of toxic, corrosive chemicals around you.
		Each time you use a non-instant steamtech talent, you create a radius 3 cloud of miasma for 5 turns. All enemies within the miasma have %d%% reduced healing and %d%% chance to fail talent usage.
		Each time miasma is reapplied the failure chance increases, up to %d%% after 5 reapplications.
		The first time each turn a target affected by miasma is hit by a melee or ranged attack the miasma seeps into their wounds, dealing an additional %0.2f acid damage.
		Miasma duration does not increase on re-apply.
		When a creature survives the miasma it becomes immune to it for 9 turns.]], [[蒸気エンジンを改造して有毒な腐食性化学物質が周囲に立ち込めます。
		　ターン消費する蒸気機械系タレントを使用する毎に、半径３マスに有毒スモッグが生成されます。これは５ターン持続します。範囲内の敵はＨＰ回復倍率が %d%% 低下して %d%% の確率でタレント使用に失敗します。
		　再付与する毎にタレント失敗率は増加し、５段階目で最高値の %d%% に達します。
		　この効果を受けている相手が近接攻撃か射撃攻撃を受けると、有毒物質が傷口に染み込み酸属性の %0.2f ダメージを追加で受けます。追加ダメージの発生はターン毎に１回までです。
		　再付与しても効果の持続時間は増加しません。
		　対象が効果を耐え抜いた場合、この有毒物質に対して９ターンの間免疫を獲得します。]], "tformat")
t("Caustic Dispersal", "スモッグシュート", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t("You fire a toxic shell that explodes in radius %d, dealing %d%% weapon damage as acid and leaving behind a cloud of miasma for %d turns that inherits all effects from your Miasma Engine.", "半径 %d マスに爆発を起こす有毒物質の弾丸を撃ちます。これは倍率 %d%% の酸属性で、有毒スモッグを %d ターンの間発生させます。この有毒物質の効果は「ミアズマエンジン」のものに準じます。", "tformat")
t("Smogscreen", "スクリーンガス", "talent name")
t("You become difficult to target through the thick smog generated by your Miasma Engine. While surrounded by miasma you have a %d%% chance to entirely avoid damage, increased by %d%% per stack.", "「ミアズマエンジン」が生成するスモッグで姿を晦まします。スモッグが取り巻いているなら %d%% の確率で被ダメージを無効化します。これはスタック数毎に %d%% 増加します。", "tformat")
t("Fumigate", "汚物は消毒", "talent name")
t("You require a steamgun and an active miasma cloud for this talent.", "スチームガンを装備していないか、有毒スモッグが発動していない。", "logPlayer")
t([[You consume all Miasma Engine stacks you have to fire a blast of corrosive death through your steamgun, dealing %d%% weapon damage as acid in a radius %d cone with a %d%% chance to remove a random beneficial physical or mental effect. For every stack beyond the first the damage dealt is increased by 50%% and there is a %d%% chance to remove an additional effect.
		This attack ignores all enemy armour, and you must have at least 1 stack of Miasma Engine to use this talent.]], [[「ミアズマエンジン」による効果のスタックを全て消費し、スチームガンから強烈な酸を放ちます。これは倍率 %d%% の酸属性で、扇状の半径 %d マスを範囲とし、対象のランダムな物理または精神系のバフを %d%% の確率で除去します。この攻撃は（スタック数－１）×５０％分、与ダメージが増加し（スタック数－１）× %d%% の確率で追加のバフ除去が発生します。
		　このタレントは敵のアーマーを完全に無視します。また、「ミアズマエンジン」のスタック数が１以上なければ使用できません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/chemistry.lua"

t("Therapeutics", "医学習得", "talent name")
t([[Allows you to create therapeutic tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[医療系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。
		　タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません）
		%s]], "tformat")
t("Chemistry", "化学習得", "talent name")
t([[Allows you to create chemical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[化学系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。
		　タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません）
		%s]], "tformat")
t("Explosives", "危険物取扱", "talent name")
t([[Allows you to create explosive tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[爆発物系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。
		　タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません）
		%s]], "tformat")
t("Steam Power", "スチームパワー", "talent name")
t("Increases the efficiency of all steamtech you operate, granting %d steampower.", "蒸気機械の出力効率が上昇します。蒸気パワーが %d 上昇します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/demolition.lua"

t("Grenade Launcher", "グレネードランチャー", "talent name")
t([[You mount a grenade launcher on your steamgun that launches high explosive rounds. Each time you make a basic attack with your steamgun or a heavy weapon, you fire a grenade at the target that explodes for %d%% steamgun damage in radius %d.
		This talent also reinforces the armor of you and your minions to give you immunity to your own grenades.
		You can only fire a single grenade once every 9 turns.]], [[大爆発を起こすグレネードランチャーをスチームガンに装着します。スチームガンか重火器で通常の攻撃を行う毎に対象へグレネード弾を撃ち、倍率 %d%% のスチームガン射撃ダメージを半径 %d マスに与えます。
		　このタレントにより自身や仲間の装甲も強化されるため、自分の撃つグレネード弾で被害を被ることはありません。
		　グレネード弾は９ターン毎にしか発射されません。]], "tformat")
t("Reactive Armor", "ボムプレート", "talent name")
t([[You line your armor with explosive plating that detonates when struck. On taking a melee or ranged hit that deals more than 8%% of your maximum life a plate detonates, reducing the damage taken by %d%% and triggering a basic grenade attack in a radius %d cone projected at the target dealing %d%% of its usual damage.
		This cannot trigger more than once per turn.
		Blocking an attack with your shield will also trigger the retaliation damage, if it has not already triggered this turn.
		You have up to 3 plates at a time, and regain one every %d turns.]], [[衝撃を受けると爆発するボムプレートを防具に敷き詰めます。近接・射撃攻撃で最大ＨＰの８％を超えるダメージを受けると、プレートが１枚爆発します。これによりそのダメージを %d%% 軽減し、通常のグレネード弾による攻撃を放ちます。このグレネード弾は攻撃者を標的とした扇状の半径 %d を範囲とし、ダメージは通常の %d%% です。
		　本タレントはターン毎に１回しか発動しません。
		　効果が未発動ならばブロックした際にもグレネード弾の反撃が発生します。
		　一度に保持しておけるプレートは３枚までです。プレートは %d ターン毎に１枚補充されます。]], "tformat")
t("Sapper", "特殊工作弾", "talent name")
t([[You load advanced grenades into your launcher.
	Incendiary Grenade: Deals fire damage over 3 turns, increasing damage taken by %d%%.
	Chemical Grenade: Deals acid damage and slows targets by %d%% for 3 turns.
	Shock Grenade: Deals lightning damage and shocks targets for %d turns, reducing stun and pin resistance by 50%%.
	In addition, your turrets now explode when destroyed, dealing %0.2f physical damage to enemies in radius 3.
	You can only choose a single type of grenade at a time.]], [[改造グレネード弾を装填します。
	
	・フレイムグレネード
	　火炎属性ダメージを３ターンかけて与え、被ダメージを %d%% 増加させます。 
	
	・ケミカルグレネード
	　酸属性ダメージを与えて３ターンの間 %d%% 減速させます。 
	
	・ショックグレネード
	　電撃属性ダメージを与えて %d ターンの間感電させます。これによりスタン・移動不能耐性が５０％低下します。 
	
	　また、タレットが破壊された際に爆発して半径３マスの敵全員に物理属性の %0.2f ダメージを与えます。
	　改造グレネード弾は一度に一種類しか装填しておけません。]], "tformat")
t("Barrage", "バラージ", "talent name")
t("You require a steamgun and an empty grenade launcher for this talent.", "スチームガンを装備していないか、グレネードが空になっていない。", "logPlayer")
t([[You load a magazine of %d grenades into your launcher, causing your next %d shots to fire a random grenade type in place of your usual Grenade Launcher, dealing 50%% of the usual grenade damage.
		While the magazine is loaded your attack speed is increased by %d%%.
		Your Grenade Launcher talent must be on cooldown to use this talent, and the magazine will only last for 6 turns.]], [[グレネードランチャーに %d 発装填します。使用後は %d 発まで、射撃をした際に通常のグレネード弾の代わりにランダムなグレネード弾を撃つようになります。ただしこの時に撃つグレネード弾は通常の５０％ダメージとなります。
		　装填中は攻撃速度が %d%% 上昇しています。
		　このタレントは「グレネードランチャー」がクールダウンしていないと使えません。また、６ターン経過すると効果は切れます]], "tformat")
t("Incendiary Grenade", "フレイムグレネード", "talent name")
t("Enhance your grenade with an incendiary agent that burns through armor, dealing fire damage over 3 turns and increasing damage taken while burning by %d%%.", "発火物質でグレネード弾を改造し、防具ごと敵を焼きます。３ターンかけて火炎属性ダメージを与え、被ダメージを %d%% 増加させます。", "tformat")
t("Chemical Grenade", "ケミカルグレネード", "talent name")
t("Enhance your grenade with incapacitating chemicals that deal acid damage and reduce global speed by %d%% for 3 turns.", "麻痺物質をグレネード弾に仕込みます。酸属性ダメージを与え、３ターンの間 %d%% 減速させます。", "tformat")
t("Shock Grenade", "ショックグレネード", "talent name")
t("Enhance your grenade with an electrical charge, causing it to deal lightning damage and shock targets for %d turns, reducing stun and pin resistance by 50%%.", "グレネード弾を帯電させます。これは対象に電撃属性ダメージを与えて %d ターン感電させます。感電した相手はスタン・移動不能耐性が５０％低下します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/dread.lua"

t("Mechanical Arms", "マシンアーム", "talent name")
t([[Using psionic forces you maintain in place on your back two giant horrific mechanical arms.
		Each basic turn (as if you had 100%% speed) they can automatically attack up to 2 foes within range 3 with a mindstar attack doing %d%% weapon damage.
		Creatures harassed by the mechanical arms have their damage reduced by %d%% for 5 turns.]], [[超能力を使用して背面に身の毛のよだつ巨大マシンアームを二本取り付けて操ります。
		　基本ターンが経過するごとに（プレイヤーが速度１００％で行動するような基準です）自動で半径３マス以内に存在する敵に攻撃します。対象となるのは最大２体までです。この攻撃はマインドスターの倍率 %d%% ダメージ攻撃となります。
		　この攻撃を受けた相手は怯んでしまい与ダメージが５ターンの間 %d%% 減少します。]], "tformat")
t("Lucid Shot", "明晰夢の一射", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t([[Fire a powerful shot at a foe doing %d%% weapon damage.
		If the creature, or any creatures in radius 3, was affected by a fear or nightmare effect it violently wakes up, shaking it off only to find itself disoriented, unable to discern friends from foes for %d turns.]], [[敵一体に強烈な射撃を行います。倍率 %d%% の射撃攻撃です。
		　対象、または対象の半径３マス以内に存在する敵のいずれかが恐怖系や悪夢系の効果を受けている場合、その相手は不意に暴れだし、正気を取り戻そうとします。ただ錯乱するだけの結果に終わるのですが。これにより、敵味方の区別が %d ターンの間つかなくなります。]], "tformat")
t("Psy Worm", "サイコワーム", "talent name")
t([[Fire a psionic-enhanced shot at a foe doing %d%% mind weapon damage and infecting it with a psy worm for 8 turns.
		Each turn the worm will do %0.2f mind damage and restore %d psi to you, double if stunned or feared.
		Also each turn the worm has 25%% chances to spread to a nearby foe in radius 3.
		When a creature infected by Psy Worm dies it spreads to all enemies in a radius of 3.]], [[理力を込めた射撃を敵一体に放ちます。倍率 %d%% の射撃です。これは精神属性となり、対象に８ターンの間サイコワームを植え付けます。
		　これは対象に毎ターン %0.2f の精神属性ダメージを与え、さらに術者のＰｓｉを %d 回復します。スタンか恐怖状態にあるときはこれは倍になります。
		　また、毎ターン２５％の確率でサイコワームは対象の周囲３マス以内に存在する敵１体に感染します。
		　対象が死亡した場合は対象の周囲３マスの全員に感染します。]], "tformat")
t("No Hope", "望みを捨てよ", "talent name")
t("Entering the mind of your foe you manipulate it to make it lose hope of defeating you, reducing all its damage by 40%% for %d turns.", "敵の心の中に入り込んで精神を操り、戦意を挫きます。対象の与ダメージが４０％低下します。持続時間は %d ターンです。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/elusiveness.lua"

t("Slip Away", "スリップアウェイ", "talent name")
t([[Using small steam motors to enhance your movements, you are able to slip past up to %d foes in a line.
		After passing the targets, you will quickly run %d tiles away.]], [[小型の蒸気モーターを利用して移動速度を強化します。直線上の敵 %d 体までをすり抜けます。
		　すり抜けた後は %d マス走ります。]], "tformat")
t("Agile Gunner", "早駆け銃士", "talent name")
t([[The thrill of the hunt invigorates you. For each foe in radius %d around you, you gain 20%% movement speed (up to %d%%).
		Current bonus: %d%%.]], [[死闘の緊迫感をバネに動きを速めます。周囲 %d マス以内に存在する敵一体当たり、術者の移動速度が２０％増加します。これは最大で %d%% が上限です。
		　現在の増加量：%d%% ]], "tformat")
t("Awesome Toss", "無双曲射", "talent name")
t("You require two steamguns for this talent.", "スチームガンを二丁拳銃していないと使えない。", "logPlayer")
t([[In an awesome feat of agility and technological prowess, you toss both of your steamguns in the air, causing them to spin madly for 3 turns.
		Each turn, they will fire twice at random targets in range, dealing %d%% weapon damage.
		While the guns are airborne, you are disarmed and cannot attack.
		The spectacle is so distracting that your foes have a hard time concentrating on you, increasing all of your resistances by %d%%.]], [[手練の早業と優れた科学技術。その二つを併用し、スチームガンを宙に放って高速回転させます。持続時間は３ターンです。
		　空中で回転している間は射程内のランダムな敵に対して毎ターン２回射撃します。これは倍率 %d%% の武器攻撃です。
		　発動中は武器解除状態となり攻撃できません。
		　敵の方は宙を舞うスチームガンから目を離すわけにはいきません。そのためタレント使用者への攻撃が疎かになり、使用者の全ての耐性が %d%% 上昇します。]], "tformat")
t("Dazzling Jump", "ハイパージャンプキック", "talent name")
t("%s seems immune to the powerful kick.", "%sを蹴っても無意味なようだ。", "logSeen")
t([[While your foes are distracted by your Awesome Toss, you use powerful steam motors to jump into the air and kick a target %d tiles away.
		The impact is so great that it ripples outwards, slowing all creatures in radius 3 by %d%% for 4 turns while the reaction force propels you %d tiles backwards.]], [[敵が「無双曲射」に気を取られている間に、対象に向かって強力な蒸気モーターを用いた飛び蹴りを放ちます。対象は %d マスノックバックします。
		　凄まじい威力のキックなので衝撃波が周囲に伝播します。これによって半径３マスのあらゆるキャラクターが %d%% 減速します。持続時間は４ターンです。使用後、術者は反動で %d マス後退します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/engineering.lua"

t("Emergency Steam Purge", "バルブオープン", "talent name")
t([[You open all steam valves at once, releasing a radius %d wave of superheated steam around yourself which deals %0.2f fire damage (but can not be a critical hit).
		If you had at least 35 steam, the vapours will be so hot that they can burn sensory organs, blinding affected creatures for %d turns.
		The effects scale with your current steam value; at 1 steam they are only 15%% as effective as at 50 or more (current factor %d%%).]], [[蒸気バルブを一斉に開放し、周囲に超高温の蒸気を放射します。これによって半径 %d マス以内の敵に火炎属性の %0.2f ダメージを与えます（クリティカルはしません）
		　蒸気の残量が３５以上の場合、敵は湯気で目を火傷してしまい %d ターンの間盲目状態になります。
		　効果量は現在の蒸気量に依存します。蒸気量１の時の効果量は、蒸気量５０以上で使用した際の１５％に過ぎません（現在の効果量 %d%% ）]], "tformat")
t("Innovation", "イノベーション", "talent name")
t([[Your knowledge of physical laws allows you to use and improve equipment in ways their creators never dreamed.
		Increases all stats, saves, armour, and defense bonuses by %d%% on equipment that is crafted by a master or powered by steamtech.]], [[物理法則に精通しているおかげで、製作者の想定を遥かに超えた装備の使用、改良ができます。
		　装備品の能力値増加量、セーブ、アーマー、回避が %d%% 増加します。これが適用されるのは、工芸品か蒸気機械に属するものだけです。]], "tformat")
t("Supercharge Tinkers", "蒸気チャージ", "talent name")
t([[Using a huge amount of steam, you temporarily supercharge your tinkers and other steam-powered talents.
		For %d turns, you gain %d steampower and %d%% steamtech critical chance.]], [[大量の蒸気を用いて工士アイテムと蒸気を用いるタレントを一時的に強化します。
		　持続時間は %d ターンです。効果中は蒸気パワーが %d 蒸気クリティカルが %d%% 上昇します。]], "tformat")
t("Last Engineer Standing", "不屈のエンジニア", "talent name")
t([[Sometimes, being a master tinker requires taking risks; yours are more calculated than others.
		Gain %d cunning, %d physical save, %d%% resistance to self-inflicted damage, and %d%% chance to avoid being critically hit.]], [[時として、一流の工士はリスクを背負わねばなりません。あなたのリスク計算は工士の中でも群を抜いています。
		　賢さが %d 上昇します。また、物理セーブが %d 増加し、自分自身を攻撃した際のダメージに対して %d%% の耐性を得ます。さらに %d%% の確率でクリティカルを免れます。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/furnace.lua"

t("Furnace", "メルトポッド", "talent name")
t([[You add a portable furnace to your steam generators.
		While it is active your fire and physical damage increases by %d%% and your fire and physical resistance penetration by %d%%.
		#{italic}#Burninate all with awesome Steam power!#{normal}#
		]], [[携帯型溶鉱炉を蒸気ジェネレーターにセットします。
		　起動中は火炎・物理属性の与ダメージが %d%% 上昇し、火炎・物理属性の属性貫通が %d%% 増加します。
		
		#{italic}#　全部燃やせ！　蒸気最高！#{normal}#
]], "tformat")
t("Molten Metal", "溶解金属ガード", "talent name")
t([[While Furnace is on your armour is so hot from the furnace it dissipates parts of all energy based attacks against you.
		All non physical, non mind damage is reduced by %d (current %d).
		Each turn this happens you gain a molten point (up to 10), decreasing the efficiency of the reduction by 25%%.
		Molten points are removed upon running or resting.
		#{italic}#Hot liquid metal, the fun!#{normal}#
		]], [[「メルトポッド」の起動中は、溶鉱炉によって鎧が高熱を帯び、エネルギー系攻撃を部分的に打ち消します。
		　物理・精神属性以外のダメージが %d 軽減されます（現在 %d 軽減）
		　ダメージ軽減が発生したターンには溶鉱ポイントが加算されます。これは最大で１０ポイントまで累積し、１ポイント辺りダメージ軽減量が０．７５倍されます。
		　溶鉱ポイントは走るか休憩するかすると元に戻ります。
		
		#{italic}#　アッツアツの液体金属！　いいね！#{normal}#
]], "tformat")
t("Furnace Vent", "ブラストファン", "talent name")
t([[Open the vents on your furnace, creating a conic blast dealing up to %0.2f fire damage at 10 molten points (currently %0.2f).
		All molten points are consumed.
		The damage will increase with your Steampower.
		#{italic}#By fire be purged!#{normal}#
		]], [[携帯式溶鉱炉の通風孔を開いて広範囲に爆風を起こします。これは火炎属性の %0.2f です。このダメージは溶鉱ポイントが１０の時のものです（現在は %0.2f ）
		　使用時に溶鉱ポイントを全て消費します。ダメージは蒸気パワーに依存します。
		
		#{italic}#　炎の裁きだ！#{normal}#
]], "tformat")
t("Melting Point", "メルティングポイント", "talent name")
t([[When you reach 10 molten points your armour overheats, reaching temperatures so high that they cauterize up to %d detrimental physical effects on you.
		A special medical injector injects you with a fire immunity serum at that precise moment to make you immune to the burning effect.
		When this happens all molten points are consumed and trigger a Furnace Vent at the creature that triggered the last molten point.
		This effect drains 15 steam when triggered, and will not trigger if steam is too low.
		#{italic}#It's only a flesh burn!#{normal}#
		]], [[溶鉱ポイントが１０に達すると鎧が過熱します。超高温によって物理系のデバフが最大 %d 種除去されます。
		　この際、特殊医療装置が発動し耐熱液を術者に注入します。これにより炎上効果を受けなくなります。
		　効果が発動すると溶鉱ポイントは０になり「ブラストファン」が発動します。「ブラストファン」の対象は溶鉱ポイントが１０になる際に術者を攻撃した相手です。
		　発動すると蒸気を１５消費します。１５未満の場合は効果を発揮しません。
		
		#{italic}#　ただの火傷だよ！#{normal}#
]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/gadgets.lua"

t("Autoloader", "オートロード", "talent name")
t([[You link your weapons and shield to your steam generators, using them to load ammunition and improve the power of your weapons. 
		Each time you fire your Steamgun, you have a %d%% chance to reload 1 Heavy Weapon ammo.
		Each time you fire a Heavy Weapon you reload %d ammo.
		Each time you raise your shield to block, you reload 1 Heavy Weapon ammo.
		This also increases weapon damage by %d%% and Physical Power by 30 when using steamguns or heavy weapons.
		In addition, your steamgun and heavy weapon shots now bypass friendly targets harmlessly.]], [[武器と盾を蒸気発生装置とリンクさせ、銃弾の装填を行い威力を高めます。
		　スチームガンで射撃する毎に %d%% の確率で重火器の専用弾を１個装填します。
		　重火器で攻撃する毎に矢弾を %d 個装填します。
		　「ブロッキング」タレントを実行する毎に重火器の専用弾を１個装填します。
		　また、スチームガンと重火器を使用する際の与ダメージが %d%% 増加し、物理パワーが３０上昇します。
		　加えてスチームガンと重火器で攻撃する際に味方にダメージを与えないようになります。]], "tformat")
t("Exoskeleton", "蒸気式パワードスーツ", "talent name")
t("#STEEL_BLUE#(%d exoskeleton)#LAST#", "#STEEL_BLUE#(%d　パワードＳ)#LAST#", "tformat")
t([[Current exoskeleton life: %d/%d
		You craft a set of steam powered armor that fits over your regular armor, enhancing your defense. The armor has %d life, and 50%% of all damage taken is redirected to it.
		Your powered armour repairs 5%% of it’s maximum life each turn, and each time you spend steam it will be repaired for %d%% of the steam cost.
		The armor's maximum life will increase with your Steampower.]], [[現在のパワードスーツ強度: %d/%d
		　普通の防具の上からフィットする蒸気式アーマーを作成し、守りを強化します。このパワードスーツは %d のＨＰを有しており、自身が受けたダメージの５０％はこちらに転嫁されます。
		　パワードスーツのＨＰはターン毎に５％回復します。また、蒸気を消費すると消費量の %d%% 分回復します。
		　スーツの最大ＨＰは蒸気パワーに依存します。]], "tformat")
t("Hypervision Goggles", "超視力ゴーグル", "talent name")
t([[Enhance your vision for %d turns, giving you vision of all targets in range %d, even through walls. While the goggles are active you also spot flaws in your opponent's defenses, increasing your resistance penetration by %d%%.
In addition, the goggles passively increase your stealth, invisibility and trap detection by %d.]], [[視界を %d ターン強化し、壁を通して半径 %d マス以内のあらゆる相手を視認できるようになります。効果中は敵の弱点を見抜けるようになり、耐性貫通が %d%% 増加します。
　また、パッシブ効果として隠密看破と透明視、罠発見が %d 増加します。]], "tformat")
t("AED", "ＡＥＤ", "talent name")
t([[Prepare a defensive device that stores an electrical charge for 8 turns.
If your life falls below 0 while the AED is active it will activate to shock you back into life, negating the triggering attack, restoring %d life and dealing %0.2f lightning damage in radius %d that dazes affected enemies for 3 turns.
If the AED does not activate, the cooldown is reduced by 15 turns.
The healing and damage will increase with your Steampower.]], [[８ターン帯電する防御デバイスをセットします。
　自身のＨＰが０未満になるとこのＡＥＤが起動し、電気ショックで意識を取り戻します。これによりトリガーとなったダメージを無効化し、ＨＰを %d 回復して電撃属性の %0.2f ダメージを半径 %d マスに与えます。この電撃を受けた相手は３ターンの間朦朧状態になります。
　ＡＥＤが起動しなかった場合、このタレントのクールダウンは１５ターン減少します。
　ＨＰ回復量と与ダメージは蒸気パワーに依存します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/gunner-training.lua"

t("Steamgun Mastery", "スチームガン・マスタリー", "talent name")
t([[Increases weapon damage by %d%% and Physical Power by 30 when using steamguns.
		Also, increases your reload rate by %d.]], [[スチームガンを用いる際の物理パワーが３０上昇します。また、与ダメージも %d%% 増加します。
		　さらに装填率も %d 増加します。]], "tformat")
t("Double Shots", "ダブルショット", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t("%s resists!", "%s は抵抗した！", "logSeen")
t([[In an overpowering display of marksmanship, you fire your steamgun(s) twice in rapid succession.
Each shot (targeted separately) deals %d%% damage and stuns its target for %d turns.
		The stun chance increases with your Steampower.]], [[圧倒的な射撃技術を生かしてスチームガンの高速連射を行います。
		　この射撃は倍率 %d%% のダメージです（別々の敵に１回ずつ撃つこともできます）対象は %d ターンの間スタンします。
		　スタン確率は蒸気パワーに依存します。]], "tformat")
t("Uncanny Reload", "超高速リロード", "talent name")
t([[You focus on managing your steamgun ammo for %d turns.
		While the effect lasts your attacks do not consume shots.]], [[スチームガンの装填に集中します。
		　持続時間は %d ターンです。効果中は弾丸を消費しません。]], "tformat")
t("Static Shot", "エレクトリッカー", "talent name")
t([[You fire a special, electrically charged shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it bursts into electrified shrapnel within radius %d, which shocks each target hit and deals %d%% weapon damage as lightning.
		Shocked targets lose up to %d non-magical effects (for the first shot that hits).
		This talent does not use ammo.]], [[射程内の地点を狙って帯電した特殊弾丸をスチームガンで撃ち込みます。
		　目標地点に着弾すると、この弾丸は爆発し、電磁気を帯びた散弾となって半径 %d に飛び散ります。これは倍率 %d%% の武器攻撃ダメージを電撃属性として与えます。
		　電撃を浴びた相手は物理・精神系のステータス効果が最大で %d 種類解除されます（最初に命中した弾丸に対して適用されます）
		　このタレントは銃弾を消費しません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/gunslinging.lua"

t("Strafe", "ストライフ", "talent name")
t("@Source@ strafes with @hisher@ steamguns!", "@Source@は@hisher@スチームガンで掃射した！", "_t")
t("You must dual wield steamguns for this talent.", "二丁拳銃していないと使えない。", "logPlayer")
t([[You have learned to fire while moving.
		In one motion, you fire your double steamguns (100%% weapon damage, 1 tile range penalty) and may then move to an adjacent tile (unless pinned to the ground or immobilized).
		This talent can be activated for up to %d consecutive turns before it goes on cooldown, and takes time according to your steamtech speed or movement speed (if you move), whichever is slower.
		When Strafe ends you may instantly reload between %d and %d ammo (based on the number of strafes you performed and your ammo capacity).]], [[動きながら射撃します。
		　二丁拳銃を撃ちつつ１マス移動するという行動をワンアクションで実行します。これは倍率１００％の射撃で射程に１マスペナルティを受けます。移動不能の場合は移動できません。
		　このタレントは連続 %d 回使用するとクールダウンが発生します。使用時には機工速度と移動速度のどちらか低い方を参照します。移動速度は移動不能の場合は参照されません。
		　移動射撃が終わると、即座に弾丸を装填します。装填数は %d から %d です。これはこのタレントを使った回数と弾丸の最大値に依存します。]], "tformat")
t("Startling Shot", "威嚇射撃", "talent name")
t("Something", "何者か", "_t")
t("%s misses %s shot.", "%sが%sワザと狙いを外した。", "logSeen")
t([[You deliberately fire a missing shot at a target, startling it for 3 turns.
		If the target fails a mental save it instinctively recoils two steps back.
		The next shot that hits the startled creature will deal %d%% more damage.]], [[わざと狙いを外して射撃します。対象は３ターンの間動揺します。
		　対象は精神セーブの判定に失敗すると２マス下がります。
		　動揺している相手に対しては次の射撃のダメージが %d%% 増加します。]], "tformat")
t("#Source# fires a retaliatory shot at #Target#!", "#Source#は#Target#に撃ち返した！", "logCombat")
t("Evasive Shots", "カウンターガン", "talent name")
t([[Using small engines to augment your reflexes you are able to automatically fire retaliatory shots at your foes doing %d%% weapon damage.
		Retaliation shots are fired when you evade/are missed by a melee or ranged attack.
		This can only happen once per turn and uses shots as normal.]], [[小型の蒸気エンジンを用いて反応速度を上昇させます。敵に対して倍率 %d%% の射撃で自動的に反撃します。
		　この反撃は近接・射撃攻撃を回避した際に発生します。
		　反撃射撃は１ターンにつき１回しか発生しません。反撃射撃時の銃弾使用は通常の射撃に準じます。]], "tformat")
t("Trick Shot", "トリックショット", "talent name")
t([[Your cunning and dexterity allow you to fire incredible trick shots that can hit multiple targets.
		You precisely aim your trick shot to ricochet amongst foes you can see so that whenever it hits something solid (creature or solid wall), it will bounce towards the next closest foe.
		It may ricochet up to %d times (or until it misses) within range 5 of your first target and will not target the same foe twice.
		Your shot deals %d%% weapon damage on its first strike, but loses %d%% damage and %d(%d%%) accuracy with each bounce.]], [[あなたは切れ者の凄腕ガンマンです。想像を絶する妙技で複数の敵を一度に撃てます。
		　視認中の敵集団へ精密射撃し、跳弾させます。この射撃は剛体（敵や硬い壁など）に当たる毎に跳ね返り、最寄りの敵に向かいます。
		　跳弾する回数は最大 %d 回です。回避された場合はその時点で終了します。最初に標的にした対象の半径５マスが跳弾する範囲です。同じ相手に複数回当たることはありません。
		　ダメージは倍率 %d%% です。一回跳弾するごとにダメージは %d%% 低下し、命中は %d (%d%%) 低下します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/heavy-weapons.lua"

t("Heavy Weapons", "重火器装備", "talent name")
t([[You gain the ability to equip one of 3 heavy weapons listed below, temporarily granting you a special attack. Heavy weapons are significantly more powerful than a steamgun, but require heavy ammunition to fire. You can store up to %d ammunition at a time, and regenerate 1 every 3 turns while a heavy weapon is not equipped.
		
		#AQUAMARINE#Flamethrower#LAST#: An incendiary device which projects streams of liquid flame at your foes. Deals %d%% steamgun fire damage over 3 turns to those in radius 5. The flamethrower ignores armor, always hits, and counts as a steamgun shot for the purpose of on-hits.
		#AQUAMARINE#Shockstaff#LAST#: An electrically charged baton wielded in close combat. Deals %d%% lightning damage to enemies in a frontal arc, as well as reducing the damage they deal by %d%% for 3 turns. This counts as a melee attack but triggers ammunition on-hit effects. All shockstaff attacks will also make a shield attack for the same damage as lightning. You can charge up to your steamgun's range to make shockstaff attacks.
		#AQUAMARINE#Boltgun#LAST#: A multi-barreled steamgun that launches efficient, chemical infused bolts. Fires twice for %d%% steamgun acid damage and generates %d steam per hit.
		
		The damage dealt by your Heavy Weapons is based off your currently equipped ammunition, and are treated as Steamguns for the purposes of weapon mastery talents and other effects.
		Firing your Steamgun will immediately unequip your heavy weapon.		
		]], [[以下の重火器３種から１つを選択して装着し、一時的に特殊攻撃を実行できるようになります。重火器はスチームガンよりも遥かに強力ですが、専用弾を必要とします。一度に保持しておける専用弾は %d 発までです。重火器を装着していなければ３ターン毎に１個補充されます。
		
		・#AQUAMARINE#火炎放射器#LAST#
		　燃え盛る液体燃料を敵に投射する火炎放射器です。これは半径５マス以内の相手に対する倍率 %d%% のスチームガン射撃です。火炎属性として３ターンかけてダメージを与えます。火炎放射はアーマーを無視し、回避されません。命中時の特殊効果はスチームガンで射撃した場合と同じ扱いになります。
		
		・#AQUAMARINE#ショックスタッフ#LAST#
		　近接戦闘用の電磁ロッドです。前方３マスに倍率 %d%% の電撃属性ダメージを与えます。これを受けた相手は３ターンの間与ダメージが %d%% 低下します。これは近接攻撃扱いですが、命中時の特殊効果は矢弾のものが発動します。盾を装備していれば同じダメージの盾攻撃を電撃属性として行います。この攻撃は離れた敵に突進して使用できます。この射程はスチームガンの射程と同じです。

		・#AQUAMARINE#ボルトガン#LAST#
		　多頭バレルのスチームガンです。強い効力を有する化学物質を銃弾に込めています。これは倍率 %d%% の射撃を２回行い、酸属性ダメージを与えます。一撃命中する毎に蒸気が %d 回復します。
		
		　重火器によるダメージは装備中の矢弾に準じます。マスタリーをはじめとした様々な効果においてスチームガンとして扱います。
		　スチームガンで射撃するとその時点で重火器は外されます。	
		]], "tformat")
t("Flamethrower", "火炎放射器", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t("You require heavy ammunition to use this talent.", "専用弾がもうない。", "logPlayer")
t([[You replace your steamgun and attack with an incendiary device that projects streams of liquid flame at your foes.
		
		Deals %d%% steamgun damage as fire over 3 turns to enemies in radius 5.

		These attacks cannot miss and ignore armor.]], [[スチームガンの代わりに火炎放射器で攻撃し、燃え盛る液体燃料を浴びせます。
		　倍率 %d%% のスチームガン射撃ダメージを火炎属性として３ターンかけて与えます。範囲は半径５マスです。
		　この攻撃は回避されず、アーマーを無視します。]], "tformat")
t("Flame Jet", "火炎ジェット", "talent name")
t("You are disarmed.", "今は武器が使えない。", "logPlayer")
t("You require heavy ammunition to fire your flamethrower.", "専用弾がもうない。", "logPlayer")
t("Fire a jet of flame, dealing %d%% weapon damage as fire over 3 turns.", "火炎ジェットで倍率 %d%% の火炎属性ダメージを３ターンかけて与えます。", "tformat")
t("Shockstaff", "ショックスタッフ", "talent name")
t("You require heavy ammunition to power your shockstaff.", "専用弾がもうない。", "logPlayer")
t([[You replace your steamgun and attack with a lightning-charged staff to engage in close combat.
		
		Deals %d%% steamgun damage as lightning to enemies in a frontal arc, as well as reducing the damage they deal by %d%% for 3 turns. This counts as a melee attack but triggers ammunition on-hit effects. All shockstaff attacks will also make a shield slam for the same damage as lightning. 

		You can charge up to your steamgun's range to make shockstaff attacks.]], [[スチームガンの代わりに近接用の電磁ロッドで攻撃します。
		　これは前方３マスを攻撃する倍率 %d%% のスチームガン射撃で、電撃属性です。対象の与ダメージを３ターンの間 %d%% 減少させます。これは近接攻撃扱いですが、矢弾の命中時効果が適用されます。盾を装備していれば同ダメージの盾攻撃を電撃属性として実行します。
		　電磁ロッドによる攻撃は、スチームガンの射程範囲にいる相手へ突進して行えます。]], "tformat")
t("Stormstrike", "ストームストライク", "talent name")
t([[Sweep your shockstaff, striking all enemies in a frontal arc for %d%% weapon damage as lightning and reducing their damage dealt by %d%% for 3 turns.
		If you have a shield, you will also strike them.
		While active this replaces your normal melee attack.]], [[電磁ロッドを薙ぎ払い、前方３マスの敵全員に倍率 %d%% の電撃属性攻撃をします。
		　これを受けた相手は３ターンの間与ダメージが %d%% 減少します。盾を装備しているなら盾攻撃も行います。
		　起動中は近接攻撃の代わりに電磁ロッドで攻撃します。]], "tformat")
t("Boltgun", "ボルトガン", "talent name")
t("You require heavy ammunition to fire your boltgun.", "専用弾がもうない。", "logPlayer")
t([[You replace your steamgun and attack with a multi-barreled bolt launcher, firing deadly chemical-infused flechettes.
		
		Each attack fires twice for %d%% weapon damage as acid and generates %d steam per hit.]], [[スチームガンの代わりに多頭バレルのボルトランチャーで、有毒化学物質を込めたフレチェット弾を撃ちます。倍率 %d%% の射撃を２回行い、酸属性ダメージを与えます。
		　一撃命中する毎に蒸気が %d 回復します。]], "tformat")
t("Flechette Burst", "フレチェットバースト", "talent name")
t("%s resists the disarm!", "%sは武器解除に抵抗した！", "logSeen")
t("Fire two chemical flechettes, dealing %d%% weapon damage as acid and generating %d steam per hit.", "有毒フレチェット弾を２発撃ちます。倍率 %d%% の酸属性攻撃で、命中する毎に蒸気が %d 回復します。", "tformat")
t("Heavy Weapon Expertise", "重火器トレーニング", "talent name")
t("You require heavy ammunition and a heavy weapon to use this talent.", "重火器と専用弾がなければこのタレントは使えない。", "logPlayer")
t("%s resists the stunning blow!", "%sはスタンに抵抗した！", "logSeen")
t("%s resists the stunning shock!", "%sはスタンショックに抵抗した！", "logSeen")
t([[Your advanced training unlocks specialised techniques, triggering an effect based on your current heavy weapon at the cost of 1 heavy weapon ammunition.
#AQUAMARINE#Flamethrower#LAST#: Sweep your flamethrower across the ground, dealing %d%% steamgun damage as fire and raising a length 7 wall of fire for 5 turns. Those inside the wall take %0.2f fire damage and have their fire resistance reduced by %d%% for 2 turns.
#AQUAMARINE#Shockstaff#LAST#: Slam your staff into the target, creating a radius 3 shockwave that deals %d%% shockstaff damage as lightning and stuns those within for %d turns.
#AQUAMARINE#Boltgun#LAST#: Fire %d boltgun shots dealing %d%% steamgun damage as acid and disarming the target for 5 turns.
The damage dealt by the fire wall and the chance to apply effects will increase with your Steampower.]], [[トレーニングを重ね、特殊技術を習得します。装着中の重火器に応じて専用弾を１つ消費し、特殊効果を発揮します。

・#AQUAMARINE#火炎放射器#LAST#
　火炎放射で地面を焼き払います。倍率 %d%% のスチームガン射撃ダメージを火炎属性として与え、炎の壁を７マスに渡って発生させます。これは５ターン持続します。炎の壁に巻かれた相手は火炎属性の %0.2f ダメージを受け、火炎耐性が２ターンの間 %d%% 低下します。

・#AQUAMARINE#ショックスタッフ#LAST#
　ロッドを対象へ叩きつけて半径３マスに衝撃波を発生させます。これは倍率 %d%% のスチームガン射撃を電撃属性として与えます。範囲内の相手は %d ターンの間スタンします。

・#AQUAMARINE#ボルトガン#LAST#
　ボルトガンによる射撃を %d 回行います。それぞれ倍率 %d%% のスチームガン射撃で、酸属性ダメージです。対象を５ターンの間武器解除状態にします。

　炎の壁によるダメージと状態異常の付与確率は蒸気パワーに依存します。]], "tformat")
t("Automated Defenses", "オートディフェンス", "talent name")
t([[You augment your shield with your heavy weapon technology, causing an effect when you Block with a heavy weapon equipped.
#AQUAMARINE#Flamethrower#LAST#: Vent choking, burning smoke in an area of the same radius as your flamethrower. Enemies caught within take %d%% shield damage as fire and are silenced for %d turns.
#AQUAMARINE#Shockstaff#LAST#: Sheathe your shield in lightning and attack all enemies in radius 3, dealing %d%% shield damage as lightning and gaining a barrier absorbing an amount of damage equal to 100%% of the highest damage dealt for 6 turns.
#AQUAMARINE#Boltgun#LAST#: Fire a blast of flechettes from your shield at all enemies in radius 7, dealing %d%% shield damage as acid. %d flechettes remain embedded in each target for 6 turns, and when struck by a melee or ranged attack a flechette will detonate and cause acid damage equal to 50%% of the shield damage dealt.
These attacks will not trigger Counterstrike.
The chance to silence will increase with your Steampower.]], [[重火器のテクノロジーを利用して盾を強化します。重火器を装着している最中にブロックすると特殊効果が発生します。

・#AQUAMARINE#火炎放射器#LAST#
　燃え盛る排気ガスで敵の呼吸を止めます。範囲は火炎放射と同じです。範囲内の敵は倍率 %d%% の盾攻撃を火炎属性として受け %d ターンの間沈黙します。

・#AQUAMARINE#ショックスタッフ#LAST#
　盾に電気を纏わせて半径３マスの敵全員を攻撃します。これは倍率 %d%% の盾攻撃で電撃属性です。さらにダメージを無効化するバリアを６ターン展開します。バリアのダメージ無効化量は、この盾攻撃で与えたダメージの中で最も高いものと同じ値になります。

・#AQUAMARINE#ボルトガン#LAST#
　半径７マスの敵全員に盾からフレチェット弾の雨を発射します。これは倍率 %d%% の盾攻撃で酸属性です。フレチェット弾 %d 発がそれぞれの敵にめり込み６ターン残留します。これらは近接・射撃攻撃を受けると爆発し酸属性のダメージを与えます。ダメージ量は与えた盾攻撃の５０％分です。

　これらの特殊効果でカウンターは発生しません。
　沈黙状態の付与確率は蒸気パワーに依存します。]], "tformat")
t("Safety Override", "セーフオーバーライド", "talent name")
t("%s resists the stun!", "%s はスタンに抵抗した！", "logSeen")
t("%s slams into something solid, emitting a pulse of stunning lightning!", "%sは衝突して強烈な電撃パルスを放った！", "logSeen")
t([[Push your heavy weapon beyond its normal limits to trigger a powerful effect. This will immediately disable your heavy weapon and expends all remaining ammunition.
#AQUAMARINE#Flamethrower#LAST#: Detonate your fuel tanks, creating a radius 4 explosion that launches you to a chosen tile in range %d. Enemies caught within the explosion take %0.2f fire damage, and further fire damage equal to %d%% of their current burning damage from the volatile fuel.
#AQUAMARINE#Shockstaff#LAST#: Drive your staff into the ground, discharging all remaining power to deal %d%% shockstaff damage as lightning in radius %d. Those struck will be knocked back %d tiles, and if they strike a wall they will emit a static pulse dealing %0.2f lightning damage in radius 1 and stunning them for 5 turns.
#AQUAMARINE#Boltgun#LAST#: Overcharge your boltgun, firing a single deadly bolt dealing %d%% steamgun damage as acid in a piercing line. For each negative physical, magical, or mental effect on the target, they take an additional %d%% damage (to a maximum of %d%%) and the duration of each negative effect is increased by %d turns.]], [[重火器の性能を限界以上に引き出して強烈な効果を発揮します。重火器が使用不能になり、専用弾を全て消費します。

・#AQUAMARINE#火炎放射器#LAST#
　燃料タンクを爆破して半径４マスに爆発を起こします。これにより半径 %d マス以内の指定した地点へ跳びます。爆発に巻き込まれた敵は火炎属性の %0.2f ダメージを受けます。また、火炎放射で受けている炎上ダメージの %d%% に等しいダメージをさらに受けます。

・#AQUAMARINE#ショックスタッフ#LAST#
　ロッドを地面に突き刺して残量チャージを開放し、倍率 %d%% の電磁ロッド攻撃を電撃属性として半径 %d マスに与えます。これを受けた相手は %d マスノックバックされ、壁に衝突した場合は静電パルスを放ちます。静電パルスは半径１マスの範囲に電撃属性の %0.2f ダメージを与え、５ターンスタンさせます。

・#AQUAMARINE#ボルトガン#LAST#
　ボルトガンを過充填し、強烈な単発射撃を行います。これは倍率 %d%% のスチームガン射撃で、射線を貫通する酸属性攻撃です。対象が受けている物理・魔法・精神系の効果１種につき %d%% の追加ダメージが発生します（最大で %d%% までです）さらにデバフの持続時間をそれぞれ %d ターン延長します。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/inscriptions.lua"

t("\
Its effects scale with your %s stat.", "\
　効果量は%sに依存します。", "tformat")
t("Implant: Steam Generator", "インプラント：蒸気発生装置", "talent name")
t([[Steam generator that permanently creates %0.1f steam per turn.
		Can be activated for an instant burst of %d steam.]], [[蒸気がターン毎に %0.1f 回復します。
		　起動すると蒸気が即 %d 回復します。]], "tformat")
t("steam %d", "蒸気 %d", "tformat")
t("Implant: Medical Injector", "インプラント：医療用注射器", "talent name")
t("#LIGHT_BLUE#Medical injector selected to be used first by salves.", "#LIGHT_BLUE#軟膏使用時に用いる第一注射器をセットしました。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "未使用ならこの注射器を軟膏使用時に優先して使用します。", "logPlayer")
t("Medical injector allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "　効果量 %d%% クールダウン %d%% で軟膏を使用できます。", "tformat")
t("efficiency %d%% / cooldown %d%%", "効果量 %d%% ／ クールダウン %d%%", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/magnetism.lua"

t("Static Shock", "静電場ブロック", "talent name")
t([[Using your Block talent surrounds you and your minions in a static barrier for 4 turns, increasing all resistances by %d%%. If an enemy deals damage to you or your minions, the barrier will shock them for %d%% of your shield damage.
		This effect cannot damage the same target more than once per turn, and will not interact with Counterstrike.
You now also use your Cunning in place of Strength when equipping shields as well as when calculating shield damage.]], [[「ブロッキング」を使用すると自身と手下が４ターンの間静電バリアを纏い、全ての耐性が %d%% 増加します。このバリアは攻撃者を感電させて自身の盾攻撃の %d%% 分のダメージを与えます。
　同一ターン内に同じ相手に対して２回以上ダメージを与えることはなく、被カウンター状態にも干渉しません。
　また、盾の装備条件と盾攻撃のダメージ計算をする際に腕力の代わりに賢さを参照するようになります。]], "tformat")
t("Magnetic Field", "磁場フィールド", "talent name")
t("You require a shield for this talent.", "盾を装備していないと使えない。", "logPlayer")
t("#Source# shatters '#Target#'.", "#Source#は#Target#を破壊した。", "logCombat")
t([[You project a powerful blast of magnetic energy from your shield in radius %d around you. Enemies caught within are knocked back %d tiles and take %d%% shield damage as lightning, and any projectiles will be destroyed.
		While this talent is not on cooldown, you also project a magnetic field from your shield, reducing the speed of incoming projectiles by %d%% and your chance to be critically hit by %d%%.]], [[盾から半径 %d マスに強烈な電磁エネルギーを放ちます。範囲内の敵は %d マスノックバックされ、倍率 %d%% の盾攻撃を電撃属性として受けます。範囲内の飛来物は全て破壊されます。
		　このタレントがクールダウンしていなければ、盾から磁場を放ちます。これにより自身を狙う飛来物の速度が %d%% 低下し、クリティカルを受ける確率が %d%% 減少します。]], "tformat")
t("Capacitor Discharge", "緩衝コンデンサー", "talent name")
t([[Mount capacitors to your shield that dampen the impact of attacks, increasing block value by %d%% and storing 100%% of the damage blocked as an electrical charge (to a maximum of %d).
Activating this ability discharges blocked damage, firing a bolt of lightning dealing %d%% shield damage as lightning to the first target, then projecting a bolt of lightning that arcs to %d other targets dealing lightning damage equal to the stored amount.
If at maximum charge, this also dazes for 2 turns and the shield strike is a guarenteed critical hit.
The maximum damage you can absorb will increase with your Steampower.]], [[盾にコンデンサーを敷き詰めて攻撃を和らげます。ブロック値が %d%% 増加し、ブロックしたダメージの100%%分帯電します（最高で %d までです）
		　このタレントを使用すると溜めた電気を開放し、電撃弾を放ちます。これを最初に受けた相手は盾攻撃の %d%% 分を電撃属性として受けます。その後電撃弾を放ち %d 体まで他の敵に連鎖させます。電撃弾のダメージは溜めた電気の量と同じ値です。
		　帯電量が上限に達している場合は電撃弾に２ターンの朦朧効果が付き、このタレントの盾攻撃が必ずクリティカルになります。
		　帯電量の上限は蒸気パワーに依存します。]], "tformat")
t("Lightning Web", "ライトニングウェッブ", "talent name")
t("lightning web", "電撃ウェブ", "_t")
t([[Project a radius 3 electric field from your shield lasting %d turns. Enemies within this field will take an automatic shield strike for %d%% lightning damage each turn, while allies will gain flat damage reduction equal to %d%% (%d) of block value.
		All damage reduced by this effect will be stored for Capacitor Discharge.]], [[盾から半径３マスの電磁フィールドを展開します。これは %d ターン持続します。敵はこの範囲内にいると毎ターン倍率 %d%% の盾攻撃を電撃属性として受けます。味方の場合はブロック値の %d%% (%d)  分に等しい固定ダメージ減少を得ます。
		　この効果で軽減した分のダメージ量は全て「緩衝コンデンサー」の帯電分に回されます。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/mecharachnid.lua"

t("disarmed", "武器解除状態", "_t")
t("no ammo", "矢弾がない", "_t")
t("bad ammo", "矢弾が合わない", "_t")
t("incompatible missile launcher", "使用不可な射撃武器", "_t")
t("incompatible ammo", "使用不可な矢弾", "_t")
t("no shooter", "射撃武器がない", "_t")
t("Mecharachnid Link", "スパイダーマシンリンク", "talent name")
t("Link to the summoner.", "召喚者とのリンクです", "_t")
t("Self-destruction", "自爆", "talent name")
t([[The mecharachnid self-destructs, destroying itself and generating a blast of fire in a radius of %d, doing %0.2f fire damage.
		This spell is only usable when the mecharachnid's master is dead.]], [[スパイダーマシンが自爆して、半径 %d マスに爆発を起こし火炎属性の %0.2f ダメージを与えます。
		　このタレントはマシンの製作者が死亡している場合にしか使えません。]], "tformat")
t("A heavily armored mechachnical spider, armed to the teeth with advanced weaponry.", "　最新装備で完全武装した重装スパイダーマシンだ。", "_t")
t("Your mecharachnid is out of sight; you cannot establish direct control.", "スパイダーマシンが視界外にいる。直接操作できない。", "logPlayer")
t("Mecharachnid", "機械蜘蛛", "talent name")
t("mecharachnid", "機械蜘蛛", "_t")
t("%s (servant of %s)", "%s(%sの配下)", "tformat")
t("mecharachnid (servant of %s)", "スパイダーマシン (%sの配下)", "tformat")
t("Not enough space to invoke!", "召喚する場所がない！", "logPlayer")
t("Your mecharachnid is not dead.", "スパイダーマシンは無事だ。", "logPlayer")
t([[You build a mighty mechanical arachnid to assist you in combat. You can equip the mecharachnid with 2 steamguns, ammunition, and armor of your choice.
If your mecharachnid is dead, this will resurrect it with %d%% of its maximum life. Your mecharachnid is automatically rebuilt at full life when combat ends.
Your mecharachnid has level %d Steamgun Mastery, Combat Accuracy and Armor Training. The mecharachnid uses Dexterity instead of Strength to equip armor.
The mecharachnid has an inbuilt teleportation device that will recall it to you when combat ends if it is not nearby.]], [[強力なスパイダーマシンを作成して戦闘支援をさせます。スパイダーマシンにはスチームガンを二丁、矢弾、鎧を装備させられます。
		　破壊されている場合、このタレントを使うことで最大ＨＰの %d%% 分の現在ＨＰを保持した状態で修復します。戦闘外なら自動的に完全修復します。
		　スパイダーマシンの「スチームガン・マスタリー」、「攻撃確度」、「重装トレーニング」のレベルは %d です。鎧を装備する際は腕力の代わりに機敏を装備条件として参照します。
		　また、テレポート装置が組み込まれており、戦闘外で傍にいない時は製作者の下へ帰ってきます。]], "tformat")
t("Stormcoil Generator", "嵐電コイル", "talent name")
t("You equip your mecharachnid with a stormcoil generator, a mechanical device that projects a powerful electrical field. On taking a hit greater than 15%% of its maximum life, the excess damage will be reduced by %d%% and converted into energy, giving your mecharachnid %d%% increased global speed for 2 turns.", "スパイダーマシンに嵐電コイルを装着します。これは強力な電磁フィールドを発生させる機能を有しています。最大ＨＰの１５％を超えるダメージを受けると、超過分を %d%% 分軽減してエネルギーに変換します。これによりスパイダーマシンが２ターンの間 %d%% 加速します。", "tformat")
t("Mecharachnid Chassis", "換装パーツ", "talent name")
t("Assault", "アサルト", "_t")
t("Armament", "シュータータイプ", "_t")
t("#LIGHT_RED#You must not be in combat to change the chassis.", "#LIGHT_RED#戦闘中はパーツ変更できない。", "logPlayer")
t("#LIGHT_RED#Your mecharachnid must not be in combat to change its chassis.", "#LIGHT_RED#戦闘中はパーツ変更できない。", "logPlayer")
t("#LIGHT_RED#Your mecharachnid is already in chassis %s.", "#LIGHT_RED#既に%sに換装している。", "logPlayer")
t("Mecharachnid chassis changed to: #GOLD#%s", "基底パーツを変更した：#GOLD#%s", "logPlayer")
t("You require your mecharachnid to be adjacent, and must be out of combat.", "スパイダーマシンが隣接していて、戦闘外でないと実行できない。", "logPlayer")
t([[You craft a new chassis for your mecharachnid, allowing you to tailor it to different situations. Each chassis grants the mecharachnid a new talent category, the ability to attach a weapon to their tail, as well as granting them %d class talent points to spend in a new category based off their chassis.

		You can choose from the 2 chassis below by activating this talent outside of combat (default chassis: Assault)
		- Assault: An armored chassis focused on close combat and defenses, specialising in wielding a steamsaw.
		- Armament: A heavily armed chassis focused on ranged combat, specialising in wielding an additional steamgun.

		Tail weapons do not attack by default, and are instead used for special talents.]], [[スパイダーマシン用の基底パーツを新たに作成し、異なる状況に対応できるようにします。それぞれの基底パーツによって機体が新たなタレントツリーを習得します。また、尻尾に武器を装備できるようになり、クラスポイントを %d 点獲得して基底パーツ用タレントに振れるようになります。
		　このタレントを戦闘外で使用すると、基底パーツ２種の中から選択できます（デフォルトの設定はアサルトパーツです）

		　アサルト:近接戦闘に重点を置いた武装パーツです。スチームソーの扱いに特化しています。
		　シューター:射撃戦に重点を置いた重武装パーツです。スチームガンをさらに装備して戦います。

		　尻尾に装備した武器は通常攻撃には用いません。その代わり特殊なタレントで使用します。]], "tformat")
t("Mecharachnid Piloting", "パイロットオン", "talent name")
t("You require your mecharachnid to be adjacent.", "スパイダーマシンと隣接していない。", "logPlayer")
t("Leap into your mecharachnid, assuming direct control of it for %d turns. While piloting it, all damage dealt is increased by %d%%, resistances are increased by %d%%, and all of its talents cooldown twice as fast.", "スパイダーマシンに飛び乗って %d ターンの間直接操作します。搭乗中は与ダメージが %d%% 上昇し、全ての耐性が %d%% 増加します。さらにタレントのクールダウンが２倍の速さで復帰します。", "tformat")
t("steamtech", "工士", "talent category")
t("armament", "射撃蜘蛛", "talent type")
t("Ranged combat mecharachnid abilities.", "スパイダーマシンの遠距離技能です。", "_t")
t("assault", "強襲蜘蛛", "talent type")
t("Close combat mecharachnid abilities.", "スパイダーマシンの近接技能です。", "_t")
t("Overrun", "スパイダー突貫", "talent name")
t("You require a tail-mounted steamsaw for this talent.", "尻尾にスチームソーを装備していないと使えない。", "logPlayer")
t("Your mecharachnid cannot do that currently.", "今はスパイダーマシンが機能しない。", "logPlayer")
t("#Source# provokes #Target# to attack it.", "#Source#は#Target#の注意を惹いた。", "logCombat")
t([[You rush to the target and strike with your tailsaw, dealing %d%% damage and taunting enemies within radius %d.
		You now also use your Dexterity in place of Strength when equipping Steamsaws as well as when calculating weapon damage, and have your Steamsaw damage increased by %d%% and Physical Power by %d.]], [[対象へ突進し、尻尾のスチームソーで攻撃します。これは倍率 %d%% の攻撃で、半径 %d マス以内の敵の注意を自分に引き付けます。
		　スチームソーの装備条件とダメージ計算の際に腕力の代わりに機敏を参照するようになります。また、スチームソーを用いる際の与ダメージが %d%% 増加し、物理パワーが %d 上昇します。]], "tformat")
t("Defensive Protocol", "防御プロトコル", "talent name")
t("Enhancements to your mecharachnid combat skill increases your melee and ranged evasion by %d%%, and causes you to automatically strike adjacent enemies with your tailsaw for %d%% damage each turn.", "スパイダーマシンの戦闘技術を強化し、近接・射撃攻撃に対する身躱し効果が %d%% 上昇します。また、毎ターン隣接する敵全員に尻尾で装備したスチームソーによる攻撃を行います。これは倍率 %d%% の攻撃です。", "tformat")
t("Pincer Strike", "サンドウィッチ", "talent name")
t("#Target# resists the pincer strike from #Source#!", "#Target#は#Source#の拘束に抵抗した。", "logCombat")
t("You strike the target with your tailsaw for %d%% damage. If this hits, you attempt to clamp them with your pincers for %d turns. This pins, reduces their attack, spell and mind speed by %d%%, and lets you make a free, unavoidable strike with your tailsaw against them each turn for %d%% damage. This ends if you move more than 1 tile from the target.", "尻尾のスチームソーで対象を撃ちすえ、倍率 %d%% の攻撃をします。命中すると相手を挟んで %d ターンの間拘束します。拘束された相手は攻撃速度・詠唱速度・精神速度が %d%% 低下します。また、相手に毎ターン尻尾のスチームソーで回避不能な倍率 %d%% 攻撃を自動で行います。対象から２マス以上離れると拘束は解けます。", "tformat")
t("Automated Repair System", "自己修復システム", "talent name")
t([[On falling below 0 life, you engage an automated repair mode. While in this mode you cannot act, but can survive below -%d life, heal for %0.1f life each turn and have all resistances increased by %d%%. This will last until you are destroyed or until you are fully healed.
		This effect has a cooldown.]], [[ＨＰが０未満になると自動修復モードに移行します。このモードでは行動できませんが、ＨＰの下限が -%d になり毎ターン %0.1f 回復します。また、効果中は全ての耐性が %d%% 増加します。破壊されるか完全回復すると通常モードに復帰します。
		　この効果にはクールダウンが存在します。]], "tformat")
t("Gauss Cannon", "ガウスカノン", "talent name")
t("You require a tail-mounted steamgun for this talent.", "尻尾にスチームガンを装備していないと使えない。", "logPlayer")
t([[Fire a charged shot at the farthest target with your tail-mounted steamgun that pierces through your enemies, ignoring armor and dealing %d%% weapon damage as lightning.
		This takes no time to use.]], [[尻尾に装備したスチームガンで帯電した弾丸を一番遠くの敵に撃ちます。これは射線上を貫通し、アーマーを無視します。倍率 %d%% の電撃属性です。
		　このタレントは使用にターンを消費しません。]], "tformat")
t("Magnetic Accelerator", "マグネットアクセル", "talent name")
t("You must have an empty space to leap to.", "　ジャンプ先のマスが空いていない。", "logPlayer")
t([[Improved power output increases the speed of your projectiles by %d%%, critical damage by %d%%, and allows you to automatically reload each turn.
		In addition, you can instantly activate this talent to gain a sudden burst of speed, moving to a tile in range %d.]], [[出力を増加し、スパイダーマシンが撃つ飛来物の速度を %d%% クリティカル倍率を %d%% 上昇させます。
		　また、毎ターン自動的にリロードするようになります。さらにこのタレントを起動することで瞬時に加速し、半径 %d マス以内の指定した地点に移動できます。この移動はターン消費しません。]], "tformat")
t("Haywire Missiles", "テイルミサイル", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t([[Fires a barrage of charged missiles from your tail-mounted steamgun at a radius %d area, dealing %d%% steamgun damage as lightning as well as dazing those within for 2 turns.
		The daze chance increases with your Accuracy.]], [[尻尾に装備したスチームガンから半径 %d マスに帯電ミサイルを乱射します。これは倍率 %d%% の電撃属性で、範囲内の相手を２ターンの間朦朧状態にします。
		　朦朧状態の付与確率は命中に依存します。]], "tformat")
t("Advanced Targeting System", "高機能ターゲッティング", "talent name")
t([[Enhancements to your targeting systems give all ranged attacks a %d%% chance to trigger an immediate shot from your tail-mounted steamgun for 100%% damage as lightning.
		In addition, your physical and lightning resistance penetration is increased by %d%%.]], [[ターゲッティングシステムを向上させ、全ての射撃攻撃時に %d%% の確率で尻尾に装備したスチームガンで追加射撃するようになります。これは倍率１００％の射撃で電撃属性です。
		　また、物理・電撃属性の耐性貫通が %d%% 増加します。]], "tformat")
t("Tail Attachment", "尻尾装備変更", "talent name")
t("%s mounts %s to its tail.", "%sは%sを尻尾に装備した。", "logSeen")
t("Attach which item?", "どのアイテムですか？", "_t")
t("Attach the chosen weapon to your tail.", "この武器は尻尾に装備できない。", "_t")
-- old translated text
t("armament", "射撃蜘蛛", "_t")
t("assault", "強襲蜘蛛", "_t")

------------------------------------------------
section "tome-orcs/data/talents/steam/mechstar.lua"

t("Metalstar", "メタルスター", "talent name")
t([[Quickly aggregate particles of metal around your mindstar and focus psionic energies into it.
		The metal explodes like shrapnel, knocking back (%d away) and dazing (%d duration) all foes in radius %d.]], [[金属粒子を一瞬でマインドスターの周囲に引き寄せます。その後、精神力を集中し出来上がった金属塊に流し込みます。
		　金属塊は散弾状に爆発し、範囲内の敵全員を %d マスノックバックします。これを受けた相手は %d ターン朦朧状態になります。範囲は半径 %d マスです。]], "tformat")
t("Bloodstar", "ブラッドスター", "talent name")
t([[When you fire your metalstar, your also establish a psionic bloodlink with the shrapnel still inside for %d turns.
		Each turn the victims are drained for %0.2f physical damage, half of which heals you (each additional victim healing is reduced by half).
		If the victim move more than twice away from the radius of Metalstar (currently %d) the effect stops.
		This damage does not break daze and increases with your Steampower.]], [[「メタルスター」を使用した際に、超能力を用いて敵の体内に残留した金属片と血の束縛を形成します。持続時間は %d ターンです。
		　ターンごとに対象は %0.2f の物理属性ダメージを受け、その半分に等しい値だけ術者のＨＰが回復します。（この回復量は回を重ねる毎に半減します）対象が「メタルスター」の効果半径×２よりも外に出ると効果は終了します（現在 %d マス）
		　この効果によってダメージを受けても対象の朦朧状態は解除されません。ダメージは蒸気パワーに依存します。]], "tformat")
t("Steamstar", "スチームスター", "talent name")
t([[Your bloodstar effect also burns part of your victim's flesh, dealing %0.2f fire damage.
		The intensity of the fire generates steam which you psionically absorb through gestalt, providing %d steam each turn (each additional victim steam generation is reduced by 66%%).
		This damage does not break daze and increases with your Steampower.]], [[「ブラッドスター」によって対象の体の一部が燃え上がります。これは火炎属性の %0.2f ダメージです。
		　強烈な炎によって蒸気が発生し、タレント使用者は心機合一を介してそれを超能力で吸収します。これにより蒸気が %d 回復します（このタレントによる蒸気回復量は発生毎に６６％低下します）
		　この効果によってダメージを受けても対象の朦朧状態は解除されません。ダメージは蒸気パワーに依存します。]], "tformat")
t("Deathstar", "デススター", "talent name")
t("When you use a shoot class talent to hit a creature affected by bloodstar an other shoot talent will have its current cooldown reduced by %d turns.", "「ブラッドスター」を受けている相手に射撃系のタレントを命中させた場合、射撃系タレントのクールダウン一種が %d ターン短縮されます。このトリガーとなったタレントは影響を受けません。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/other.lua"

t("Medical Injector", "医療注射器", "talent name")
t("Medical Urgency Vest", "救急医療ベスト", "talent name")
t("#LIGHT_BLUE#Medical Urgency Vest selected to be used first by salves.", "#LIGHT_BLUE#軟膏使用時に緊急医療ベストを優先して使います。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "未使用ならこの注射器を軟膏使用時に優先して使用します。", "logPlayer")
t("The medical urgency vest allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "緊急医療ベストです。医療系の工士アイテムを効果量 %d%% クールダウン %d%% で使用できます。", "tformat")
t("Life Support", "ライフサポート", "talent name")
t("#LIGHT_BLUE#Life Support Suit selected to be used first by salves.", "#LIGHT_BLUE#軟膏使用時に生命維持スーツを優先して使います。", "saySimple")
t("The life support suit allows using therapeutics with %d%% efficiency and cooldown mod of %d%%.", "生命維持スーツです。医療系の工士アイテムを効果量 %d%% クールダウン %d%% で使用できます。", "tformat")
t("Create Tinker", "工士アイテム生成", "talent name")
t("Allows you to create tinkers.", "工士アイテムを作成できます。", "_t")
t("Weapon Automaton: One Handed", "片手武器用バトルオートマトン", "talent name")
t("You cannot use %s without a one handed melee weapon in your inventory!", "%sを使うには道具欄に片手武器が必要だ！", "logPlayer")
t("Select a weapon for your Automaton", "武器を選択してください。", "_t")
t("Weapon Automaton: %s", "自動化武器: %s", "tformat")
t("An Automaton wielding a chosen weapon.", "　選択武器を装備したロボットだ。", "_t")
t("#F53CBE#%s runs out of power.", "#F53CBE#%sはエネルギー切れを起こした。", "logSeen")
t("Summon", "召喚生物", "_t")
t([[Deploy a Weapon Automaton based on a selected one handed melee item.  The Automaton will wield the selected weapon and drop it when it times out or is destroyed.  Aside from the weapon selected, the Automaton will scale off Tinker talent levels, your own stats, and other things that will be described in this tooltip at some point.  
		]], "片手武器を選択し、自動戦闘ロボットを配置します。このロボットは選択した片手武器を装備しています。活動時間が終了するか破壊されるかすると武器は地面に落ちます。このロボットの能力は選択した武器の他工士アイテムを制作するタレントレベル、自身のステータス、その他一覧に表示される要素に依存します。", "tformat")
t("Hand Cannon", "ハンドキャノン", "talent name")
t("You have no ammo!", "弾丸がない！", "logPlayer")
t([[Fires your ammo at an enemy in range %d for %d%% weapon damage.  If this tinker is made of voratun you will fire an additional shot.
			This shot is a ranged melee attack but will use the ranged procs of your ammo as well.]], [[銃弾を敵一体に撃ちます。範囲は %d マスで倍率 %d%% の武器攻撃です。このタレントを発動する工士アイテムがヴォラタン製の場合、さらに追加射撃します。
			　この射撃は近接攻撃を離れた相手に対して行うものですが、銃弾の射撃命中時効果も乗ります。]], "tformat")
t("Fatal Attractor", "サイキックデコイ", "talent name")
t("Not enough space to summon!", "召喚する場所がない！", "logPlayer")
t("fatal attractor", "サイキックデコイ", "_t")
t("A psionic contraption that reflects damage and forces things to attack it.", "　ダメージを反射する超能力装置だ。自らを攻撃するように強制する。", "_t")
t([[Quickly create a psionic-enhanced metal contraption that lures all your foes to it and reflects %d%% of the damage it takes to its attackers.
		The contraption will have %d life and last 5 turns.
		Damage, life, resists, and armor scale with your Steampower.]], [[瞬時に超能力を付与した金属製装置を組み立てます。これは敵全員をおびき寄せ、受けたダメージの %d%% を攻撃者に反射します。
		　装置のＨＰは %d です。５ターン持続します。
		　装置のダメージ、ＨＰ、耐性およびアーマーは術者の蒸気パワーに依存します。]], "tformat")
t("Rocket Boots", "ロケットブーツ", "talent name")
t([[Activate the rocket boots, firing huge flames from your boots increasing your movement speed by %d%%.
		Each movement will leave a trail of flames doing %0.2f fire damage for 4 turns.
		Doing any other actions will break the effect.
		#{italic}#Burninate them all!#{normal}#]], [[ロケットブーツを起動し爆炎を噴射して移動速度を %d%% 上昇させます。
		　移動するごとに火炎の滞留を残します。これは火炎属性の %0.2f ダメージを４ターンかけて与えます。
		　移動以外の行動をすると効果は消えます。
		
		#{italic}#　燃えちまえ！#{normal}#]], "tformat")
t("Iron Grip", "アイアングリップ", "talent name")
t("%s resists the iron grip!", "%sはアイアングリップに抵抗した！", "logSeen")
t([[Activate the pistons to crush your target for %d turns and dealing %d%% unarmed melee damage.
		While the target is held it can not move and its armour and defense are reduced by %d.
		#{italic}#Crush their bones!#{normal}#]], [[ピストンを起動して対象を握り潰します。持続時間は %d ターンです。また、徒手格闘の %d%% ダメージを与えます。
		　捕まれている相手は移動不能となり、アーマーと回避が %d 低下します。
		
		#{italic}#　へし折ってやる！#{normal}#]], "tformat")
t("Spring Grapple", "スプリングキャッチャー", "talent name")
t("%s resists the pin!", "%sは移動不能に抵抗した！", "logSeen")
t("Grab the target and pull them towards you, striking for %d%% unarmed melee damage, and if you hit, pinning them for %d turns.", "対象を掴み、引き寄せます。徒手格闘の倍率 %d%% ダメージを与え、命中したならば %d ターンの間移動不能にします。", "tformat")
t("Toxic Cannister Launcher", "ポイズンスモッグランチャー", "talent name")
t("toxic cannister", "ポイズンスモッグランチャー", "_t")
t("A smelly cannister.", "　悪臭漂う弾筒だ。", "_t")
t([[Launch a cannister filled with toxic gas at a location.
		Every 2 turns the cannister emits a poison cloud of radius 3 around it each turn.
		The poison does %0.2f nature damage over 5 turns.
		The cannister has %d life and lasts 8 turns. When it ends or is destroyed a last cloud is created.
		Damage, life, resists, and armor scale with your Steampower.
		Damage and penetration are inherited from the creator.]], [[有毒ガスで充満した弾筒を設置します。
		　これは２ターン毎に自身を中心とした半径３マスの範囲へ毒ガスを放ちます。
		　毒ガスは自然属性の %0.2f ダメージを５ターンかけて与えます。
		　この装置のＨＰは %d です。持続時間は８ターンとなります。持続時間が切れるか破壊された際にも毒ガスを放ちます。
		　ダメージ、ＨＰ、耐性アーマーは術者の蒸気パワーに依存します。
		　属性ダメージ増加量と耐性貫通は術者のものを継承します。]], "tformat")
t("Steam Powered Armour", "スチームパワードアーマー", "talent name")
t([[Activate the armour's active defense system.
		A flow of electricity covers your armour to attenuate the force of energy attacks while small steam engines move key pieces of the armour to attenuate physical attacks.
		All damage except mind damage is reduced by a flat %d.
		In addition the electric power of the armour sometimes leaks, each turn there is a 50%% chance to produce a electrical arc toward a foe, dealing %0.2f to %0.2f lightning damage to all foes in radius 1.
		The effects increase with your Steampower.]], [[鎧のアクティブ防御システムを起動します。
		　鎧に電流が流れてエネルギー系の攻撃を緩和します。同時に小型の蒸気機関によって鎧の主要部を動かし、物理的な攻撃を緩和します。
		　これによって精神属性以外のダメージを固定値で %d 軽減します。さらに鎧を流れる電流が外部に漏れることがあります。毎ターン５０％の確率で敵に向かって電弧が発生し、電撃属性の %0.2f から %0.2f ダメージを周囲１マスの全員に与えます。
		　各種効果量は蒸気パワーに依存します。]], "tformat")
t("Viral Needlegun", "ウイルスニードル", "talent name")
t([[You fire a cone of blighted needles, hitting everything in a frontal cone of radius %d for %0.2f physical damage.
		Each creature hit has a %d%% chance of being infected by a random disease, doing %0.2f blight damage and reducing either Constitution, Strength or Dexterity by %d for 20 turns.
		The damage and disease effects increase with your Steampower.]], [[腐敗の力を込めた針を前方へ乱射します。扇状の範囲 %d マスの敵全員に物理属性の %0.2f ダメージを与えます。
		　これを受けた相手は %d%% の確率でランダムな病気に感染します。病気に感染した相手は %0.2f の腐敗属性ダメージを２０ターンかけて受けます。その間、耐久、腕力、機敏のいずれかが %d 低下します。ダメージと
		　病気の効果量は蒸気パワーに依存します。]], "tformat")
t("Sand Shredder", "砂壁掘り", "talent name")
t("%s shreds through sandwalls!", "%sは砂壁を粉々にした！", "logSeen")
t("You shred pieces of sandwalls. Brrrmmm!.", "砂壁を粉々にします。ブーン！", "_t")
t("Flamethrower", "火炎放射器", "talent name")
t([[Throw a cone of flame with radius %d
		The damage will increase with your Steampower.]], [[半径 %d マスに火炎流を放ちます。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Mass Repair", "マシンリペア", "talent name")
t([[Throw a cone of healing with radius %d, healing other mechanical creatures (steam spiders) for %d.
		The healing will increase with your Steampower.]], [[癒しの渦を半径 %d に放ちます。機械系のキャラクター（蒸気機関スパイダー）のＨＰが %d 回復します。
		　回復量は蒸気パワーに依存します。]], "tformat")
t("Arcane Disruption Wave", "魔法阻害波", "talent name")
t([[Let out a technopsionic wave that silences for %d turns all those affected in a radius of %d, including the user.
		The silence chance will increase with your Steampower.]], [[人工精神波を放って周囲の相手を %d ターン沈黙状態にします。範囲は %d マスです。使用者も沈黙します。
		　沈黙の付与確率は蒸気パワーに依存します。]], "tformat")
t("Mind Crush", "ブレインバスター", "talent name")
t("%s resists the mental assault!", "%sは精神攻撃に抵抗した！", "logSeen")
t([[Shatters the mind of your victim, giving you full control over its actions for 6 turns.
		When the effect ends, you pull out your mind and the victim's body collapses, dead.
		This effect does not work on rares, bosses, or undead.
		.]], [[対象の精神を破壊し６ターンの間操ります。
		　効果が終了すると術者の精神は対象から抜け出し、後には物言わぬ死体が残ります。
		　このタレントはレア、ボス、アンデッド系の相手には効きません。
]], "tformat")
t("Shocking Touch", "電撃タッチ", "talent name")
t([[Touch a creature to release a nasty electrical charge into them, doing %0.2f lightning damage.
		If this tinker is above tier 1, the electricity can arc to another target up to 2 tiles away.
		The number of enemies hit is at most the tinker tier.
		The damage increases with your Steampower.]], [[対象に触れ、電流を強かに解き放ちます。電撃属性の %0.2f ダメージです。
		　このタレントを発動する工士アイテムがランク２以上の場合、電撃は２マス以内の別の敵へ更に跳んでいきます。
		　電撃が命中する敵の数は工士アイテムのランクの値が上限となります。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Flash Powder", "フラッシュパウダー", "talent name")
t("%s resists the blinding light!", "%s はまぶしい光に抵抗した！", "logSeen")
t([[Throw a handful of dust that rapidly oxidises, releasing a blinding light.
		Creatures in a cone of radius %d are blinded for %d turns.
		The blindness effect is applied with your Steampower.]], [[急速酸化する粉末を放って目の眩む閃光を発生させます。
		　扇状の半径 %d マス以内の相手は %d ターンの間盲目状態になります。
		　盲目効果は蒸気パワーを用いた判定で付加します。]], "tformat")
t("Itching Powder", "発蕁パウダー", "talent name")
t("%s resists the itching powder!", "%sは痒みに耐えた！", "logSeen")
t([[Throw a handful of dust that is very itchy to touch.
		Creatures in a cone of radius %d are itchy for %d turns, causing them to fail talents %d%% of the time.
		The itchiness effect is applied with your Steampower.]], [[耐え難い痒みを引き起こすパウダーを放ります。
		　範囲は扇状の半径 %d マスです。範囲内の相手は %d ターンの間 %d%% の確率でタレントの使用に失敗します。
		　この効果は蒸気パワーを用いた判定で付加します。]], "tformat")
t("Thunder Grenade", "スタングレネード", "talent name")
t("%s resists the explosion!", "%sは爆発に抵抗！", "logSeen")
t([[Throw a grenade at your foes, dealing %0.2f physical damage in radius %d.
		Creatures hit will also be stunned for %d turns.
		The stun effect is applied with your Steampower.]], [[グレネードを投げつけます。物理属性の %0.2f ダメージを半径 %d マスに与えます。
		　これを受けた相手は %d ターンの間スタンします。
		　スタン効果は蒸気パワーを用いた判定で付加します。]], "tformat")
t("Project Saw", "ソーシューター", "talent name")
t([[You activate hidden springs to project a saw towards your foes.
		Any creature caught in the beam takes %0.2f physical damage and bleeds for half more in 5 turns.
		The damage increases with your Steampower.]], [[隠しバネを起動して敵へスチームソーを撃ちます。
		　経路上の相手は %0.2f の物理属性ダメージを受け、さらにその半分を出血効果として５ターンかけて受けます。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Voltaic Bolt", "電撃ボルト", "talent name")
t([[Fires a bolt of lightning, doing %0.2f lightning damage.
		The damage will increase with your Steampower.]], [[電撃を放ちます。これは電撃属性の %0.2f ダメージです。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Voltaic Sentry", "ボルトセントリー", "talent name")
t("volatic sentry", "ボルトセントリー", "_t")
t("A strange device. Your hair stands on end when you approach.", "　不思議な装置だ。近づくと髪が逆立つ。", "_t")
t([[Place an electrically charged sentry device at a location.
		Every turn it will fire a bolt of electricity at a nearby enemy.
		The bolts do %0.2f lightning damage.
		The sentry has %d life and lasts 10 turns.
		Damage, life, resists, and armor scale with your Steampower.
		Damage and penetration are inherited from the creator.]], [[充電済みの防衛装置を設置します。
		　ターン毎に近くの敵へ電撃を放つ装置です。
		　この電撃は %0.2f ダメージとなります。
		　装置のＨＰは %d で１０ターン持続します。
		　ダメージ、ＨＰ、耐性、アーマーは蒸気パワーに依存します。
		　属性ダメージ増加量と耐性貫通は術者のものを継承します。]], "tformat")
t("Explosive Shell", "爆裂弾", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and explodes within radius %d, which does %0.2f physical damage.
		This talent does not use ammo as it is the ammo.]], [[爆裂弾を撃ちます。
		　目標に命中すると通常射撃のダメージを与え、半径 %d に爆発を起こして物理属性の %0.2f ダメージを与えます。
		　このタレントは弾丸を消費しませんが、装備中の弾丸を用いた射撃です。]], "tformat")
t("Flare Shell", "フレア弾", "talent name")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and explodes within radius %d, which lights up the area and blinds for %d turns.
		This talent does not use ammo as it is the ammo.]], [[特殊爆発弾を撃ちます。
		　目標地点に着弾すると通常射撃のダメージを与え、半径 %d マスに爆発を起こします。これにより範囲内を照らして %d ターン盲目状態にします。
		　このタレントは弾丸を消費しませんが、装備中の弾丸を用いた射撃です。]], "tformat")
t("Incendiary Shell", "焼夷弾", "talent name")
t("clusterbomb", "Incendiary Shell", "_t")
t([[You fire a special explosive shot with your steamgun(s) at a spot within range.
		When each shot reaches its target, it does normal steamgun damage and releases %d explosive charges in a radius of 2.
		These charges will shortly explode for %0.2f fire damage in a radius of 1.
		This talent does not use ammo as it is the ammo.]], [[特殊爆発弾を撃ちます。
		　目標地点に着弾すると通常射撃のダメージを与え、半径２マスに爆発弾 %d 発をばら撒きます。
		　この爆発弾はすぐさま爆発し、半径１マスに %0.2f の火炎属性ダメージを与えます。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Solid Shell", "徹甲弾", "talent name")
t("%s is knocked back!", "%s はノックバックした！", "logSeen")
t("%s resists the knockback!", "%s はノックバックに抵抗した！", "logSeen")
t([[You fire a special solid shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The weight of the shot will knock the target back %d tiles.
		This talent does not use ammo as it is the ammo.]], [[徹甲弾を放ち通常射撃の %d%% ダメージを物理属性として与えます。
		　銃弾の重みで敵は %d マスノックバックします。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Impaler Shell", "杭打ち弾", "talent name")
t([[You fire a special stake shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The weight of the shot will knock the target back 2 tiles and they will be pinned for %d turns.
		This talent does not use ammo as it is the ammo.]], [[杭打ち弾を撃ちます。対象に倍率 %d%% の射撃を物理属性として与えます。
		　弾丸の重みで対象は２マスノックバックし %d ターンの間移動不能となります。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Saw Shell", "鋸刃弾", "talent name")
t([[You fire a special steamsaw shot with your steamgun(s) at a target for %d%% physical weapon damage.
		The steamsaw will cut into the target, doing %d%% physical weapon damage over 5 turns.
		This talent does not use ammo as it is the ammo.]], [[スチームソーを撃ちます。倍率 %d%% の射撃です。
		　このスチームソーは敵を切り裂き、倍率 %d%% 射撃に相当する物理属性ダメージを５ターンかけて与えます。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Hook Shell", "フック弾", "talent name")
t("%s resists the pull!", "%sは踏ん張った！", "logSeen")
t([[You fire a special hook shot with your steamgun(s) at a target creature or location.
		If you target a creature, they are pulled up to %d tiles towards you.
		If you target an empty tile, you are pulled up to %d tiles towards it.
		This talent does not use ammo as it is the ammo.]], [[選択した対象、もしくは位置に向かってフックを射出します。
		　目標がキャラクターの場合、自分に向かって %d マス引き寄せます。
		　目標に誰もいない場合、その場所へ %d マス移動します。このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Magnetic Shell", "磁石弾", "talent name")
t([[You fire a special magnetic shot with your steamgun(s) at a target for normal weapon damage.
		The shot will magnetise the target for %d turns. This lowers their defense and increases fatigue by %d.
		This talent does not use ammo as it is the ammo.
		Effect strength scales with Steampower.]], [[磁石弾を撃ち、通常射撃のダメージを与えます。
		　対象は %d ターンの間磁場を帯び、回避が低下して疲労度が上昇します。効果量はそれぞれ %d です。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。]], "tformat")
t("Voltaic Shell", "電流弾", "talent name")
t([[You fire a special voltaic shot with your steamgun(s) at a target for 100%% weapon damage as lightning.
		The shot will release powerful electrical currents at up to %d nearby enemies. 
		Each bolt does %0.2f lightning damage.
		This talent does not use ammo as it is the ammo.
		Bolt damage scales with Steampower.]], [[電流弾を撃ちます。通常射撃ダメージを電撃属性として与えます。
		　命中すると強烈な電流を最大 %d 体までの近場の敵に放ちます。
		　これは電撃属性の %0.2f ダメージです。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。
		　電流のダメージは蒸気パワーに依存します。]], "tformat")
t("Antimagic Shell", "反魔弾", "talent name")
t([[You fire a special antimagic shot with your steamgun(s) at a target for 100%% normal weapon damage.
		The shot will release antimagic sap on the target, doing %0.2f arcane resource burn damage.
		This talent does not use ammo as it is the ammo.
		Sap damage scales with Steampower.]], [[反魔弾を撃ち、通常射撃のダメージを与えます。
		　反魔の力が対象の魔力を吸収し、魔法系リソースを %0.2f 減少させます。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。
		　減少量は蒸気パワーに依存します。]], "tformat")
t("Botanical Shell", "植物弾", "talent name")
t([[You fire a special botanical shot with your steamgun(s) at a target for 100%% weapon damage as nature.
		The shot will release spores which grow into Nourishing Moss in a radius of %d for %d turns.
		Each turn the moss deals %0.2f nature damage to each foe within its radius.
		This moss has vampiric properties and heals the user for %d%% of the damage done.
		This talent does not use ammo as it is the ammo.
		Moss damage scales with Steampower.]], [[植物弾を撃ち、通常射撃のダメージを自然属性として与えます。
		　命中後、弾丸は胞子を振り撒き吸血苔が半径 %d マスに生えていきます。持続時間は %d ターンです。
		　ターン毎にこの苔は範囲内の敵全員に %0.2f の自然属性ダメージを与えます。
		　吸血能力を持つため、このダメージの %d%% 分、術者のＨＰが回復します。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。
		　吸血苔によるダメージは蒸気パワーに依存します。]], "tformat")
t("Corrosive Shell", "腐食弾", "talent name")
t([[You fire a special corrosive shot with your steamgun(s) at a target for %d%% weapon damage as acid.
		The acid released by the shot will also corrode the target, reducing its accuracy, defense and armour by %d.
		This talent does not use ammo as it is the ammo.
		Corrosion strength scales with Steampower.]], [[腐食弾を撃ちます。通常射撃の %d%% ダメージを酸属性として与えます。
		　弾丸に込めた酸は敵を傷つけるだけではなく、命中、回避、アーマーを %d 低下させます。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。低下量は蒸気パワーに依存します。]], "tformat")
t("Toxic Shell", "有害物質弾", "talent name")
t("%s resists the toxin!", "%sは有害物質に抵抗した！", "logSeen")
t([[You fire a special toxic shot with your steamgun(s) at a target for 100%% weapon damage as blight.
		The shot will release heavy metals into the target, inflicting %0.2f blight damage per turn and reducing their global speed by %d%% for %d turns.
		This talent does not use ammo as it is the ammo.
		Toxin strength scales with Steampower.]], [[有害物質を含んだ弾丸を撃ち、通常射撃と同じダメージを腐敗属性として与えます。
		　この弾丸は命中した相手の体内に重金属を撒き散らします。これにより対象は毎ターン %0.2f の腐敗属性ダメージを受け %d%% 減速します。持続時間は %d ターンです。
		　このタレントは弾丸を消費しませんが装備中の弾丸を用いた射撃です。
		　重金属による効果は蒸気パワーに依存します。]], "tformat")
t("Moss Tread", "フォレストウォーカー", "talent name")
t([[For %d turns, you lay down Grasping Moss where you walk or stand.
		The moss is placed automatically every step and lasts %d turns.
		Each turn the moss deals %0.2f nature damage to each foe standing on it.
		This moss is very thick and sticky causing all foes passing through it have their movement speed reduced by %d%% and have a %d%% chance to be pinned to the ground for 4 turns.
		The damage scales with your Steampower.]], [[粘着苔が足跡に生えてきます。持続時間は %d ターンです。
		　移動する毎に自動的に苔が発生します。苔は %d ターン持続し、これに触れた敵に %0.2f の自然属性ダメージを与えます。
		　粘着苔は極めて分厚く、べたついているため、この上を通る敵は皆移動速度が %d%% 低下します。さらに %d%% の確率で４ターンの間移動不能となります。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Arcane Dynamo", "魔導ダイナモ", "talent name")
t([[Allows the use of Technomancy spells.
		Grants a magical steam reserve that regenerates %d steam per 10 mana spent.
		Grants Spellpower based on current steam level (currently %d; %d%% steam filled).
		Outside of combat, you relax and let your steam reserve slowly wither away.
		#{italic}#Metal Arcane Power!#{normal}#]], [[魔導工学の魔法が使えるようになります。
		　魔法蒸気を溜めておけるようになり、マナを１０消費すると蒸気が %d 回復します。
		　また、現在の蒸気量に応じて魔法パワーが上昇します（現在 %d 蒸気量 %d%% ）
		　戦っていない時は集中を切らしており、溜めた蒸気は霧散してしまいます。
		
		　#{italic}#機械魔法だ！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/physics.lua"

t("Smith", "鍛冶習得", "talent name")
t([[Allows you to create smithed tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[鍛冶系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません
		%s]], "tformat")
t("Mechanical", "機械いじり", "talent name")
t([[Allows you to create mechanical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[機工系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。
		　タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません
		%s]], "tformat")
t("Electricity", "電磁気学", "talent name")
t([[Allows you to create electrical tinkers of level %d.
		You will learn a new schematic at level 1.
		Each other talent level, you have a 20%% chance to learn one more random schematic, if you have not gained it by level 5 you are guaranteed it (unless all are known).
		%s]], [[電磁系の工士アイテムが制作可能になります。アイテムレベル上限は %d です。
		　タレントレベル１の時点で新たに工士アイテムの製作法を一種習得します。
		　タレントレベルが上昇する毎に２０％の確率で製作法を一種習得できます。タレントレベル５の時点でこれが一度も発生していなかった場合、１００％の確率で一種習得します（全て習得してしまっている場合は何も起きません
		%s]], "tformat")
t("Compact Steam Tank", "小型スチームタンク", "talent name")
t("Increases the capacity of your steam tank by %d.", "蒸気の上限が %d 上昇します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/psytech-gunnery.lua"

t("Psyshot", "サイコガン", "talent name")
t([[Increases weapon damage by %d%% and Physical Power by 30 when using steamguns.
		When your bullets hit a target you instinctively reach out to the impact and use the kinetic force to project a mindstar attack doing %d%% damage (guaranteed hit), if you wield one in the offhand.
		This projection requires a pure mindstar; it will not work if extended into a psiblade.

		Also activable for a shot that deals %d%% weapon damage as mind damage.]], [[スチームガンを用いる際の物理パワーが３０増加し、与ダメージが %d%% 上昇します。
		　さらに銃弾が命中した際、反射的に着弾点を追って念動力を使用し、マインドスターの攻撃を放ちます。これは倍率 %d%% の攻撃で必中です。逆手にマインドスターを装備している場合に限り発動します。
		　純粋なマインドスターである必要があり、サイブレードになっていると効果を発揮しません。
		　アクティブ系タレントとして使用すると倍率 %d%% の射撃を精神属性として与えます。]], "tformat")
t("Boiling Shot", "ボイリングシュート", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t([[Using psionic energies you overheat your shot, making it deal %d%% damage.
		If the shot hits a wet foe it will vaporize, removing the wet effect and dealing %0.2f fire damage in a radius 4.]], [[超能力を用いて弾丸を過熱します。倍率 %d%% の射撃です。
		　水浸しの相手に命中すると、水分が蒸発し、水浸し状態を解除して半径４マスに火炎属性の %0.2f ダメージを与えます。
]], "tformat")
t("Blunt Shot", "スタンシュート", "talent name")
t("Fire a relatively low-powered shot at a foe doing %d%% weapon damage, if it hits a cone-shaped shockwave of radius 4 emanates from the impact, stunning it and all creatures caught inside for %d turns.", "弱めの射撃を撃ちます。倍率 %d%% の射撃です。命中すると着弾点を基準とした扇状の範囲に半径４マスの衝撃波が発生し、範囲内の全員を %d ターンスタンさせます。", "tformat")
t("Vacuum Shot", "バキュームシュート", "talent name")
t([[Attach a psionic steam device to a shot doing %d%% weapon damage.
		When it hits a foe the device activates, violently sucking all the air nearby, pulling in all creatures in radius %d.]], [[蒸気で動く超能力発生装置を弾丸に取り付けて撃ちます。これは倍率 %d%% のダメージです。
		　命中すると装置が起動し、周囲の空気を悉く吸引して、半径 %d マス以内の全員を引き寄せます。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/sawmaiming.lua"

t("To The Arms", "腕刻み", "talent name")
t("You require a steamsaw for this talent.", "スチームソーを装備していない。", "logPlayer")
t([[Hits the target on the arms with one rotating saw doing %d%% damage and trying to maim it for %d turns.
		Maimed foes deal %d%% less damage.
		The chance improves with your Physical power.
		#{italic}#Cutting your foes has never been so simple!#{normal}#]], [[回転するスチームソーで対象の両腕を攻撃し、倍率 %d%% のダメージを与えます。さらに %d ターンの間大怪我を負わせます。
		　怪我を負った対象は与ダメージが %d%% 低下します。
		　怪我を負わせる確率は物理パワーに依存します。
		
		#{italic}#　こんなに簡単に切り刻めるなんて！#{normal}#]], "tformat")
t("Bloodstream", "スプラッシュ", "talent name")
t([[You "gently" slam your saws into the wounds of a creature, dealing %d%% weapon damage and deepening the wounds.
		All bleeding wounds durations are increased by %d turns and the damage by %d%% (this may be done only once per bleeding effect).
		When this happens a gush of blood is projected in a narrow cone of radius 4, dealing %0.2f physical damage to all creatures.
		The power and damage improves with your Steampower.
		#{italic}#The marvels of technology, now at the service of true butchery!#{normal}#]], [[スチームソーを「やんわり」と敵の傷口へ叩き付けます。倍率 %d%% のダメージを与え、傷口を広げます。
		　全ての怪我に対して持続時間を %d ターン延長し、さらにダメージを %d%% 増加させます（出血一種に対して一回だけ発生します）
		　この効果が発生すると、半径４マスの狭い扇状に血飛沫が飛び、範囲内の全員に %0.2f の物理属性ダメージを与えます。
		　ダメージ倍率とダメージ増加量は蒸気パワーに依存します。
		
		#{italic}#　科学技術の驚異を意のままに！　大殺戮を繰り広げろ！#{normal}#]], "tformat")
t("Spinal Break", "背骨断ち", "talent name")
t([[You try to sever the spine of your foe, reducing its global speed by %d%% for 4 turns and dealing %d%% weapon damage.
		The power of the blow also removes up to %d physical effects.
		If your talent level is at least 3 %d physical or magical sustains are also removed.
		#{italic}#Break them, grind them, mow them down!#{normal}#]], [[敵の背骨を両断せんと斬りつけます。対象の速度が４ターンの間 %d%% 低下します。この攻撃は倍率 %d%% の武器攻撃です。
		　強烈な攻撃で相手の物理系ステータス効果を最大 %d 種除去する効果もあります。
		　タレントレベルが３以上ならば、物理または魔法系のオンオフ系タレントを最大で %d 解除します。
		
		#{italic}#　粉微塵にしてやるぜ！#{normal}#]], "tformat")
t("Goresplosion", "機械仕掛けの惨劇", "talent name")
t([[When you kill a foe you place small explosives with shrapnels inside its body, making it explode in radius %d.
		Any foes hit will bleed for %0.2f damage per turn for 6 turns. The shrapnels also damage the vocal cords (or related organ), silencing them for %d turns.
		#{italic}#Use the finest of wartech now: shrapnels. For blood and mayhem!#{normal}#]], [[敵を撃破した際に榴散弾を体に埋め込み、半径 %d マスの範囲に爆発させます。
		　範囲内の敵は出血し、毎ターン %0.2f のダメージを受けます。持続時間は６ターンです。
		　榴弾によって声帯（もしくはそれに類する器官）も損傷するため、これを受けた相手は %d ターン沈黙します。
		
		#{italic}#　最新兵器、榴弾だ。こいつで皆殺しにしちまいな！#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/steam.lua"

t("Steam Pool", "スチームプール", "talent name")
t("Allows you to have a steam pool. Steam is used to use most steamtech equipments and powers.", "　蒸気のリソースを得ます。蒸気は主に蒸気機械系の装備や技能に消費します。", "_t")
t("inscriptions", "封入品", "talent category")
t("implants", "内蔵機器", "talent type")
t("Steamtech directly embedded on the skin.", "　皮膚下に直接埋め込んだ蒸気機械です。", "_t")
t("steamtech", "工士", "talent category")
t("other", "その他", "talent type")
t("Tinkers with stuff.", "　工士が扱う機械類です。", "_t")
t("physics", "蒸気力学", "talent type")
t("Learn the mechanical side of steamtech.", "　蒸気機械の力学分野です。", "_t")
t("chemistry", "蒸気化学", "talent type")
t("Learn the chemistry side of steamtech.", "　蒸気機械の化学分野です。", "_t")
t("blacksmith", "鍛冶師", "talent type")
t("All this metalworking has improved you.", "金属類を扱ううちに自身も強靭になりました。", "_t")
t("engineering", "蒸気工学", "talent type")
t("You don't just know how tinkering works, you know all the interesting details too!", "　蒸気機械の原理だけではなく、その玄妙な構造を余すところなく理解しています！", "_t")
t("butchery", "屠殺", "talent type")
t("Strap saws to your arms and rush into battle!", "　スチームソーを両手に装備し、戦いに繰り出そう！", "_t")
t("sawmaiming", "断壊", "talent type")
t("Use steam powered saws to their maximum efficiency! Maim! Cut! Shred!", "　スチームソーの力を最大限に引き出そう！　壊せ！　ぶった切れ！　ミンチにしろ！", "_t")
t("battlefield management", "貫走", "talent type")
t("Use steam powered saws to maneuver around the battlefield, gaining strategic advantage.", "　スチームソーを用いて戦場を駆け巡り、有利に立ち回ります。", "_t")
t("battle machinery", "戦闘機器", "talent type")
t("Use steam powered engines to tilt the battle in your favour.", "　蒸気エンジンを用いて戦局を操ります。", "_t")
t("automated butchery", "自動屠殺", "talent type")
t("Improve your saws and tinkers with automated processes to help shred your foes.", "　スチームソーや蒸気機械に自動化システムを組み込んで強化し、敵を切り刻みます。", "_t")
t("furnace", "溶鉱", "talent type")
t("Harness the power of fire.", "炎の力を制御します。", "_t")
t("gunner training", "銃器訓練", "talent type")
t("Use steam powered guns to rain bullets of death on your foes!  (Learning these talents allow you to fire two steamguns at once.)", "　スチームガンで凶弾を雨霰と撃ち込みます！（二丁拳銃が可能に）", "_t")
t("gunslinging", "銃士", "talent type")
t("Use advanced marksmanship to confound and overwhelm your foes!  (Learning these talents allow you to fire two steamguns at once.)", "　高度な射撃技術で敵を圧倒します！（二丁拳銃が可能に）", "_t")
t("bullets mastery", "弾丸改造", "talent type")
t("Use various kinds of technology to temporarily enhance your bullets.  (Learning these talents allow you to fire two steamguns at once.)", "　様々なテクノロジーを用い、弾丸を強化して撃ち込みます（二丁拳銃が可能に）", "_t")
t("avoidance", "回避装置", "talent type")
t("Using various enhancements of your cloak you are able to manage incoming damage.", "　クロークに取り付けた様々な機能を生かして攻撃を凌ぎます。", "_t")
t("elusiveness", "跳技", "talent type")
t("Incredible feats of slipperiness!", "　ぴょんぴょんするんじゃあ！", "_t")
t("automation", "自動機械", "talent type")
t("Use small automated devices to control the battlefield.", "　小型の自動デバイスを用いて戦局をコントロールします。", "_t")
t("psytech gunnery", "サイコガンナー", "talent type")
t("Meld your psionic powers with awesome steamtech! For mayhem!", "　超能力を驚異の蒸気機械と融合させます！　皆殺しだ！", "_t")
t("thoughts of iron", "アイアンウィル", "talent type")
t("Apply some of your formidable willpower through steam devices.", "　蒸気機械を凄まじい意志の力で満たします。", "_t")
t("mechstar", "メックスター", "talent type")
t("Control your mindstar and infuse it with steamtech.", "　マインドスターを操り、蒸気機械と合体させます。", "_t")
t("dread", "ホラーマシン", "talent type")
t("Behold the mechanized horrors.", "　テクノロジーの狂気をご覧あれ。", "_t")
t("magnetism", "磁気盾", "talent type")
t("Use the power of electricity to supercharge your shield.", "　電気の力を用いて盾を荷電させます。", "_t")
t("demolition", "爆破", "talent type")
t("The use of high explosives.", "　強烈な爆発物を扱います。", "_t")
t("gadgets", "近接兵装", "talent type")
t("Cunning devices to augment your combat skill.", "　便利なデバイスで近接戦闘を補助します。", "_t")
t("heavy weapons", "重火器", "talent type")
t("Wield powerful steamtech tools of destruction.", "　蒸気を利用した強力な破壊兵器です。", "_t")
t("turrets", "支援設置", "talent type")
t("Deploy steam powered turrets to assist you in combat.", "　蒸気機関で動くタレットを設置して支援させます。", "_t")
t("The various kinds of turrets.", "　様々なタレットです。", "_t")
t("artillery", "砲技", "talent type")
t("Advanced explosive weaponry.", "　高度な爆破兵器です。", "_t")
t("mecharachnid", "機械蜘蛛", "talent type")
t("Build and deploy a powerful mechanical arachnid to assist you.", "　強力なスパイダーマシンを作成して戦闘支援に用います。", "_t")
t("chemical warfare", "化学兵器", "talent type")
t("Unleash toxic steamtech weaponry on your enemies.", "　有毒な蒸気を敵に放ちます。", "_t")
t("#VIOLET#EUREKA!", "#VIOLET#ヘウレーカ！", "log")
t("#VIOLET#EUREKA!#WHITE# Schematic learnt: #LIGHT_BLUE#%s", "#VIOLET#EUREKA!#WHITE#作成法を習得#LIGHT_BLUE#%s", "saySimple")
