t(" #LIGHT_BLUE#(known)#LAST#", " #LIGHT_BLUE#（習得済み）#LAST#", "_t")
t("#{italic}#* ...perhaps more to discover...#{normal}#", "#{italic}#他にもあるかもしれません。#{normal}#", "_t")
