section "tome-orcs/data/talents/steam/thoughts-of-iron.lua"

t("Molten Iron Blood", "アイアンブラッド", "talent name")
t([[Using psionic energies you temporarily alter your blood, turning it into molten iron.
		When affected by molten blood all creatures that hit you in melee take %0.2f fire damage, all your resistances are increased by %d%% and all new detrimental effects on you have their duration reduced by %d%%.
		Damage increases with your Steampower.
		]], [[精神エネルギーを用いて一時的に血液を煮え滾る鉄に変じます。
		　起動中は近接攻撃してきた相手に %0.2f の火炎属性ダメージを与えます。また全ての耐性が %d%% 増加し、新たに付加されるデバフの持続時間が %d%% 減少します。
		　ダメージは蒸気パワーに依存します。
]], "tformat")
t("Mind Drones", "マインドドローン", "talent name")
t([[Melding psionics with steamtech you create 5 mind drones at your sides that fly towards your target.
		If they encounter a creature they will latch on it and bore into its skull for 6 turns, disrupting its thoughts.
		Disrupted creatures have %d%% chances to fail to use talents and suffer a -%d%% reduction to fear and sleep immunity.]], [[蒸気機械に超能力を込めて、５体のマインドドローンを作り出します。これは対象に向かって飛んでいきます。
		　誰かに接触するとマインドドローンは対象に取り付いて頭の中に入り込み、６ターンの間精神を乱します。
		　これを受けた相手は %d%% の確率でタレントの使用に失敗し、恐怖と睡眠耐性が %d%% 低下します。]], "tformat")
t("Psionic Mirror", "Ｐｓｉミラー", "talent name")
t([[You cleanse your mind of %d mental debuffs.
		Cleansed effects will be randomly sent to closeby foes (range 5, subject to a mental save).]], [[精神を浄化します。精神系のデバフが %d 種類解除されます。
		　解除したデバフは近場の敵へランダムに付与されます（範囲５マス、精神セーブで抵抗します）]], "tformat")
t("Mind Injection", "超能力インジェクター", "talent name")
t("#LIGHT_BLUE#Mind Injection selected to be used first by salves.", "#LIGHT_BLUE#軟膏使用時に超能力インジェクターを優先して使用します。", "saySimple")
t("This medical injector will now be used first if available when using medical salves.", "未使用ならこの注射器を軟膏使用時に優先して使用します。", "logPlayer")
t("By using a direct psionic link to your body you can use even more therapeutics. This talent acts as an extra medical injector with %d%% efficiency and %d%% cooldown mod.", "肉体へ直に繋いだ超能力リンクを用いて医療系の工士アイテムをさらに使用できます。効果量に %d%% クールダウンに %d%% の修正を受けて使用する注射器として機能します。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/steam/turrets.lua"

t("Deploy Turret", "タレット設置", "talent name")
t([[You are able to deploy turrets, stationary constructs that defend you in combat. Turrets last 10 turns, have a 20 turn cooldown, and deploying a turret places the others on a 5 turn cooldown.
You learn new turrets as you invest in this talent.

At raw talent level 1 you can use Steamgun turrets, which fire at a random target nearby for %d%% steamgun damage. These shots bypass allies.
At raw talent level 3 you can use Flame turrets, which deal fire damage to enemies in a radius 3 cone. Flame turrets gain %d bonus armor and 30%% resistance to all damage.
At raw talent level 4 you can use Medic turrets, which emit a healing mist that restores %d life to allies and reduces the duration of newly applied detrimental effects by %d%%.
This talent also increases the Dexterity, Constitution and Cunning of all Turrets by %d.

All turrets gain bonus armor equal to 1/2 your level, are immune to all detrimental effects, and inherit your increased damage, resistance penetration, Steampower, Physical Power, and Accuracy.
The stat bonus as well as the damage and healing dealt by Flame and Medic Turrets will increase with your Steampower.]], [[タレットを設置できます。その場に留まって設置者を防御する機械です。存在時間はそれぞれ１０ターンで、２０ターンのクールダウンを有します。タレットを設置すると、他のタレットのクールダウンが５ターンに設定されます。
		　このタレントにポイントを振ることで新たなタレットを習得します。
		
		・タレントレベル１：ガンタレット
		　近場のランダムな敵１体に倍率 %d%% のスチームガン射撃を行います。この射撃は味方を素通りします。
		
		・タレントレベル３：フレイムタレット
		　半径３マスの扇状範囲に火炎属性ダメージを与えます。このタレットはアーマーに %d ポイントのボーナスがあり、全耐性が３０％です。
		
		・タレントレベル５：医療タレット
		　味方全員のＨＰを %d 回復するヒーリングミストを散布します。これは新たに付与されるデバフの持続時間を %d%% 短縮する効果もあります。
		
		　このタレントによってタレットの機敏・耐久・賢さが %d 上昇します。各タレットのアーマーには設置者のレベル／２が加算されます。また、デバフを一切受けません。設置者の与ダメージ上昇量、耐性貫通、蒸気パワー、物理パワー、命中を継承します。
		　能力値の上昇量とフレイムタレットの与ダメージ、医療タレットの回復量は蒸気パワーに依存します。]], "tformat")
t("Steamgun Turret", "ガンタレット", "talent name")
t("Not enough space to summon!", "召喚する場所がない！", "logPlayer")
t("steamgun turret", "ガンタレット", "_t")
t("An automated turret equipped with a steamgun.", "　スチームガンを搭載した自動タレットだ。", "_t")
t("Turret", "タレット", "_t")
t("Deploy a turret mounted with a steamgun that fires at foes within range for %d%% steamgun damage. The turret gains +%d Dexterity, Constitution and Cunning and %0.2f Steamgun Mastery.", "スチームガン搭載のタレットを設置します。これは射程内の敵に倍率 %d%% のスチームガン射撃をします。このタレットの機敏、耐久、賢さが %d 増加し、スチームガン・マスタリーのレベルが %0.2f となります。", "tformat")
t("Rocket Launcher", "タレットランチャー", "talent name")
t("You require a steamgun for this talent.", "スチームガンを装備していないと使えない。", "logPlayer")
t("Fire a missile dealing steamgun damage as fire in radius 2.", "半径２マスにスチームガンによるダメージを与えるミサイルを放ちます。", "tformat")
t("Dual Steamgun", "デュアルガン", "talent name")
t("Gain a second steamgun that deals %d%% damage.", "二丁目のスチームガンを装備できます。この射撃の倍率は %d%% です。", "tformat")
t("Flame Turret", "フレイムタレット", "talent name")
t("flame turret", "フレイムタレット", "_t")
t("An automated turret equiped with a flamethrower.", "　火炎放射器を搭載した自動タレットだ。", "_t")
t("Deploy a turret mounted with a flamethrower, scorching nearby targets. The turret gains +%d Dexterity, Constitution and Cunning.", "火炎放射器を搭載した自動タレットを設置して、周囲の敵を燃やします。このタレットの機敏、耐久、賢さが %d 上昇します。", "tformat")
t("Flamethrower", "火炎放射器", "talent name")
t([[Throw a cone of flame with radius %d, dealing %0.2f fire damage.
		The damage will increase with your Steampower.]], [[扇状の %d マスに火炎放射して火炎属性の %0.2f ダメージを与えます。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Flame Vortex", "熱風渦", "talent name")
t([[Project a radius %d vortex of superheated air, dealing %0.2f fire damage and pulling targets towards you.
		The damage will increase with your Steampower.]], [[半径 %d マスを巻き込む熱風の渦を生成します。これは火炎属性の %0.2f ダメージを与え、相手を引き寄せます。
		　ダメージは蒸気パワーに依存します。]], "tformat")
t("Medic Turret", "医療タレット", "talent name")
t("medic turret", "医療タレット", "_t")
t("An automated turret emitting a healing mist.", "　ヒーリングミストを散布する自動タレットだ。", "_t")
t("Deploy a turret that emits a healing mist in radius 3. The turret gains +%d Dexterity, Constitution and Cunning.", "半径３マスにヒーリングミストを散布するタレットを設置します。このタレットの機敏、耐久、賢さが %d 上昇します。", "tformat")
t("Overclock", "オーバークロック", "talent name")
t([[Send a surge of power into all turrets in sight, extending their duration by %d turns and granting them a charged shield absorbing %d damage for 10 turns. While the shield holds, each turn the turret will project a bolt of lightning dealing %0.2f lightning damage to a random enemy in radius 6, with a 25%% chance to daze.
		The effects will increase with your Steampower.]], [[視界内の全タレットをオーバークロックします。各タレットの存在時間が %d ターン延長し、１０ターンの間 %d ダメージを無効化する電磁シールドを張ります。電磁シールドを張っている間は毎ターン、各タレットから半径６マス以内のランダムな敵に電撃弾を放ちます。これは電撃属性の %0.2f ダメージで、２５％の確率で朦朧状態を付与します。
		　効果量は蒸気パワーに依存します。]], "tformat")
t("Upgrade", "アップグレード", "talent name")
t([[Upgrade the target turret, granting it %d%% increased maximum life and enhanced abilities based on type:
		Steamgun: Gains a second steamgun dealing %d%% damage, and every 3 turns will fire a rocket dealing %d%% steamgun damage as fire in radius 2.
		Flame: Increases damage by %d%%, range by %d, and every 3 turns will project a vortex of superheated air that drags targets within range %d towards the turret as well as dealing normal flamethrower damage.
		Medic: Increases healing on affected targets by %d%%, and has a %d%% chance to cleanse a negative effect each turn.]], [[指定したタレットをアップグレードします。対象の最大ＨＰが %d%% 増加し、種類に応じて強化能力を得ます。
		
		・ガンタレット
		　倍率 %d%% の射撃をするスチームガンを追加で搭載します。また、３ターン毎にロケット弾を撃ちます。これは半径２マスにダメージを与える倍率 %d%% のスチームガン射撃です。

		・フレイムタレット
		　与ダメージが %d%% 射程が %d マス増加します。また、３ターン毎に熱風の渦を起こします。これは半径 %d マス以内に火炎放射のダメージを与えて引き寄せます。

		・医療タレット
		　ヒーリングミストを受けた相手の回復倍率を %d%% 上昇させ、毎ターン %d%% の確率でデバフを１種除去します。]], "tformat")
t("Hunker Down", "ガーディアンタレット", "talent name")
t("guardian turret", "ガーディアンタレット", "_t")
t("An advanced turret equipped with dual steamguns.", "　スチームガンを二丁搭載した新型タレットだ。", "_t")
t([[Deploy a defensive emplacement around you, summoning 2 guardian turrets in adjacent tiles for %d turns. Guardian turrets redirect %d%% of all damage taken by other adjacent allies (other than fellow guardian turrets) to themselves, and each is armed with a powerful turret capable of firing piercing bullets.
			Guardian Turrets gain %0.2f ranks in Steamgun Mastery based on your Hunker Down talent level.]], [[ガーディアンタレット２基を召喚し、周囲に防衛砲座を設置します。これは %d ターン持続します。このタレットは隣接する仲間が受けたダメージの %d%% を自身に転嫁します。ただし他のガーディアンタレットのダメージは肩代わりしません。貫通弾を撃つ強力なタレットです。
		　このタレットのスチームガン・マスタリーはレベル %0.2f です。これはこのタレントのレベルに依存します。]], "tformat")
t("Gauss Cannon", "ガウスカノン", "talent name")
t("Fire your twin-linked gauss cannons, dealing 100%% steamgun damage as lightning in a piercing beam that bypasses all armor. This does not harm friendly targets.", "ツインリンク式の電磁キャノンを撃ちます。これは倍率１００％のスチームガン射撃で電撃属性です。射線を貫通しアーマーを無視します。また、味方は素通りします。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/const.lua"

t("Subcutaneous Metallisation", "メタリックボディ", "talent name")
t([[When your life dips below 50%% of your total life an automated process turns some of your lower skin layers (or other internal organs) into a thick metallic layer for 6 turns.
		While the effect lasts all damage done to you is reduced by a flat amount equal to 100%% of your Constitution.
		This effect can only trigger once every %d turns.]], [[ＨＰが最大値の５０％未満になった際、自動システムが皮膚下組織（と他の臓器）を分厚い金属層に変化させます。持続時間は６ターンです。
		　効果中は被ダメージの全てを耐久に等しい値だけ固定値減少します。
		　この効果は %d ターン毎にしか発動しません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/cun.lua"

t("Master of Disasters", "トラブルメイカー", "talent name")
t([[You are adept at wreaking havoc onto your foes!
		Any time you deal damage to a creature you apply the Incoming Disasters effect for 20 turns.
		Each time you (or any others) would try to apply a cross-tier effect to this creature, you also try to apply the other two.
		In addition your physical, steam, spell and mind powers are increased by %d.
		The powers increase scales of your Cunning.]], [[敵をハメるのはお手の物！
		　ダメージを与えるとその対象に２０ターンの間、トラブルメイカーの効果を付与します。
		　この対象に自身が（もしくはほかのキャラクターが）クロスティアー効果の付与を試みる際、他のクロスティアー効果２種の付与判定も発生します。
		　また、物理・蒸気・魔法・精神パワーが %d 増加します。
		　パワー増加量は賢さに依存します。]], "tformat")
t("Rak'Shor's Cunning", "ラク・ショルの秘策", "talent name")
t("Quaffed the Blood of Undeath, not already undead and not antimagic.", "★不死の小瓶の中身を飲み干しており、アンデッドでなければ反魔法習得者でもない。", "_t")
t("Rak'Shor's Cunning", "ラク・ショルの秘策", "_t")
t([[#GREY#Applying you cunning plans, you escape death by turning to undeath in an instant!

#{italic}#You may now choose to customize your undead appearance, this can not be changed afterwards.]], [[#GREY#秘策を発動し、アンデッドとなって即座に蘇ります！

#{italic}#復活後の外見を選択できますが、一度決定すると後から変えられません。]], "_t")
t("Cosmetic Options", "外見オプション", "_t")
t("Customize Appearance", "外見を変える", "_t")
t("Use Default", "デフォルトのまま", "_t")
t("Rak'Shor's Cunning (Skeleton)", "ラク・ショルの秘策（スケルトン）", "_t")
t("Rak'Shor's Cunning (Ghoul)", "ラク・ショルの秘策（グール）", "_t")
t([[Set up some cunning contingency plans in case of death.
		If you die you will have the option to raise back from the dead once, by becoming a ghoul or a skeleton (you can choose which).
		When rising this way you will keep access to your racial tree and gain access to the ghoul or skeleton racial tree with 2 levels of each talents already learnt.
		As undead will not able to use infusions anymore.
		If you choose to become a skeleton, the Re-assemble talent will consider that you already used your resurrection.]], [[絶体絶命の危機に備えて秘策を用意しておきます。
		　死亡した場合、一回だけアンデッドとなって復活できるようになります。グールかスケルトンになるのです（選択できます）
		　復活後も元の種族タレントツリーは消えません。さらにアンデッド用の種族ツリーを獲得し、その各タレントレベルが２ずつ上昇します。
		　アンデッドなのでハーブ物は以後使用できません。
		　スケルトンになった場合、「再構成」タレントの復活効果は既に使用した扱いになります。]], "tformat")
t("All steamtech criticals reduce the remaining cooldown of a random steamtech talent by 1.", "　蒸気機械系タレントのクリティカルが発生する毎に、ランダムな蒸気機械系タレント１種のクールダウンが１減少します。", "_t")

------------------------------------------------
section "tome-orcs/data/talents/uber/dex.lua"

t("Automated Reflex System", "自動反応システム", "talent name")
t("Have gained the #{italic}#Matrix Style#{normal}# achievement with this or any previous character for the current difficulty & permadeath settings.", "ローグライクモードにおいて、現在プレイ中の難易度で「マトリックス！」の実績を習得したことがある（プレイ中のキャラクターでなくてもいい）", "_t")
t([[A small automatic detection system is always looking for incoming projectiles, when one is about to hit you it injects drugs into your system to boost your reactivity, granting you a free turn.
		This effect can not happen more than once every 5 turns.]], [[小型の自動感知システムが常時飛来物を感知します。飛来物が命中する瞬間に感知システムが薬品を注射し、反射神経を向上させます。これにより行動ターンを１ターン獲得します。
		　この効果は５ターン毎にしか発動しません。]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/mag.lua"

t("Arcane Amplification Drone Effect", "魔力増幅ドローン", "talent name")
t("Spell damage done to it ripples in radius 4 doing 130% arcane damage.", "　魔法でダメージを与えると、半径４マスにその１３０％分を神秘属性ダメージとして与える。", "_t")
t("Arcane Amplification Drone", "魔力増幅ドローン", "talent name")
t("Have gained the #{italic}#Tales of the Spellblaze#{normal}# achievement with this or any previous character for the current difficulty & permadeath settings.", "ローグライクモードにおいて、現在プレイ中の難易度で「魔法大禍の記憶」実績を習得したことがある（プレイ中のキャラクターでなくてもいい）", "_t")
t("Not enough space to summon!", "召喚する場所がない！", "logPlayer")
t("arcane amplification drone", "魔力増幅ドローン", "_t")
t("Any spell damage you deal to it will ripple around in radius 4 as 160% arcane damage.", "　このドローンに魔法でダメージを与えると１６０％分を半径４マスに伝播する。", "_t")
t([[You create an Arcane Amplification Drone at the selected location for 3 turns.
		When you cast a spell that damages the drone it will ripple the damage as 130%% arcane damage of the initial hit in radius 4.]], [[魔力増幅ドローンを指定した地点に３ターン生成します。
		　ドローンにダメージを与える魔法を使用すると、魔力波を放ちそのダメージの１３０％分を半径４マスに神秘属性として与えます。]], "tformat")
t("Technomancer", "魔工学士", "talent name")
t("Unlocked the Technomancer evolution", "魔工学士のクラス進化をアンロック。", "_t")
t("Technomancer", "魔工学士", "_t")
t("Occult Technomancy", "空霊魔学", "_t")
t("These talents focus on arcane and temporal damage, using a super-spinned steamsaw to rip holes in reality.", "　神秘の力と時空の力に焦点を置いたタレントです。高速回転するスチームソーを用いて空間に断裂を発生させます。", "_t")
t("Galvanic Technomancy", "熱電魔学", "_t")
t("These talents focus on fire and lightning damage, strategically placing galvanic rods to create fields of death and stuns.", "　炎と雷に焦点を置いたタレントです。帯電ロッドを上手く配置してフィールドを作り出し、敵をスタンさせ死に至らしめます。", "_t")
t("Terrene Technomancy", "冷地魔学", "_t")
t("These talents focus on cold and physical damage, summoning micro spiderbots to harass and pin their foes or protect themselves.", "　冷気と物理に焦点を置いたタレントです。微小なスパイダーボットを作り出して敵の行動を阻害し、動きを止めます。自身を守ることも可能です。", "_t")
t("Choose your free Technomancy unlock?", "どの分野をアンロックしますか？", "_t")
t([[Available talents:
]], [[習得可能タレント:
]], "_t")
t([[Technomancers are Archmages that dabble in steam technology to enhance their already formidable arsenal of spells.
		Once this class evolution is taken, you gain the following:
		- Arcane Dynamo tinker schematic
		- Steamtech/Physics category (unlocked)
		- Steamtech/Chemistry category (locked)
		- An Automated Portable Extractor (A.P.E.)
		- One point in the Physics talent Smith and two in Mechanical and Electricity
		- Spell/Galvanic Technomancy category (locked) - deals with fire and lightning
		- Spell/Terrene Technomancy category (locked) - deals with earth and water
		- Spell/Occult Technomancy category (locked) - deals with time and arcane
		- The ability to unlock one of the three Technomancy categories for free

		Once put in a robe, the Arcane Dynamo will regenerate Steam each time mana is spent and increase Spellpower based on current steam level.

		#{bold}#As soon as this evolution is used you will need to craft the Arcane Dynamo to place in a robe to benefit from all the powers of the Technomancer.#{normal}#]], [[魔工学士は蒸気機関の技術を嗜む魔導士です。ただでさえ破壊力抜群の攻撃魔法を強化しようとしているのです。
		　このクラス進化を習得すると以下の効果を得ます。
		
		・魔導ダイナモの製作法を習得
		・工士／蒸気力学のツリーをアンロック状態で習得
		・工士／蒸気化学のツリーをロック状態で習得
		・工士用携帯式自動変換機を入手
		・工士／蒸気力学の「鍛冶習得」に１点、「機械いじり」と「電磁気学」にそれぞれ２点ずつポイントが振られる
		・魔術／熱電魔学のツリーをロック状態で習得。火炎と電撃を操ります。
		・魔術／冷地魔学のツリーをロック状態で習得。大地と冷気を操ります。
		・魔術／空霊魔学のツリーをロック状態で習得。神秘の力と時空を操ります。
		・上記三種のツリーのいずれか１つをアンロックする権利
		
		　魔導ダイナモをローブにセットすると、マナを消費する毎に蒸気が回復します。またこのダイナモは現在の蒸気に応じて魔法パワーが増加する効果があります。

		#{bold}#　このクラス進化を習得したら、体防具にセットする魔導ダイナモをすぐに作成する必要があります。これがなければ魔導工学の利点を余すところなく受けられません。#{normal}#]], "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/str.lua"

t("Pain Enhancement System", "ペインエンハンス", "talent name")
t("Earned the achievement 'Size Matters' on this character.", "このキャラクターで「デカけりゃいいのさ」の実績を達成している。", "_t")
t("When you deal a critical hit your embedded system activates, increasing all your primary stats except Strength by 50%% of your Strength for 6 turns.", "　攻撃をクリティカルヒットさせると内蔵システムが起動し腕力の５０％に等しい値だけ全能力値が上昇します。腕力自体はこの対象になりません。持続時間は６ターンです。", "tformat")

------------------------------------------------
section "tome-orcs/data/talents/uber/wil.lua"

t("Range Amplification Device", "射程延長デバイス", "talent name")
t("Have a light radius of 10 or more", "光源半径が１０マス以上。", "_t")
t([[Activate a special focusing device that extends all your ranged spells and psionic powers range by 3 (only works on those with range 2 or more and up to 10 max).
		The use of this device is very strenuous, increasing fatigue by 20%% while active.]], [[特殊な集中力強化装置を用いて遠距離用の魔法・超能力の射程を全て３マス伸ばします。これは射程が２以上のタレントにのみ効果があります。最大でも１０マスを超えることはありません。
		　この装置は精神に絶大な負荷がかかるため起動中は疲労度が２０％増加します。]], "tformat")

