section "tome-orcs/data/timed_effects/floor.lua"

t("Warm", "暖気", "_t")
t("The target is warm from the campfire. Increasing steam regeneration by 6/turn, stun immunity by 30% and stamina regeneration by 4/turn.", "　焚火で温まっています。ターン毎の蒸気回復量が６増加し、スタン耐性が３０％、ターン毎のスタミナ回復量が４ポイント上昇します。", "_t")
t("Sun Radiance", "天照光輝", "_t")
t("The target is under the effect of the sun. Increasing lite and sight radius by 2, blindness immunity by 30%, stealth seeing by 20 and light resistance by 30%.", "　太陽を戴いています。光源半径と視界範囲が２マス上昇し、盲目耐性が３０％、隠密看破が２０、光耐性が３０％増加しています。", "_t")
t("Moon Radiance", "夜天光輝", "_t")
t("The target is under the effect of the moons. Decreasing lite and sight radius by 1, increasing stun immunity by 30%, granting 10 stealth and darkness resistance by 30%.", "　月を戴いています。光源半径と視界範囲が１マス低下し、スタン耐性が３０％、隠密効果量が１０、暗黒耐性が３０％増加しています。", "_t")

