section "tome-orcs/data/timed_effects/magical.lua"

t("disease", "病気", "effect subtype")
t("blight", "腐敗", "effect subtype")
t("Viral Injection", "ウイルスニードル", "_t")
t("The target is infected by a disease, reducing its highest %d stats by %d and doing %0.2f blight damage per turn.", "　ウイルスに感染しています。基本能力値が高い順に %d 種類低下しています。低下量は %d です。ターン毎に腐敗属性の %0.2f ダメージを受けます。", "tformat")
t("#Target# is injected with a pathogen!", "#Target#は病原菌を注入された！", "_t")
t("#Target# is free from the pathogen.", "#Target#の体から病原菌が消えた。", "_t")
t("arcane", "神秘", "effect subtype")
t("shield", "シールド", "effect subtype")
t("Steam Shield", "蒸気シールド", "_t")
t("The target is surrounded by a magical steam shield, absorbing %d/%d damage and burning attackers for %d fire damage before it crumbles.", "　魔法蒸気のシールドで包まれています。強度 %d/%d 攻撃者を燃やして %d の火炎属性ダメージを与えます。", "tformat")
t("A shield forms around #target#.", "#Target#はシールドを生成した", "_t")
t("+Shield", "+シールド", "_t")
t("The shield around #target# crumbles.", "#Target#のシールドが崩壊した", "_t")
t("-Shield", "-シールド", "_t")
t("dark", "闇", "effect subtype")
t("light", "光", "effect subtype")
t("Twilit Echoes", "トワイライトエコー", "_t")
t("The target feels the echoes of all light and dark damage it takes. Light damage slows the target by %0.2f%% per point of damage dealt, up to a maximum of %d%% at %d damage. Dark damage creates an effect at the tile for %d turns which deals %d%% of the damage dealt each turn. It will be refreshed as long as the target continues taking damage from it or another source.", "　光属性の被ダメージ１点当たり %0.2f%% 減速します。減速量の上限は %d%% で、これは光属性被ダメージが %d ポイントの時です。暗黒属性のダメージを受けると、トリガーとなったダメージの %d%% 分を毎ターン与えるダメージ場を %d ターン生成します。ダメージ場は暗黒属性ダメージを受ける毎に更新されます。", "tformat")
t("slow", "減速", "effect subtype")
t("Echoed Light", "光の残響", "_t")
t("The light damage the target has taken is echoed, slowing them by %d%%. Taking additional damage while Twilit Echoes is active will refresh and increase the slow up to a maximum of %d%%.", "　対象が受けた光属性ダメージは反響して %d%% の減速効果を引き起こします。効果中に光属性ダメージを受ける毎に効果は更新され、最大で減速 %d%% に達します。", "tformat")
t("temporal", "時空", "effect subtype")
t("Mirror Worlded", "鏡の世界", "_t")
t("This unit will flip spaces soon.", "　すぐに反対側に出ます。", "_t")
t("That space is occupied!", "反対側に出られなかった！", "logPlayer")
t("celestial", "天球", "effect subtype")
t("Starscape", "星界", "_t")
t("Has summoned the starscape, slowing all creatures 67%.", "　星界を呼び出しています。全てのキャラクターが６７％減速しています。", "_t")
t("corruption", "邪悪", "effect subtype")
t("Vampiric Surge", "ヴァンパイアサージ", "_t")
t("This unit is recovering %d%% of all damage it deals as health.", "　与ダメージの %d%% 分ＨＰが回復します。", "tformat")
t("#Target# is overflowing with dark power!", "#Target#に闇の力が満ちる！", "_t")
t("+Vamp Surge", "+ヴァンパイアサージ", "_t")
t("#Target#'s dark aura fades.", "#Target#から闇の力が消えていく。", "_t")
t("-Vamp Surge", "-ヴァンパイアサージ", "_t")
t("chronomancy", "時間操作", "effect subtype")
t("Temporal Ripples", "時の波紋", "_t")
t("Attackers dealing damage will be healed for %d%% of the damage done.", "　攻撃者は与えたダメージの %d%% 分回復します。", "tformat")
t("#Target# is fluctuating in time!", "#Target#の時間がざわめいた。", "_t")
t("#Target# is no longer fluctuating.", "#Target#の時間が安定した。", "_t")
t("undead", "アンデッド", "effect subtype")
t("Death Momentum", "死の衝撃", "_t")
t("You have %d charges.", "　チャージ数 %d ", "tformat")
t("steam", "蒸気", "effect subtype")
t("technomancy", "魔導工学", "effect subtype")
t("Ethereal Steam", "イセリアルリンク", "_t")
t("Deals %0.2f occult damage per turn and each time a talent is used, the caster regens one turn of a random cooldown.", "　毎ターン空霊属性の %0.2f ダメージを受けます。また、タレントを使用すると、このデバフ元の術者はランダムなタレント１種のクールダウンが１ターン短縮されます。", "tformat")
t("#Target# covered in arcane-infused steam!", "#Target#は魔法の蒸気に包まれた！", "_t")
t("#Target# is free from the steam.", "#Target#は蒸気から抜け出した。", "_t")
t("Ethereal Link", "イセリアルリンク", "_t")
t("While Ethereal Steam exists the cooldown of Metaphasic Spin is reduced to 6.", "　イセリアルリンクが継続しているなら「メタフェイズスピン」のクールダウンが６ターンになります。", "tformat")
t("Metaphasic Echoes", "メタフェイズエコー", "_t")
t("Project your saw along the leftover breaches.", "　空間断裂に沿って鋸刃が発射されます。", "tformat")
t("Spiderbots Shield", "ボットシールド", "_t")
t("%d spiderbots are protecting you, each with %d life. Current top spiderbot has %d life remaining.", "　スパイダーボット %d 体で身を守っています。それぞれＨＰは %d です。今被弾を担当しているボットのＨＰは %d です。", "tformat")
t("#Target# covered with micro spiderbots!", "#Target#は小さなスパイダーボットを身を守った！", "_t")
t("#Target# is no longer protected by spiderbots.", "#Target#はもうスパイダーボットに守られていない。", "_t")
t("#SLATE#(%d to spiderbot - destructed)#LAST#", "#SLATE#(%d ボット被弾－破壊)#LAST#", "tformat")
t("#SLATE#(%d to spiderbot)#LAST#", "#SLATE#(%d ボット被弾)#LAST#", "tformat")
