t("Electron Incantation", "電子操作術", "_t")
t("Arcane Dynamo returns %d more steam per 10 mana spent.", "　魔導ダイナモの蒸気回復量が消費マナ１０あたり %d 増加します。", "tformat")
t("Defensive Circuit: Dynamo Boost", "防御回路：ダイナモ強化", "_t")
t("Defensive Circuit: Resistances Boost", "防御回路：耐性強化", "_t")
