section "tome-orcs/data/timed_effects/mental.lua"

t("psionic", "超能力", "effect subtype")
t("gestalt", "心機合一", "effect subtype")
t("Gestalt", "心機合一", "_t")
t("Steampower increased by %d.", "　蒸気パワーが %d 増加しています。", "tformat")
t("Forced Gestalt", "ゲシュタルト接続", "_t")
t("All powers increased by %d.", "　全パワーが %d 増加しています。", "tformat")
t("#Target# is drains all powers around #himher#.", "#Target#は#himher#周囲の全パワーを吸収した。", "_t")
t("#Target# is less powerful.", "#Target#のパワーが戻った。", "_t")
t("All powers reduced by %d.", "　全パワーが %d 低下しています。", "tformat")
t("#Target# is drained of all powers.", "#Target#は全てのパワーを吸収された。", "_t")
