t("+Bullet Mastery", "+弾丸強化", "_t")
t("Bullet Mastery: Supercharged", "弾丸強化：ピアースバレット", "_t")
t("Bullets shot are supercharged:  They can pass through multiple targets and have %d additional armour penetration.", "　貫通弾になっています。複数体の敵を貫通し、アーマー貫通が %d 上昇しています。", "tformat")
t("Bullet Mastery: Percussive", "弾丸強化：ラージバレット", "_t")
t("Bullets shot are percussive:  When striking, they have a %d%% chance to knock back and a %d%% chance to stun.", "　衝撃弾になっています。命中時に %d%% の確率でノックバックし %d%% の確率でスタンさせます。", "tformat")
