t("Bullets shot are combustive:  When striking their target, they explode (radius 2) for %d fire damage.", "　爆発弾になっています。命中時に半径２マスに爆発して火炎属性の %d ダメージを与えます。", "tformat")
t("Uncanny Reload", "超高速リロード", "_t")
t("Firing steamguns does not consume shots.", "　スチームガン射撃が弾丸を消費しません。", "tformat")
t("#Target# is focuses on firing.", "#Target#は射撃に徹している。", "_t")
t("+Uncanny Reload", "+超高速リロード", "_t")
t("#Target# is less focused.", "#Target#はリロードをやめた。", "_t")
t("-Uncanny Reload", "-超高速リロード", "_t")
t("Cloak", "クローキング", "_t")
