t("nature", "自然", "effect subtype")
t("Pain Suppressor Salve", "痛覚抑制", "_t")
t("Fight to the brink of death, can not die before going under -%d life (but life under 0 is not shown) and increases all resistances by %d%%.", "　死の瀬戸際まで戦えます。ＨＰの下限が %d 上昇しています（ＨＰが０未満の時は表示されません）また、全ての耐性が %d%% 上昇しています。", "tformat")
