t("fire", "火炎", "effect subtype")
t("Fiery Salve", "火炎軟膏", "_t")
t("Provides a frost aura, giving you +%d%% fire, light, and lightning affinity.", "　火炎のオーラを纏っています。火炎、光、電撃の属性吸収が +%d%%", "tformat")
t("#Target# uses a fiery salve.", "#Target#は火炎軟膏を使った。", "_t")
t("+Fiery Salve", "+火炎軟膏", "_t")
t("-Fiery Salve", "-火炎軟膏", "_t")
