t("Provides a frost aura, giving you +%d%% blight, mind and acid affinity.", "　静水のオーラを纏っています。腐敗、精神、酸の属性吸収が +%d%%", "tformat")
t("#Target# uses a water salve.", "#Target#は静水軟膏を使った。", "_t")
t("+Water Salve", "+静水軟膏", "_t")
