t("The target has been impregnated with %d developing ritch larvae which are feeding on it%s.  After a %d turn gestation period, each will burst out violently, dealing %0.2f physical and %0.2f fire damage to its host.", "　リッチ虫の卵を %d 個植え付けられています。卵は宿主を餌にして成長します%s　%d ターン経過すると孵化して体を食い破り、物理属性の %0.2f ダメージと火炎属性の %0.2f ダメージを宿主に与えます。", "tformat")
