t("The target is covered in burning chemicals, taking %0.2f fire damage each turn. Subsequent shots deal %0.2f fire damage, and if they fall below 25%% life they have a %d%% chance to panic.", "　化学物質が燃えています。毎ターン火炎属性の %0.2f ダメージを受けます。この状態で射撃を受けると火炎属性の %0.2f ダメージを受け、そこでＨＰが２５％未満になると %d%% の確率でパニックを起こします。", "tformat")
