t("grapple", "拘束", "effect subtype")
t("Pincer Strike", "サンドウィッチ", "_t")
t("The target is grappled by %s, pinning them, reducing attack, spell and mind speed by %d%% and subjecting them to an automatic tailsaw strike each turn for %d%% damage.", "　%s に捕まれて移動不能です。攻撃速度、詠唱速度、精神速度が %d%% 低下しています。また、毎ターン倍率 %d%% の尻尾攻撃を受けます。", "tformat")
