t("Reactive Armor", "ボムプレート", "_t")
t("Next melee or ranged attack that deals more than 8%% of maximum life is reduced by %d%% and triggers a radius %d conal explosion dealing %d%% steamgun damage. %d stacks remaining.", "　最大ＨＰの８％分を超えるような近接・遠距離攻撃の被ダメージを %d%% を低下させ、半径 %d マスの扇状範囲に倍率 %d%% スチームガン射撃ダメージを与えます。プレートの残り枚数 %d ", "tformat")
