t("The target is surrounded by a toxic cloud or radius %d. Enemies within will suffer %d%% talent failure, %d%% reduced healing, and take %0.2f additional acid damage from melee and ranged attacks.", "　有害物質スモッグに覆われています。範囲は半径 %d マスです。範囲内の敵は %d%% の確率でタレント使用に失敗するようになりＨＰ回復倍率が %d%% 低下します。また、近接・遠距離攻撃を受ける毎に追加で酸属性の %0.2f ダメージを受けます。", "tformat")
