無効化します。]], "tformat")
t("Miasma", "ミアズマ", "_t")
t("Affected by toxic chemicals. Has %d%% talent failure, %d%% reduced healing, and takes %0.2f additional acid damage from melee and ranged attacks.", "　有害化学物質を受けています。タレント失敗率 %d%% ＨＰ回復倍率低下 %d%% 近接・遠距離攻撃で酸属性の %0.2f 追加ダメージを受けます。", "tformat")
t("Death From Above", "上からくるぞ！", "_t")
