section "tome-orcs/data/tinkers/chemistry.lua"

t("Winterchill Edge", "フリーズエッジ", "_t")
t("Heat is energy.  Using your knowledge of physics, chemistry, and blacksmithing you can add a chilling edge to your weapons.  While the damage this deals is relatively small each blow will also cause your enemies to lose one tenth of a turn.", "　熱とはエネルギー。物理学、化学、冶金の知識を駆使して凍結の刃を武器に付加します。このダメージはそれほど大きいものではありませんが攻撃毎に対象は行動ターンを１／１０失います。", "_t")
t("Acid Groove", "アシッドスプラッシャー", "_t")
t("Allows your weapon to spray caustic acid on hit, reducing armor.", "　攻撃毎に武器が強烈な酸を射出し、アーマーを低下させます。", "_t")
t("Brain Cap", "ブレインキャップ", "_t")
t("By mounting a brain in a jar in a stralite frame this marvel will increases your mental resistances and allow you to emit a powerful magic disrupting wave.", "ストラライトのフレームを組んだ容器に脳味噌を入れた大発明。精神的な抵抗力が高まり、魔法阻害の精神波を撃てるようになります。", "_t")
t("Brain Flare", "ブレインバスター", "_t")
t("By mounting a brain in a jar in a stralite frame this marvel will increases your mental resistances and to invade your foe's minds, taking control.", "ストラライトのフレームを組んだ容器に脳味噌を入れた大発明。精神的な抵抗力が高まり、敵の精神を支配して操れるようになります。", "_t")
t("Waterproof Coating", "防水コーティング", "_t")
t("Old cloak not keeping you as dry as it used to? A waterproof coating it just what you need!", "　古くなったクロークがじっとりするようになってしまいましたか？　そんな時はとにかく防水コーティング！", "_t")
t("Fireproof Coating", "耐火コーティング", "_t")
t("New cloak doesn't have all the resistances you wanted? A fireproof coating it just what you need!", "　新調したクロークの耐性に御不満が？　そんな時にはまず耐火コーティング！", "_t")
t("Flash Powder", "フラッシュパウダー", "_t")
t("What is better than throwing sand in someone's face? Throwing sand that shines as bright as the Sun!", "　顔面に砂を浴びせるのって最高ですよね？　それが太陽みたいに輝くこのパウダーなら！", "_t")
t("Itching Powder", "発蕁パウダー", "_t")
t("The 'Crawling Ants' itching powder will distract your enemies from any complicated actions.", "　「蟻が這いまわる」この発蕁パウダーを使えば、敵は集中を欠くようになります。", "_t")
t("Rogue's Gallery", "★江湖の外套", "_t")
t("Lined with reactive mechanisms, this cloak is equipped for any situation you might possibly encounter, and several you couldn't possibly encounter!", "様々な反応型機構を有し、想定しうる全ての状況に対応します。場合によっては想定外の事態にも！", "_t")
t("flash powder", "フラッシュパウダー", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("diamond", "ダイアモンド", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Rustproof Coating", "耐酸コーティング", "_t")
t("Protects your armour from nasty corrosives like swamp, sea spray, acids, orc sweat, drake saliva...", "　鎧をうんざりするような腐食から守ります。沼地や潮風。酸、オークの汗、ドラゴンの唾液など・・・", "_t")
t("Alchemist's Helper", "アルケミストヘルパー", "_t")
t("An ingenius collection of tough no-spill pockets allows you to keep all those dangerous reagents close at hand. (increases acid, fire, nature and blight damage.)", "　気密性に優れた頑丈な容器を並べた逸品です。ああいった危険な試薬を残らず手元に置いておけます（酸、火炎、自然、腐敗属性ダメージ上昇", "_t")
t("Black Light Emitter", "ブラックライト", "_t")
t("Make the invisible visible.", "　見えないものが見えるように。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/electricity.lua"

t("Lightning Coil", "ライトニングコイル", "_t")
t("Lightning coils can be attached to melee weapons to generate a short range beam of electricity on melee crits.", "　武器に装着することで、近接攻撃クリティカル時に短距離のビームを放つようになります。", "_t")
t("Mana Coil", "マナコイル", "_t")
t("Mana coils can be attached to staves to improve mana regeneration and cast a lightning spell on spell hits.", "　杖に装着することでマナの自動回復量が増加し、魔法命中時に電撃魔法が発動するようになります。", "_t")
t("sapphire", "サファイア", "_t")
t("Arcane Dynamo", "魔導ダイナモ", "_t")
t("Arcane Dynamos build a bridge between arcane forces and steamtech, regenerating steam supplies when casting spells and allowing the use of Technomancy.", "　魔法の力と蒸気機械の橋渡しをします。魔法を使用すると蒸気が回復し、魔導工学系のタレントが使用可能になります。", "_t")
t("amethyst", "アメジスト", "_t")
t("Shocking Touch", "ショックハンド", "_t")
t("Gives you the Electric Touch. Higher tiers will chain.", "　電撃タッチが使えるようになります。高ランクになると連鎖するように。", "_t")
t("Deflection Field", "歪曲フィールド発生装置", "_t")
t("Protect yourself with the Power of Magnetism! Attach this device to your belt and watch those bullets miss every time! (not guaranteed to work every time)", "　周囲を磁場で守ります！　ベルトに装着し、弾丸が次々と逸れていく様を見物しましょう！（必ず逸れるわけではありません。悪しからず）", "_t")
t("Galvanic Retributor", "ガルバニック・リベンジャー", "_t")
t("Fortify your shield with electricity and prepare to unleash GALVANIC RETRIBUTION against your attackers!", "　盾を電気の力で強化し、攻撃者に強烈な電撃で反撃します！", "_t")
t("Shocking Edge", "ショックエッジ", "_t")
t("Attaching a capacitor to your weapon in just the right way is a great way to shock your enemies.", "　コンデンサーを理にかなったやり方で武器に組み込むのが、敵を感電させる一番の近道です。", "_t")
t("Steamsaw: Stormcutter", "★ストームカッター", "_t")
t("The pinnacle of steamsaws technology. Every one of your hits will unleash the power of the storm onto your foes, chaining between them and stunning them!", "　スチームソーの最高傑作。攻撃毎に嵐を起こし、敵集団を駆け巡ってスタンさせます！", "_t")
t("shocking edge", "ショックエッジ", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("diamond", "ダイアモンド", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Voltaic Sentry", "ボルトセントリー", "_t")
t("Just drop it down and watch the sparks fly when your enemies get near.", "　適当に放って、近づいてきた敵に電撃が走るのを見物しましょう。", "_t")
t("Mental Stimulator", "メンタルブースター", "_t")
t("Supercharge your thinking and give your brain a boost with the Mental Stimulator!", "　思考能力を強化し、脳の機能を高めます！", "_t")
t("Power Distributor", "パワーチャージ", "_t")
t("The Power Distributor V2 ensures you have the energy where and when you need it, without any of the side effects like V1 had.", "　いつでも好きな時にエネルギーを供給するパワーチャージバージョン２です。バージョン１のような副作用は一切ございません。", "_t")
t("White Light Emitter", "ホワイトライト", "_t")
t("Add more light to your light!", "　もっと光を！", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/explosive.lua"

t("Thunderclap Coating", "バーストコーティング", "_t")
t("Coat your weapon in a substance that will react destructively on impact, causing your attacks to burst out in an area.", "　衝撃を加えると反応する物質を武器に塗ります。攻撃時に範囲内に爆発を起こします。", "_t")
t("Steamgun", "スチームガン", "_t")
t("Dismantle any one sling, add some amazing steampower to it and make a powerful steamgun to fire a bullet hell at your foes!", "　スリングを解体して素晴らしい蒸気の力を付与し、強力なスチームガンを作り出します。弾丸をぶち込んでやれ！", "_t")
t("a sling (not unique)", "スリング（ユニークアイテムは不可）", "_t")
t("Convert which sling?", "どのスリングにしますか？", "_t")
t("Converted %s into %s", "　%sを%sに造り替えた。", "log")
t("Headlamp", "ヘッドランプ", "_t")
t("So much more convenient than a lantern on your waist.", "　腰に吊るすランタンよりずっと便利です。", "_t")
t("Ablative Armour", "反発アーマー", "_t")
t("Reinforcing your armour with explosions isn't as crazy as it sounds!  Adds armor and resists very large hits.", "　鎧に爆発物を仕込んで強化するというのは、割合、合理的な発想なのです！　アーマーが向上し、強烈な攻撃に耐えられるようになります。", "_t")
t("Incendiary Groove", "オイルスプラッシャー", "_t")
t("A special reservoir seeps liquid fire onto the weapon, adding fire damage and setting the ground on fire when you hit.", "　可燃性物質を吐き出す特殊タンクを武器に取り付けます。攻撃命中時に火炎属性の追加ダメージを与え、火柱を起こします。", "_t")
t("Thunder Grenade", "スタングレネード", "_t")
t("Small radius, but stuns quite well.", "　範囲は狭いものの、強烈なスタン効果のある爆弾です。", "_t")
t("Steamgun: Payload", "★エクスプロード", "_t")
t("The pinnacle of steamguns technology. Critical strikes with this gun will feel like a massive explosion of flames! And it actually will be one!", "　最高のスチームガンです。クリティカル時の衝撃たるや爆発が起きたと思うほど！　実際に起こるんですけどね！", "_t")
t("incendiary groove", "オイルスプラッシャー", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("diamond", "ダイアモンド", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Explosive Shell", "ボムショット", "_t")
t("A special shot that explodes on impact.", "　命中時に爆発する特殊弾丸です。", "_t")
t("Flare Shell", "フレアショット", "_t")
t("A special shot that releases intense light on impact.", "　命中時に閃光を放つ特殊弾丸です。", "_t")
t("Solid Shell", "ハードショット", "_t")
t("A special shot that packs a punch.", "　対象を弾き飛ばす特殊弾丸です。", "_t")
t("Saw Shell", "ソーショット", "_t")
t("A special shot that slices 'n' dices.", "　敵を細切れにする特殊弾丸です。", "_t")
t("Magnetic Shell", "マグネットショット", "_t")
t("A special shot that magnetises on impact.", "　命中時に対象へ磁気を付与する特殊弾丸です。", "_t")
t("Antimagic Shell", "アンチマジックショット", "_t")
t("A special shot filled with antimagic sap.", "　反魔法の力を宿した特殊弾丸です。", "_t")
t("Corrosive Shell", "スラッグショット", "_t")
t("A special shot that releases acid on impact.", "　命中時に酸を巻き散らす特殊弾丸です。", "_t")
t("Hook Shell", "フックショット", "_t")
t("A special shot moving yourself, or others quickly.", "　自身や相手を引っ張る特殊弾丸です。", "_t")
t("Voltaic Shell", "ボルトショット", "_t")
t("A special shot that releases electricity on impact.", "　命中時に電撃を放つ特殊弾丸です。", "_t")
t("Botanical Shell", "プラントショット", "_t")
t("A special shot grows moss on impact.", "　命中時に苔が生えてくる特殊弾丸です。", "_t")
t("Toxic Shell", "ポイズンショット", "_t")
t("A special shot that contains a deadly toxin.", "　猛毒が入っている特殊弾丸です。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/mechanical.lua"

t("Rocket Boots", "ロケットブーツ", "_t")
t("Attach small steam rocket to your boots, granting faster movement and leaving a trail of fire to burn those foolish enough to follow you.", "　小型の蒸気ロケットをブーツに装着します。移動速度が増加し、追いかけてくる馬鹿者共を炎の軌跡で燃やします。", "_t")
t("Hand Cannon", "ハンドキャノン", "_t")
t("Allows you to fire your equipped shot or arrow ammo via your gloves.", "　装備中の矢弾を小手から射出します。", "_t")
t("Fatal Attractor", "サイキックデコイ", "_t")
t("Creates a small psionic device that will taunt nearby enemies and reflect damage received.", "　小型の超能力発生装置を作成します。これは近場の敵をおびき寄せ、ダメージを反射します。", "_t")
t("Iron Grip", "アイアングリップ", "_t")
t("Attach powerful steam-powered pistons to your gloves, giving you a tight grip on your weapon (preventing disarming) and allowing you to crush a foe, pinning it and reducing its defense and armour.", "　高出力の蒸気ピストンを小手に装着します。武器をしっかりと握れるようになり（武器解除を防ぎます）敵を握りつぶせるようになります。これで掴んだ相手は移動不能となり、回避とアーマーが低下します。", "_t")
t("Spring Grapple", "スプリングキャッチャー", "_t")
t("Attach a spring loaded mechanism to your gloves, allowing you to drag enemies into melee range and deliver a quick blow, pinning them in front of you.", "　バネ仕掛けの機構を小手に装着します。敵を間近に引き寄せ、同時に一撃を加えます。対象は目の前で移動不能となります。", "_t")
t("Steam Powered Armour", "★スチームパワードアーマー", "_t")
t("Using small steam engines and the miracles of the latest automation discoveries you are able to create a Steam Powered Armour. A full plate armour that helps your movement and has intrinsic protection mechanisms.", "　小型の蒸気エンジンと最新式自動化技術の粋を駆使してスチームパワードアーマーを作成します。移動補助機能を有し、防御機構を内蔵したフルプレートアーマーです。", "_t")
t("lightning coil", "ライトニングコイル", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("diamond", "ダイアモンド", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Saw Projector", "ソーシューター", "_t")
t("A mechanical device for launching a spinning buzzsaw! What else could you want?", "　回転する鋸刃を発射する装置です！　最強！", "_t")
t("Kinetic Stabiliser", "スタビライザー", "_t")
t("Helps keep your feet on the ground, but still allows mobility.", "　両足を地面に固定し、なおかつ移動できるようになります。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/smith.lua"

t("Steamsaw", "スチームソー", "_t")
t("Dismantle any one handed sword/axe/mace, add some amazing steampower to it and make a powerful steamsaw to shred your foes to pieces!", "　片手用の剣、斧、メイスを分解し素晴らしい蒸気の力を付与して強力なスチームソーを作成します。敵は微塵切りだ！", "_t")
t("a one handed sword/axe/mace (not unique, without a special damage type)", "片手武器（ユニークアイテム以外。特殊な攻撃属性のものは駄目です）", "_t")
t("Convert which weapon?", "どの武器にしますか？", "_t")
t("Converted %s into %s", "　%sを%sに造り替えた。", "log")
t("Focus Lens", "フォーカスレンズ", "_t")
t("A simple contraption consisting of a gem and some metal to enhance your sight, detection and infravision! At tier 4 it even allows you to fight while blinded. #{italic}#Amazing!#{normal}#", "　宝石と金属を合わせたシンプルな仕掛けです。視界を明瞭にし、察知能力と赤外線視力を増強します！　ランク４からは盲目状態でも問題なく戦えるようになります。#{italic}#素晴らしい！#{normal}#", "_t")
t("citrine", "シトリン", "_t")
t("aquamarine", "アクアマリン", "_t")
t("quartz", "クォーツ", "_t")
t("ruby", "ルビー", "_t")
t("diamond", "ダイアモンド", "_t")
t("Toxic Cannister Launcher", "ポイズンスモッグランチャー", "_t")
t("Amaze your friends with this cannister launcher which lets you project deadly poison clouds with but a wave of your hand. #{italic}#Deadly!#{normal}#", "　この弾筒兵器でお友達をびっくりさせてあげましょう。軽く手を振るだけで猛毒ガスが発生します。#{italic}#猛毒です！#{normal}#", "_t")
t("Viral Needlegun", "ウイルスニードル", "_t")
t("Blight is not dirty to a Tinker, it is useful! By combining blighted materials with a simple mechanical gun, you can fire a low damaging attack that infects foes with terrible diseases.", "　腐敗の力は工士にとって忌まわしいものではありません。有用視されています！　不浄なる物質とシンプルな構造の銃を組み合わせ、低ダメージの攻撃ができるようになります。これは敵を恐ろしい病に侵す効果があります。", "_t")
t("Razor Edge", "レイザーエッジ", "_t")
t("Properly working and tempering a metal can make it harder than normal, and hold a sharper edge.", "　金属をきちんと鍛えてやれば元の素材より強固になり、鋭い切れ味が出せます。", "_t")
t("Armour Reinforcement", "アーマーブースター", "_t")
t("Want more defense? Wear more armour!", "　守りを固めたいときには？　もっと鎧を着よう！", "_t")
t("Crystal Edge", "クリスタルエッジ", "_t")
t("Adding a crystal blade to your weapon will make it the flashiest around! (with added light damage and increased critical multiplier)", "　武器にクリスタルの刃を取り付ければ注目の的に！（光属性の追加ダメージを付与し、クリティカル倍率増加）", "_t")
t("Crystal Plating", "クリスタルプレート", "_t")
t("Boring armour not fancy enough? Bling it up with crystal plating!  Increases all of your base stats.", "　地味な鎧には飽き飽きですか？　クリスタルプレートでキラキラ感を追加しましょう！　全ステータスが増加します。", "_t")
t("Hands of Creation", "★烈火の手甲", "_t")
t("From your hands have been wrought incredible works. Your works have been forged in fire, and so have you.", "あなたの手によって数々の素晴らしい作品が生み出されてきました。それらは炎の中で鍛え上げられたものです。作者もまた然り。", "_t")
t("shocking touch", "ショックハンド", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Spike Attachment", "スパイクオプション", "_t")
t("Adding metal spikes to anything makes it more dangerous. (and also unwieldy and inconvenient)", "　金属の棘を装着すれば何だって凶悪になります。（扱いづらく、不便にも）", "_t")
t("Silver Filigree", "シルバーフィルグリー", "_t")
t("In addition to making a weapon look more fancy, it also makes it more deadly against undead and other nasties.", "　武器がかっこよくなるばかりか、アンデッド等の不浄な敵に対して致命的な威力を発揮するようになります。", "_t")
t("Back Support", "リフトサポート", "_t")
t("Just what you need to support your back when lifting heavy things; like armour, weapons or Yetis.", "　重たい荷物を背負う際のサポートにうってつけです。鎧とか、武器とか、イエティとか。", "_t")
t("Grounding Strap", "アースストラップ", "_t")
t("Keeping yourself grounded is very important, especially around lightning mages.  Increases lightning and stun resistance.", "　体を接地させておくのはとても重要です。とりわけ電撃魔法の使い手を相手にする時は。電撃耐性とスタン耐性が増加します。", "_t")

------------------------------------------------
section "tome-orcs/data/tinkers/therapeutics.lua"

t("Healing Salve", "治癒軟膏", "_t")
t([[A powerful healing salve.
To be used with the medical injector implant.]], "　強力な治癒力を有する軟膏です。医療注射インプラントを介して使用します。", "_t")
t("Pain Suppressor Salve", "痛覚抑制", "_t")
t([[A powerful salve that steels your body for a while, letting you survive below 0 life while increasing resistances.
To be used with the medical injector implant.]], "　一時的に肉体を強化する軟膏です。ＨＰの下限が上昇し、各種耐性が増加します。医療注射インプラントを介して使用します。", "_t")
t("Frost Salve", "冷気軟膏", "_t")
t([[A powerful salve that can clean physical detrimental effects from your body and grant a frost aura (cold, darkness and nature affinity).
To be used with the medical injector implant.]], "　物理系のデバフを治療し、冷気のオーラを付与する軟膏です（冷気、暗黒、自然属性の吸収増加）医療注射インプラントを介して使用します。", "_t")
t("Fiery Salve", "火炎軟膏", "_t")
t([[A powerful salve that can clean magical detrimental effects from your body and grant a fiery aura (fire, light and lightning affinity).
To be used with the medical injector implant.]], "　魔法系のステータス異常を治療し、火炎のオーラを付与する軟膏です（火炎、光、電撃属性の吸収増加）医療注射インプラントを介して使用します。", "_t")
t("Water Salve", "静水軟膏", "_t")
t([[A powerful salve that can clean mental detrimental effects from your body and grant a water aura (blight, mind and acid affinity).
To be used with the medical injector implant.]], "　精神系のステータス異常を治療し、水のオーラを付与する軟膏です（腐敗、精神、酸属性の吸収増加）医療注射インプラントを介して使用します。", "_t")
t("Unstoppable Force Salve", "限界突破軟膏", "_t")
t([[A powerful salve that makes you more resilient to physical, mental and magic effects and grants increased healing.
To be used with the medical injector implant.]], "　物理、精神、魔法系の効果に強くなり、ＨＰの回復倍率が増加します。医療注射インプラントを介して使用します。", "_t")
t("frost salve", "冷気軟膏", "_t")
t("fiery salve", "火炎軟膏", "_t")
t("water salve", "清水軟膏", "_t")
t("Poison Groove", "ポイズンタンク", "_t")
t("Poison grooves can be attached to weapons to apply a stacking poison on attacks.  While this is ideal for stacking simple damage, you can't help but wonder if you could inflict stronger effects with more knowledge..", "　武器に装着することで攻撃毎に累積していく毒を付与します。単純にダメージを与えていくなら何も問題はないのですが「もっと知識があればさらに強力な効果が得られるのでは」という考えが頭を離れません・・・", "_t")
t("Viral Injector", "ウイルスタンク", "_t")
t("Viral grooves allow your weapons to apply an infectious agent on contact, dealing immediate blight damage and reducing their highest stat.  While this strain is effective it lacks the ability to spread or adapt to its hosts weaknesses.  Perhaps there are better methods to be found.", "　武器に装着することで接触感染する病原体を付与します。直接腐敗属性のダメージを与え、一番高いステータスを低下させます。この病原体は強力ですが二次感染せず、宿主の弱点に対応して突然変異することもありません。もっといい手法があるのかもしれません。", "_t")
t("Life Support Suit", "★生命維持スーツ", "_t")
t("Apply your extensive therapeutics knowledge to try and defeat death itself!", "　深い医療知識を活用し、死そのものに抗ってみます！", "_t")
t("unstoppable force salve", "限界突破軟膏", "_t")
t("fire opal", "ファイアオパール", "_t")
t("pearl", "パール", "_t")
t("diamond", "ダイアモンド", "_t")
t("bloodstone", "ブラッドストーン", "_t")
t("Second Skin", "人工皮膚", "_t")
t("Not only does it help seal wounds, protecting you from bleeding and enhancing your healing, it also protects from armour chafe!", "　傷口を塞ぐだけではなく、裂傷を防ぎ治癒力を高めます。鎧ずれの予防にも！", "_t")
t("Air Recycler", "エアリサイクル", "_t")
t("Helps keep your airway open and lets you hold your breath longer.", "　気道を確保し、長時間息を止めていられるようになります。", "_t")
t("Moss Tread", "苔歩き", "_t")
t("Where you walk nature grows! Well moss. Sticky moss.", "　その一歩一歩に自然の恵みが！　元気な苔が生えてきます。べっとりとしたやつがね。", "_t")
t("Fungal Web", "真菌網", "_t")
t("This mesh of fungal threads absorbs nutrients for salves to provide you with added healing!", "　このカビの網が軟膏の栄養素を吸収することで、装備者の体力がさらに回復します。", "_t")

