section "tome-orcs/data/zones/cave-hatred/npcs.lua"

t("undead", "不死者", "entity type")
t("shadow", "影", "entity subtype")
t("shadow of pain", "クツウ", "entity name")
t("A shadowy embodiment of pain.", "　苦痛が顕現した影だ。", "_t")
t("shadow of hate", "ウラミ", "entity name")
t("A shadowy embodiment of hate.", "　憎悪が顕現した影だ。", "_t")
t("shadow of despair", "ゼツボウ", "entity name")
t("A shadowy embodiment of despair.", "　絶望が顕現した影だ。", "_t")
t("shadow of remorse", "カシャク", "entity name")
t("A shadowy embodiment of remorse.", "　自責の念が顕現した影だ。", "_t")
t("shadow of guilt", "ツミ", "entity name")
t("A shadowy embodiment of guilt.", "　罪悪感が顕現した影だ。", "_t")
t("shadow of anger", "イカリ", "entity name")
t("A shadowy embodiment of anger.", "　怒りが顕現した影だ。", "_t")
t("human", "人間", "entity subtype")
t("Crimson Templar John", "落日の赤騎士ジョン", "entity name")
t([[Where you once saw a warrior bathed in light, whom in an other life you could have even respected, you now see only hatred.
This warrior's once glowing armor now emits a sinister crimson light. As he marches towards you can see his eyes, they are empty.]], "　かつては陽光を纏う戦士であり、敵として出会わなければ敬意を以って接することもあっただろう。それが今や憎悪を宿すのみ。鎧は輝きを失い、邪悪な紅の光を発している。歩を詰めながらこちらに向けるその瞳はどこまでも虚ろだ。", "_t")
t([[Where you once saw a warrior bathed in light, whom in an other life you could have even respected, you now see only hatred.
This warrior's once glowing armor now emits a sinister crimson light. As he marches towards your foes you can see his eyes, they are empty.]], "　かつては陽光を纏う戦士であり、敵として出会わなければ敬意を以って接することもあっただろう。それが今や憎悪を宿すのみ。鎧は輝きを失い、邪悪な紅の光を発している。敵に歩を進めるその瞳はどこまでも虚ろだ。", "_t")

