t("Haze Commander Parmor", "噴霧司令官パーマー", "entity name")
t("The Commander of the G.E.M. this noble looking giant looks down upon you in contempt. She wields two huge rotating saws still covered in various horror entrails.", "　地熱探査モグラの司令官だ。上品な面立ちをしたジャイアントで、こちらに侮蔑の視線を向けている。彼女は巨大スチームソーを一組装着しており、その刃には多種多様な化け物どもの臓物がびっしりとこびり付いている。", "_t")
t("Half-Mechanized Yeti", "サイボーグイエティ", "entity name")
t("Whoever tortured and tormented this yeti did an amazing job of pain and destruction. As you gaze upon its fur you notice several vital spots reinforced with stralite plating. One of its arms has been replaced with a steamsaw.", "　誰がこのイエティにこんな惨たらしい真似をしたのかは知らないが、なんとも見事な殺戮兵器を作り上げたものである。毛皮をよく見ると急所に当たる部分はところどころストラライト板で補強してあるのが判る。さらに片腕がスチームソーに挿げ替えられてしまっている。", "_t")

