t("Arch-Merchant Kaltor", "大商人カルター", "entity name")
t("A well dressed giant, covered in gold, gems and fineries. Also wielding nasty looking guns at his sides. He seems to look strangely friendly while eyeing your gold purse.", "　派手な身なりのジャイアントだ。金銀宝石を身に着けた絢爛豪華な装いをしている。両脇には剣呑な銃器が収まっているのだが。なんだか不気味なほどに親しげだが、その視線はこちらの財布から離れない", "_t")
t("Kaltor", "カルター", "_t")
