section "tome-orcs/data/zones/kaltor-shop/objects.lua"

t("Pressure-enhanced Slashproof Combat Suit", "★圧力式防刃戦闘スーツ", "entity name")
t("steam-enhanced leather coat", "蒸気レザーコート", "_t")
t("A simple leather armour of excellent facture that has been craftily enhanced with hidden miniature steam engines to enhance reflexes and provide safety features.", "素晴らしい機能を有するシンプルなレザーアーマーだ。複数の小型蒸気エンジンを巧みに仕込んであり、反応性向上効果、および防御機構を有する。", "_t")
t("When you take a hit of more than 10% of your total life the suit's motors activate for the next turn, displacing you before any blow could hit you.", "最大ＨＰの１０％を超えるダメージを受けた際、次のターンにスーツのモーターが起動する。これにより攻撃を受ける際に別のマスに移動してダメージを免れる。", "_t")
t("Brilliant Auto-loading Orc Expeller", "★最高級自動装填オークキラー", "entity name")
t("expensive gun", "高級品の銃", "_t")
