section "tome-orcs/data/zones/krimbul/npcs.lua"

t("Nektosh the One-Horned", "一本角ネクトッシュ", "entity name")
t("A withered Whitehoof, with two horns that curve over his head and spiral into a cone.  The tip of his \"horn\" glows intensely, but is slowly fading; he acts confident, but his darting, wild eyes reveal panic behind them.", "　痩身の白蹄族だ。二本の角が捻じれて絡まり、一本に合わさっている。「角」の先端は眩い光を放っているが徐々に輝きを失いつつある。尊大な態度とは裏腹に、興奮して視線が定まらず、パニックに陥っていることが見て取れる。", "_t")
t("KNOW MY POWER, FOOLISH MORTAL!", "我が力を見よ！　愚かなる常命の者よ！", "_t")
t("Stop--  stop moving and this will be over before you can feel pain!  STOP!", "止まれ、動くな。痛みを感じる暇もないはず！　動くなというに！", "_t")
t("No...  come on, come on, there has to be something left...", "なんと・・・どうした、どうした、まだ残っているはずだ・・・", "_t")
t("...it's gone...  FINE!  I don't need that power to destroy you!", "終わり・・・か・・・まあいい！　貴様を殺すのにあの力は要らぬ！", "_t")

------------------------------------------------
