section "tome-orcs/data/zones/palace-fumes/npcs.lua"

t("giant", "ジャイアント", "entity type")
t("steam", "蒸気", "entity subtype")
t("Council Member Nashal", "ナシャール議員", "entity name")
t("The noble features on the face of this giantess contrast heavily with the evil grin she carries and the huge rotating saws on her arms.", "　上品な顔立ちをしたジャイアントの女性だ。しかしそれとは真逆の邪悪な笑みを浮かべており、両腕には巨大なスチームソーを装着している。", "_t")
t("Council Member Tormak", "トーマック議員", "entity name")
t("A master in all things arcane, Tormak stands in your way, steadfast in his resolution to crush you under his mighty spells.", "　魔法の達人トーマックが行く手を塞ぎ、その強力な術の数々でこちらの息の根を止めんと息巻いている。", "_t")
t("Council Member Pendor", "ペンダー議員", "entity name")
t("Wielding two huge steamguns this giant is amazingly elusive and agile for his size. Oh and very deadly!", "　二丁拳銃を構えたジャイアントだ。その巨体とは裏腹に、身のこなしには目を見張るものがある。おっと、殺傷力も折り紙付きだ！", "_t")
t("Council Member Palaquie", "パラクワイエ議員", "entity name")
t("Standing proud, the giantess wields both a steamgun and a mindstar, as the bullets fly you can feel a powerful mental pressure on your mind, numbing you.", "　超然としたジャイアントの女性だ。片手にスチームガン、もう片方にはマインドスターを携えている。彼女が銃を撃つと強烈な威圧感を覚え、体が動かなくなる。", "_t")
t("Council Member Tantalos", "タンタロス議員", "entity name")
t("It seems like a safe assumption that the highest elected official of the Atmos Tribe was not always a hideous, titanic abomination, reminiscent of the few images of Sher'Tul you have seen, with a combination of unnatural appearance and sickening gurgling noises that revulses you on every level from intellectual and moral disgust, all the way down to a primal instinct that roars wordlessly in your mind with a fear and hatred older than any language.  If he was, his campaign's gerrymandering talents must have been legendary.", "　「アトモス族の議長に就任したタンタロスは生まれた時からおぞましい化物であった」と考えるのは妥当ではないだろう。その姿はこれまでに幾度か見たシェール・タルの外観を連想してしまう。ゴボゴボと気色悪い音を立てるその不気味な姿を見ると、理性であれ本能であれ、ありとあらゆる種類の嫌悪感が沸き上がり、例えようのない原始的な恐怖と憎悪に頭がいっぱいになる。元からこういう姿だったというのなら、彼の選挙手腕はとてつもないものだったに違いない。", "_t")
t("construct", "人造生物", "entity type")
t("mechanical", "機械仕掛け", "entity subtype")
t("steam defence turret", "蒸気式防衛タレット", "entity name")
t([[This appears to be mechanized pedestal.
Two steamguns mounted on its top constantly swivel back and forth, seeking enemies of the Atmos.]], "　これは機械仕掛けの台座なのか。てっぺんにスチームガンが二丁設置してあり、しきりに回転してアトモス族の敵を狙っている。", "_t")

