section "tome-orcs/data/zones/slumbering-caves/npcs.lua"

t("Amakthel's Hand", "アマクテルの手", "entity name")
t("god", "神", "entity type")
t("eyal", "イヤル", "entity subtype")
t([[You never thought this could even exist. You certainly never thought you'd encounter it. But this is true, in front of you stands a piece of Amakthel himself.
The god that myths say was slain by the Sher'tul, themselves nothing but a myth.
But there it is, half alive, half dead but you can feel his thoughts in your head, there is no mistake: #{bold}#The Dead God is here!#{normal}#]], [[　まさか実在していたとは。間近に見ることになろうとは夢にも思っていなかった。だが現にここにある。目の前にかのアマクテルの体の一部があるのだ。神話によればアマクテルはシェール・タルの手で斃されたという。だがこれはあくまでも神話に過ぎない。
　しかしこの場所に、生きているでもなく、死んでいるでもない、アマクテルの一部があり、その思考が頭の中に伝わってくる。間違いない。
#{bold}#　死せる神がここにいる！#{normal}#]], "_t")
t("Amakthel's Mouth", "アマクテルの口", "entity name")
t("#PURPLE#%s shouts: 'YOU DO NOT GET AWAY!'", "#PURPLE#%sが呼ばわる。「逃すものか！」", "saySimple")
t("#PURPLE#%s shouts: 'YOU DO NOT GET AWAY!'", "#PURPLE#%sが呼ばわる。「逃すものか！」", "log")
t("Amakthel's Eye", "アマクテルの目", "entity name")
t("spiked tentacle", "棘を生やした触手", "entity name")
t("A huge tentacle, ready to crush you with its many spikes.", "　巨大な触手だ。無数のスパイクでこちらを叩き潰そうとしている。", "_t")
t("oozing tentacle", "粘液が湧き出る触手", "entity name")
t("Ooze pours out of this disgusting tentacle.", "　このおぞましい触手からは粘液が溢れている。", "_t")
t("eyed tentacle", "一つ目の触手", "entity name")
t("A single malevolent eye is set atop this tentacle. And it watches you.", "　この触手の先端には悪意に満ちた目玉がついている。そしてこちらを眺めているのだ。", "_t")
t("Sher'Tul High Priest", "シェール・タルの大祭司", "entity name")
t("shertul", "シェール・タル", "entity subtype")
t("So they do exist! Sher'Tul! The stuff of myth and legends. The stuff of terror. The stuff of nightmares. The stuff of unlimited power. The race that turned on the gods of old and actually won. This one seems intent on resurrecting Amakthel, the most powerful of all the gods. You do not know why but this cannot happen or all Orcs, and the world, will be doomed.", "　やはり実在した！　シェール・タルだ！　神話の住人。恐怖の化身。悪夢の顕現。比類なき力を持つ者。この種族は古き神々に反旗を翻し、その手で勝利を収めた。このシェール・タルは最高神たるアマクテルの復活に着手しているらしい。なぜそんなことをしているのかは判らないが、これを許せばオークが、ひいては全世界が滅亡することになる。", "_t")
t("#CRIMSON#%s awakens and empowers %s!", "#CRIMSON#%sが目覚め%sに力を与えた！", "saySimple")

------------------------------------------------
section "tome-orcs/data/zones/slumbering-caves/objects.lua"

t("a journal", "日記", "entity name")
t("A journal.", "日記だ。", "_t")
t("Gardanion, the Light of God", "★光の神ガーダニオン", "entity name")
t("pure white amulet", "純白のアミュレット", "_t")
t([["#{italic}#When Amakthel arrived, he created the Sun and brought life to this world.
You carry a piece of His Sun with you now. Do not forget who gave it to you, lest you become like those wretched fools who would forsake Him.#{normal}#"]], "\"#{italic}#アマクテル来たりて太陽を創り、この世界に命をもたらした。今、その太陽の破片が手の中にある。これを誰に負っているのか覚えておくがいい。さもなくば最高神に背を向けた卑劣な愚か者どもの轍を踏むことになる。#{normal}#\"", "_t")
t("When worn, gives you an additional prodigy point.", "装備時に奥義ポイントを１点獲得する。", "_t")
t("#GOLD#The light of the Amulet envelops you, then subsides. You feel stronger. (+1 Prodigy Points)", "#GOLD#アミュレットの輝きが体を包み、そしてゆっくりと消えていった。強くなった気がする（奥義ポイント＋１", "logPlayer")
t("#GOLD#The light of the Amulet envelops you, then subsides. You feel stronger. (+1 Prodigy Points)", "#GOLD#アミュレットの輝きが体を包み、そしてゆっくりと消えていった。強くなった気がする（奥義ポイント＋１", "saySimple")

