t("elf", "エルフ", "entity subtype")
t("Star Gazer", "星見", "entity name")
t("This astromancer radiates the power of all celestial bodies. You can discern a distinct elven shape under the hood and robes.", "　全天の力を発して輝く星界師だ。フードを被ったローブ姿の下にはエルフのシルエットがはっきりと判る。", "_t")
t("Astral-Infused Yeti", "アストラルイエティ", "entity name")
t("You wonder how this yeti can have wandered so far from its native habitat in the Clork Peninsula. You also wonder what happened to it that produced the celestial energies-wielding creature you angrily marching towards you.", "　一体どういう経緯でこのイエティは本来の生息地であるクローク半島を遠く離れてここまでやってきたのだろうか。星々の力を纏い、憤然と迫るこの獣が生まれたきっかけも気になるところだ。", "_t")

