section "tome-orcs/superload/mod/class/Actor.lua"

t("#FFD700#St. power#FFFFFF#: ", "#FFD700#蒸気パワー#FFFFFF#: ", "_t")
t("Kruk Invasion", "クルク族防衛", "_t")
t("You can not recall until you have placed the bomb at the tunnel's end!", "　今は帰還できない。まずトンネルの終端に爆弾を設置しよう！", "_t")
t("scroll", "巻物", "_t")
t("This parchment contains some lore.", "　この紙片には何か書いてある。", "_t")
