t("Race: Yeti", "種族：イエティ", "_t")
t("Race: Whitehooves", "種族：白蹄族", "_t")
t("Class tree: Undead drake", "タレントツリー：不死竜", "_t")
t("Cosmetic: orcs", "キャラ装飾：オーク", "_t")
t("Build Option: Tinkers in Maj'Eyal Campaign", "オプション：マイ・イヤル・工士クラス", "_t")
t("Build Option: Mages in Orcs Campaign", "オプション：オーク・魔導士クラス", "_t")
t("Build Option: Rogues in Orcs Campaign", "オプション：オーク・盗賊クラス", "_t")
